    def _replace_library_reader_preference(
        self,
        destination: LibraryReaderDestination,
        key: Literal["library_open", "items_open"],
        value: bool,
    ) -> None:
        """Replace one pane choice, sharing only the Library-pane preference."""
        attributes = {
            "media": "_media_state.reader_preferences",
            "collections": "_collections_state.reader_preferences",
            "conversations": "_conversations_state.reader_preferences",
            "notes": "_notes_state.reader_preferences",
            "notes_files": "_notes_state.file_notes_reader_preferences",
            "prompts": "_prompts_state.reader_preferences",
            "skills": "_skills_state.reader_preferences",
        }
        attribute = attributes[destination]
        preferences = operator.attrgetter(attribute)(self)
        _assign_library_reader_preferences_attribute(
            self, attribute, dataclasses.replace(preferences, **{key: value})
        )
        if key != "library_open":
            return
        for other_attribute in attributes.values():
            if other_attribute == attribute:
                continue
            other = operator.attrgetter(other_attribute)(self)
            _assign_library_reader_preferences_attribute(
                self,
                other_attribute,
                dataclasses.replace(other, library_open=value),
            )

    @staticmethod
    def _library_reader_persistence_key(
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
    ) -> str:
        if pane == "library":
            return "library"
        return (
            "notes_file_items"
            if destination == "notes_files"
            else f"{destination}_items"
        )

    def _claim_library_reader_persistence(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
    ) -> int:
        """Claim the shared Library or destination-specific Items authority."""
        key = self._library_reader_persistence_key(destination, pane)
        generation = self._library_reader_persistence_generations[key] + 1
        self._library_reader_persistence_generations[key] = generation
        self._library_reader_dirty_persistence_authorities.add(key)
        return generation

    def _library_reader_persistence_is_current(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
        generation: int,
    ) -> bool:
        key = self._library_reader_persistence_key(destination, pane)
        return self._library_reader_persistence_generations[key] == generation

    def _sync_library_reader_preference_layout(
        self,
        destination: LibraryReaderDestination,
        key: Literal["library_open", "items_open"],
        priority: Literal["library", "items"] | None = None,
        *,
        manual_reopen: PaneName | None = None,
        automatic_priority: bool = True,
    ) -> None:
        """Sync the mounted consumer of one optimistic choice or rollback."""
        if key == "library_open" or destination == "media":
            self._sync_library_media_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "collections":
            self._sync_library_collections_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "conversations":
            self._sync_library_conversation_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "notes":
            self._sync_library_notes_reader_layout_from_shell(
                priority,
                manual_reopen=manual_reopen,
            )
        if key == "library_open" or destination == "notes_files":
            self._sync_library_file_notes_reader_layout_from_shell(
                priority,
                manual_reopen=manual_reopen,
                automatic_priority=automatic_priority,
            )
        if key == "library_open" or destination == "prompts":
            self._sync_library_prompts_reader_layout_from_shell(priority)
        if key == "library_open" or destination == "skills":
            self._sync_library_skills_reader_layout_from_shell(priority)

    async def _read_library_reader_persisted_preference(
        self,
        section: str,
        key: str,
    ) -> bool | None:
        """Read one effective pane value from the authoritative config boundary."""
        try:
            serialized = await asyncio.to_thread(read_cli_config_serialized)
            values = tomllib.loads(serialized)
            if section == "library.reader" and key == "library_open":
                library = values.get("library", {})
                if not isinstance(library, Mapping):
                    raise KeyError("library")
                reader = library.get("reader", {})
                legacy = library.get("media_reader", {})
                if isinstance(reader, Mapping) and key in reader:
                    raw_value = reader.get(key)
                elif isinstance(legacy, Mapping):
                    raw_value = legacy.get(key)
                else:
                    raw_value = None
            else:
                value: object = values
                for part in section.split("."):
                    if not isinstance(value, Mapping):
                        raise KeyError(part)
                    value = value.get(part, {})
                if not isinstance(value, Mapping):
                    raise KeyError(key)
                raw_value = value.get(key)
            logical_key = "library_open" if key == "library_open" else "items_open"
            return getattr(
                normalize_adaptive_reader_preferences({logical_key: raw_value}),
                logical_key,
            )
        except Exception:
            logger.warning("Library reader persisted pane value could not be verified.")
            return None

    async def _persist_library_reader_preference(
        self,
        destination: LibraryReaderDestination,
        pane: Literal["library", "items"],
        value: bool,
        generation: int,
        verify_failure_from_config: bool = False,
    ) -> None:
        """Persist one grip choice and reconcile writes superseded in flight."""
        key: Literal["library_open", "items_open"] = (
            "library_open" if pane == "library" else "items_open"
        )
        authority = self._library_reader_persistence_key(destination, pane)
        preferences_attribute = {
            "media": "_media_state.reader_preferences",
            "collections": "_collections_state.reader_preferences",
            "conversations": "_conversations_state.reader_preferences",
            "notes": "_notes_state.reader_preferences",
            "notes_files": "_notes_state.file_notes_reader_preferences",
            "prompts": "_prompts_state.reader_preferences",
            "skills": "_skills_state.reader_preferences",
        }[destination]
        locks = {
            "media": self._media_state.reader_persistence_locks,
            "collections": self._collections_state.reader_persistence_locks,
            "conversations": self._conversations_state.reader_persistence_locks,
            "notes": self._notes_state.reader_persistence_locks,
            "notes_files": self._notes_state.file_notes_reader_persistence_locks,
            "prompts": self._prompts_state.reader_persistence_locks,
            "skills": self._skills_state.reader_persistence_locks,
        }[destination]
        section = (
            "library.reader"
            if pane == "library"
            else (
                "library.notes_reader"
                if destination == "notes_files"
                else f"library.{destination}_reader"
            )
        )
        config_key = (
            "library_open"
            if pane == "library"
            else "files_tree_open"
            if destination == "notes_files"
            else "items_open"
        )
        mirror = {
            "media": self._mirror_library_media_reader_preference,
            "collections": self._mirror_library_collections_reader_preference,
            "conversations": self._mirror_library_conversation_reader_preference,
            "notes": self._mirror_library_notes_reader_preference,
            "notes_files": self._mirror_library_file_notes_reader_preference,
            "prompts": self._mirror_library_prompts_reader_preference,
            "skills": self._mirror_library_skills_reader_preference,
        }[destination]
        attempted_generation = generation
        attempted_value = value
        verified_physical_value = False
        async with locks[pane]:
            if (
                not self._library_reader_persistence_is_current(
                    destination, pane, attempted_generation
                )
                or getattr(operator.attrgetter(preferences_attribute)(self), key) != attempted_value
            ):
                return
            while True:
                if (
                    self._library_reader_durable_generations[authority]
                    == attempted_generation
                    and self._library_reader_durable_preferences[authority]
                    == attempted_value
                ):
                    return
                try:
                    persisted = await asyncio.to_thread(
                        save_setting_to_cli_config,
                        section,
                        config_key,
                        attempted_value,
                    )
                except Exception:
                    persisted = False
                if persisted is True:
                    self._library_reader_durable_preferences[authority] = (
                        attempted_value
                    )
                    self._library_reader_durable_generations[authority] = (
                        attempted_generation
                    )

                current_generation = self._library_reader_persistence_generations[
                    authority
                ]
                current_value = getattr(operator.attrgetter(preferences_attribute)(self), key)
                if persisted is True:
                    if (
                        attempted_generation == current_generation
                        and attempted_value == current_value
                    ):
                        app_config = getattr(self.app_instance, "app_config", None)
                        library_config = (
                            app_config.get("library", {})
                            if isinstance(app_config, Mapping)
                            else {}
                        )
                        section_name = (
                            "reader"
                            if pane == "library"
                            else "notes_reader"
                            if destination == "notes_files"
                            else f"{destination}_reader"
                        )
                        section_config = (
                            library_config.get(section_name, {})
                            if isinstance(library_config, Mapping)
                            else {}
                        )
                        if (
                            isinstance(section_config, Mapping)
                            and section_config.get(config_key) is attempted_value
                        ):
                            self._library_reader_dirty_persistence_authorities.discard(
                                authority
                            )
                        return
                    attempted_generation = current_generation
                    attempted_value = current_value
                    continue
                if verify_failure_from_config:
                    physical_value = (
                        await self._read_library_reader_persisted_preference(
                            section, config_key
                        )
                    )
                    current_generation = self._library_reader_persistence_generations[
                        authority
                    ]
                    current_value = getattr(operator.attrgetter(preferences_attribute)(self), key)
                    if (
                        attempted_generation != current_generation
                        or attempted_value != current_value
                    ):
                        return
                    if physical_value is None:
                        notify = getattr(self.app_instance, "notify", None)
                        if callable(notify):
                            notify(
                                "Library reader layout could not be verified from configuration; the current pane choice was kept.",
                                severity="warning",
                            )
                        return
                    self._library_reader_durable_preferences[authority] = physical_value
                    self._library_reader_durable_generations[authority] = (
                        attempted_generation
                    )
                    if physical_value == current_value:
                        self._library_reader_dirty_persistence_authorities.discard(
                            authority
                        )
                        return
                    verified_physical_value = True
                    break
                if (
                    attempted_generation != current_generation
                    or attempted_value != current_value
                ):
                    return
                break

        durable_value = self._library_reader_durable_preferences[authority]
        self._replace_library_reader_preference(destination, key, durable_value)
        mirror(key, durable_value)
        self._sync_library_reader_preference_layout(destination, key)
        if (
            verified_physical_value
            and self._library_reader_persistence_generations[authority]
            == attempted_generation
        ):
            self._library_reader_dirty_persistence_authorities.discard(authority)
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(
                "Library reader layout could not be saved; the previous pane choice was restored.",
                severity="warning",
            )

    def _restore_library_media_reader_width_on_open(self) -> None:
        """Reclaim the Reader's width when an item opens (task-31979).

        Selecting an item flips the view to the viewer, so the list-view
        widening -- which hands the empty Reader's columns to the Items list --
        must be undone. Patched straight onto the shell so it does NOT advance
        the presentation epoch or re-arm return settlement: the full resolver
        sync (``_sync_library_media_reader_layout_from_shell``) does both, and
        doing either mid-open corrupts the media-return settlement fence.
        """
        try:
            shell = self.query_one(
                ".library-media-route", LibraryBrowseReaderShell
            )
        except (NoMatches, QueryError):
            return
        if not self._library_adaptive_reader_allocation_is_current(shell):
            return
        layout = resolve_media_reader_layout(
            shell.region.width,
            self._media_state.reader_preferences,
            previous=self._media_state.reader_layout,
            reader_has_item=self._media_state.view == _MEDIA_VIEW_VIEWER,
        )
        if layout == self._media_state.reader_layout:
            return
        shell.sync_layout(layout)
        self._media_state.reader_layout = layout
        self._sync_library_media_rail_return(layout, shell.region.width)

    def _library_media_rail_return_visible(
        self, layout: MediaReaderEffectiveLayout, width: int
    ) -> bool:
        """Whether the Media stage needs its own named way back to the rail.

        task-32065: below the ordinary single-stage floor the Library pane
        cannot be co-present, so the rail is otherwise reachable only through
        a one-cell grip that says nothing about where it leads. Above the
        floor the rail is one pane away and the control would be noise.

        Args:
            layout: The layout the shell is showing.
            width: The shell's width in cells; a not-yet-measured 0 is not an
                emergency (``ordinary_emergency_required`` rejects it).

        Returns:
            Whether the "‹ Library" control belongs on screen.
        """
        return (
            width > 0
            and not layout.library_open
            and layout.items_open
            and ordinary_emergency_required(width)
        )

    def _build_library_media_rail_return(self) -> Button:
        """Build the Media stage's named way back to the rail (task-32065).

        One builder for both the compose and the remount below, so the label
        (and its ASCII fallback), the id and the initial visibility cannot
        drift apart.

        Returns:
            The "‹ Library" control, already showing or hidden.
        """
        control = Button(
            "< Library" if ascii_glyph_mode() else "‹ Library",
            id="library-media-rail-return",
            classes="library-canvas-action",
            compact=True,
        )
        control.display = self._library_media_rail_return_visible(
            self._media_state.reader_layout, self.size.width
        )
        return control

    def _sync_library_media_rail_return(
        self, layout: MediaReaderEffectiveLayout, width: int
    ) -> None:
        """Patch the "‹ Library" control's visibility in place (task-32065).

        Args:
            layout: The layout just applied to the shell.
            width: The shell's settled width in cells.
        """
        visible = self._library_media_rail_return_visible(layout, width)
        controls = self.query("#library-media-rail-return")
        if controls:
            controls.first(Button).display = visible
            return
        if not visible:
            return
        # Fix round 1: every route swap replaces the WHOLE child list of
        # ``#library-canvas`` (four sites do ``remove_children(host.children)``
        # then mount the new route), so this control is detached with the
        # outgoing canvas -- live at 60x24 the second visit to Media had the
        # list but no way back. The ordinary shell escapes that by nesting its
        # route in ``#library-canvas-route-content``; the Media items host has
        # no such wrapper, so the control puts itself back instead.
        try:
            host = self.query_one("#library-canvas", Vertical)
        except (NoMatches, QueryError):
            return
        host.mount(self._build_library_media_rail_return(), before=0)

    @on(Button.Pressed, "#library-media-rail-return")
    def handle_library_media_rail_return(self, event: Button.Pressed) -> None:
        """Reopen the Library pane through the grip's own seam (task-32065).

        Args:
            event: The ``Button.Pressed`` from the "‹ Library" control; stopped
                here so the canvas-action handlers do not also see it.
        """
        event.stop()
        self.action_library_narrow_stage_return()

    def _library_slash_would_land(self) -> bool:
        """Whether "/" would actually move focus right now (re-review N4).

        The chip promises a jump to a search or filter box. Below 64 columns
        every one of those boxes can be inside a CLOSED pane -- mounted, so a
        query finds it, but absent from the focus chain, so ``focus()`` is a
        no-op. Measured in the Media Reader at 60x24: "/ focus search" was the
        first painted chip, ``#library-media-filter`` was mounted inside the
        collapsed Items pane, and the key moved nothing. That is the same
        dead-chip lie task-32225 closed for Escape, one key over.

        Mirrors ``on_key``'s order (Conversations' own gate, then the Notes
        binding's ``check_action``, then the shared canvas-filter map, then
        the rail's global search) and shares that map with it, so the two can
        only disagree about a destination one of them stops modelling. The
        handler stays the authority on what the key DOES; this only decides
        whether the footer says so.

        Returns:
            Whether some reachable control would take the key.
        """
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            selector = (
                "#library-conversations-filter"
                if self._conversations_state.reader_layout.items_open
                else ""
            )
        elif self.check_action("library_notes_focus_filter", ()):
            return True
        else:
            selector = (
                _LIBRARY_SLASH_CANVAS_FILTERS.get(self._library_selected_row_id) or ""
            )
            if not self._library_focusable(selector):
                rail = self._active_library_rail()
                selector = (
                    "#library-search-input"
                    if rail is not None and rail.display
                    else ""
                )
        return self._library_focusable(selector)

    def _library_focusable(self, selector: str) -> bool:
        """Whether ``selector`` names a control that can take focus now."""
        if not selector:
            return False
        controls = self.query(selector)
        if not controls:
            return False
        return controls.first(Widget) in self.focus_chain

    def _library_narrow_stage_return_active(self) -> bool:
        """Whether the Library pane is closed on the live adaptive route.

        task-32225: while it is, the footer's "esc focus rail" chip was a lie
        on every adaptive-reader destination -- the hop's destination
        (``#library-search-input``) lives INSIDE the closed pane, so Escape
        moved nothing at 60x24 and the "‹ Library" control that does work was
        never named. This is the eighth honest Escape context; it is disjoint
        from ``library_emergency_return`` by construction (that stage is only
        ever set when NO reader shell is mounted, see
        ``_apply_library_emergency_geometry``).

        Fix round 1 (review finding 1): this is also the LAST of the Escape
        contexts, not a width-only one. Every Escape binding declared above
        ``library_narrow_stage_return`` -- viewer back, the three editor
        backs, trash back, an armed delete confirm, ... -- and Textual gives
        the key to the first gate that passes, so at 60x24 in the Media viewer
        the footer read "back to Library" while Escape went to the media list
        and the Library pane stayed shut. The gate now stands down whenever an
        earlier Escape action is live, which is the same stand-down the
        ``emergency.enabled`` branch beside it performs through its own
        ``guarded`` projection ("an editor/viewer/confirm is open").

        Returns:
            Whether Escape should reopen the Library pane instead of hopping.
        """
        # Bounded to the single-stage band, the same floor task-32065 gave the
        # "‹ Library" control. ABOVE it a closed Library pane is an ordinary
        # collapsed pane one grip away, and Escape there is the pinned
        # step-back through the visible roles ("focus Items", then "focus
        # Library"); taking the key from that would break the contract
        # test_conversations_escape_moves_to_nearest_visible_prior_role holds.
        #
        # ``Screen.size`` is ``self.app.size - gutter``, NOT ``Widget.size``:
        # read without an active app it RAISES ``NoActiveAppError`` rather
        # than returning ``Size(0, 0)``. This gate is reached from
        # ``_register_footer_shortcuts`` <- ``apply_navigation_context``,
        # which is driven on an unmounted screen, so the guard is the same
        # ``is_mounted`` one ``_library_emergency_return_eligibility`` (two
        # lines above this branch's caller) carries for its own ``self.app``
        # read. The width check stays for the measured-but-zero case that
        # ``ordinary_emergency_required`` refuses.
        if not self.is_mounted:
            return False
        width = self.size.width
        if width <= 0 or not ordinary_emergency_required(width):
            return False
        # Read off BINDINGS rather than a second hand-written list of their
        # names: ``library_blur_text_field`` learned the same lesson
        # (task-32051), and every hard-coded roster -- or COUNT -- of Escape
        # bindings in this file has gone stale at least once, this docstring
        # included (re-review N2: it said "eleven"; there are twelve).
        if any(
            self.check_action(earlier, ())
            for earlier in self._library_escape_actions_before(
                "library_narrow_stage_return"
            )
        ):
            return False
        shells = self.query(_LIBRARY_READER_SHELL_SELECTOR)
        if not shells:
            return False
        # Queried, not read from ``_library_reader_shell_ref``: that cache is
        # probed once per compose generation and stays False for the rest of
        # it when the probe ran before the route mounted -- which is exactly
        # the first frames of the visit this context has to be right about.
        layout = getattr(shells.first(Widget), "effective_layout", None)
        return layout is not None and not layout.library_open

    @on(LibraryPaneVisibilityChanged)
    def _library_pane_visibility_changed(
        self, event: LibraryPaneVisibilityChanged
    ) -> None:
        """Re-register the footer when a pane's applied visibility settles.

        task-32225 / task-32228: the footer is registered from
        ``compose_content``, which runs BEFORE the shell has resolved its
        allocation -- so several chips were decided against a pane state that
        was not yet true and nothing revisited them. Live on the seeded
        profile: at 60x24 the "back to Library" chip never appeared though
        Escape worked, and at 100x30 the Conversations canvas advertised only
        "F6 next pane" while its Filter box was on screen and "/" focused it.
        Both chips read a pane-open flag, and this message fires exactly when
        one of those flags changes, so one re-registration fixes both.

        Unconditional because the message itself is the gate: the shell posts
        it only when an APPLIED visibility genuinely flips (route entry, a
        grip press, a breakpoint crossing), never per frame.
        """
        event.stop()
        self._register_footer_shortcuts()

    def action_library_narrow_stage_return(self) -> None:
        """Reopen the closed Library pane (task-32225).

        The one seam the "‹ Library" control, its keyboard binding and the
        pane grips all reach: the shell's own ``PaneToggleRequested``, so the
        preference write and the persistence generation are handled exactly
        once, by ``_toggle_library_media_reader_pane``.
        """
        self.post_message(PaneToggleRequested("library"))

    def _sync_library_media_reader_layout_from_shell(
        self,
        priority: Literal["library", "items"] | None = None,
        focus_intent: tuple[Widget, int] | None = None,
    ) -> None:
        """Resolve the settled Media shell width and patch geometry in place."""
        try:
            shell = self.query_one(
                ".library-media-route", LibraryBrowseReaderShell
            )
        except (NoMatches, QueryError):
            return
        width = shell.region.width
        if not self._library_adaptive_reader_allocation_is_current(shell):
            return
        if (
            priority is None
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._media_state.view == "trash"
            and self._media_state.reader_preferences.items_open
            and not (
                self._media_state.reader_layout.priority_pane == "library"
                and self._media_state.reader_preferences.library_open
            )
        ):
            # Trash is an Items surface. At the compact allocation the reader
            # otherwise consumes every cell after a screen recompose, even
            # though the user's Items preference remains open. Reassert that
            # existing preference as layout priority. A still-requested,
            # explicitly prioritized Library pane wins until it is collapsed;
            # an explicit Items close flips that preference first too.
            priority = "items"
        previous = self._media_state.reader_layout
        # ``__init__`` resolves a zero-width sentinel before Textual has
        # assigned the mounted shell its first real region. Treating that
        # sentinel as a genuine previous layout lets hysteresis preserve its
        # necessarily-collapsed panes at borderline usable widths forever.
        # The first settled measurement has no user-visible prior layout, so
        # resolve it without hysteresis; subsequent measurements keep the
        # normal anti-flap behavior.
        if (
            previous.reader_width == 0
            and previous.library_width == 0
            and previous.items_width == 0
        ):
            previous = None
        layout = resolve_media_reader_layout(
            width,
            self._media_state.reader_preferences,
            previous=previous,
            priority=priority,
            # task-31979: only the viewer shows a real document; in the list
            # and trash views the Reader holds just its placeholder, so its
            # width goes to the Items list to stop long titles truncating.
            reader_has_item=self._media_state.view == _MEDIA_VIEW_VIEWER,
        )
        layout_changed = layout != self._media_state.reader_layout
        focused = self.focused
        if focus_intent is not None and (
            focus_intent[1] == self._notes_state.focus_intent_generation
            or self._notes_state.resize_settling
        ):
            focused = focus_intent[0]
        hidden_focus_target: tuple[Widget, Widget] | None = None
        for now_open, pane, grip in (
            (
                layout.library_open,
                shell.library,
                shell.library_grip,
            ),
            (
                layout.items_open,
                shell.items,
                shell.items_grip,
            ),
        ):
            if (
                not now_open
                and focused is not None
                and (focused is pane or pane in focused.ancestors)
            ):
                hidden_focus_target = (focused, grip)
                break
        generation = self._notes_state.focus_intent_generation
        if layout_changed:
            tree = self._library_media_settlement_tree()
            self._media_controller._advance_library_media_presentation_epoch(
                tree[2] if tree is not None else None,
                rearm=False,
            )
        shell.sync_layout(layout)
        self._media_state.reader_layout = layout
        self._sync_library_media_rail_return(layout, width)
        if layout_changed:
            receipt = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(receipt):
                self._arm_library_media_return_settlement(receipt)
            # task-31272: the Reader's "‹ Back" control and its Escape chip
            # both derive from this layout, and the first settled
            # measurement always arrives AFTER the viewer was composed
            # against __init__'s zero-width sentinel. The viewer sync is a
            # no-op unless a compose input genuinely changed. Gated on the
            # viewer being MOUNTED: ``_sync_library_media_viewer_or_
            # recompose`` falls back to a whole-screen recompose when it is
            # not, which task-21116 pins to zero on this path.
            if (
                self._media_state.view == _MEDIA_VIEW_VIEWER
                and self._mounted_library_media_viewer() is not None
            ):
                self._sync_library_media_viewer_or_recompose()
        if hidden_focus_target is not None:
            self._focus_library_media_grip_if_current(
                generation,
                *hidden_focus_target,
            )
        elif (
            layout.items_open
            and self._library_pending_list_entry_focus
            and not self._library_media_return_candidate(
                self._library_pending_list_entry_media_return
            )
            and (
                self._library_pending_list_entry_media_return is not None
                or focused is None
                or not focused.has_class("library-media-row")
            )
        ):
            # Reapply only when focus has not already landed on a Media row,
            # and cross one refresh so the Items host has final geometry.
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )

    def _mirror_library_media_reader_preference(self, key: Literal['library_open', 'items_open'], value: bool) -> None:
        return self._media_controller._mirror_library_media_reader_preference(key, value)

    def request_library_reader_layout_refresh(self, generation: int) -> None:
        """Apply newer Library reader settings without reloading destination data."""
        if generation <= self._library_reader_layout_refresh_generation:
            return
        locally_persisted = {
            authority: authority in self._library_reader_dirty_persistence_authorities
            for authority in self._library_reader_persistence_generations
        }
        previous_persistence_generations = dict(
            self._library_reader_persistence_generations
        )
        previous_durable_generations = dict(self._library_reader_durable_generations)
        previous_durable_values = dict(self._library_reader_durable_preferences)
        self._library_reader_layout_refresh_generation = generation
        self._media_state.layout_refresh_generation = generation
        for authority in self._library_reader_persistence_generations:
            self._library_reader_persistence_generations[authority] += 1
        (
            self._library_reader_shared_preferences,
            self._media_state.reader_preferences,
            self._collections_state.reader_preferences,
            self._conversations_state.reader_preferences,
            self._notes_state.reader_preferences,
            self._notes_state.file_notes_reader_preferences,
            self._prompts_state.reader_preferences,
            self._skills_state.reader_preferences,
        ) = self._load_library_reader_preference_snapshot()
        current_values = {
            "library": self._library_reader_shared_preferences.library_open,
            "collections_items": self._collections_state.reader_preferences.items_open,
            "conversations_items": self._conversations_state.reader_preferences.items_open,
            "media_items": self._media_state.reader_preferences.items_open,
            "notes_items": self._notes_state.reader_preferences.items_open,
            "notes_file_items": self._notes_state.file_notes_reader_preferences.items_open,
            "prompts_items": self._prompts_state.reader_preferences.items_open,
            "skills_items": self._skills_state.reader_preferences.items_open,
        }
        persistence_authorities: tuple[
            tuple[
                LibraryReaderDestination,
                str,
                str,
            ],
            ...,
        ] = (
            ("media", "library", "library"),
            ("media", "items", "media_items"),
            ("collections", "items", "collections_items"),
            ("conversations", "items", "conversations_items"),
            ("notes", "items", "notes_items"),
            ("notes_files", "items", "notes_file_items"),
            ("prompts", "items", "prompts_items"),
            ("skills", "items", "skills_items"),
        )
        repair_authorities = {
            authority
            for authority in current_values
            if locally_persisted[authority]
            and (
                previous_durable_generations[authority]
                != previous_persistence_generations[authority]
                or previous_durable_values[authority] != current_values[authority]
            )
        }
        for authority, value in current_values.items():
            if authority not in repair_authorities:
                self._library_reader_durable_preferences[authority] = value
                self._library_reader_durable_generations[authority] = (
                    self._library_reader_persistence_generations[authority]
                )
        self._sync_library_media_reader_layout_from_shell()
        self._sync_library_collections_reader_layout_from_shell()
        self._sync_library_conversation_reader_layout_from_shell()
        self._sync_library_notes_reader_layout_from_shell()
        self._sync_library_file_notes_reader_layout_from_shell()
        self._sync_library_prompts_reader_layout_from_shell()
        self._sync_library_skills_reader_layout_from_shell()
        self._sync_library_ordinary_rail_width_contract()
        for destination, pane, authority in persistence_authorities:
            if authority not in repair_authorities:
                continue
            self.run_worker(
                self._persist_library_reader_preference(
                    destination,
                    pane,
                    current_values[authority],
                    self._library_reader_persistence_generations[authority],
                    verify_failure_from_config=True,
                ),
                group=f"library_reader_{authority}_settings_persistence",
            )
        self._library_reader_dirty_persistence_authorities.difference_update(
            authority
            for authority, dirty in locally_persisted.items()
            if dirty and authority not in repair_authorities
        )

    def request_library_media_layout_refresh(self, generation: int) -> None:
        return self._media_controller.request_library_media_layout_refresh(generation)

    def _focus_library_media_grip_if_current(
        self,
        generation: int,
        hidden_focus: Widget,
        grip: Widget,
    ) -> None:
        """Move focus only when no newer user focus intent superseded resize."""
        if (
            generation != self._notes_state.focus_intent_generation
            and not self._notes_state.resize_settling
        ):
            return
        focused = self.focused
        if focused is hidden_focus or focused is None or not focused.display:
            self.set_focus(grip, scroll_visible=False)

    @on(PaneToggleRequested)
    def _toggle_library_media_reader_pane(self, event: PaneToggleRequested) -> None:
        """Apply and persist one manual preferred pane choice."""
        event.stop()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            layout = self._collections_state.reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key: Literal["library_open", "items_open"] = (
                "library_open" if event.pane == "library" else "items_open"
            )
            generation = self._claim_library_reader_persistence(
                "collections", event.pane
            )
            self._replace_library_reader_preference("collections", key, opening)
            self._mirror_library_collections_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "collections", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "collections", event.pane, opening, generation
                ),
                group=f"library_collections_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            layout = self._conversations_state.reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key: Literal["library_open", "items_open"] = (
                "library_open" if event.pane == "library" else "items_open"
            )
            generation = self._claim_library_reader_persistence(
                "conversations", event.pane
            )
            self._replace_library_reader_preference("conversations", key, opening)
            self._mirror_library_conversation_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "conversations", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "conversations", event.pane, opening, generation
                ),
                group=f"library_conversation_reader_{event.pane}_persistence",
            )
            return
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_FILES
        ):
            layout = self._notes_state.file_notes_reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            if (
                event.pane == "library"
                and opening
                and self._notes_state.work_session_phase
                is NotesWorkSessionPhase.ACTIVE
            ):
                self._dispatch_library_notes_work_session(
                    NotesWorkSessionEvent.MANUAL_LIBRARY_EXPAND,
                    sync_layout=False,
                )
                if self._notes_state.file_notes_reader_preferences.library_open:
                    self._sync_library_reader_preference_layout(
                        "notes_files",
                        key,
                        "library",
                        manual_reopen="library",
                        automatic_priority=False,
                    )
                    return
            generation = self._claim_library_reader_persistence(
                "notes_files", event.pane
            )
            self._replace_library_reader_preference("notes_files", key, opening)
            self._mirror_library_file_notes_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "notes_files",
                key,
                event.pane if opening else None,
                manual_reopen=event.pane if opening else None,
                automatic_priority=False,
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "notes_files", event.pane, opening, generation
                ),
                group=f"library_file_notes_reader_{event.pane}_persistence",
            )
            return
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_NOTES, LIBRARY_ROW_CREATE_NOTE)
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            layout = self._notes_state.reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            if (
                event.pane == "library"
                and opening
                and self._notes_state.work_session_phase
                is NotesWorkSessionPhase.ACTIVE
            ):
                self._dispatch_library_notes_work_session(
                    NotesWorkSessionEvent.MANUAL_LIBRARY_EXPAND,
                    sync_layout=False,
                )
                if self._notes_state.reader_preferences.library_open:
                    self._sync_library_reader_preference_layout(
                        "notes",
                        key,
                        "library",
                        manual_reopen="library",
                    )
                    return
            generation = self._claim_library_reader_persistence("notes", event.pane)
            self._replace_library_reader_preference("notes", key, opening)
            self._mirror_library_notes_reader_preference(key, opening)
            if (
                event.pane == "library"
                and not opening
                and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
                and self._notes_state.view == "list"
            ):
                # At the narrow widths where opening Library necessarily
                # evicts Items, closing it must return the reclaimed cells to
                # the title navigator rather than leaving only Work visible.
                self._sync_library_notes_reader_layout_from_shell(
                    (
                        "items"
                        if self._notes_state.reader_preferences.items_open
                        else None
                    ),
                    ignore_previous=True,
                )
            else:
                self._sync_library_reader_preference_layout(
                    "notes",
                    key,
                    event.pane if opening else None,
                    manual_reopen=event.pane if opening else None,
                )
            self.run_worker(
                self._persist_library_reader_preference(
                    "notes", event.pane, opening, generation
                ),
                group=f"library_notes_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_CREATE_PROMPT,
        }:
            layout = self._prompts_state.reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            generation = self._claim_library_reader_persistence("prompts", event.pane)
            self._replace_library_reader_preference("prompts", key, opening)
            self._mirror_library_prompts_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "prompts", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "prompts", event.pane, opening, generation
                ),
                group=f"library_prompts_reader_{event.pane}_persistence",
            )
            return
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_SKILL,
        }:
            layout = self._skills_state.reader_layout
            opening = not (
                layout.library_open if event.pane == "library" else layout.items_open
            )
            key = "library_open" if event.pane == "library" else "items_open"
            generation = self._claim_library_reader_persistence("skills", event.pane)
            self._replace_library_reader_preference("skills", key, opening)
            self._mirror_library_skills_reader_preference(key, opening)
            self._sync_library_reader_preference_layout(
                "skills", key, event.pane if opening else None
            )
            self.run_worker(
                self._persist_library_reader_preference(
                    "skills", event.pane, opening, generation
                ),
                group=f"library_skills_reader_{event.pane}_persistence",
            )
            return
        layout = self._media_state.reader_layout
        opening = not (
            layout.library_open if event.pane == "library" else layout.items_open
        )
        key: Literal["library_open", "items_open"] = (
            "library_open" if event.pane == "library" else "items_open"
        )
        generation = self._claim_library_reader_persistence("media", event.pane)
        self._replace_library_reader_preference("media", key, opening)
        self._mirror_library_media_reader_preference(key, opening)
        self._sync_library_reader_preference_layout(
            "media", key, event.pane if opening else None
        )
        self.run_worker(
            self._persist_library_reader_preference(
                "media",
                event.pane,
                opening,
                generation,
            ),
            group=f"library_media_reader_{event.pane}_persistence",
        )

    @on(AdaptiveReaderShellResized)
    def _resize_library_adaptive_reader_shell(
        self,
        event: AdaptiveReaderShellResized,
    ) -> None:
        """Resolve one mounted shared shell through its destination authority."""
        event.stop()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self._sync_library_collections_reader_layout_from_shell()
        elif self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            self._sync_library_conversation_reader_layout_from_shell()
        elif (
            self._library_selected_row_id in LIBRARY_NOTES_RAIL_ROWS
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_FILES
        ):
            self._sync_library_file_notes_reader_layout_from_shell()
        elif self._library_selected_row_id in LIBRARY_NOTES_RAIL_ROWS:
            self._sync_library_notes_reader_layout_from_shell()
            if self._notes_state.work_session_activation_pending:
                self._activate_database_note_work_session(self._notes_state.selected_note_id)

    @on(MediaShellResized)
    def _resize_library_media_reader_shell(self, event: MediaShellResized) -> None:
        return self._media_controller._resize_library_media_reader_shell(event)

    def _sync_library_ingest_rail_for_width(self, width: int) -> None:
        return self._ingest_controller._sync_library_ingest_rail_for_width(width)

    def _transition_library_notes_presentation(
        self,
        compact: bool,
        identity: LibraryNotesFocusIdentity,
    ) -> None:
        """Cross the one measured compact/wide boundary losslessly."""
        landing_prefix = "landing-control:"
        if (
            compact
            and self._library_notes_compact_stage_applies()
            and identity.semantic_role.startswith(landing_prefix)
        ):
            control_id = identity.semantic_role.removeprefix(landing_prefix)
            row_id = self._library_landing_control_row_id(control_id)
            if row_id:
                self._library_landing_responsive_focus_id = control_id
                identity = dataclasses.replace(
                    identity,
                    stage="rail",
                    semantic_role=f"library-row:{row_id}",
                )
        elif not compact and self._library_landing_responsive_focus_id:
            control_id = self._library_landing_responsive_focus_id
            row_id = self._library_landing_control_row_id(control_id)
            if identity.semantic_role == f"library-row:{row_id}":
                identity = dataclasses.replace(
                    identity,
                    stage="notes",
                    semantic_role=f"{landing_prefix}{control_id}",
                )
            else:
                self._library_landing_responsive_focus_id = ""
        self._notes_state.compact = compact
        self._notes_controller._sync_library_notes_source_controls()
        if compact:
            self._notes_state.stage = self._notes_controller._compact_library_notes_stage(identity)
            self._notes_state.explicit_stage_intent = False
        self._notes_state.transition_scroll_generation = (
            self._notes_state.scroll_intent_generation
        )
        self._notes_state.transition_focus_generation = (
            self._notes_state.focus_intent_generation
        )
        guard = _LibraryNotesRestoreGuard(
            scroll_generation=self._notes_state.transition_scroll_generation,
            focus_generation=self._notes_state.transition_focus_generation,
        )
        self._apply_library_notes_stage_visibility()
        self._apply_library_note_presentation_state()
        self._apply_library_notes_footer_context()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA and self.query(
            ".library-media-route"
        ):
            # Media's resolver owns pane visibility and focus settlement;
            # the Notes tuple would otherwise restore focus into hidden Items.
            self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
            return
        self.call_after_refresh(
            self._restore_library_notes_focus_identity,
            identity,
            guard,
        )
        self.call_after_refresh(
            self._queue_library_notes_settled_focus_restore,
            identity,
            guard,
        )

    def _queue_library_notes_settled_focus_restore(self, expected: LibraryNotesFocusIdentity, guard: _LibraryNotesRestoreGuard | None=None) -> None:
        return self._notes_controller._queue_library_notes_settled_focus_restore(expected, guard)


    def _update_library_notes_responsive_state(self) -> None:
        return self._notes_controller._update_library_notes_responsive_state()

    def _library_ref_is_live(self, widget: Widget) -> bool:
        """Return whether a cached reference is still this screen's live node.

        TASK-23025: ``is_mounted`` alone is NOT a validity check --
        ``_is_mounted`` lags detachment, and ``App._prune`` marks the doomed
        subtree ``_pruning`` synchronously while the detach happens later
        (the task-2200 lesson: ``is_mounted`` != in-the-DOM; a targeted
        canvas sync's replaced notes list measured exactly this, the scroll
        restore landing on the pruned corpse). Walking the ``_parent`` chain
        back to this screen is a handful of attribute hops -- still far
        cheaper than a DOM walk -- and matches what ``query_one`` would
        resolve.
        """
        if getattr(widget, "_pruning", False) or not widget.is_mounted:
            return False
        node: DOMNode | None = widget
        while node is not None:
            if node is self:
                return True
            node = node._parent
        return False

    def _library_layout_ref(self, selector: str) -> Widget | None:
        """Resolve one invariant shell-chrome widget through the ref cache.

        TASK-23025: positive references only, validated by
        ``_library_ref_is_live`` and cleared in ``compose_content`` (the
        choke point every whole-screen recompose passes through), so hot
        per-frame paths read attributes instead of re-walking the DOM. A
        miss falls back to one id-selector ``query_one`` and re-caches;
        absence is never cached, so a widget that mounts later is still
        found.
        """
        cached = self._library_layout_ref_cache.get(selector)
        if cached is not None and self._library_ref_is_live(cached):
            return cached
        try:
            widget = self.query_one(selector, Widget)
        except (NoMatches, QueryError):
            self._library_layout_ref_cache.pop(selector, None)
            return None
        self._library_layout_ref_cache[selector] = widget
        return widget

    def _library_compose_scoped_ref(self, selector: str) -> Widget | None:
        """Positive AND negative ref cache for compose_content-exclusive ids.

        TASK-23025: only valid for ids constructed exclusively inside
        ``compose_content`` (e.g. the note work pane) -- cached absence
        would otherwise go stale when a widget mounts through another seam.
        The cache, including cached absence, is cleared in
        ``compose_content``.
        """
        if selector in self._library_compose_ref_cache:
            cached = self._library_compose_ref_cache[selector]
            if cached is None:
                return None
            if self._library_ref_is_live(cached):
                return cached
        try:
            widget: Widget | None = self.query_one(selector, Widget)
        except (NoMatches, QueryError):
            widget = None
        self._library_compose_ref_cache[selector] = widget
        return widget

    def _library_adaptive_reader_shell_active(self) -> bool:
        """Report adaptive reader-shell presence without a per-frame walk.

        All five ``*-reader-shell`` ids are constructed exclusively in
        ``compose_content``, so shells (un)mount only across a compose
        generation -- one failed probe per recompose is exact, and a
        mounted shell is revalidated by its own ``is_mounted`` flag.
        """
        cached = self._library_reader_shell_ref
        if cached is not None and self._library_ref_is_live(cached):
            return True
        if (
            self._library_reader_shell_probe_generation
            == self._library_compose_generation
        ):
            return False
        self._library_reader_shell_probe_generation = self._library_compose_generation
        shells = self.query(_LIBRARY_READER_SHELL_SELECTOR)
        self._library_reader_shell_ref = shells.first(Widget) if shells else None
        return self._library_reader_shell_ref is not None

    def _library_resize_layout_signature(self) -> tuple[Any, ...] | None:
        """Signature of every width-derived decision the resize legs make.

        TASK-23025 (AC: gate before query work): built from cached widget
        references and cheap flags only -- ``region``/``content_region``
        attribute reads, never a DOM walk. Mirrors, in order, the inputs of
        ``_sync_library_ingest_rail_for_width`` (ingest collapse bucket),
        ``_sync_library_ordinary_rail_width_contract`` (the resolved
        contract itself, so the custom-width clamp band stays exact),
        ``_apply_library_notes_stage_visibility`` (its route/stage flags
        plus ``_apply_library_emergency_geometry``'s bucket), and the
        compact-crossing check. Returns ``None`` when it cannot be decided
        cheaply; callers then run the full legs, exactly as before.
        """
        shell = self._library_layout_ref("#library-shell-grid")
        rail = self._library_layout_ref("#library-rail")
        canvas = self._library_layout_ref("#library-canvas")
        if shell is None or rail is None or canvas is None:
            return None
        width = shell.region.width
        if width <= 0:
            return None
        viewport = self.size.width if self.is_mounted else 0
        effective = min(width, viewport) if viewport > 0 else width
        content_width = shell.content_region.width
        emergency_width = min(width, viewport)
        reader_active = self._library_adaptive_reader_shell_active()
        contract: OrdinaryRailStyleContract | None = None
        if not reader_active and content_width >= LIBRARY_EMERGENCY_WIDTH:
            if not rail.display:
                presentation = OrdinaryRailPresentation.HIDDEN
            elif not canvas.display:
                presentation = OrdinaryRailPresentation.RAIL_ONLY
            else:
                presentation = OrdinaryRailPresentation.ALONGSIDE
            shared = self._library_reader_shared_preferences
            contract = resolve_ordinary_rail_contract(
                content_width,
                presentation,
                shared.custom_widths_enabled,
                shared.library_width,
            )
        return (
            self._library_compose_generation,
            shell,
            rail,
            canvas,
            self._library_selected_row_id,
            self._notes_state.source,
            self._notes_state.view,
            self._notes_state.stage,
            self._notes_state.compact,
            self._library_rail_collapsed,
            self._ingest_state.auto_collapsed_rail,
            self._library_emergency_stage,
            self._file_notes_active(),
            rail.display,
            canvas.display,
            reader_active,
            self._library_reader_shared_preferences,
            width < LIBRARY_NOTES_COMPACT_BREAKPOINT,
            effective < LIBRARY_INGEST_RAIL_COLLAPSE_BREAKPOINT,
            (
                ordinary_emergency_required(emergency_width)
                if emergency_width > 0
                else None
            ),
            content_width < LIBRARY_EMERGENCY_WIDTH,
            contract,
        )

    def on_resize(self, event: events.Resize) -> None:
        """Capture only a crossing, decided by the measured invariant grid."""
        del event
        self._notes_state.resize_epoch += 1
        self._notes_state.resize_settling = True
        # TASK-22228 (item 7): the Media reader layout leg is scheduled only
        # while Browse Media owns the canvas -- the one route that wears
        # ``.library-media-route`` on the shared browse shell (``compose``'s
        # ``canvas_kind == "media"`` branch; the same predicate
        # ``_sync_library_media_viewer_state`` gates the viewer on). Anywhere
        # else the scheduled call could only walk the whole Library DOM
        # looking for a shell that is not mounted and return: a FAILED
        # ``query_one`` takes no id-cache fast path, so every Notes /
        # Conversations / Ingest resize frame paid two full breadth-first
        # walks (measured 16.0 us each on a 118-widget fixture) to do
        # nothing. Behaviour is unchanged -- the skipped call was already a
        # no-op on those routes.
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            focused = self.focused
            focus_intent = (
                (focused, self._notes_state.focus_intent_generation)
                if focused is not None
                else None
            )
            self.call_after_refresh(
                self._sync_library_media_reader_layout_from_shell,
                focus_intent=focus_intent,
            )
        # TASK-23025: decide from cheap state -- cached references and
        # width-bucket arithmetic -- whether this frame can change anything
        # the legs below derive, BEFORE any of their query work. The
        # signature is recorded pre-legs, so a frame whose legs mutate flags
        # simply runs once more on the next event and then settles; a skip
        # can never hide a crossing because every bucket the legs compare is
        # part of the signature.
        signature = self._library_resize_layout_signature()
        if signature is not None:
            if signature == self._library_resize_applied_signature:
                self._notes_state.pre_resize_focus = None
                return
            self._library_resize_applied_signature = signature
        try:
            width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            return
        if width <= 0:
            return
        self._sync_library_ingest_rail_for_width(width)
        self._sync_library_ordinary_rail_width_contract()
        self._apply_library_notes_stage_visibility_for_resize()
        compact = width < LIBRARY_NOTES_COMPACT_BREAKPOINT
        if compact == self._notes_state.compact:
            self._notes_state.pre_resize_focus = None
            return
        current = self._capture_library_notes_focus_identity(stage_from_focus=True)
        identity = current
        for cached in (
            self._notes_state.last_user_focus,
            self._notes_state.interaction_focus,
            self._notes_state.last_presented_focus,
            self._notes_state.responsive_focus_memory,
        ):
            if (
                cached is not None
                and cached.region == current.region
                and cached.note_id == current.note_id
                and (
                    not current.semantic_role.startswith(
                        (
                            "media-row:",
                            "media-preview-open:",
                            "landing-control:",
                            "library-row:",
                        )
                    )
                    or cached.semantic_role == current.semantic_role
                )
            ):
                identity = dataclasses.replace(
                    cached,
                    stage=current.stage,
                    body_selection_start=current.body_selection_start,
                    body_selection_end=current.body_selection_end,
                )
                break
        user_scroll = self._notes_state.last_user_scroll_focus
        if (
            user_scroll is not None
            and user_scroll.region == current.region
            and user_scroll.note_id == current.note_id
            and (
                not current.semantic_role.startswith(
                    (
                        "media-row:",
                        "media-preview-open:",
                        "landing-control:",
                        "library-row:",
                    )
                )
                or user_scroll.semantic_role == current.semantic_role
            )
        ):
            identity = dataclasses.replace(
                identity,
                scroll_offset=user_scroll.scroll_offset,
            )
        self._notes_state.pre_resize_focus = identity
        self.call_after_refresh(self._update_library_notes_responsive_state)

    def _mark_library_notes_user_interaction(self) -> None:
        return self._notes_controller._mark_library_notes_user_interaction()

    def on_mouse_down(self, event: events.MouseDown) -> None:
        """Let click-driven focus changes supersede resize memory."""
        try:
            target, _ = self.get_widget_at(event.screen_x, event.screen_y)
        except (NoMatches, NoWidget):
            target = None
        self._advance_library_ordinary_emergency_user_interaction(target)
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def on_mouse_scroll_down(self, event: events.MouseScrollDown) -> None:
        """Let wheel scrolling supersede resize and list-return memory."""
        self._advance_library_ordinary_emergency_user_interaction(
            getattr(event, "widget", None)
        )
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def on_mouse_scroll_up(self, event: events.MouseScrollUp) -> None:
        """Let wheel scrolling supersede resize and list-return memory."""
        self._advance_library_ordinary_emergency_user_interaction(
            getattr(event, "widget", None)
        )
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()

    def _notes_footer_tier(
        self,
        wide: tuple[tuple[str, str], ...],
        compact: tuple[tuple[str, str], ...],
    ) -> tuple[tuple[str, str], ...]:
        """Pick the width tier of one Notes footer set (task-4023 AC#5).

        Same keys and destinations in both tiers; the compact tier only
        compresses labels so the context still fits the ≤100-col displayed
        footer -- mirroring ``AppFooterStatus``'s own FULL/COMPACT global
        tiers rather than inventing a second dialect.
        """
        return compact if self._notes_state.compact else wide

    def _library_notes_footer_shortcuts(self) -> tuple[tuple[str, str], ...]:
        """Return exact one-row local help for the visible Notes state."""
        if not self._library_notes_workflow_active() or (
            self._notes_state.compact and self._notes_state.stage != "notes"
        ):
            return self._library_footer_shortcuts_for_current_state()
        snapshot = self._library_note_session.snapshot
        if snapshot is not None and (
            snapshot.in_conflict
            or self._library_note_session.conflict_resolution_running
        ):
            # A running resolution locks every key -- advertise nothing
            # (globals only) rather than a dead entry (AC#5 honesty).
            if self._library_note_session.conflict_resolution_running:
                return ()
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_CONFLICT_SHORTCUTS,
                self.LIBRARY_NOTES_CONFLICT_SHORTCUTS_COMPACT,
            )
        if self._notes_state.confirming_delete:
            # task-32132 AC#2: name the FOCUSED button's own action -- entry
            # focus lands on Cancel, where Enter cancels, not "confirm
            # delete" as the old static copy claimed regardless of focus.
            enter_label = self._library_focus_enter_label() or "cancel"
            return self._notes_footer_tier(
                (("enter", enter_label), ("tab", "switch button"), ("esc", "cancel")),
                (("enter", enter_label), ("tab", "switch"), ("esc", "cancel")),
            )
        region = self._library_notes_focus_region()
        if region == "navigator":
            if self._notes_state.select_mode:
                return self._notes_footer_tier(
                    (("enter", "select note"), ("esc", "done")),
                    (("enter", "select"), ("esc", "done")),
                )
            if self._notes_state.sort_choices_visible:
                return self._notes_footer_tier(
                    (("enter", "choose sort"), ("esc", "cancel")),
                    (("enter", "choose sort"), ("esc", "cancel")),
                )
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_NAVIGATOR_SHORTCUTS,
                self.LIBRARY_NOTES_NAVIGATOR_SHORTCUTS_COMPACT,
            )
        if region == "preview":
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_PREVIEW_SHORTCUTS,
                self.LIBRARY_NOTES_PREVIEW_SHORTCUTS_COMPACT,
            )
        if region == "context":
            return self._notes_footer_tier(
                self.LIBRARY_NOTES_CONTEXT_SHORTCUTS,
                self.LIBRARY_NOTES_CONTEXT_SHORTCUTS_COMPACT,
            )
        if region == "editor":
            tier = self._notes_footer_tier(
                self.LIBRARY_NOTES_EDITOR_SHORTCUTS,
                self.LIBRARY_NOTES_EDITOR_SHORTCUTS_COMPACT,
            )
            # task-32246 AC#2: Tab out of the body lands on a toolbar Button,
            # where typed characters go nowhere. Name it, so focus is never
            # unaccounted for -- the honest-footer rule, applied to the
            # editor the way the create canvas and delete prompt apply it.
            #
            # APPENDED, not prepended (fix round 1, review F1). The real
            # footer keeps only the leading chips that fit, and the
            # <=64-column narrow stage fits exactly one
            # (``test_only_one_context_chip_paints_at_sixty_columns``), so a
            # LEADING "enter …" evicted the exit outright: after the very Tab
            # this task fixes the footer painted "enter back to list" alone,
            # and with Save focused it advertised neither an exit nor a way
            # back. Naming focus is the smaller promise of the two, so it
            # yields wherever the two compete for the budget.
            enter_label = self._library_focus_enter_label()
            if enter_label:
                return tier + (("enter", enter_label),)
            return tier
        if region == "create":
            if self._notes_state.create_running:
                return ()
            # task-32052 AC#4: "enter create note" is true on Blank note and
            # the template rows -- where entry focus now lands -- but not on
            # the canvas's "‹ Notes" button, where Enter goes back. The
            # honest-footer rule the sibling tiers already follow.
            if self._library_focus_enter_label() != "create note":
                return self._notes_footer_tier(
                    (("esc", "back to notes"),),
                    (("esc", "notes"),),
                )
            return self._notes_footer_tier(
                (("enter", "create note"), ("esc", "back to notes")),
                (("enter", "create"), ("esc", "notes")),
            )
        if region in {"lasting_add", "lasting_roots"}:
            phase = self._library_notes_sync_controller.snapshot.phase
            if phase in {"checking", "activating"}:
                return (("wait", "current step"),)
            return self._notes_footer_tier(
                (("enter", "run action"), ("esc", "back to notes")),
                (("enter", "act"), ("esc", "notes")),
            )
        if region == "trash":
            # Only what this view answers: no Enter chip, because entry focus
            # lands on a Restore button whose action "r" already names.
            if not (self._notes_state.trash and self._notes_state.trash.rows):
                return self._notes_footer_tier(
                    (("esc", "back to notes"),), (("esc", "notes"),)
                )
            return self._notes_footer_tier(
                (("r", "restore note"), ("esc", "back to notes")),
                (("r", "restore"), ("esc", "notes")),
            )
        if region == "import":
            phase = self._library_note_import_controller.snapshot.phase
            if phase in {NoteImportPhase.CHECKING, NoteImportPhase.IMPORTING}:
                return (("esc", "cancel"),)
            return (("esc", "back to notes"),)
        return self._library_footer_shortcuts_for_current_state()

    def _apply_library_notes_footer_context(self) -> None:
        return self._notes_controller._apply_library_notes_footer_context()

    def _rehydrate_library_notes_after_recompose(self, restore: _LibraryNotesRecomposeCapture) -> None:
        return self._notes_controller._rehydrate_library_notes_after_recompose(restore)

    def refresh(
        self,
        *regions: Region,
        repaint: bool = True,
        layout: bool = False,
        recompose: bool = False,
    ) -> "LibraryScreen":
        """Capture Notes rehydration only for actual screen recomposes.
        BaseAppScreen owns the single focus capture/restore pair, including Media
        rules and whole-screen fallback. Do not queue a second focus restore here.
        Plain repaints must not capture or schedule Notes widget-state restoration."""
        if recompose:
            self._commit_library_note_widgets_before_recompose()
        restore = self._capture_library_notes_recompose_state() if recompose else None
        if restore is not None:
            self._notes_state.recompose_generation += 1
            restore = dataclasses.replace(
                restore,
                recompose_generation=self._notes_state.recompose_generation,
            )
        self._apply_library_notes_footer_context()
        result = super().refresh(
            *regions,
            repaint=repaint,
            layout=layout,
            recompose=recompose,
        )
        if restore is not None:
            self.call_after_refresh(
                self._rehydrate_library_notes_after_recompose, restore
            )
        elif recompose:
            self.call_after_refresh(self._apply_library_notes_stage_visibility)
            self.call_after_refresh(self._apply_library_notes_footer_context)
        return result

    def _focus_identity_for_recompose(self) -> str | None:
        """Media's capture rules; the base rule everywhere else (task-31946).

        The Media route refuses to record a reader pane GRIP -- Textual
        dumps focus there by accident on exactly this recompose, so
        restoring it would perpetuate the bug PR F fixed rather than undo
        it. Every other route has no such trap and uses the base's plain
        "the focused widget's id" rule.
        """
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            return self._capture_library_media_focus_identity()
        return super()._focus_identity_for_recompose()

    def restore_focus_after_recompose(self, previous: str | None) -> None:
        """Restore focus once per recompose, with Media restore before generic fallback.
        Stand down only for a one-shot channel that will actually land focus: a foreign
        focus change would revoke its receipt. Rail-only, rowless Conversations, and
        empty Media still need fallback; other empty lists focus their filter input."""
        if self._library_focus_channel_owns_this_window():
            return
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            self._restore_library_media_focus(previous)
        super().restore_focus_after_recompose(previous)

    def _library_focus_channel_owns_this_window(self) -> bool:
        """Whether an armed one-shot channel will land focus itself.

        The two ``return``s below mirror the two at the TOP of
        ``_focus_library_list_entry`` -- deliberately those two and no
        more, so this predicate stays a statement about which route/stage
        the channel serves and never a second copy of its row-picking
        logic. The one exception is Media's EMPTY page (Qodo #2483): its
        recovery controls are conditional, and a filter MISS composes none
        of them, so the channel lands nothing there -- the shared
        ``_library_media_empty_list_fallback_target`` answers that for
        both this predicate and the channel itself rather than being
        re-derived here. One no-landing case is still knowingly left
        inside "owns": a pending Find focus whose input never mounts --
        narrow, and it ends at ``None`` rather than at a wrong widget.

        task-32213: that empty page now keeps its toolbar, so the shared
        helper always finds a target for Media and the ``is None`` leg
        below no longer fires for a filter miss. It is kept because the
        helper still answers ``None`` for the states that compose no
        enabled control at all (an open type/sort chooser replaces the
        toolbar row), and because both readers must keep agreeing.
        """
        if self._media_state.find_focus_pending:
            return True
        if not self._library_pending_list_entry_focus:
            return False
        if self._library_emergency_stage == "rail-only":
            return False
        row_class = _LIBRARY_LIST_ROW_CLASS_BY_ROW_ID.get(
            self._library_selected_row_id
        )
        if row_class is None:
            return False
        if (
            row_class == "library-media-row"
            and not self.query(f".{row_class}")
            and self._library_media_empty_list_fallback_target() is None
        ):
            return False
        return True

    async def action_library_notes_new(self) -> None:
        return await self._notes_controller.action_library_notes_new()

    def action_library_notes_focus_filter(self) -> None:
        return self._notes_controller.action_library_notes_focus_filter()

    def _show_library_note_shortcut_refusal(self, message: str) -> None:
        return self._notes_controller._show_library_note_shortcut_refusal(message)

    async def action_library_notes_save(self) -> None:
        """Request an immediate save or explain the owning safety gate."""
        if self._notes_state.select_mode:
            self._show_library_note_shortcut_refusal(
                "Save unavailable — finish bulk selection first."
            )
            return
        snapshot = self._library_note_session.snapshot
        if snapshot is None:
            return
        if (
            self._notes_state.confirming_delete
            or self._library_note_session.destructive_running
            or self._library_note_session.destructive_admission is not None
        ):
            self._show_library_note_shortcut_refusal(
                "Save locked — finish or cancel the destructive action."
            )
            if self._notes_state.confirming_delete:
                self._focus_library_note_control("#library-note-delete-cancel")
            return
        if (
            snapshot.in_conflict
            or self._library_note_session.conflict_resolution_running
        ):
            self._show_library_note_shortcut_refusal(
                "Save locked — resolve the note conflict below."
            )
            self._focus_library_note_conflict_callout()
            return
        self._invalidate_library_note_autosave()
        await self._save_library_note(explicit=True)

    async def action_library_notes_escape(self) -> None:
        return await self._notes_controller.action_library_notes_escape()

    def _register_footer_shortcuts(self) -> None:
        """Register Library shortcuts via BaseAppScreen's persisting API.

        Persistence matters here: the destination-switch failsafes call
        ``screen.refresh(recompose=True)``, which replaces the footer widget;
        the registration must survive that. This method is ALSO called from
        ``compose_content`` on every recompose (not just at the transition
        call sites elsewhere in this class), so a sub-view entered from ANY
        of the editor/viewer's several call sites (see
        ``_library_note_editor_active`` etc.) can never leave the footer
        stale the way an easily-missed per-call-site registration could.
        """
        shortcuts = self._library_notes_footer_shortcuts()
        self.register_footer_shortcuts(source="library", shortcuts=shortcuts)
        for bar in self.query(LibraryEmergencyReturn):
            self._sync_library_emergency_return(bar)

    def _sync_library_emergency_guard_presentation(self) -> None:
        """Repaint guarded return truth after an in-place state transition."""
        if (
            getattr(self, "_is_mounted", False)
            and self._library_emergency_stage == "canvas-only"
        ):
            self._register_footer_shortcuts()

    def on_key(self, event: Key) -> None:
        """Handle guarded search, landing actions and list navigation.

        F-012/task-1715: ``/`` uses a screen handler, not a palette Binding.
        Input/TextArea keep printable keys; LibraryRailSearchInput re-arms
        its own query when focused.

        task-2237/3302: ``i`` opens Ingest from any canvas; ``n`` creates a
        note from the landing only. Both use the dirty-edit row-switch guard.

        task-2856: Up/Down move only focused list rows, leaving rail/forms/palette
        untouched; any key disarms pending entry focus before the text-field return.
        Descendant focus handles mouse interaction; timers cover idle requests.
        """
        emergency_tab = bool(
            event.key in {"tab", "shift+tab", "backtab"}
            and self._library_emergency_stage == "canvas-only"
            and self._library_emergency_restore_receipt is not None
        )
        if emergency_tab:
            # task-32052 AC#3 (fix round 1): through
            # ``_move_library_screen_focus``, not the bare
            # ``Screen.focus_next``/``focus_previous``. This branch handles
            # Tab itself and stops the event, so ``action_focus_next`` never
            # runs here -- and the bare calls default to selector "*", which
            # walks the nav bar. The narrow-terminal emergency stage is a
            # Library canvas like any other.
            if event.key == "tab":
                focused = self._move_library_screen_focus(1)
            else:
                owner = self._library_entry_canvas_owner()
                route_focus_chain = (
                    [
                        widget
                        for widget in self.focus_chain
                        if widget is not owner and owner in widget.ancestors_with_self
                    ]
                    if owner is not None
                    else []
                )
                if route_focus_chain and self.focused is route_focus_chain[0]:
                    try:
                        focused = self.query_one(
                            "#library-emergency-return", LibraryEmergencyReturn
                        )
                    except (NoMatches, QueryError):
                        focused = None
                    else:
                        focused.focus()
                else:
                    focused = self._move_library_screen_focus(-1)
            self._advance_library_ordinary_emergency_user_interaction(focused)
        self._mark_library_notes_user_interaction()
        if self._library_pending_list_entry_focus:
            self._disarm_library_list_entry_focus()
        if emergency_tab:
            event.stop()
            event.prevent_default()
            return
        # task-32132 AC#3: while the note-delete confirmation is open, Tab /
        # Shift+Tab must stay inside it -- the natural focus chain used to
        # walk straight out into the Info pane's other Danger-section
        # buttons (Copy/Export/the Delete button itself) and beyond, into a
        # pane grip, with the prompt still open and no visible cue why.
        if (
            self._notes_state.confirming_delete
            and event.key in ("tab", "shift+tab", "backtab")
        ):
            try:
                cancel_button = self.query_one("#library-note-delete-cancel", Button)
                confirm_button = self.query_one("#library-note-delete-confirm", Button)
            except (NoMatches, QueryError):
                pass
            else:
                (
                    confirm_button if self.focused is cancel_button else cancel_button
                ).focus()
                event.stop()
                event.prevent_default()
                return
        if isinstance(self.focused, (Input, TextArea)):
            return
        if event.key in ("up", "down") and _move_library_list_row_focus(
            self.focused, event.key
        ):
            event.stop()
            event.prevent_default()
            return
        is_slash = (
            event.key in {"/", "slash"} or getattr(event, "character", None) == "/"
        )
        if is_slash:
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                if self._conversations_state.reader_layout.items_open:
                    try:
                        self.query_one("#library-conversations-filter", Input).focus()
                    except (NoMatches, QueryError):
                        return
                    event.stop()
                    event.prevent_default()
                return
            # task-32046: on any list canvas that owns its own filter input,
            # `/` focuses THAT filter -- the footer's "/ focus search" then
            # lands where the user is looking, not on the rail's global
            # search two panes away (the lead critique-#7 P1). Mirrors the
            # Conversations branch above and the notes action below; Notes
            # keeps its own check_action-gated path (it adds scroll-visible
            # and a navigator-region gate). A lookup miss -- or an absent
            # widget, e.g. the Media viewer sub-view where no list filter is
            # mounted -- falls through to the rail-search grab, the prior
            # behaviour.
            canvas_filter = _LIBRARY_SLASH_CANVAS_FILTERS.get(
                self._library_selected_row_id
            )
            if canvas_filter is not None:
                try:
                    self.query_one(canvas_filter, Input).focus()
                except (NoMatches, QueryError):
                    pass
                else:
                    event.stop()
                    event.prevent_default()
                    return
            # task-3315: this screen-wide rail-search grab predates the
            # notes-adaptive "/" binding (library_notes_focus_filter, PR
            # #1439) and runs BEFORE bindings dispatch, so the notes-scoped
            # "/" could never fire -- inside the Notes Navigator with a
            # non-text control focused, "/" jumped to the rail search
            # instead of the notes filter (reproduced failing at dev base
            # ebeae1440). Defer to the binding's own check_action gate so
            # the precedence lives in exactly one place.
            if self.check_action("library_notes_focus_filter", ()):
                self.action_library_notes_focus_filter()
                event.stop()
                event.prevent_default()
                return
            if self._library_lifecycle in (
                LibraryLifecycle.UNKNOWN,
                LibraryLifecycle.STARTER,
            ):
                return
            rail = self._active_library_rail()
            if rail is None:
                return
            try:
                rail.query_one("#library-search-input", Input).focus()
            except (NoMatches, QueryError):
                return
            event.stop()
            event.prevent_default()
            return
        # task-3302 (MI-04): `i` (import content) works from ANY Library
        # canvas, not just the landing -- there was no keyboard route into
        # Ingest once a row was selected. Still never fires while an
        # Input/TextArea owns focus (the early return above), and it rides
        # the same guarded row switch as the rail rows, so dirty
        # note/prompt/skill edits still flush-or-veto the jump. A no-op
        # while Ingest already owns the canvas.
        if event.key == "i":
            if self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA:
                return
            self.run_worker(
                self._select_library_rail_row(LIBRARY_ROW_INGEST_MEDIA),
                exclusive=True,
                group="library_rail_row_switch",
            )
            event.stop()
            event.prevent_default()
            return
        # `n` (new note) accelerator (task-2237), landing-scoped by design --
        # unlike `i`, it opens a CREATE editor, which would be a surprising
        # context loss from a browse canvas OTHER than Notes. task-32138
        # widened it to also fire wherever ctrl+n already does (inside the
        # Notes workflow itself): the two keys share ``library_notes_new``'s
        # ``check_action`` gate now, rather than the landing check here and
        # a separate ctrl+n-only Binding disagreeing about where New note
        # works.
        if event.key != "n":
            return
        if not self.check_action("library_notes_new", ()):
            return
        self.run_worker(
            self.action_library_notes_new(),
            exclusive=True,
            group="library_rail_row_switch",
        )
        event.stop()
        event.prevent_default()

    def action_focus_next_workbench_pane(self) -> None:
        """F6: move focus to the next Library workbench pane (task-2237).

        Previously the screen defined no pane targets, so the app's global
        F6 dead-ended in a "no focus target" notification here. The rail's
        search box is the rail target; on the landing the hub's first
        action is the canvas target (other canvases mount their own focus
        order and are skipped when the target is absent).
        """
        focus_relative_workbench_pane(
            self,
            self._library_workbench_focus_targets(),
            direction=1,
        )

    #: task-32052 AC#3: the Tab region. ``#screen-content`` is
    #: ``BaseAppScreen.compose``'s wrapper around every screen's own content
    #: -- everything except the nav bar above it and the footer below.
    _LIBRARY_TAB_REGION = "#screen-content, #screen-content *"

    def action_focus_next(self) -> None:
        """Tab: move focus to the next control inside the Library content.

        task-32052 AC#3: the inherited ``app.focus_next`` walks the whole
        screen focus chain, which starts with the fifteen nav-bar buttons --
        so one Tab from the New-note canvas landed on "Home", where Enter
        left Library. Tab now cycles within ``#screen-content``; the nav bar
        keeps its own documented keys (Ctrl+digit / F-keys) and stays
        traversable once focus is genuinely in it (mirrors ``ChatScreen``).

        task-32106 (PR #2571 re-review, NEW-1): the note editor's fields
        carry a PRIORITY ``tab`` binding, and ``App._check_bindings``
        consumes a priority key before ``on_key`` ever runs -- so for a
        focused note field this action, not ``on_key``, is the whole Tab
        path. ``on_key``'s preamble marks the keystroke as a Notes user
        interaction, which is the only keyboard site that clears
        ``resize_settling``; without it the first Tab after a terminal
        resize was classified programmatic in ``on_descendant_focus``.
        Marking it here covers both the field bindings and this screen's
        own (``on_key`` marks it a second time for non-priority keys, and
        marking twice is a no-op).
        """
        self._mark_library_notes_user_interaction()
        self._move_library_screen_focus(1)

    def action_focus_previous(self) -> None:
        """Shift+Tab: the reverse of ``action_focus_next``."""
        self._mark_library_notes_user_interaction()
        self._move_library_screen_focus(-1)

    #: task-32246: the Tab region INSIDE an open note editor. The body is the
    #: last focusable of ``#screen-content``, so one Tab out of it used to
    #: wrap the whole cycle round to that region's first control --
    #: ``#library-notes-source-database``, the browse chrome's source switch
    #: above the editor. Live at dev 4a14b3f36f: the body lost its focus
    #: border and "TAILEDIT" typed straight after vanished, because a Button
    #: swallows printable keys; the switch's focus treatment is the same
    #: background-and-bold it already wears for ``-selected``, which is why
    #: the pane read as having nothing focused at all. Tab now closes inside
    #: the editor the way it already closes inside the delete prompt
    #: (``on_key``) and inside ``#screen-content`` (task-32052). F6 and
    #: Escape remain the ways out, as the guide says.
    _LIBRARY_NOTE_EDITOR_TAB_REGION = (
        "#library-note-work-pane, #library-note-work-pane *"
    )

    def _library_note_editor_owns_tab(self, focused: Widget | None) -> bool:
        """Whether Tab should cycle inside the open note editor."""
        if focused is None or self._notes_state.view != "editor":
            return False
        return any(
            node.id == "library-note-work-pane"
            for node in focused.ancestors_with_self
        )

    def _move_library_screen_focus(self, direction: int) -> Widget | None:
        """Cycle focus within the Library content, or app-wide from chrome.

        Returns the newly focused widget, which the emergency-stage Tab path
        in ``on_key`` hands to
        ``_advance_library_ordinary_emergency_user_interaction``.
        """
        focused = self.focused
        if self._library_note_editor_owns_tab(focused):
            selector = self._LIBRARY_NOTE_EDITOR_TAB_REGION
            if direction >= 0:
                return self.focus_next(selector)
            return self.focus_previous(selector)
        inside = focused is not None and any(
            node.id == "screen-content" for node in focused.ancestors
        )
        selector = self._LIBRARY_TAB_REGION if inside or focused is None else "*"
        if direction >= 0:
            return self.focus_next(selector)
        return self.focus_previous(selector)

    def action_focus_previous_workbench_pane(self) -> None:
        """Shift+F6: move focus to the previous Library workbench pane."""
        focus_relative_workbench_pane(
            self,
            self._library_workbench_focus_targets(),
            direction=-1,
        )

    def _library_workbench_focus_targets(
        self,
    ) -> tuple[WorkbenchPaneTarget, ...]:
        """Return the active destination's stable global focus regions."""
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            return self._MEDIA_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            return self._COLLECTIONS_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            return self._CONVERSATION_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES:
            return self._NOTES_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            return self._PROMPTS_WORKBENCH_FOCUS_TARGETS
        if self._library_selected_row_id in {
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_CREATE_SKILL,
        }:
            return self._SKILLS_WORKBENCH_FOCUS_TARGETS
        return self._WORKBENCH_FOCUS_TARGETS

    def refresh_notes_sync_runtime(self) -> None:
        """Project the app-owned runtime after detached startup settles."""

        self._library_notes_sync_controller.refresh_roots()
        if (
            self.is_mounted
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
            and self._notes_state.view == "list"
        ):
            # This callback is scheduled from ``on_mount``/``on_screen_resume``
            # and may run while the retained Notes canvas is still mounting.
            # Its roots refresh is opportunistic; the ordinary source snapshot
            # reconciliation owns the authoritative projection.  Falling back
            # to a whole-screen recompose here tears down the just-mounted
            # shell and races that reconciliation.
            _sync_library_canvas(self, "notes", allow_screen_fallback=False)

    def on_screen_suspend(self) -> None:
        """Quiesce visit-scoped work while this screen is covered.

        TASK-31521: the library route is reusable (`ScreenRoute.reusable`),
        so navigation SUSPENDS this screen instead of unmounting it -- and
        Textual only auto-cancels timers on a real removal, never on
        suspend. Every armed debounce timer would otherwise fire against
        the hidden screen (three of them relied entirely on the
        real-unmount auto-cancel and had no explicit stop anywhere).

        Deliberately NOT done here: cache wipes, generation bumps, or
        authority-flag flips. Those exist in ``on_unmount`` because a
        FRESH instance must not trust a dead visit's state; a suspended
        instance is live, and a background result landing on it while
        hidden simply means fresher data at resume. Rejecting in-flight
        work at suspend would re-create the stranded-"Loading" class this
        design avoids.

        No super() call -- Textual's dispatcher invokes every handler
        along the MRO separately for this event (the on_mount contract).
        """
        self._library_screen_suspended = True
        self._unavailable_navigation.clear_character_return(self)
        self._disarm_library_list_entry_focus()
        self._stop_library_media_selection_debounce()
        self._stop_library_media_filter_timer()
        for attr in ("_library_source_snapshot_timeout_timer",):
            timer = getattr(self, attr, None)
            if timer is not None:
                timer.stop()
                setattr(self, attr, None)
        # The ingest path-debounce timer lives on ``_ingest_state``, not as a
        # flat screen attribute, so the string loop above cannot reach it --
        # a ``getattr`` for the old flat name silently returns None.
        ingest_timer = self._ingest_state.path_debounce_timer
        if ingest_timer is not None:
            ingest_timer.stop()
            self._ingest_state.path_debounce_timer = None
        # (wave-6 task 3) The prompts search-debounce timer moved to
        # ``_prompts_state`` for the same reason, and left the string loop
        # above for the same explicit block the ingest timer already uses.
        prompts_timer = self._prompts_state.debounce_timer
        if prompts_timer is not None:
            prompts_timer.stop()
            self._prompts_state.debounce_timer = None
        # (wave-8 task 3) The notes autosave timer moved to ``_notes_state``
        # for the same reason, and left the string loop above for the same
        # explicit block the ingest and prompts timers already use.
        notes_timer = self._notes_state.autosave_timer
        if notes_timer is not None:
            notes_timer.stop()
            self._notes_state.autosave_timer = None

    def on_screen_resume(self) -> None:
        """Refresh every visible surface for this visit (initial and repeat).

        TASK-31521: the ONLY dispatch seam for per-visit surface refresh --
        Textual posts ``ScreenResume`` on the initial push too, so ``on_mount``
        must not also dispatch (Qodo #2402 finding 4: worker exclusivity
        cancels a superseded handle but cannot undo synchronous provider
        work already running on its thread).
        """
        self._library_screen_suspended = False
        # task-32039 AC#1: a new visit's auto-refresh (below) re-issues the
        # same scope; the fault episode must not read that as a consecutive
        # Retry and prepend the reopen recovery step on a first failure.
        self._library_media_browse_controller.state.clear_fault_episode()
        # task-32039 AC#2: the select-mode bulk-Analyze reason is memoised for
        # the whole select-mode session (resolving it shells out to the
        # keychain). A provider configured mid-session (while Library was
        # suspended) leaves that memo stale, so drop it here -- the next
        # canvas sync re-resolves it exactly once.
        self._media_state.analyze_reason_cache = None
        self.call_after_refresh(self._navigation_controller.present_pending_repair)
        self.call_after_refresh(self.refresh_notes_sync_runtime)
        if getattr(self, "_prepared_library_inspection_entry", None) is not None:
            from ..Library_Modules.library_inspection_admission import (
                consume_prepared_character_inspection,
            )

            self.run_worker(
                consume_prepared_character_inspection(self),
                exclusive=True,
                group="library_nav_character",
            )
        self._refresh_library_visit_surfaces()

    def _stop_library_media_selection_debounce(self) -> None:
        """Stop the media-selection settle timer without dispatching."""
        if self._media_state.selection_timer is not None:
            self._media_state.selection_timer.stop()
            self._media_state.selection_timer = None

    def _refresh_library_visit_surfaces(self) -> None:
        """Refresh entry/resume data, retaining each surface's admission gates.
        Prompt mutations own settlement reads; modal return must not compete.
        """
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and self._pending_library_source_open is None
            and self._pending_library_character_navigation is None
            and self._library_unavailable_browse_scope is None
            and getattr(self, "_prepared_library_inspection_entry", None) is None
        ):
            self._start_library_conversation_page_request(
                self._conversations_state.requested_page,
                self._conversations_state.requested_query,
            )
        elif (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and self._pending_library_source_open is None
            and self._pending_library_character_navigation is None
            and self._library_unavailable_browse_scope is not None
        ):
            self._unavailable_navigation._start_library_unavailable_conversation_page_request(
                self,
                self._conversations_state.requested_page,
                self._conversations_state.requested_query,
            )
        if (
            self._library_media_list_surface_active(require_focus=False)
            and self._pending_library_source_open is None
        ):
            self._request_library_media_browse(
                self._library_media_browse_controller.state.mutation_refresh_scope,
                focus_identity=None,
            )
            self._request_library_media_facets()
            # task-28245: NO auto-resume kick here, deliberately. The first
            # dispatch runs during boot when Library is the initial tab, and
            # the worker's lazy review-set imports raced the _ui_ready module
            # census on slow runners (977 > 972, flaky Perf Guard). The
            # rail-select seam is the explicit user gesture that resumes a
            # set (AC#3's cold-start concern is structurally avoided there).
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._media_state.view == "trash"
            and self._pending_library_source_open is None
        ):
            trash = self._library_media_trash_browse_controller
            if not self._library_visit_entered:
                # First visit: pristine entry state, entry focus.
                self._media_state.trash_query_draft = ""
                self._media_state.trash_input_error = ""
                self._media_state.trash_type_choices_visible = False
                trash.invalidate()
                trash.state = MediaTrashBrowseState()
                trash.request(
                    MediaTrashScope(),
                    origin="entry",
                    focus_identity="#library-media-trash-row-0",
                )
            else:
                # Repeat visit: refresh the scope the user was looking at
                # WITHOUT resetting their filter draft or state -- the live
                # instance's trash view is current context, not stale debris.
                scope = (
                    trash.state.applied_result.scope
                    if trash.state.applied_result is not None
                    else trash.state.requested_scope
                )
                trash.request(
                    scope or MediaTrashScope(),
                    origin="entry",
                    focus_identity=None,
                )
        # task-31632 AC#2: returning to Library is the source snapshot's
        # automatic retry -- one per return, no timer. A snapshot that missed
        # its DEADLINE is exactly the case a later attempt may beat, so it
        # keeps this refresh; a HARD failure does not re-run itself (its
        # callout carries the Retry, in reach, and a failing read is not
        # worth the deadline again on every visit).
        source_failure = self._library_source_load_failure()
        if not self._prompts_state.mutation_in_flight and (
            source_failure is None or source_failure.severity != "error"
        ):
            self._refresh_local_source_snapshot()
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            self._request_library_notes_tree_initial_load()
        if (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT)
            and self._prompts_state.view == "list"
            and not self._prompts_state.mutation_in_flight
        ):
            self._request_library_prompts_browse(
                self._library_prompt_browse_controller.scope,
                focus_identity=None,
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._skills_state.view == "list"
        ):
            self._request_library_skills_browse(
                self._library_skills_browse_controller.mutation_refresh_scope,
                focus_identity=None,
            )
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self.run_worker(
                self._load_library_collections_capture_entry(),
                exclusive=True,
                group="library_collections_capture_entry",
            )
        if (
            self._library_ingest_suspended_activity
            and self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA
        ):
            # One reconciliation pass for registry events that were gated
            # while suspended, instead of N wasted hidden-screen refreshes.
            # Regions AND footer shortcuts together -- the visible handler
            # updates them as a pair, and hidden-time state changes (a job
            # becoming retryable) change the shortcut set too (Qodo #2414
            # finding 2).
            self._update_library_ingest_dynamic_regions()
            shortcuts = self._library_ingest_shortcuts_for_current_state()
            registration = ("library", tuple(shortcuts))
            if self._footer_shortcut_registration != registration:
                self.register_footer_shortcuts(
                    source="library", shortcuts=shortcuts
                )
        self._library_ingest_suspended_activity = False
        self._library_visit_entered = True

    def on_mount(self) -> None:
        """Populate the Library on entry, rendering instantly from cache.

        The constructor has already seeded any valid, recent app-scoped
        snapshot before first compose. Mount arms the snapshot-timeout
        failsafe and unconditionally kicks ``_refresh_local_source_snapshot``
        to reconcile against the DB. It also seeds the ingest registry listener
        and runs deferred deep-link loads (collections / note editor / media
        viewer) that ``apply_navigation_context`` could not run before mount.
        """
        self._conversations_state.reader_mounted_authority = True
        self._media_state.trash_mounted_authority = True
        self._register_footer_shortcuts()
        self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
        self.call_after_refresh(self._sync_library_ordinary_rail_width_contract)
        self.call_after_refresh(self._present_library_skills_import_choice_if_needed)
        self.call_after_refresh(self._navigation_controller.present_pending_repair)
        if (
            self._library_new_profile_admission
            and not self._library_lifecycle_was_stored
        ):
            self._queue_library_lifecycle_persistence(LibraryLifecycle.UNKNOWN)
        # No super().on_mount(): the dispatcher already invokes
        # BaseAppScreen.on_mount separately for this Mount event.
        self.call_after_refresh(self._update_library_notes_responsive_state)
        # refresh_notes_sync_runtime is dispatched from on_screen_resume,
        # which also fires on the initial push (TASK-31521 single-seam).
        self._load_library_ingest_options_from_config()
        # Handle retained so on_screen_suspend can stop it (Qodo #2414
        # finding 3): un-retained, this 5s failsafe survived suspension and
        # applied an error snapshot to the hidden screen. Resume's own
        # snapshot re-kick owns freshness after a suspend.
        self._library_source_snapshot_timeout_timer = self.set_timer(
            LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS,
            self._apply_source_snapshot_timeout,
        )
        # TASK-31521: the per-visit surface re-kicks (conversations, media,
        # media trash, source snapshot, notes tree, prompts, skills,
        # collections) moved to `_refresh_library_visit_surfaces`, dispatched
        # from `on_screen_resume` ONLY. Textual posts ScreenResume on the
        # initial push too, so a mount-time dispatch would double-run them on
        # every first visit (the exact Qodo #2402 finding-4 bug on Home) --
        # and with the library route reusable, resume is the seam that fires
        # per visit while this method fires once per app run.
        registry = self._library_ingest_registry()
        if registry is not None:
            counts_fn = getattr(registry, "counts", None)
            if callable(counts_fn):
                # Seed from whatever the registry already knows so a
                # freshly composed screen doesn't treat jobs that finished
                # during a previous Library visit as a brand-new
                # done-transition and fire a redundant snapshot refresh.
                self._ingest_state.last_done_count = counts_fn().get("done", 0)
            registry.add_listener(self._handle_library_ingest_registry_changed)
            add_progress_listener = getattr(registry, "add_progress_listener", None)
            if callable(add_progress_listener):
                add_progress_listener(self._handle_library_ingest_progress_changed)
        if (
            self._notes_state.view == "editor"
            and self._notes_state.selected_note_id
            and self._library_note_detail is None
        ):
            # Mirrors the collections case above: a note_id deep-link applied
            # before mount cannot run_worker yet, so the detail fetch is
            # deferred to here once the canvas has actually been composed.
            self.run_worker(
                self._refresh_library_note_detail(
                    self._notes_state.selected_note_id,
                    entry_origin=True,
                ),
                exclusive=True,
                group="library_note_detail",
            )
        if (
            self._media_state.view == "viewer"
            and self._media_state.selected_media_id
            and self._media_state.detail is None
        ):
            # Cross-visit state restore (``restore_state``) sets the media
            # viewer's selection/view attrs before mount the same way a
            # note_id nav-context deep-link does above, but -- unlike that
            # case -- nothing else pre-mount kicks off the detail fetch:
            # ``handle_library_media_row`` (the only other caller of
            # ``_refresh_library_media_detail``) only runs from a live row
            # click. Without this, a restored viewer would render its
            # "Loading media…" placeholder forever. Deleted-record safety
            # uses the permanent Reader's explicit error + Retry surface,
            # matching a live row whose backing record vanished before open.
            if self._media_state.reader_session.pending_request is None:
                reader_identity = self._library_media_reader_identity(
                    self._media_state.selected_media_id
                )
                if reader_identity is not None:
                    canonical_id, backing_id = reader_identity
                    self._media_state.reader_session = begin_selection(
                        self._media_state.reader_session,
                        canonical_id,
                        backing_id,
                        self._media_state.selected_media_id,
                        immediate=True,
                    )
            self.run_worker(
                self._refresh_library_media_detail(
                    self._media_state.selected_media_id,
                    entry_origin=True,
                ),
                exclusive=True,
                group="library_media_detail",
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT
            and self._export_state.counts is None
        ):
            # Same restored-placeholder class as the media viewer/notes
            # editor above: a cross-visit ``restore_state`` (or a tab
            # round-trip whose ``save_state`` persisted
            # ``_library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT``)
            # lands a fresh instance on the export canvas with
            # ``_export_state.counts is None`` -> the scope line renders
            # "Counting…" and Export stays disabled. But the counts worker
            # is only kicked from the two LIVE entry points
            # (``_select_library_rail_row`` and
            # ``_open_library_export_canvas``), never from a restore --
            # so without this re-kick the form would stay stuck
            # "Counting…" with Export permanently disabled until the user
            # clicked another rail row and back. Mirrors
            # ``_select_library_rail_row``'s own post-recompose kick. The
            # ``is None`` guard keeps this from redundantly re-running when
            # counts already landed (they never survive a restore today --
            # ``save_state`` doesn't persist them -- but the guard makes
            # the intent explicit and is cheap insurance).
            self._start_library_export_counts_worker()
        if self._pending_library_source_open is not None:
            self.run_worker(
                self._open_pending_library_source(),
                exclusive=True,
                group="library_nav_open_source",
            )
        if self._pending_library_character_navigation is not None:
            self.run_worker(
                self._unavailable_navigation._open_pending_library_character_navigation(self, ),
                exclusive=True,
                group="library_nav_character",
            )
        pending_entry_focus_row = self._pending_library_entry_focus_row
        self._pending_library_entry_focus_row = None
        if pending_entry_focus_row:
            # task-32245: a pre-mount navigation context selected this row
            # but could not arm its entry focus; the canvas exists now.
            self._arm_library_row_entry_focus(pending_entry_focus_row)

    async def on_unmount(self) -> None:
        """Unregister the ingest registry listener registered in ``on_mount``.

        ``on_unmount`` (not ``on_screen_suspend``) is the correct pairing:
        listener add/remove must be symmetric with the mount/unmount
        cycle, not the temporary suspend/resume pair a screen gets while
        merely covered by another screen on the stack (suspend does not
        tear down this screen, so pairing removal with it would silently
        stop live updates while
        still fully composed and, per the plan brief, still able to
        resume). The registry itself is a plain in-memory object owned by
        the app, not this screen, and can keep firing mutations long after
        this screen is gone -- the listener body also guards on
        ``self.is_mounted`` (belt and braces, matching this file's
        established convention elsewhere), though note that in this
        Textual version ``is_mounted`` tracks "has been mounted at least
        once" rather than "currently mounted" (it is never reset back to
        ``False`` after removal) -- so this call is what actually closes
        the window, not the guard.
        """
        if self._media_state.analyze_running:
            # task-28007 AC#4: this screen owns the bulk-Analyze worker, so
            # Textual cancels it here (Widget._on_unmount -> cancel_node),
            # and navigating back builds a NEW LibraryScreen, so the
            # receipt's five fields die with this instance. Say where it
            # stopped BEFORE any await below, while the counts are still
            # true -- the cancelled worker cannot resume until this handler
            # yields. Finished items persisted; the rest simply never ran,
            # and a fresh run skips what is already analyzed.
            #
            # (task-28007 Task 3, N1) ``_library_media_analyze_total`` is
            # only stamped once the AC#3 partition pass resolves -- an
            # unmount that lands DURING that pass (still awaiting
            # ``_library_media_unanalyzed_ids``) sees total == 0 and would
            # otherwise notify the nonsensical "stopped at 0 of 0".
            # (fix round 1, I-3) The recovery pointer names the surface the
            # interrupted run actually started from -- a run started from
            # the Import queue's "Analyze N skipped" has no "Select ▸
            # Analyze" to reopen; that copy stays for the Media-canvas
            # (Select mode) origin only.
            from_import = (
                getattr(self._media_state, "analyze_origin", _ANALYZE_ORIGIN_MEDIA)
                == _ANALYZE_ORIGIN_IMPORT
            )
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify) and self._media_state.analyze_total == 0:
                notify(
                    "Analysis stopped before it started",
                    severity="warning",
                )
            elif callable(notify) and from_import:
                notify(
                    f"Analysis stopped at {self._media_state.analyze_done} "
                    f"of {self._media_state.analyze_total} · reopen the "
                    "import run and press Analyze N skipped to continue",
                    severity="warning",
                )
            elif callable(notify):
                notify(
                    f"Analysis stopped at {self._media_state.analyze_done} "
                    f"of {self._media_state.analyze_total} · reopen "
                    "Select ▸ Analyze to continue; finished items are skipped",
                    severity="warning",
                )
        self._disarm_library_list_entry_focus()
        self._invalidate_library_notes_tree_for_unmount()
        self._conversations_state.reader_mounted_authority = False
        self._invalidate_library_conversation_reader_authority()
        self._library_notes_sync_controller.invalidate_for_remount()
        # A local thread read may outlive this screen. Revoke apply authority
        # before any awaited shutdown work can yield back to its completion.
        self._library_onboarding_generation += 1
        self._conversations_state.request_generation += 1
        self._invalidate_library_prompts_browse()
        self._library_skills_browse_controller.invalidate()
        self._prompts_controller._invalidate_library_prompt_detail_generation()
        self._media_state.lifecycle_generation += 1
        self._media_state.return_settlement = None
        self._media_state.last_settlement_outcome = None
        self._media_state.current_owner = None
        self._media_state.geometry_floor_owner_identity = None
        self._media_state.geometry_floor = 0
        self._media_state.trash_mounted_authority = False
        self._library_media_browse_controller.invalidate()
        self._library_media_trash_browse_controller.invalidate()
        if self._library_collections_capture_controller is not None:
            self._library_collections_capture_controller.unmount()
        lifecycle_worker = self._library_lifecycle_persist_worker
        if lifecycle_worker is not None and not lifecycle_worker.is_finished:
            try:
                await lifecycle_worker.wait()
            except Exception:
                logger.warning(
                    "Pending Library lifecycle write failed during unmount."
                )
        if self._library_lifecycle_pending_persist is not None:
            await self._drain_library_lifecycle_persistence()
        # TASK-22210: the last captured reading position must survive
        # teardown. Await the drainer, then re-queue a value it may have
        # been cancelled under mid-write (the abandoned thread may or may
        # not have committed; the upsert is idempotent, so rewriting the
        # ambiguous value is harmless), then drain any residue inline.
        progress_worker = self._media_state.progress_write_worker
        if progress_worker is not None and not progress_worker.is_finished:
            try:
                await progress_worker.wait()
            except Exception:
                logger.opt(exception=True).warning(
                    "Pending Library media progress write failed during unmount."
                )
        inflight = self._media_state.progress_inflight_write
        if inflight is not None:
            self._media_state.progress_inflight_write = None
            self._media_state.progress_pending_writes.setdefault(
                inflight[0], (inflight[1], inflight[2])
            )
        if self._media_state.progress_pending_writes:
            await self._drain_library_media_progress_writes()
        self._library_note_import_controller.cancel()
        workspace = self._notes_state.file_notes_workspace
        if workspace is not None:
            await workspace.shutdown()
        self._invalidate_library_note_autosave()
        self._library_prompt_collections_controller.invalidate()
        self._clear_library_prompt_selection(announce=False)
        self._prompts_state.mutation_disabled_states.clear()
        self._invalidate_library_external_submission()
        # No super().on_unmount(): the dispatcher already invokes
        # BaseAppScreen.on_unmount separately for this Unmount event (TASK-31418).
        registry = self._library_ingest_registry()
        if registry is not None:
            registry.remove_listener(self._handle_library_ingest_registry_changed)
            remove_progress_listener = getattr(
                registry, "remove_progress_listener", None
            )
            if callable(remove_progress_listener):
                remove_progress_listener(self._handle_library_ingest_progress_changed)

    @staticmethod
    def _restore_library_prompts_scope(state: Mapping[str, Any]) -> PromptBrowseScope:
        from ..Library_Modules.library_prompts_controller import (
            LibraryPromptsController,
        )

        return LibraryPromptsController._restore_library_prompts_scope(state)

    @staticmethod
    def _restore_library_skills_scope(state: Mapping[str, Any]) -> SkillBrowseScope:
        from ..Library_Modules.library_skills_controller import LibrarySkillsController

        return LibrarySkillsController._restore_library_skills_scope(state)

    @staticmethod
    def _restore_library_collections_page(state: Mapping[str, Any]) -> int:
        from ..Library_Modules.library_collections_controller import (
            LibraryCollectionsController,
        )

        return LibraryCollectionsController._restore_library_collections_page(state)

    def save_state(self) -> dict[str, Any]:
        """Persist lightweight selection, view and successful browse scope for revisits.
        Do not retain fetched snapshots, derived filter rows or dirty editor text:
        flush_pending_work saves edits first; mount refetches data. Ingest, rail
        preferences and history keep their existing registry/config owners.
        Frozen RAG rows and settled recovery state may travel; restore normalizes
        transient searching. Prompt restore excludes drafts, failures and loading."""
        state = super().save_state()
        continue_receipt = self._library_continue_receipt_for_current_route()
        if continue_receipt is not None:
            self._library_continue_receipt = continue_receipt
        state["library_continue_receipt"] = self._copy_library_continue_receipt(
            self._library_continue_receipt
        )
        state["library_selected_row_id"] = self._library_selected_row_id
        state["selected_conversation_id"] = self._selected_conversation_id
        state["selected_note_id"] = self._notes_state.selected_note_id
        state["library_notes_view"] = self._notes_state.view
        state["selected_media_id"] = self._media_state.selected_media_id
        state["library_media_view"] = self._media_state.view
        state["library_rag_query"] = self._rag_search_state.query
        state["library_rag_mode"] = self._rag_search_state.mode
        state["library_rag_scope_deselected"] = set(
            self._rag_search_state.scope_deselected
        )
        state["library_rag_results"] = tuple(self._rag_search_state.results)
        state["library_rag_selected_result_id"] = (
            self._rag_search_state.selected_result_id
        )
        state["library_rag_retrieval_status"] = self._rag_search_state.retrieval_status
        state["library_rag_recovery_state"] = self._rag_search_state.recovery_state
        state["library_rag_diagnostics"] = dict(self._rag_search_state.diagnostics)
        state["library_rag_searched_query"] = self._rag_search_state.searched_query
        # PR-3 Task 4: the answer travels with the results it was generated
        # from -- same lifecycle as the two fields above, and for the same
        # reason (a `LibraryRagAnswer` is a frozen dataclass, so it is safe
        # to carry verbatim). `_rag_search_state.answer_in_flight` is
        # deliberately absent: see its `__init__` comment.
        state["library_rag_answer"] = self._rag_search_state.answer
        state["library_rag_answer_query"] = self._rag_search_state.answer_query
        state["library_rag_answer_mode"] = self._rag_search_state.answer_mode
        applied_media = self._library_media_browse_controller.state.applied_result
        state["library_media_scope"] = dataclasses.asdict(
            applied_media.scope if applied_media is not None else MediaBrowseScope()
        )
        state["library_notes_sort"] = self._notes_state.sort
        state["library_notes_filter"] = self._notes_state.filter
        applied_prompts = self._library_prompt_browse_controller.applied_result
        state["library_prompts_scope"] = dataclasses.asdict(
            applied_prompts.scope
            if applied_prompts is not None
            else PromptBrowseScope()
        )
        applied_skills = self._library_skills_browse_controller.applied_result
        state["library_skills_scope"] = dataclasses.asdict(
            applied_skills.scope if applied_skills is not None else SkillBrowseScope()
        )
        capture_controller = self._library_collections_capture_controller
        applied_collections = (
            capture_controller.state.applied_scope
            if capture_controller is not None
            else None
        )
        state["library_collections_page"] = (
            applied_collections.page if applied_collections is not None else 1
        )
        state["selected_prompt_id"] = self._prompts_state.selected_prompt_id
        conversation_applied = self._conversations_state.freshness != "uninitialized"
        state["library_conversation_page"] = (
            self._conversations_state.page if conversation_applied else 1
        )
        state["conversation_archive_scope"] = self._conversation_recovery().scope
        state["library_conversation_query"] = (
            self._conversations_state.query if conversation_applied else ""
        )
        # task-2858 AC#3 (LIB-12): extend the receipt's durability past a
        # full navigate-away-and-back, not just within-instance canvas
        # switches (see the field's own ``__init__`` comment).
        state["library_export_last_path"] = self._export_state.last_path
        state["library_export_last_at"] = self._export_state.last_at
        state["library_export_last_items"] = self._export_state.last_items
        state["library_export_last_bytes"] = self._export_state.last_bytes
        return state

    @staticmethod
    def _copy_library_continue_receipt(
        receipt: Mapping[str, Any] | None,
    ) -> dict[str, Any] | None:
        """Detach the small primitive returning-Library receipt."""

        if receipt is None:
            return None
        scope = dict(receipt["scope"])
        deselected = scope.get("scope_deselected")
        if isinstance(deselected, list):
            scope["scope_deselected"] = list(deselected)
        return {
            "version": receipt["version"],
            "row_id": receipt["row_id"],
            "scope": scope,
            "source_list_adjusted": receipt["source_list_adjusted"],
        }

    def _library_continue_receipt_for_current_route(self) -> dict[str, Any] | None:
        """Return an authoritative, content-free receipt for the active source."""

        row_id = self._library_selected_row_id
        scope: dict[str, Any]
        source_list_adjusted = False

        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            if self._media_state.view == "trash":
                return None
            applied = self._library_media_browse_controller.state.applied_result
            if applied is None:
                return None
            media_scope = applied.scope
            scope = {
                "query": media_scope.query,
                "media_type": media_scope.media_type,
                "sort_by": media_scope.sort_by,
                "page": media_scope.page,
            }
            source_list_adjusted = self._media_state.view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            applied = self._library_prompt_browse_controller.applied_result
            if applied is None:
                return None
            prompt_scope = applied.scope
            scope = {
                "query": prompt_scope.query,
                "collection_id": prompt_scope.collection_id,
                "sort_by": prompt_scope.sort_by,
                "sort_order": prompt_scope.sort_order,
                "page": prompt_scope.page,
            }
            source_list_adjusted = self._prompts_state.view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            if (
                not self._conversations_state.page_loaded
                or self._conversations_state.freshness not in {"fresh", "stale"}
            ):
                return None
            scope = {
                "page": self._conversations_state.page,
                "query": self._conversations_state.query,
            }
        elif row_id == LIBRARY_ROW_BROWSE_NOTES:
            if (
                self._notes_state.source != LIBRARY_NOTES_SOURCE_DATABASE
                or not self._library_loaded
                or self._library_lookup_error
            ):
                return None
            scope = {
                "sort": self._notes_state.sort,
                "filter": self._notes_state.filter,
            }
            source_list_adjusted = self._notes_state.view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
            applied = self._library_skills_browse_controller.applied_result
            if applied is None:
                return None
            skill_scope = applied.scope
            scope = {
                "sort": skill_scope.sort,
                "filter": skill_scope.query,
                "page": skill_scope.page,
            }
            source_list_adjusted = self._skills_state.view != "list"
        elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            controller = self._library_collections_capture_controller
            applied = controller.state.applied_scope if controller is not None else None
            if applied is None or controller.state.page_stale:
                return None
            scope = {"page": applied.page}
        elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
            if self._rag_search_state.retrieval_status not in {"ready", "empty"}:
                return None
            scope = {
                "query": self._rag_search_state.searched_query,
                "mode": self._rag_search_state.mode,
                "scope_deselected": sorted(self._rag_search_state.scope_deselected),
            }
        else:
            return None

        return {
            "version": 1,
            "row_id": row_id,
            "scope": scope,
            "source_list_adjusted": source_list_adjusted,
        }

    @classmethod
    def _restore_library_continue_receipt(
        cls,
        value: object,
    ) -> dict[str, Any] | None:
        """Validate one versioned receipt without recovering private row data."""

        if type(value) is not dict or set(value) != {
            "version",
            "row_id",
            "scope",
            "source_list_adjusted",
        }:
            return None
        if type(value["version"]) is not int or value["version"] != 1:
            return None
        if type(value["source_list_adjusted"]) is not bool:
            return None
        row_id = value["row_id"]
        raw_scope = value["scope"]
        if type(row_id) is not str or type(raw_scope) is not dict:
            return None

        try:
            if row_id == LIBRARY_ROW_BROWSE_MEDIA:
                if set(raw_scope) != {"query", "media_type", "sort_by", "page"}:
                    return None
                normalized = MediaBrowseScope(**raw_scope)
                scope = {
                    "query": normalized.query,
                    "media_type": normalized.media_type,
                    "sort_by": normalized.sort_by,
                    "page": normalized.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                if set(raw_scope) != {
                    "query",
                    "collection_id",
                    "sort_by",
                    "sort_order",
                    "page",
                }:
                    return None
                normalized_prompt = PromptBrowseScope(**raw_scope)
                scope = {
                    "query": normalized_prompt.query,
                    "collection_id": normalized_prompt.collection_id,
                    "sort_by": normalized_prompt.sort_by,
                    "sort_order": normalized_prompt.sort_order,
                    "page": normalized_prompt.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                if set(raw_scope) != {"page", "query"}:
                    return None
                page = raw_scope["page"]
                query = raw_scope["query"]
                if (
                    type(page) is not int
                    or cls._normalize_library_conversation_page(page) != page
                    or type(query) is not str
                ):
                    return None
                scope = {"page": page, "query": query.strip()[:200]}
            elif row_id == LIBRARY_ROW_BROWSE_NOTES:
                if set(raw_scope) != {"sort", "filter"}:
                    return None
                sort = raw_scope["sort"]
                filter_value = raw_scope["filter"]
                if (
                    sort not in {"newest", "oldest", "title"}
                    or type(filter_value) is not str
                ):
                    return None
                scope = {"sort": sort, "filter": filter_value}
            elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
                if set(raw_scope) not in (
                    {"sort", "filter"},
                    {"sort", "filter", "page"},
                ):
                    return None
                sort = raw_scope["sort"]
                filter_value = raw_scope["filter"]
                page = raw_scope.get("page", 1)
                normalized_skill = SkillBrowseScope(
                    query=filter_value,
                    sort=sort,
                    page=page,
                )
                scope = {
                    "sort": normalized_skill.sort,
                    "filter": normalized_skill.query,
                    "page": normalized_skill.page,
                }
            elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
                if set(raw_scope) not in (set(), {"page"}):
                    return None
                page = raw_scope.get("page", 1)
                if type(page) is not int or not 1 <= page <= 2**31 - 1:
                    return None
                scope = {"page": page}
            elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
                if set(raw_scope) != {"query", "mode", "scope_deselected"}:
                    return None
                query = raw_scope["query"]
                mode = raw_scope["mode"]
                deselected = raw_scope["scope_deselected"]
                if (
                    type(query) is not str
                    or mode not in {"search", "rag"}
                    or type(deselected) is not list
                    or any(type(item) is not str for item in deselected)
                    or len(set(deselected)) != len(deselected)
                    or not set(deselected).issubset(
                        LIBRARY_RAG_SCOPE_TOGGLE_SOURCE_TYPES
                    )
                ):
                    return None
                scope = {
                    "query": query,
                    "mode": mode,
                    "scope_deselected": sorted(deselected),
                }
            else:
                return None
        except (TypeError, ValueError):
            return None

        return {
            "version": 1,
            "row_id": row_id,
            "scope": scope,
            "source_list_adjusted": value["source_list_adjusted"],
        }

    def restore_state(self, state: dict[str, Any]) -> None:
        """Restore saved selection, views, filters and sorting before first mount.
        Missing IDs degrade to lists; failed detail fetches use Notes-list or Reader-Retry
        recovery. Reissue restored conversation queries against the complete dataset
        and sanitize their text again because saved-state dictionaries are untyped."""
        super().restore_state(state)
        if not isinstance(state, dict):
            return

        has_continue_receipt = "library_continue_receipt" in state
        continue_receipt = self._restore_library_continue_receipt(
            state.get("library_continue_receipt")
        )
        self._library_continue_receipt = continue_receipt
        self._library_selected_row_id = (
            ""
            if has_continue_receipt
            else str(state.get("library_selected_row_id") or "")
        )
        self._selected_conversation_id = str(
            state.get("selected_conversation_id") or ""
        )

        selected_note_id = str(state.get("selected_note_id") or "")
        notes_view = str(state.get("library_notes_view") or "list")
        if notes_view == "editor" and not selected_note_id:
            notes_view = "list"
        self._notes_state.selected_note_id = selected_note_id
        self._notes_state.view = notes_view

        selected_media_id = str(state.get("selected_media_id") or "")
        media_view = str(state.get("library_media_view") or "list")
        if media_view == "viewer" and not selected_media_id:
            media_view = "list"
        # task-4025: the Trash view is session-transient -- its fetched
        # page is never persisted, so a restored session lands on the
        # media list (which is where its "Trash" entry point lives)
        # rather than an unloaded Trash shell nothing would populate.
        if media_view == "trash":
            media_view = "list"
        self._media_state.selected_media_id = selected_media_id
        self._media_state.view = media_view

        self._rag_search_state.query = str(state.get("library_rag_query") or "")
        rag_mode = state.get("library_rag_mode")
        self._rag_search_state.mode = (
            rag_mode if rag_mode in ("search", "rag") else "search"
        )
        scope_deselected = state.get("library_rag_scope_deselected")
        self._rag_search_state.scope_deselected = (
            set(scope_deselected)
            if isinstance(scope_deselected, (set, frozenset, list, tuple))
            else set()
        )
        rag_results = state.get("library_rag_results")
        self._rag_search_state.results = (
            tuple(rag_results) if isinstance(rag_results, (list, tuple)) else ()
        )
        self._rag_search_state.selected_result_id = str(
            state.get("library_rag_selected_result_id") or ""
        )
        restored_retrieval_status = str(state.get("library_rag_retrieval_status") or "")
        self._rag_search_state.retrieval_status = (
            ""
            if restored_retrieval_status == "searching"
            else restored_retrieval_status
        )
        recovery_state = state.get("library_rag_recovery_state")
        self._rag_search_state.recovery_state = (
            recovery_state
            if isinstance(recovery_state, DestinationRecoveryState)
            else None
        )
        rag_diagnostics = state.get("library_rag_diagnostics")
        self._rag_search_state.diagnostics = (
            dict(rag_diagnostics) if isinstance(rag_diagnostics, Mapping) else {}
        )
        self._rag_search_state.searched_query = str(
            state.get("library_rag_searched_query") or ""
        )
        rag_answer = state.get("library_rag_answer")
        self._rag_search_state.answer = (
            rag_answer if isinstance(rag_answer, LibraryRagAnswer) else None
        )
        self._rag_search_state.answer_query = str(
            state.get("library_rag_answer_query") or ""
        )
        rag_answer_mode = state.get("library_rag_answer_mode")
        self._rag_search_state.answer_mode = (
            rag_answer_mode if rag_answer_mode in ("search", "rag") else ""
        )
        # `_rag_search_state.answer_in_flight` (and its Task 3 companion,
        # `_rag_search_state.answer_in_flight_provider`) are intentionally
        # left at their `__init__` defaults (False / ""): this instance has
        # no answer worker running, so restoring an in-flight "answering"
        # status would be a dangling one nothing could ever resolve.

        restored_media_scope = self._restore_library_media_scope(state)
        self._library_media_browse_controller.invalidate(restored_media_scope)
        self._media_state.type_filter = restored_media_scope.media_type
        notes_sort = state.get("library_notes_sort")
        self._notes_state.sort = (
            notes_sort if isinstance(notes_sort, str) and notes_sort else "newest"
        )
        notes_filter = state.get("library_notes_filter")
        self._notes_state.filter = (
            notes_filter if isinstance(notes_filter, str) else ""
        )
        restored_prompts_scope = self._restore_library_prompts_scope(state)
        self._library_prompt_browse_controller.invalidate(restored_prompts_scope)
        restored_skills_scope = self._restore_library_skills_scope(state)
        self._library_skills_browse_controller.invalidate(restored_skills_scope)
        self._skills_state.sort = restored_skills_scope.sort
        self._skills_state.filter = restored_skills_scope.query
        self._collections_state.requested_page = (
            self._restore_library_collections_page(state)
        )
        selected_prompt_id = state.get("selected_prompt_id")
        self._prompts_state.selected_prompt_id = (
            selected_prompt_id if isinstance(selected_prompt_id, int) else None
        )
        self._conversations_state.page_records = ()
        self._conversations_state.page = 1
        self._conversations_state.query = ""
        self._conversations_state.total = 0
        self._conversations_state.total_known = False
        self._conversations_state.has_more = False
        self._conversations_state.page_loaded = False
        self._conversations_state.loading = False
        self._conversations_state.error = ""
        self._conversations_state.freshness = "uninitialized"
        self._conversations_state.stale_copy = ""
        self._conversations_state.selection_notice = ""
        self._conversations_state.focus_after_apply = ""
        self._conversations_state.select_mode = False
        self._conversations_state.row_selection.clear()
        from ...Utils.input_validation import validate_conversation_archive_scope

        try:
            archive_scope = validate_conversation_archive_scope(
                state.get("conversation_archive_scope")
            )
        except ValueError:
            archive_scope = "active"
        self._conversation_recovery().scope = archive_scope
        conversation_query = state.get("library_conversation_query")
        self._conversations_state.requested_query = self._safe_text(
            conversation_query if isinstance(conversation_query, str) else "",
            "",
            max_length=200,
        )
        self._conversations_state.requested_page = (
            self._normalize_library_conversation_page(
                state.get("library_conversation_page")
            )
        )
        if continue_receipt is not None:
            scope = continue_receipt["scope"]
            row_id = continue_receipt["row_id"]
            if row_id == LIBRARY_ROW_BROWSE_MEDIA:
                receipt_media_scope = MediaBrowseScope(**scope)
                self._library_media_browse_controller.invalidate(receipt_media_scope)
                self._media_state.type_filter = receipt_media_scope.media_type
                self._media_state.view = "list"
                self._media_state.selected_media_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                receipt_prompt_scope = PromptBrowseScope(**scope)
                self._library_prompt_browse_controller.invalidate(receipt_prompt_scope)
                self._prompts_state.view = "list"
                self._prompts_state.selected_prompt_id = None
            elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                self._conversations_state.requested_page = scope["page"]
                self._conversations_state.requested_query = scope["query"]
                self._selected_conversation_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_NOTES:
                self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
                self._notes_state.sort = scope["sort"]
                self._notes_state.filter = scope["filter"]
                self._notes_state.view = "list"
                self._notes_state.selected_note_id = ""
            elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
                receipt_skills_scope = SkillBrowseScope(
                    query=scope["filter"],
                    sort=scope["sort"],
                    page=scope.get("page", 1),
                )
                self._library_skills_browse_controller.invalidate(receipt_skills_scope)
                self._skills_state.sort = receipt_skills_scope.sort
                self._skills_state.filter = receipt_skills_scope.query
                self._skills_state.view = "list"
                self._skills_state.selected_skill_name = ""
            elif row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
                self._collections_state.requested_page = scope.get("page", 1)
            elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
                self._rag_search_state.query = scope["query"]
                self._rag_search_state.mode = scope["mode"]
                self._rag_search_state.scope_deselected = set(
                    scope["scope_deselected"]
                )
        # task-2858 AC#3 (LIB-12): restore the durable export receipt
        # (see the field's ``__init__`` comment) -- a foreign/corrupted
        # dict degrades to "no receipt yet" rather than raising.
        last_export_path = state.get("library_export_last_path")
        self._export_state.last_path = (
            last_export_path if isinstance(last_export_path, str) else ""
        )
        last_export_at = state.get("library_export_last_at")
        self._export_state.last_at = (
            float(last_export_at)
            if isinstance(last_export_at, (int, float))
            and not isinstance(last_export_at, bool)
            else None
        )
        # task-32232 AC#4: the artifact-read counts ride along, so a
        # restored session still shows the receipt the run produced. Only a
        # POSITIVE integer is accepted (PR #2568 review): a real written
        # archive always has both, so a negative/zero/foreign value can only
        # be corruption -- and accepting it would render an impossible
        # receipt AND re-persist it through the next ``save_state``. An
        # invalid value degrades to the path-only receipt, which still names
        # the artifact.
        for key, field in (
            ("library_export_last_items", "last_items"),
            ("library_export_last_bytes", "last_bytes"),
        ):
            value = state.get(key)
            usable = (
                isinstance(value, int) and not isinstance(value, bool) and value > 0
            )
            setattr(self._export_state, field, int(value) if usable else None)
        # task-15459: re-seed from the cache now that ``_selected_
        # conversation_id`` above reflects the RESTORED id, not ``__init__``'s
        # empty default -- ``_apply_local_source_snapshot``'s carry-forward
        # (``_carry_selected_conversation_into_snapshot``) needs the real id
        # to know whether a not-on-the-cached-page selected conversation
        # must be prepended. Safe to call unconditionally: a cache miss here
        # is a no-op, and a hit is idempotent pre-mount attribute assignment
        # (see the method's own docstring).
        self._seed_local_source_snapshot_from_cache()

    def _file_notes_active(self) -> bool:
        """Return whether the retained File Notes workspace owns the canvas."""
        return (
            getattr(
                self._notes_state,
                "source",
                LIBRARY_NOTES_SOURCE_DATABASE,
            )
            == LIBRARY_NOTES_SOURCE_FILES
            and getattr(self, "_library_selected_row_id", "")
            == LIBRARY_ROW_BROWSE_NOTES
            and getattr(self._notes_state, "file_notes_workspace", None) is not None
        )

    def _library_media_viewer_substate_active(self) -> bool:
        return self._media_controller._library_media_viewer_substate_active()

    def _library_note_editor_active(self) -> bool:
        return self._notes_controller._library_note_editor_active()

    def _library_list_canvas_showing_list(self) -> bool:
        """True while Media/Notes/Prompts/Skills shows its plain LIST sub-view.

        The state task-2856's Escape-to-rail action targets: entering a
        detail/viewer/editor/create/sync sub-view of any of these four
        canvases returns False here (each of those has its own more
        specific Escape gate, or genuinely nothing to leave toward the
        rail for). Prompts/Skills also check the CREATE_* row id -- a
        "New prompt"/"New skill" editor exited back to the list never
        reassigns ``_library_selected_row_id`` away from CREATE_PROMPT/
        CREATE_SKILL (mirroring ``_library_skill_editor_active``'s own
        dual-row-id gate), so the list is genuinely showing under either
        id.
        """
        row_id = self._library_selected_row_id
        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            return getattr(self._media_state, "view", "list") == "list"
        if row_id == LIBRARY_ROW_BROWSE_NOTES:
            return (
                getattr(
                    self._notes_state,
                    "source",
                    LIBRARY_NOTES_SOURCE_DATABASE,
                )
                == LIBRARY_NOTES_SOURCE_DATABASE
                and getattr(self._notes_state, "view", "list") == "list"
            )
        if row_id in (LIBRARY_ROW_BROWSE_PROMPTS, LIBRARY_ROW_CREATE_PROMPT):
            return getattr(self._prompts_state, "view", "list") == "list"
        if row_id in (LIBRARY_ROW_BROWSE_SKILLS, LIBRARY_ROW_CREATE_SKILL):
            return getattr(self._skills_state, "view", "list") == "list"
        if row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            return bool(self.query("#library-conversations-canvas"))
        return False

    def _arm_library_list_entry_focus(
        self,
        *,
        media_return: _LibraryMediaReturnReceipt | None = None,
    ) -> None:
        """Arm immediate list-entry focus plus a bounded background-settlement window.
        Use this at every list entry/return, never schedule the focus callback directly.
        Stop the previous timer before rearming. User keys or foreign focus disarm
        immediately; the timer only bounds retries across idle background recomposes."""
        self._media_state.successful_focus_ownership = None
        # Same reason PR #1410's review stopped the settle timer below: a
        # retry tick left over from the PREVIOUS arm carries that arm's
        # generation, so it no-ops when it fires -- while its stored handle
        # blocks this arm from starting a chain of its own. Live effect after
        # dev's conversations change added a second arm to the route entry:
        # the rows mounted 0.44s in, with 1.75s of window left, and nothing
        # re-requested focus.
        if self._library_list_entry_focus_retry_timer is not None:
            self._library_list_entry_focus_retry_timer.stop()
            self._library_list_entry_focus_retry_timer = None
        if self._library_list_entry_focus_timer is not None:
            self._library_list_entry_focus_timer.stop()
            self._library_list_entry_focus_timer = None
        self._library_list_entry_focus_deadline = (
            time.monotonic() + LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS
        )
        self._library_list_entry_focus_generation += 1
        self._library_pending_list_entry_focus = True
        self._library_pending_list_entry_media_return = media_return
        self._library_pending_list_entry_focus_anchor = self.focused
        settlement_media_return = self._library_media_return_candidate(media_return)
        if settlement_media_return:
            self._arm_library_media_return_settlement(media_return)
            # Preserve the bounded outer-arm continuation. It may construct
            # fresh authority after composition, but `_arm` still requires a
            # current owner's public geometry before exact settlement.
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )
        else:
            # One branch since Qodo #3 on PR #2585 guarded the ``media_return
            # is None`` case: the plain call re-checked neither the pending
            # flag nor the arm generation, so a user who took control between
            # this schedule and the callback had focus pulled back into the
            # list -- the yank task-2856's review round 2 added the immediate
            # disarm for. Both remaining cases now want the identical guarded
            # continuation, so they say so once.
            self.call_after_refresh(
                self._focus_library_list_entry_if_current,
                self._library_list_entry_focus_generation,
            )
        if self._library_list_entry_focus_timer is None:
            self._library_list_entry_focus_timer = self.set_timer(
                LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS,
                self._disarm_library_list_entry_focus,
            )

    def _retry_library_list_entry_focus_while_armed(self) -> None:
        """Re-attempt entry focus once the list's rows have actually mounted.

        task-32228: the arm schedules ONE ``call_after_refresh`` attempt and
        then relies on ``compose_content`` re-requesting while the flag stays
        armed. That covers a canvas whose rows arrive on a SCREEN recompose;
        it does not cover one whose rows arrive on a canvas-level recompose,
        which is why Conversations landed on nothing (measured: the single
        attempt ran with zero ``.library-conversation-row`` widgets mounted,
        the flag was still armed when they appeared, and nothing re-fired).

        Bounded by the arm's own settle window on both axes: the deadline
        stops the polling, and ``_focus_library_list_entry_if_current`` drops
        any tick whose generation a disarm has already superseded. So this
        cannot outlive a user taking control, and on a genuinely empty list it
        stops at the deadline rather than spinning. One chain at a time, and
        the handle is stored so a disarm can stop it early -- the same shape
        ``_arm_library_list_entry_focus`` uses for its own settle timer
        (re-review N5: every no-rows attempt used to start its own chain, and
        ``compose_content`` re-requests on each recompose while armed, so
        several ran concurrently for one arm).
        """
        # ponytail: bounded by LIBRARY_LIST_ENTRY_FOCUS_ARMED_SECONDS (2s), so
        # a list that takes longer than that to arrive still lands nowhere --
        # measured live on the seeded profile, where the FIRST visit to
        # Conversations (cold DB) misses the window and a warm re-entry hits
        # it. The other list canvases share that ceiling (a cold Prompts visit
        # lands in its filter rather than row 0), and task-32260 measured
        # Library at 12.6s to open, so the miss is routine rather than rare.
        # Upgrade path filed as task-32301: re-arm from each destination's own
        # "list arrived" seam instead of a fixed window.
        deadline = self._library_list_entry_focus_deadline
        if (
            self._library_list_entry_focus_retry_timer is not None
            or not self._library_pending_list_entry_focus
            or deadline is None
            or time.monotonic() >= deadline
        ):
            return
        generation = self._library_list_entry_focus_generation

        def _tick() -> None:
            self._library_list_entry_focus_retry_timer = None
            self._focus_library_list_entry_if_current(generation)

        self._library_list_entry_focus_retry_timer = self.set_timer(
            LIBRARY_LIST_ENTRY_FOCUS_RETRY_SECONDS, _tick
        )

    def _disarm_library_list_entry_focus(self) -> None:
        """End an entry-focus request's settle window (task-2856 AC1).

        Fired by: the timer ``_arm_library_list_entry_focus`` sets; the
        top of ``on_key`` for ANY key while the request is armed (the
        user doing anything at all is "taking control"; disarming an
        already-idle flag is a harmless no-op); or ``on_descendant_focus``
        the moment focus lands somewhere other than a row of the armed
        list (Tab, Shift+Tab, a mouse click -- anything that is not the
        system's own re-focus of its own row) -- whichever comes first.
        Also stops and clears the stored timer handle (PR #1410 review)
        so an interaction-driven disarm never leaves the settle-window
        timer dangling behind it.
        """
        self._library_list_entry_focus_generation += 1
        # re-review N5: the retry chain gets the same early stop the settle
        # timer has, instead of ticking on to its deadline after a disarm.
        if self._library_list_entry_focus_retry_timer is not None:
            self._library_list_entry_focus_retry_timer.stop()
            self._library_list_entry_focus_retry_timer = None
        self._library_pending_list_entry_focus = False
        self._library_pending_list_entry_media_return = None
        self._library_pending_list_entry_focus_anchor = None
        self._media_state.return_settlement = None
        self._media_state.last_exact_settlement = None
        self._media_state.last_successful_settlement = None
        self._media_state.successful_focus_ownership = None
        self._media_state.last_settlement_attempt = None
        self._library_list_entry_focus_deadline = None
        if self._library_list_entry_focus_timer is not None:
            self._library_list_entry_focus_timer.stop()
            self._library_list_entry_focus_timer = None

    def _disarm_library_media_return_for_route_change(self) -> None:
        return self._media_controller._disarm_library_media_return_for_route_change()

    def on_descendant_focus(self, event: DescendantFocus) -> None:
        """Record Notes focus intent and disarm foreign list-entry focus.

        The Notes workbench caches meaningful semantic focus changes so a
        breakpoint crossing can restore the same control and scroll owner.
        Independently, task-2856's list-entry settle window is disarmed as
        soon as focus leaves the list rows it owns.

        Textual posts ``DescendantFocus`` for every focus change, including
        the system's OWN ``_focus_library_list_entry()`` call -- that case
        must NOT immediately disarm what it just armed, so it is excluded
        by checking the newly-focused widget against the armed list's own
        row class. Anything else (Tab/Shift+Tab landing elsewhere in the
        canvas, a mouse click on a different control, `/` moving focus to
        the rail search box) disarms: the user has taken over, and a later
        background recompose must never yank focus back out from under
        them. Complements the unconditional disarm at the top of
        ``on_key`` -- this hook is what also covers mouse clicks, which
        never reach ``on_key`` at all.

        Args:
            event: The queued descendant-focus event. Its ``widget`` is the
                newly focused node, evaluated for user focus intent: a
                genuine one vetoes deferred restores and supersedes a
                running locator that wants focus (task-32100).

        Returns:
            None.
        """
        focused = event.widget
        if focused is not self.focused:
            # Focus bubbles are queued. A transactional Media rollback may
            # restore its prior live focus before the abandoned target's
            # earlier bubble arrives; that stale event owns no authority.
            if self._library_notes_programmatic_focus_target is focused:
                self._library_notes_programmatic_focus_target = None
            return
        # task-31223: the footer's typing-context swap (drop keys a text
        # field will swallow) must follow focus, not just route changes.
        self._refresh_footer_typing_context(focused)
        self._notes_controller._remember_library_notes_authority_focus(focused)
        target_restore = self._library_notes_programmatic_focus_target is focused
        pending_receipt = self._library_pending_list_entry_media_return
        successful_return_focus = bool(
            pending_receipt is not None
            and self._media_controller._library_media_successful_focus_is_allowed(
                pending_receipt,
                pending_receipt.stable_id,
            )
        )
        programmatic = bool(
            target_restore
            or successful_return_focus
            or self._library_notes_restoring_focus
            or self._notes_state.resize_settling
        )
        if (
            self._library_pending_list_entry_focus
            and pending_receipt is not None
        ):
            guarded_return_focus = bool(
                (target_restore or successful_return_focus)
                and focused is not None
                and self._library_media_focus_target_matches_receipt(
                    focused,
                    pending_receipt,
                    pending_receipt.stable_id,
                )
            )
            if not guarded_return_focus:
                # Revoke the retained receipt before a genuine row selection
                # can recompose Media and expose any newer owner geometry.
                self._disarm_library_list_entry_focus()
        if (
            focused is not None
            and focused.has_class("library-media-row")
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and not self._media_state.select_mode
            and not programmatic
        ):
            media_id = str(getattr(focused, "media_id", "") or "")
            title = str(getattr(focused, "_library_media_title", "") or media_id)
            if media_id and media_id != self._media_state.selected_media_id:
                self._select_library_media_reader_row(media_id, title, immediate=False)
        if self.is_mounted:
            stage = self._library_notes_focus_stage(focused)
            relevant = bool(
                self._library_notes_workflow_active()
                or stage == "rail"
                or (
                    self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                    and self._media_state.view in {"list", "trash"}
                )
                or self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            )
            if target_restore:
                self._library_notes_programmatic_focus_target = None
            user_intent = relevant and not programmatic
            if user_intent:
                # Veto every older deferred restore before its next turn can
                # steal the control the user just chose.
                self._notes_state.focus_intent_generation += 1
                # PR #2571 review, finding 4: the supersede below does four
                # more things -- it clears the pending focus handoff, the
                # navigation status and the branch navigation requests. None
                # of those run now while a focus=False locator is in flight.
                # The status and the in-flight branch requests are that
                # locator's own and MUST survive. The pending focus handoff
                # is the one that could in principle go stale, and the
                # invariant that makes this safe is: nothing arms a pending
                # handoff while a focus=False locator runs -- the only
                # arming site (`_exit_library_note_editor_guarded`)
                # supersedes navigation itself and arms with the generation
                # that supersede returns. Hoisting the handoff clear out of
                # the supersede was TRIED and reverted: it reds the notes
                # focus/footer pins in `test_library_canvas_sync_defects.py`,
                # because `_rehydrate_library_notes_after_recompose` reads
                # that same pending identity to decide it MAY restore focus
                # at all.
                # task-32100: a running locator that would take focus is the
                # one this focus change overrules. A ``focus=False`` locator
                # only reveals a row, and the row click that started it lands
                # here ~20 ms later -- superseding it abandoned every open.
                # Its status and its in-flight branch requests are its own and
                # must survive, which is why the rest of the supersede does
                # not run for it.
                if (
                    self._notes_state.navigation_status
                    and self._notes_state.navigation_focus_intent
                ):
                    LibraryScreen._supersede_library_notes_navigation(self)
            self.call_after_refresh(
                self._notes_controller._record_library_notes_focus_interaction,
                focused,
                user_intent,
            )
            if (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._media_state.view == "viewer"
            ):
                self._register_footer_shortcuts()

        if not self._library_pending_list_entry_focus:
            return
        if (
            (target_restore or successful_return_focus)
            and pending_receipt is not None
            and focused is not None
        ):
            if self._library_media_focus_target_matches_receipt(
                focused,
                pending_receipt,
                pending_receipt.stable_id,
            ):
                return
        row_class = _LIBRARY_LIST_ROW_CLASS_BY_ROW_ID.get(self._library_selected_row_id)
        widget = event.widget
        if row_class is not None and widget is not None and widget.has_class(row_class):
            return
        if (
            self._library_notes_restoring_focus
            and self._library_pending_list_entry_media_return is not None
        ):
            return
        self._disarm_library_list_entry_focus()

    def _focus_library_list_entry_if_current(self, generation: int) -> None:
        """Apply one semantic Media return only while its arm still owns focus."""
        if (
            self._library_pending_list_entry_focus
            and generation == self._library_list_entry_focus_generation
        ):
            receipt = self._library_pending_list_entry_media_return
            if self._library_media_return_candidate(receipt):
                self._arm_library_media_return_settlement(receipt)
                tree = self._library_media_settlement_tree()
                revised_row_without_origin = bool(
                    receipt is not None
                    and receipt.final_focus_policy == "row"
                    and not self._media_controller._library_media_exact_return_candidate(receipt)
                    and tree is not None
                    and not self._media_controller._library_media_semantic_row_is_current(
                        receipt,
                        tree[1],
                    )
                )
                if tree is None or revised_row_without_origin:
                    # Empty Media has no row-scroll geometry owner. Preserve
                    # its Import/recovery focus path; a revised list whose
                    # origin disappeared likewise uses its retained first row.
                    self._focus_library_list_entry()
                return
            self._focus_library_list_entry()

    def _library_media_empty_list_fallback_target(self) -> Widget | None:
        """The control an EMPTY Media list can hand keyboard focus to.

        The first of the candidates below that is both present and
        enabled, or ``None`` when the page offers none. One owner for both
        readers: ``_focus_library_list_entry`` lands on it, and
        ``_library_focus_channel_owns_this_window`` asks whether there is
        anything to land on at all, so the answer has to be the same in
        both places or the seam stands down for a channel that never
        arrives (Qodo #2483).

        task-32213 changed the shape of this question. The empty page used
        to compose NONE of the four recovery controls on a filter MISS --
        the canvas returned right after its query-echoing status line --
        and the whole point of the shared owner was to say "nothing to
        land on" there. The toolbar now survives that page, so
        ``#library-media-type-filter`` is always present and enabled on it
        (``fresh_zero`` excludes ``mutation_action_reason``, so
        ``_gate_mutation_action`` never disables it) and this helper no
        longer returns ``None`` for a Media miss.

        That would have landed entry focus on ``type:`` -- the facet the
        user did NOT type into, and the same symptom task-32214 was filed
        for. The intent recorded here still stands: with a query in force
        the filter ``Input`` is the right place to retype, so it LEADS the
        list rather than being left to the shared seam. ``#library-media-
        filter-clear`` is still deliberately not a candidate: Clear
        discards the query rather than letting the user fix it.
        """
        selectors = (
            "#library-media-type-filter",
            "#library-media-empty-clear-type",
            "#library-media-empty-import",
            "#library-media-retry",
        )
        applied = self._library_media_browse_controller.state.applied_scope
        if applied is not None and applied.query:
            selectors = ("#library-media-filter", *selectors)
        for selector in selectors:
            try:
                control = self.query_one(selector, Widget)
            except (NoMatches, QueryError):
                continue
            if not getattr(control, "disabled", False):
                return control
        return None

    def _focus_library_list_entry(self) -> None:
        """Focus the primary list's first row -- see ``_arm_library_list_entry_focus``.

        A no-op when the canvas isn't one of the four list canvases
        (nothing to focus), the list is empty, or the query can't resolve
        (e.g. a recompose still in flight).

        task-3020 AC3: while the Media canvas is in Select mode with a
        non-empty selection (a partial, or total, bulk-delete failure
        leaves the failed id(s) still checked, waiting for a retry), the
        first STILL-CHECKED row is preferred over the literal first row --
        landing keyboard focus on a row the user never selected would be
        a worse regression than the original "nothing focused" bug this
        method exists to fix. Every other caller is unaffected: the
        preference requires BOTH the Media row class and a non-empty
        selection, so notes/prompts/skills (no row_selection concept
        here) and Media outside an active selection (e.g. the bulk
        delete's own full-success path, which clears the selection before
        arming this) fall straight through to the plain first-row
        behavior, unchanged from before.
        """
        if self._library_emergency_stage == "rail-only":
            return
        row_class = _LIBRARY_LIST_ROW_CLASS_BY_ROW_ID.get(self._library_selected_row_id)
        if row_class is None:
            return
        rows = list(self.query(f".{row_class}"))
        if not rows:
            fallback_selector = {
                "library-prompt-row": "#library-prompts-filter",
                "library-skill-row": f"#{LIBRARY_SKILLS_FILTER_ID}",
                # task-31946 (PR L review item 2): an empty NOTES list left
                # this a no-op, so a background recompose inside the armed
                # settle window -- which stands the screen-level focus seam
                # down, precisely because this channel owns the window --
                # ended with nothing focused at all. Same filter-input
                # answer the two rows above already give.
                "library-notes-row": "#library-notes-filter",
            }.get(row_class)
            if row_class == "library-conversation-row":
                for selector in (
                    "#library-conversations-filter",
                    "#library-conversations-empty-console",
                ):
                    candidates = self.query(selector)
                    if candidates:
                        control = candidates.first(Widget)
                        if control.is_attached and control.focusable:
                            fallback_selector = selector
                            break
            if fallback_selector is not None:
                try:
                    control = self.query_one(fallback_selector, Widget)
                except (NoMatches, QueryError):
                    pass
                else:
                    self.set_focus(control)
                    # task-32228: only a landing counts as done. A control
                    # that is mounted but not yet focusable (a canvas still
                    # composing) leaves focus on None, and returning here made
                    # that indistinguishable from success -- which is how
                    # Conversations ended up with nothing focused while its
                    # rows were mounting.
                    if self.focused is control:
                        return
            if row_class == "library-media-row":
                control = self._library_media_empty_list_fallback_target()
                if control is not None:
                    self._library_notes_programmatic_focus_target = control
                    self.set_focus(control)
                    if self.focused is control:
                        return
            self._retry_library_list_entry_focus_while_armed()
            return
        if (
            row_class == "library-media-row"
            and self._media_state.select_mode
            and self._media_state.row_selection.count
        ):
            for row in rows:
                if self._media_state.row_selection.is_selected(
                    getattr(row, "media_id", "")
                ):
                    self.set_focus(row)
                    if self.focused is not row:
                        self._retry_library_list_entry_focus_while_armed()
                    return
        target = rows[0]
        media_return = self._library_pending_list_entry_media_return
        if row_class == "library-media-row" and media_return is not None:
            target = next(
                (
                    row
                    for row in rows
                    if str(getattr(row, "media_id", "") or "")
                    == media_return.stable_id
                ),
                target,
            )
        if row_class == "library-media-row":
            # Initial entry focus is system-owned just like a viewer return;
            # it must not be mistaken for user row selection by
            # ``on_descendant_focus`` and activate the Reader before Enter.
            self._library_notes_programmatic_focus_target = target
        self.set_focus(target, scroll_visible=False)
        if self.focused is not target:
            # task-32302: a MOUNTED row is not necessarily a FOCUSABLE one --
            # ``Widget.focusable`` is also false while it is disabled, hidden or
            # loading, and ``set_focus`` on such a widget is a silent no-op. The
            # Conversations regression was exactly that: dev's archive-scope
            # recovery hop fires a second page request during route entry, and
            # ``LibraryConversationRecovery.project`` folds ``loading`` into
            # ``actions_disabled``, which the canvas paints onto every row
            # (``button.disabled = actions_disabled``). The first load's rows
            # were up, the arm's one attempt spent itself on a disabled row, and
            # returning here made that indistinguishable from success -- the
            # same rule the empty-list fallback above already applies to its
            # controls. Keep the arm owed a landing instead; the retry chain is
            # bounded by the arm's own window either way (task-32301 owns that).
            self._retry_library_list_entry_focus_while_armed()
            return
        if row_class == "library-media-row" and media_return is not None:
            scroll_offset = media_return.scroll_offset
            if scroll_offset is not None:
                try:
                    scroll = self.query_one("#library-media-row-scroll", Widget)
                except (NoMatches, QueryError):
                    return
                scroll.scroll_to(
                    x=max(0, min(scroll_offset[0], int(scroll.max_scroll_x))),
                    y=max(0, min(scroll_offset[1], int(scroll.max_scroll_y))),
                    animate=False,
                    force=True,
                    immediate=True,
                )

    def _begin_library_structural_wait(
        self,
        label: str,
        owner: str,
        *,
        cancel: Callable[[], None] | None = None,
        repaint: Callable[[], None] | None = None,
    ) -> StructuralWait:
        """Start the screen's one structural wait and arm its patience repaint.

        Args:
            label: What is happening, without a trailing ellipsis.
            owner: Which surface started it (only that surface renders it).
            cancel: How to abandon the operation, when it can be abandoned.
            repaint: Called once the patience window closes, so the surface
                can re-render the now-longer status line.

        Returns:
            The started wait.
        """
        wait = StructuralWait(
            label=label,
            started_at=time.monotonic(),
            cancel=cancel,
            owner=owner,
        )
        self._library_structural_waits[owner] = wait
        # task-32102: whatever this owner had armed is gone the moment its
        # wait is replaced -- a second folder change must not inherit the
        # first one's patience clock.
        self._stop_library_structural_wait_timer(owner)
        if repaint is not None:
            # One shot: the line only changes once, when patience runs out.
            # Retained so a wait that settles inside the patience window can
            # stop it; unretained, the repaint fired into whatever the
            # surface had become three seconds later (task-32102).
            self._library_structural_wait_timers[owner] = self.set_timer(
                STRUCTURAL_WAIT_PATIENCE_SECONDS, repaint
            )
        return wait

    def _stop_library_structural_wait_timer(self, owner: str) -> None:
        """Stop and forget ``owner``'s armed patience repaint, if any."""
        timer = self._library_structural_wait_timers.pop(owner, None)
        if timer is not None:
            timer.stop()

    def _library_structural_wait_for(self, owner: str) -> StructuralWait | None:
        """Return ``owner``'s in-flight wait, if it has one."""
        return self._library_structural_waits.get(owner)

    def _end_library_structural_wait(self, owner: str) -> None:
        """Clear the wait once ``owner``'s operation has settled."""
        self._library_structural_waits.pop(owner, None)
        self._stop_library_structural_wait_timer(owner)

    @on(Button.Pressed, "#library-structural-wait-cancel")
    def _library_structural_wait_cancel_pressed(self, event: Button.Pressed) -> None:
        """Abandon the skill import behind the Import row's Cancel.

        The File Notes workspace mounts a button with this id too, but
        handles and stops it itself (it owns that wait), so the only press
        that reaches the screen is the Skills Import row's; the export ships
        its own ``#library-export-cancel``.
        """
        event.stop()
        wait = self._library_structural_wait_for(WAIT_OWNER_SKILL_IMPORT)
        if wait is not None:
            wait.request_cancel()

    async def _flush_active_file_notes(self) -> bool:
        """Delegate the common leave guard only while Files owns Notes.

        task-32055: this is the one seam Escape, the "‹ Library / Notes"
        cue, the Database strip button and the app's own navigation flush
        all reach, so it is where a structural wait is abandoned. Before
        this, a folder change held ``_root_transitioning`` for as long as
        its scan took and ``flush_pending_work`` refused for exactly that
        long -- which is how a wedged folder change swallowed every exit.
        The wait still gates the WRITE (``set_root`` refuses to start a
        second change), never the way out.
        """
        if not self._file_notes_active():
            return True
        assert self._notes_state.file_notes_workspace is not None
        # task-32102: this seam is only ever reached on the way out, so the
        # outcome is announced -- the root row it used to be written to is
        # part of the canvas being torn down.
        self._notes_state.file_notes_workspace.cancel_structural_wait(leaving=True)
        return await self._notes_state.file_notes_workspace.flush_pending_work()

    def _acquire_file_notes_transition(
        self,
        kind: Literal["screen", "source"],
    ) -> Callable[[], None] | Literal[False] | None:
        """Synchronously admit a transition for the active exact root binding."""
        if not self._file_notes_active():
            return None
        assert self._notes_state.file_notes_workspace is not None
        return self._notes_state.file_notes_workspace.acquire_transition(kind)

    def acquire_navigation_transition(
        self,
    ) -> Callable[[], None] | Literal[False] | None:
        """Admit outgoing screen navigation after the awaited leave flush."""
        if self._prompts_state.mutation_in_flight:
            return False
        return self._acquire_file_notes_transition("screen")

    async def flush_pending_work(self) -> bool:
        """Persist pending note edits before the app navigates away.

        The app awaits this from ``handle_screen_navigation`` before
        discarding this screen instance -- without it, a note edit whose
        debounced autosave has not fired yet (the timer re-arms on every
        keystroke) would be destroyed with the screen when the user switches
        tabs mid-edit.

        Returns:
            True only for the coordinator's typed ``PERMITTED`` result and
            successful prompt/skill barriers. Conflict, failure, validation,
            blocked, and stale Notes outcomes all veto navigation even when a
            presentation scalar or snapshot appears clean.
        """
        if self._prompts_state.mutation_in_flight:
            return False
        file_notes_flush_allowed = await self._flush_active_file_notes()
        note_flush = await self._flush_library_note_save()
        prompt_flush_allowed = await self._flush_library_prompt_save()
        skill_flush_allowed = await self._flush_library_skill_save()
        if not prompt_flush_allowed:
            self._prompts_controller._notify_prompt_dirty_veto()
        if not skill_flush_allowed:
            # task-449: the app-level navigation veto only logs, so tell
            # the user why the tab switch was refused -- same toast as the
            # in-screen Back / row-switch / rail-switch vetoes. Notes show
            # their own conflict banner and prompts predate this pattern,
            # so only the skill veto reports here.
            self._notify_skill_dirty_veto()
        return (
            file_notes_flush_allowed
            and note_flush.kind is NoteFlushOutcomeKind.PERMITTED
            and prompt_flush_allowed
            and skill_flush_allowed
        )


    def apply_navigation_context(self, context: Mapping[str, Any]) -> None:
        """Admit route context through the Library-owned navigation controller."""
        self._navigation_controller.apply_navigation_context(context)

    async def prepare_character_inspection(
        self, context: Mapping[str, Any], *, is_current: Callable[[], bool]
    ) -> PreparedLibraryInspection | None:
        """Prepare exact local inspection without replacing the retained view.

        Args:
            context: Closed typed Character inspection navigation context.
            is_current: Request-owned visit and cancellation validity callback.

        Returns:
            A single-use Library preparation, or None if admission is rejected.
        """
        from ..Library_Modules.library_inspection_admission import (
            prepare_character_inspection,
        )

        return await prepare_character_inspection(
            self, context, is_current=is_current
        )

    def commit_character_inspection(self, prepared: PreparedLibraryInspection) -> bool:
        """Consume the Library-owned preparation synchronously.

        Args:
            prepared: Exact selection token returned by this screen's preparation.

        Returns:
            True if the still-current token installs its selection; False otherwise.
        """
        from ..Library_Modules.library_inspection_admission import (
            commit_character_inspection,
        )

        return commit_character_inspection(self, prepared)

    def _library_navigation_context_target_row(
        self,
        context: Mapping[str, Any],
    ) -> str | None:
        """Return the validated destination row, or ``None`` for no route."""
        requested_mode = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_MODE),
            max_length=64,
        )
        target_row_id = LIBRARY_NAV_MODE_TO_ROW_ID.get(requested_mode)
        conversation_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_CONVERSATION_ID),
            max_length=200,
        )
        note_id = self._safe_text(
            context.get(LIBRARY_NAV_CONTEXT_NOTE_ID),
            max_length=200,
        )
        if conversation_id:
            target_row_id = LIBRARY_ROW_BROWSE_CONVERSATIONS
        if requested_mode == "notes" and not note_id:
            target_row_id = LIBRARY_ROW_BROWSE_NOTES
        if bool(context.get(LIBRARY_NAV_CONTEXT_NOTES_CREATE)):
            target_row_id = LIBRARY_ROW_CREATE_NOTE
        if bool(context.get(LIBRARY_NAV_CONTEXT_INGEST)):
            target_row_id = LIBRARY_ROW_INGEST_MEDIA
        if note_id:
            target_row_id = LIBRARY_ROW_BROWSE_NOTES

        raw_source_type = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_TYPE)
        raw_source_id = context.get(LIBRARY_NAV_CONTEXT_OPEN_SOURCE_ID)
        if type(raw_source_type) is str and type(raw_source_id) is str:
            source_type = self._safe_text(raw_source_type, max_length=64)
            source_id = self._safe_text(raw_source_id, max_length=500)
            if (
                source_type == raw_source_type
                and source_id == raw_source_id
                and source_type in {"media", "notes", "conversations", "prompt"}
                and source_id
            ):
                target_row_id = {
                    "media": LIBRARY_ROW_BROWSE_MEDIA,
                    "notes": LIBRARY_ROW_BROWSE_NOTES,
                    "conversations": LIBRARY_ROW_BROWSE_CONVERSATIONS,
                    "prompt": LIBRARY_ROW_BROWSE_PROMPTS,
                }[source_type]
        return target_row_id


    async def _apply_navigation_context_after_flush(
        self,
        context: Mapping[str, Any],
        target_row_id: str | None = None,
        generation: int | None = None,
        character_admission: _LibraryCharacterNavigationAdmission | None = None,
    ) -> None:
        """Admit every mounted editor/source, then apply navigation context.

        Pending saves are awaited before the recompose that tears an editor
        down. If unsaved edits survive any guard, the switch aborts and leaves
        the current route in place -- the same contract as a rail-row switch.
        """
        if self._prompts_state.mutation_in_flight:
            return
        if target_row_id is None:
            target_row_id = self._library_navigation_context_target_row(context)
        if target_row_id is None:
            return
        if generation is None:
            generation = self._library_navigation_context_generation
        if generation != self._library_navigation_context_generation:
            return
        if not await self._unavailable_navigation._validate_library_character_admission(self, character_admission):
            return
        file_notes_flush_allowed = await self._flush_active_file_notes()
        if not self._unavailable_navigation._library_character_admission_is_current(self, character_admission):
            self._unavailable_navigation._discard_library_character_admission(self, character_admission)
            return
        if generation != self._library_navigation_context_generation:
            return
        if not file_notes_flush_allowed:
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            await self._apply_navigation_context_after_source_admission(
                context,
                target_row_id,
                generation,
                character_admission,
            )
        finally:
            if callable(release_source):
                release_source()

    async def _apply_navigation_context_after_source_admission(
        self,
        context: Mapping[str, Any],
        target_row_id: str,
        generation: int,
        character_admission: _LibraryCharacterNavigationAdmission | None = None,
    ) -> None:
        """Apply mounted navigation context while source admission is held."""
        from ..Library_Modules.library_inspection_admission import (
            _flush_library_navigation_sources,
        )

        if self._prompts_state.mutation_in_flight:
            return
        if generation != self._library_navigation_context_generation:
            return
        def source_is_current() -> bool:
            return (
                generation == self._library_navigation_context_generation
                and self._unavailable_navigation._library_character_admission_is_current(
                    self, character_admission
                )
            )

        if not await _flush_library_navigation_sources(
            self, is_current=source_is_current
        ):
            self._unavailable_navigation._discard_library_character_admission(self, character_admission)
            return
        if target_row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._clear_library_prompt_selection(announce=True)
        self._apply_navigation_context_state(
            context,
            recompose=False,
            character_admission=character_admission,
        )
        if not self._unavailable_navigation._library_character_admission_is_current(self, character_admission):
            self._unavailable_navigation._discard_library_character_admission(self, character_admission)
            return
        if self.is_mounted and self._pending_library_source_open is None:
            await self.recompose()
            if not self._unavailable_navigation._library_character_admission_is_current(self, character_admission):
                self._unavailable_navigation._discard_library_character_admission(self, character_admission)
                return
        # task-32245: a deep link owes its destination the same entry focus a
        # rail-row press does.
        self._arm_library_row_entry_focus(target_row_id)
        if character_admission is not None:
            await self._unavailable_navigation._open_pending_library_character_navigation(self, )

    def _apply_navigation_context_state(
        self,
        context: Mapping[str, Any],
        *,
        recompose: bool = True,
        character_admission: _LibraryCharacterNavigationAdmission | None = None,
    ) -> None:
        """Commit admitted routes through the Library navigation owner."""
        from ..Library_Modules import library_unavailable_navigation

        library_unavailable_navigation._apply_navigation_context_state(
            self, context, recompose=recompose, character_admission=character_admission
        )

    async def _open_pending_library_source(
        self,
    ) -> LibraryEntryReconcileResult | None:
        """Consume one validated navigation target through Library's opener.

        A conversation point lookup may overlap the initial paged snapshot.
        That snapshot advances entry generation, so the first lookup result is
        correctly rejected; while the same pending target still owns the same
        conversation selection, retry under the new generation instead of
        permanently falling back to the first loaded row.
        """

        if self._prompts_state.mutation_in_flight:
            return

        pending = self._pending_library_source_open
        if pending is None:
            return
        while self._pending_library_source_open == pending:
            result = await self._open_library_item_by_id(*pending, entry_origin=True)
            if result is not LibraryEntryReconcileResult.SUPERSEDED:
                if result is None and pending[0] == "conversations":
                    return result
                if self._pending_library_source_open == pending:
                    self._pending_library_source_open = None
                return result
            if not self._pending_library_source_open_is_current(pending):
                if self._pending_library_source_open == pending:
                    self._pending_library_source_open = None
                return result
            # Let a scheduled snapshot reconcile finish before recapturing the
            # current generation in the next point-lookup attempt.
            await asyncio.sleep(0)
        return LibraryEntryReconcileResult.SUPERSEDED

    def _pending_library_source_open_is_current(self, pending: tuple[str, str]) -> bool:
        """Return whether a generation-only retry still owns its deep link."""

        source_type, record_id = pending
        if source_type == "media":
            return (
                self._pending_library_source_open == pending
                and self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and self._media_state.selected_media_id == record_id
            )
        return (
            source_type == "conversations"
            and self._pending_library_source_open == pending
            and self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
            and self._selected_conversation_id == record_id
        )

    # Own group, deliberately separate from the "default" group the plain
    # `self.run_worker(self._sync_collections_panel(...))` calls above use
    # (they take no explicit group either). Both were previously exclusive
    # in the SAME (default) group, so an ingest-completion poke into this
    # worker (see `_handle_library_ingest_registry_changed`) could cancel
    # an in-flight Collections load. A separate group makes the two
    # `exclusive=True` scopes independent.
    @work(exclusive=True, group="library_source_snapshot")
    async def _refresh_local_source_snapshot(self) -> None:
        self._refresh_library_onboarding_evidence()
        (
            records,
            counts,
            total_known,
            lookup_error,
            recovery_state,
            study_counts,
        ) = await self._list_local_source_snapshot()
        # Refresh the app-scoped instant-repeat-visit cache (seeded in
        # `__init__` before first compose)
        # with this fresh snapshot before applying it, so any other
        # LibraryScreen instance mounted from here on -- including a
        # concurrent one, since screens are recomposed per visit -- reads
        # this fetch's result rather than stale/no data.
        #
        # Only a SUCCESSFUL snapshot (``lookup_error is None``) is cached: an
        # error/service-unavailable result still applies to the current view
        # as usual below (unchanged), but must not become the next visit's
        # instant-apply seed -- otherwise a return visit within TTL would
        # flash the "services unavailable" banner for one frame before the
        # reconcile corrects it. Skipping the write leaves the previous good
        # snapshot (or nothing) in place, so the next visit does a normal
        # fresh fetch instead.
        if lookup_error is None:
            snapshot = clone_library_source_snapshot(
                (
                    records,
                    counts,
                    total_known,
                    lookup_error,
                    recovery_state,
                    study_counts,
                )
            )
            if snapshot is not None:
                self.app_instance._library_source_snapshot_cache = snapshot
                self.app_instance._library_source_snapshot_cache_stamp = (
                    time.monotonic()
                )
        presentation_changed = self._apply_local_source_snapshot(
            records, counts, total_known, lookup_error, recovery_state, study_counts
        )
        if (
            not presentation_changed
            and self._notes_state.pending_focus_waits_for_snapshot
        ):
            # A no-op snapshot has no reconciliation callback to finish the
            # pending Notes Back receipt. Release it after the current frame
            # just as a changed snapshot does from
            # `_complete_library_entry_reconcile` below.
            self.call_after_refresh(self._release_library_notes_focus_after_snapshot)
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS:
            # Task 5: this snapshot includes the skills entry the list view
            # reads (``_build_library_skills_state``) -- re-check the trust
            # posture alongside it (scoped to when skills are actually
            # being browsed, so every OTHER content type's refresh doesn't
            # pay for an off-thread keyring read it has no use for).
            self._refresh_library_skills_trust_posture()

    async def _read_library_collections_count(self) -> None:
        """Read the unfiltered Collections page-one total inside the source snapshot.

        Use the canvas's scope service, without selecting a capture or arming a
        reader scope. Once the canvas owns a scope, its total takes precedence.
        Run alongside the shared gather, with an independent bounded deadline:
        unrelated source failures must not discard this count or serialize waits.
        Clear the stored total on every failed/unavailable/stale-authority path.
        See TASK-32057 and the entry-compose-once tests.
        """
        collections = self._collections_controller
        controller = collections._ensure_library_collections_capture_controller()
        scope_service = (
            controller.scope_service if controller is not None else None
        )
        authority = getattr(scope_service, "active_authority", None)
        if authority is None:
            self._library_collections_prefetched_total = None
            self._library_collections_count_authority = None
            self._library_collections_count_failure = ""
            return
        started_at = time.monotonic()
        try:
            # (task-32103) The shared unfiltered page-1 read: the
            # onboarding evidence seam asks the same question in the same
            # pass, and one read now answers both.
            page = await asyncio.wait_for(
                scope_service.read_unfiltered_first_page(),
                timeout=LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS,
            )
        except Exception as exc:
            # Reason, not raw text: in server mode this seam is an HTTP
            # round trip, and an httpx exception's own message carries the
            # server URL. ``_retry_failure_reason`` is the shared leak rule
            # already applied to the Media callout -- it keeps an OS/SQLite
            # message (paths redacted, 80 chars) and reduces anything else
            # to its KIND, so the log gains context without a URL or a
            # private path reaching a persistent sink.
            logger.debug(
                "Library Collections count read failed: {}",
                _retry_failure_reason(exc),
            )
            self._library_collections_prefetched_total = None
            self._library_collections_count_authority = authority.key
            # (fix round 1) A read that failed in 20 ms must not tell the
            # user it waited five seconds, so the KIND is recorded, not just
            # the fact. (fix round 2) By the CLOCK, not by the exception
            # type: since 3.10 ``socket.timeout is TimeoutError`` and the
            # OSError family raises it for ETIMEDOUT, so an isinstance check
            # let a transport timeout that fired instantly claim the
            # deadline's copy -- and ``wait_for`` propagates an inner
            # TimeoutError unchanged, so catching at that line cannot tell
            # them apart either. The sentence claims elapsed time, so
            # elapsed time is what decides it.
            self._library_collections_count_failure = (
                "timeout"
                if time.monotonic() - started_at
                >= LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS
                else "error"
            )
            return
        self._library_collections_prefetched_total = page.total
        self._library_collections_count_authority = authority.key
        self._library_collections_count_failure = ""

    @staticmethod
    def _structural_records_for_comparison(
        records: Mapping[str, tuple[Any, ...]],
    ) -> dict[str, Any]:
        """Mask decorative counts for structural snapshot equality.
        Drop the entire prompts entry (rows have a separate owner). Mask only the
        Skills count, retaining available/blocked payloads that affect canvas content.

        Args:
            records: Incoming or currently rendered local-source snapshot.

        Returns:
            Shallow copy with decorative-only fields neutralized."""
        view = {key: value for key, value in records.items() if key != "prompts"}
        skills_entry = view.get("skills")
        if isinstance(skills_entry, tuple) and len(skills_entry) == 2:
            view["skills"] = (None, skills_entry[1])
        return view

    def _library_entry_route_key(self) -> tuple[object, ...]:
        """Return the state fields that select the mounted Library owner."""
        return (
            self._library_selected_row_id,
            self._notes_state.source,
            self._notes_state.view,
            self._media_state.view,
            self._prompts_state.view,
            self._skills_state.view,
            self._notes_state.selected_note_id,
            self._media_state.selected_media_id,
            self._prompts_state.selected_prompt_id,
            self._skills_state.selected_skill_name,
        )

    def _library_entry_canvas_host(self) -> Vertical | None:
        """Return the route-only host, or an adaptive reader's items host."""
        retained_hosts = self.query("#library-canvas-route-content")
        if retained_hosts:
            return retained_hosts.first(Vertical)
        try:
            return self.query_one("#library-canvas", Vertical)
        except (NoMatches, QueryError):
            return None

    def _library_entry_canvas_owner(self) -> Widget | None:
        """Return the active route child without treating recovery chrome as one.

        task-32065: "without treating recovery chrome as one" used to rest on
        that chrome being hidden. The Media items host has no
        ``#library-canvas-route-content`` wrapper to keep chrome out of the
        route's own container, so its VISIBLE "‹ Library" became the route
        owner -- neither a route nor a focus-restore target. (The ordinary
        ``LibraryEmergencyReturn`` needs no such clause: it is a sibling of
        that wrapper, so it is never among this host's children.)
        """
        host = self._library_entry_canvas_host()
        if host is None:
            return None
        return next(
            (
                child
                for child in host.children
                if child.display and child.id != "library-media-rail-return"
            ),
            None,
        )

    def _capture_library_entry_focus(self) -> LibraryEntryFocusIdentity | None:
        """Capture a focused canvas descendant by stable control or row identity."""
        focused = self.focused
        owner = self._library_entry_canvas_owner()
        route_key = self._library_entry_route_key()
        capture = self._library_entry_focus_capture
        if focused is None:
            if capture is not None and capture.route_key == route_key:
                return capture.identity
            self._library_entry_focus_capture = None
            return None
        if owner is None or owner not in focused.ancestors_with_self:
            self._library_entry_focus_capture = None
            return None

        source_id = ""
        for attribute in (
            "conversation_id",
            "media_id",
            "note_id",
            "prompt_id",
            "skill_name",
            "record_id",
            "source_id",
        ):
            value = getattr(focused, attribute, None)
            if value is not None and str(value):
                source_id = str(value)
                break
        scroll_offset: tuple[int, int] | None = None
        if hasattr(owner, "scroll_x") and hasattr(owner, "scroll_y"):
            scroll_offset = (int(owner.scroll_x), int(owner.scroll_y))
        identity = LibraryEntryFocusIdentity(
            widget_id=str(focused.id or ""),
            source_id=source_id,
            scroll_offset=scroll_offset,
        )
        notes_identity = (
            self._capture_library_notes_focus_identity()
            if owner.id == "library-notes-canvas"
            else None
        )
        self._library_entry_focus_capture = _LibraryEntryFocusCapture(
            identity=identity,
            outgoing_focus=focused,
            route_key=route_key,
            notes_identity=notes_identity,
        )
        # Detach DOM focus before the owner removes its focused child. Textual
        # otherwise falls back to unrelated screen chrome during teardown,
        # which is indistinguishable from a user focus move at restore time.
        # Any real focus move after this point lands on a non-None widget and
        # is therefore protected by `_restore_library_entry_focus`'s guard.
        self.set_focus(None)
        return identity

    def _restore_library_entry_focus(
        self,
        identity: LibraryEntryFocusIdentity,
        *,
        generation: int,
        route_key: tuple[object, ...],
    ) -> bool:
        """Restore one current semantic target without overriding user movement."""
        if generation != self._library_snapshot_state_generation:
            return False
        if route_key != self._library_entry_route_key():
            return False
        capture = self._library_entry_focus_capture
        outgoing_focus = (
            capture.outgoing_focus
            if capture is not None and capture.identity is identity
            else None
        )

        owner = self._library_entry_canvas_owner()
        if owner is None:
            return False
        target: Widget | None = None
        if identity.source_id:
            for candidate in owner.query(Widget):
                if any(
                    str(getattr(candidate, attribute, "") or "") == identity.source_id
                    for attribute in (
                        "conversation_id",
                        "media_id",
                        "note_id",
                        "prompt_id",
                        "skill_name",
                        "record_id",
                        "source_id",
                    )
                ):
                    target = candidate
                    break
        elif identity.widget_id:
            try:
                target = owner.query_one(f"#{identity.widget_id}", Widget)
            except (NoMatches, QueryError):
                target = None
        if (
            self.focused is not outgoing_focus
            and self.focused is not None
            and self.focused is not target
        ):
            if self._library_entry_focus_capture is capture:
                self._library_entry_focus_capture = None
            return False
        if target is not None and not getattr(target, "disabled", False):
            self.set_focus(target, scroll_visible=False)
        if identity.scroll_offset is not None and hasattr(owner, "scroll_to"):
            owner.scroll_to(
                x=identity.scroll_offset[0],
                y=identity.scroll_offset[1],
                animate=False,
                force=True,
            )
        if self._library_entry_focus_capture is capture:
            self._library_entry_focus_capture = None
        return True

    def _finish_library_entry_canvas_sync(
        self,
        identity: LibraryEntryFocusIdentity | None,
        *,
        generation: int,
        route_key: tuple[object, ...],
    ) -> bool:
        """Restore focus/scroll and complete one generation in one callback."""
        focus_is_current = True
        if identity is not None:
            focus_is_current = self._restore_library_entry_focus(
                identity,
                generation=generation,
                route_key=route_key,
            )
        self._complete_library_entry_reconcile(generation, route_key)
        return focus_is_current

    def _library_entry_reconcile_is_current(
        self, generation: int, route_key: tuple[object, ...]
    ) -> bool:
        """Return whether deferred entry work still owns this screen route."""
        return (
            self.is_mounted
            and generation == self._library_snapshot_state_generation
            and route_key == self._library_entry_route_key()
        )

    def _schedule_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> None:
        """Queue one generation/route-specific DOM projection on this pump."""
        pending = (generation, route_key)
        if self._library_entry_reconcile_pending == pending:
            return
        self._library_entry_reconcile_pending = pending
        self.call_later(self._reconcile_library_entry_state, generation, route_key)

    def _complete_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> None:
        """Mark a still-current snapshot generation as rendered."""
        if generation != self._library_snapshot_state_generation:
            return
        if route_key != self._library_entry_route_key():
            return
        self._library_snapshot_rendered_generation = generation
        self._library_entry_reconcile_dirty = False
        self._library_entry_reconcile_pending = None
        self._library_entry_reconcile_retry_generation = None
        if self._notes_state.pending_focus_waits_for_snapshot:
            # Notes Back waits for the fresh list projection so its row and
            # scroll receipt cannot be overwritten by the snapshot-driven
            # list sync. The pending identity is Notes-owned and generation
            # guarded; all other destinations are a no-op here.
            self.call_after_refresh(self._release_library_notes_focus_after_snapshot)

    def _supersede_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Release markers owned by one stale reconciliation callback."""
        pending = (generation, route_key)
        if self._library_entry_reconcile_pending == pending:
            self._library_entry_reconcile_pending = None
            if self._library_entry_reconcile_retry_generation == pending:
                self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.SUPERSEDED

    def _retry_or_fail_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Retry one still-current missing target, then leave it dirty."""
        if generation != self._library_snapshot_state_generation:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if route_key != self._library_entry_route_key():
            return self._supersede_library_entry_reconcile(generation, route_key)
        self._library_entry_reconcile_dirty = True
        pending = (generation, route_key)
        if self._library_entry_reconcile_retry_generation != pending:
            self._library_entry_reconcile_retry_generation = pending
            self._library_entry_reconcile_pending = pending
            self.call_later(self._reconcile_library_entry_state, generation, route_key)
            return LibraryEntryReconcileResult.FAILED
        self._library_entry_reconcile_pending = None
        self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.FAILED

    def _fail_library_entry_reconcile(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Leave a failed generation dirty and release its owned markers."""
        pending = (generation, route_key)
        self._library_entry_reconcile_dirty = True
        if self._library_entry_reconcile_pending == pending:
            self._library_entry_reconcile_pending = None
            if self._library_entry_reconcile_retry_generation == pending:
                self._library_entry_reconcile_retry_generation = None
        return LibraryEntryReconcileResult.FAILED

    def _build_library_entry_active_child(self) -> Widget | None:
        """Build the active entry-owned child from the latest screen state."""
        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        if shell.canvas_kind == "conversations":
            state = self._build_library_conversations_state()
            self._conversations_controller._adopt_library_conversation_state_selection(
                state.selected_id
            )
            return LibraryConversationsCanvas(state, id="library-conversations-canvas")
        if shell.canvas_kind == "media":
            # Every media view (list / viewer / trash) resolves through the
            # one shared builder -- the duplicated "trash" check that used
            # to live here is exactly what let the builder itself go
            # missing one (task-21116 review, M1).
            return self._build_library_media_active_child()
        if shell.canvas_kind in (
            LIBRARY_CANVAS_KIND_NOTES,
            LIBRARY_CANVAS_KIND_NOTES_CREATE,
        ):
            if self._notes_state.source == LIBRARY_NOTES_SOURCE_FILES:
                return self._notes_state.file_notes_workspace or Static(
                    "Opening File Notesâ€¦",
                    id="library-file-notes-loading",
                    classes="destination-purpose",
                    markup=False,
                )
            return LibraryNotesCanvas(
                **self._library_notes_list_canvas_kwargs(),
                id="library-notes-canvas",
            )
        if shell.canvas_kind == "prompts":
            return LibraryPromptsListCanvas(
                **self._library_prompts_canvas_kwargs(),
                id="library-prompts-canvas",
            )
        if shell.canvas_kind == "skills":
            return LibrarySkillsListCanvas(
                **self._skills_controller._library_skills_canvas_kwargs(),
                id="library-skills-canvas",
            )
        if shell.canvas_kind == "collections":
            # Collections changes the whole route topology (rail scopes +
            # Items + Work), so the ordinary one-child replacement seam must
            # fall through to the central recompose path.
            return None
        if shell.canvas_kind == "export":
            return LibraryExportCanvas(
                self._build_library_export_state(),
                id="library-export-canvas",
            )
        if shell.canvas_kind == "search":
            return LibrarySearchRagPanel(
                self._library_rag_panel_state(),
                id="library-search-rag-panel",
            )
        if shell.canvas_kind == "ingest-media":
            return LibraryIngestCanvas(
                self._build_library_ingest_state(),
                external_busy=self._library_external_submit_busy,
                external_status=self._library_external_submit_status,
                id="library-ingest-canvas",
            )
        if shell.canvas_kind == "handoff":
            return LibraryStudyHandoffCanvas(
                self._library_study_handoff_canvas_state(shell.canvas_target),
                id="library-study-handoff-canvas",
            )
        if shell.canvas_kind == "empty":
            return LibraryLandingCanvas(
                self._library_landing_canvas_state(),
                id="library-landing-canvas",
            )
        return None

    def _sync_library_entry_owner_from_current_state(self, owner: Widget) -> bool:
        """Re-read state into a matching retained owner after an await."""
        if isinstance(owner, LibraryMediaViewer):
            return self._sync_library_media_viewer_state(owner)
        kind = None
        if isinstance(owner, LibraryConversationsCanvas):
            kind = "conversations"
        elif isinstance(owner, LibraryMediaCanvas):
            kind = "media"
        elif isinstance(owner, LibraryMediaTrashCanvas):
            kind = "media-trash"
        elif isinstance(owner, LibraryNotesCanvas):
            kind = "notes"
        elif isinstance(owner, LibraryPromptsListCanvas):
            kind = "prompts"
        elif isinstance(owner, LibrarySkillsListCanvas):
            kind = "skills"
        elif isinstance(owner, LibraryExportCanvas):
            kind = "export"
        elif isinstance(owner, LibraryLandingCanvas):
            kind = "landing"
        elif isinstance(owner, LibraryStudyHandoffCanvas):
            kind = "handoff"
        if kind is None:
            return False
        return _sync_library_canvas(
            self,
            kind,
            allow_screen_fallback=False,
            projection_owned=True,
            sync_prompt_work=kind != "prompts",
        )

    async def _repair_library_entry_canvas_owner(self) -> bool:
        """Converge an interrupted child swap on the latest route, in place.

        Two review-round (m3) hardenings:

        * the generation/route pair is captured AFTER the builder runs.
          ``_build_library_entry_active_child`` RESOLVES state as it builds
          (the media arm mirrors the resolved ``_selected_media_id`` back
          onto the screen, and that field is part of the route key), so
          capturing first made this loop see its own builder's resolution
          as a newer navigation -- the identical shape as the supersede
          defect found in ``_apply_library_open_item_surface``. It
          self-healed in one iteration, but only by spinning.
        * the iteration count is bounded. Every ``continue`` path here is
          await-free, so a mismatch that does NOT clear would spin this
          loop hot rather than merely retry it.
        """
        mount_failures = 0
        # Bounded purely as a hot-spin guard: convergence normally happens
        # on the first or second pass.
        for _attempt in range(8):
            if not getattr(self, "_is_mounted", False):
                break
            replacement = self._build_library_entry_active_child()
            if replacement is None:
                return False
            # Captured AFTER the builder -- see the docstring.
            generation = self._library_snapshot_state_generation
            route_key = self._library_entry_route_key()
            canvas_host = self._library_entry_canvas_host()
            if canvas_host is None:
                return False
            owner = self._library_entry_canvas_owner()
            if (
                owner is not None
                and type(owner) is type(replacement)
                and owner.id == replacement.id
            ):
                if self._library_entry_reconcile_is_current(generation, route_key):
                    return self._sync_library_entry_owner_from_current_state(owner)
                continue
            # This loop detaches the host's child across awaits too, so it
            # holds the same projection marker: a ``_sync_library_canvas``
            # landing inside the window must suppress its whole-screen
            # fallback rather than race a duplicate-id canvas into the
            # mount (review round, M3).
            self._library_canvas_projection_depth += 1
            try:
                outgoing = tuple(canvas_host.children)
                for child in outgoing:
                    child.display = False
                if outgoing:
                    await canvas_host.remove_children(outgoing)
                if not self._library_entry_reconcile_is_current(generation, route_key):
                    continue
                await canvas_host.mount(replacement)
                if not self._library_entry_reconcile_is_current(generation, route_key):
                    continue
                return self._sync_library_entry_owner_from_current_state(replacement)
            except Exception:
                mount_failures += 1
                logger.debug("Library entry canvas repair attempt failed.")
                if mount_failures >= 2:
                    return False
            finally:
                self._finish_library_canvas_projection()
        return False

    def _schedule_library_entry_canvas_repair(self) -> None:
        """Project already-settled state under fresh generation authority."""
        if getattr(self, "_is_mounted", False):
            self.call_later(self._repair_library_entry_canvas_owner)

    def _finish_library_canvas_projection(self) -> None:
        """Close one projection window and replay any suppressed state sync."""

        self._library_canvas_projection_depth = max(
            0, self._library_canvas_projection_depth - 1
        )
        if (
            self._library_canvas_projection_depth == 0
            and self._library_canvas_resync_pending
        ):
            self._library_canvas_resync_pending = False
            self._schedule_library_entry_canvas_repair()

    async def _replace_library_canvas_child(
        self,
        widget: Widget,
        *,
        generation: int,
        route_key: tuple[object, ...],
        rail_mode: str = "sync",
        then: Callable[[], None] | None = None,
    ) -> LibraryEntryReconcileResult:
        """Replace the active canvas child only for the current generation/route.
        Check ownership before mutations and after awaits; resync the mounted owner
        from current state so suspension cannot strand a stale constructor snapshot.

        Args:
            widget: Destination child.
            generation: Projection generation.
            route_key: Projection route.
            rail_mode: "sync" rebuilds counts/sections; "selection" patches only rows.
            then: Follow-up after the owner's own sync recompose, only if applied.
                Measuring earlier can clamp scroll against children about to detach."""
        if not self._library_entry_reconcile_is_current(generation, route_key):
            return LibraryEntryReconcileResult.SUPERSEDED

        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        try:
            rail = self.query_one("#library-rail", LibraryRail)
            header = self.query_one("#library-header-line", Static)
        except (NoMatches, QueryError):
            return LibraryEntryReconcileResult.FAILED
        canvas_host = self._library_entry_canvas_host()
        if canvas_host is None:
            return LibraryEntryReconcileResult.FAILED

        focus_identity = self._capture_library_entry_focus()
        restore_focus = (
            partial(
                self._restore_library_entry_focus,
                focus_identity,
                generation=generation,
                route_key=route_key,
            )
            if focus_identity is not None
            else None
        )
        try:
            if rail_mode == "selection":
                rail.apply_selection(
                    shell,
                    lifecycle=self._library_lifecycle,
                    onboarding_all_empty=self._library_onboarding_all_empty,
                )
            else:
                rail.sync_state(
                    shell,
                    self._library_rail_preferences(),
                    query=self._library_rail_search_value(),
                    lifecycle=self._library_lifecycle,
                    onboarding_all_empty=self._library_onboarding_all_empty,
                    workspace_handoff_action=self._workspace_handoff_action_state(
                        self._library_workspace_depth_state()
                    ),
                    workspace_handoff_summary=self._workspace_handoff_summary_label(
                        self._library_workspace_depth_state()
                    ),
                )
            header_renderable = header.renderable
            header_text = getattr(header_renderable, "plain", str(header_renderable))
            expected_header = self._library_header_line(shell.header_line)
            if header_text != expected_header:
                header.update(expected_header)
            if self.is_running:
                self.app.capture_mouse(None)
        except Exception:
            logger.debug("Strict Library entry shell synchronization failed.")
            if restore_focus is not None:
                restore_focus()
            return LibraryEntryReconcileResult.FAILED

        if not self._library_entry_reconcile_is_current(generation, route_key):
            return LibraryEntryReconcileResult.SUPERSEDED

        # From here the canvas host's child is detached across awaits.
        # Mark the window so a ``_sync_library_canvas`` landing inside it
        # suppresses its whole-screen fallback instead of racing a
        # duplicate-id canvas into the in-flight mount (review round, M3).
        # try/finally rather than an inline guard: this region has eight
        # early returns.
        self._library_canvas_projection_depth += 1
        try:
            return await self._project_library_canvas_child(
                widget,
                canvas_host=canvas_host,
                generation=generation,
                route_key=route_key,
                focus_identity=focus_identity,
                restore_focus=restore_focus,
                then=then,
            )
        finally:
            self._finish_library_canvas_projection()

    async def _project_library_canvas_child(
        self,
        widget: Widget,
        *,
        canvas_host: Vertical,
        generation: int,
        route_key: tuple[object, ...],
        focus_identity: LibraryEntryFocusIdentity | None,
        restore_focus: Callable[[], bool] | None,
        then: Callable[[], None] | None,
    ) -> LibraryEntryReconcileResult:
        """Swap the canvas host's child and synchronize the new owner.

        Split out of ``_replace_library_canvas_child`` purely so that its
        caller can hold ``_library_canvas_projection_depth`` across every
        one of this region's early-return paths (review round, M3).
        """
        outgoing = tuple(canvas_host.children)
        try:
            for child in outgoing:
                child.display = False
            if outgoing:
                await canvas_host.remove_children(outgoing)
        except Exception:
            logger.debug("Strict Library entry canvas removal failed.")
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.FAILED

        if not self._library_entry_reconcile_is_current(generation, route_key):
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.SUPERSEDED
        try:
            await canvas_host.mount(widget)
        except Exception:
            logger.debug("Strict Library entry canvas mount failed.")
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.FAILED
        if not self._library_entry_reconcile_is_current(generation, route_key):
            await self._repair_library_entry_canvas_owner()
            return LibraryEntryReconcileResult.SUPERSEDED

        sync_kind: str | None = None
        if isinstance(widget, LibraryConversationsCanvas):
            sync_kind = "conversations"
        elif isinstance(widget, LibraryMediaCanvas):
            sync_kind = "media"
        elif isinstance(widget, LibraryNotesCanvas):
            sync_kind = "notes"
        elif isinstance(widget, LibraryPromptsListCanvas):
            sync_kind = "prompts"
        elif isinstance(widget, LibrarySkillsListCanvas):
            sync_kind = "skills"
        elif isinstance(widget, LibraryExportCanvas):
            sync_kind = "export"
        elif isinstance(widget, LibraryMediaViewer):
            if not self._sync_library_media_viewer_state(widget):
                return LibraryEntryReconcileResult.FAILED
        follow_up: Callable[[], bool | None] | None = restore_focus
        if then is not None:
            if restore_focus is None:
                follow_up = then
            else:

                def follow_up(
                    _restore: Callable[[], bool] = restore_focus,
                    _then: Callable[[], None] = then,
                ) -> bool:
                    # Preserve the restore's veto-relevant return while
                    # still running the caller's follow-up.
                    restored = _restore()
                    _then()
                    return restored

        if sync_kind is not None:
            capture = self._library_entry_focus_capture
            if not _sync_library_canvas(
                self,
                sync_kind,
                then=follow_up,
                allow_screen_fallback=False,
                notes_focus_identity=(
                    capture.notes_identity
                    if capture is not None and capture.identity is focus_identity
                    else None
                ),
                projection_owned=True,
            ):
                return LibraryEntryReconcileResult.FAILED
        elif then is not None:
            # No owner-driven sync recompose to order against (loading
            # Static, media viewer, collections): after-refresh is the
            # settled point.
            self.call_after_refresh(then)
        self._apply_library_notes_stage_visibility()
        self._apply_library_notes_footer_context()
        return LibraryEntryReconcileResult.APPLIED

    async def _apply_library_open_item_surface(
        self,
        build: Callable[[], Widget],
        *,
        then: Callable[[], None] | None = None,
    ) -> None:
        """Project selected destination state with canvas-only replacement.
        Call after updating row/view/IDs; synchronize rail/header/footer in place.

        Args:
            build: Lazy destination builder; failure uses whole-screen fallback.
            then: Run after mounted-owner synchronization settles. On fallback run
                immediately after refresh, matching legacy order; drop if superseded."""
        if not self.is_mounted:
            # Parity with the retired unconditional refresh: an unmounted
            # screen simply records the recompose request for mount time.
            self.refresh(recompose=True)
            if then is not None:
                then()
            return
        self._advance_library_stage_interaction()
        self._register_footer_shortcuts()
        # Crossing the Notes boundary is STRUCTURAL: the Database/Files
        # source strip is route-owned chrome composed OUTSIDE the canvas
        # host (above the shell grid), so adding/removing it must go
        # through the central whole-screen seam -- the same rule
        # ``_replace_library_browse_canvas`` enforces. Every other
        # transition keeps the targeted path.
        destination_shell: LibraryShellState | None = None
        try:
            destination_shell = build_library_shell_state(
                self._build_library_shell_input(),
                selected_row_id=self._library_selected_row_id,
            )
            strip_mounted = bool(self.query("#library-notes-source-strip"))
            strip_needed = (
                destination_shell.canvas_kind in LIBRARY_NOTES_SOURCE_STRIP_CANVAS_KINDS
            )
        except Exception:
            logger.debug("Library open-surface strip probe failed.", exc_info=True)
            strip_mounted, strip_needed = False, True
        adaptive_shell_selectors = {
            LIBRARY_CANVAS_KIND_NOTES: ".library-notes-route",
            LIBRARY_CANVAS_KIND_NOTES_CREATE: ".library-notes-route",
            "prompts": "#library-prompts-reader-shell",
            "skills": "#library-skills-reader-shell",
            "collections": "#library-collections-reader-shell",
            "conversations": "#library-conversations-reader-shell",
            "media": ".library-media-route",
        }
        destination_reader = adaptive_shell_selectors.get(
            destination_shell.canvas_kind if destination_shell is not None else ""
        )
        mounted_reader = next(
            (
                selector
                for selector in set(adaptive_shell_selectors.values())
                if self.query(selector)
            ),
            None,
        )
        if strip_mounted != strip_needed or mounted_reader != destination_reader:
            await self.recompose()
            if then is not None:
                self.call_after_refresh(then)
            return
        try:
            widget = build()
        except Exception:
            logger.debug("Targeted Library open-surface build failed.", exc_info=True)
            widget = None
        if widget is None:
            self.refresh(recompose=True)
            if then is not None:
                then()
            return
        # Captured AFTER ``build()``: the state builders are allowed to
        # RESOLVE state as they build (``_build_library_media_active_child``
        # mirrors the resolved ``_media_state.selected_media_id`` back onto
        # the screen when the requested row no longer exists), and that field
        # is part of the route key. Capturing before the build made the
        # replacement seam see its own builder's resolution as a newer
        # navigation and silently SUPERSEDE the projection -- reproduced:
        # viewer Back after the opened row was deleted left the dead viewer
        # on screen while the state said "list".
        generation = self._library_snapshot_state_generation
        route_key = self._library_entry_route_key()
        try:
            result = await self._replace_library_canvas_child(
                widget,
                generation=generation,
                route_key=route_key,
                # A per-click open moves only the rail SELECTION; counts and
                # sections are untouched, so patch the two affected rows in
                # place instead of recreating every rail row per click.
                rail_mode="selection",
                then=then,
            )
        except Exception:
            logger.debug(
                "Targeted Library open-surface projection failed.", exc_info=True
            )
            result = LibraryEntryReconcileResult.FAILED
        if result is LibraryEntryReconcileResult.FAILED:
            self.refresh(recompose=True)
            if then is not None:
                then()
        elif (
            result is LibraryEntryReconcileResult.SUPERSEDED
            and then is not None
            and route_key == self._library_entry_route_key()
        ):
            # A GENERATION-only supersede is not a navigation (review round,
            # M4). ``_library_entry_reconcile_is_current`` compares the
            # snapshot generation as well as the route key, and the ORDINARY
            # local-source snapshot bumps that generation -- one that
            # ``_exit_library_media_viewer`` itself kicks (via
            # ``_load_library_media_list_if_needed``) a line before
            # scheduling this projection. A snapshot landing mid-await
            # therefore dropped the follow-up, silently losing BOTH the
            # task-2856 AC1 first-row focus and the media_return scroll
            # restore that the pre-conversion code armed unconditionally.
            #
            # The route is unchanged here, so the destination is still ours
            # and the follow-up is still meaningful; the reconcile pass the
            # new generation schedules repaints the canvas. A genuine
            # ROUTE-change supersede still skips it -- that is the
            # TASK-15706 transitioning-surface rule, and it is the only
            # case the branch below now covers.
            then()
        # A ROUTE-change SUPERSEDED is deliberately NOT a fallback: the route
        # moved mid-await, so a newer navigation owns the canvas and will
        # paint (or already painted) its own surface -- rebuilding the
        # whole screen here is exactly the transitioning-surface stomp
        # lessons-testing-evidence.md records for TASK-15706.

    async def _apply_library_media_active_surface(self) -> None:
        return await self._media_controller._apply_library_media_active_surface()

    def _sync_library_media_surfaces_or_recompose(self) -> None:
        """Patch the mounted Reader and the Items rows in place, else recompose.

        The shared tail of the two Media sync seams (task-28009 review M-3).
        A viewer-scoped sync that succeeds must repaint the Items rows beside
        it too: the row's review-state slot moves on a done mark that loads no
        new item (`m`, and the final `]` completion gesture). A viewer that is
        gone, or a sync that reports nothing patched, falls back to the
        whole-screen recompose, which rebuilds both surfaces anyway.
        """
        viewer = self._mounted_library_media_viewer()
        if viewer is None or not self._sync_library_media_viewer_state(viewer):
            self.refresh(recompose=True)
            return
        try:
            canvas = self.query_one("#library-media-canvas", LibraryMediaCanvas)
        except (NoMatches, QueryError):
            return
        canvas.apply_reader_state(self._build_library_media_state())

    async def _apply_library_media_list_return(self, media_return: _LibraryMediaReturnReceipt | None) -> None:
        return await self._media_controller._apply_library_media_list_return(media_return)

    async def _reconcile_library_entry_state(
        self, generation: int, route_key: tuple[object, ...]
    ) -> LibraryEntryReconcileResult:
        """Project one current snapshot into the mounted rail and canvas."""
        pending = (generation, route_key)
        if not self.is_attached:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if generation != self._library_snapshot_state_generation:
            return self._supersede_library_entry_reconcile(generation, route_key)
        if route_key != self._library_entry_route_key():
            return self._supersede_library_entry_reconcile(generation, route_key)
        if (
            not self._library_entry_reconcile_dirty
            and self._library_snapshot_rendered_generation == generation
        ):
            if self._library_entry_reconcile_pending == pending:
                self._library_entry_reconcile_pending = None
            self._library_entry_reconcile_retry_generation = None
            return LibraryEntryReconcileResult.ALREADY_CURRENT

        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        try:
            rail = self.query_one("#library-rail", LibraryRail)
            header = self.query_one("#library-header-line", Static)
        except (NoMatches, QueryError):
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        identity = self._capture_library_entry_focus()
        restore_focus = (
            partial(
                self._restore_library_entry_focus,
                identity,
                generation=generation,
                route_key=route_key,
            )
            if identity is not None
            else None
        )
        try:
            rail.sync_state(
                shell,
                self._library_rail_preferences(),
                query=self._library_rail_search_value(),
                lifecycle=self._library_lifecycle,
                onboarding_all_empty=self._library_onboarding_all_empty,
                workspace_handoff_action=self._workspace_handoff_action_state(
                    self._library_workspace_depth_state()
                ),
                workspace_handoff_summary=self._workspace_handoff_summary_label(
                    self._library_workspace_depth_state()
                ),
            )
            header_renderable = header.renderable
            header_text = getattr(header_renderable, "plain", str(header_renderable))
            expected_header = self._library_header_line(shell.header_line)
            if header_text != expected_header:
                header.update(expected_header)
        except Exception:
            logger.debug("Library snapshot shell reconciliation failed.")
            if restore_focus is not None:
                restore_focus()
            return self._fail_library_entry_reconcile(generation, route_key)

        sync_kind: str | None = None
        expected_selector = ""
        replacement: Widget | None = None
        local_list_surface = False
        if shell.canvas_kind == "conversations":
            local_list_surface = True
            expected_selector = "#library-conversations-canvas"
            # Conversation paging has its own failure and retry state. A broad
            # source outage must not replace a successful independent page.
            conversations_state = self._build_library_conversations_state()
            self._conversations_controller._adopt_library_conversation_state_selection(
                conversations_state.selected_id
            )
            sync_kind = "conversations"
            replacement = LibraryConversationsCanvas(
                conversations_state,
                id="library-conversations-canvas",
            )
        elif (
            shell.canvas_kind
            in (LIBRARY_CANVAS_KIND_NOTES, LIBRARY_CANVAS_KIND_NOTES_CREATE)
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            # task-32245: NOTES_CREATE belongs here too. ``compose_content``
            # mounts the shared "Loading local Library sources…" placeholder
            # for BOTH kinds (they share one retained Items pane), but this
            # reconciler only knew ``notes`` -- so a first entry that landed
            # on New note before the snapshot resolved (the wizard's "Write
            # your first note" hand-off, the Console setup card's notes
            # action, a cold command-palette "new_note") kept that
            # placeholder for the life of the visit. ``_build_library_entry_
            # active_child`` and ``_LIBRARY_RESIDENT_CANVAS_OWNER_ROWS``
            # already pair the two kinds; this site was the odd one out.
            local_list_surface = True
            expected_selector = "#library-notes-canvas"
            if self._library_lookup_error is None:
                sync_kind = "notes"
                replacement = LibraryNotesCanvas(
                    **self._library_notes_list_canvas_kwargs(),
                    id="library-notes-canvas",
                )
        elif shell.canvas_kind == "prompts":
            local_list_surface = True
            expected_selector = "#library-prompts-canvas"
            if self._library_lookup_error is None:
                sync_kind = "prompts"
                replacement = LibraryPromptsListCanvas(
                    **self._library_prompts_list_canvas_kwargs(),
                    id="library-prompts-canvas",
                )
        elif shell.canvas_kind == "skills":
            local_list_surface = True
            expected_selector = "#library-skills-canvas"
            # task-31263: Skills state is registry/trust-worker owned,
            # independent of the Library source snapshot -- a sources outage
            # must not replace a working Skills list with the source-error
            # surface. Mirrors compose_content's ungated Skills mount (the
            # same decision, recorded there since the adaptive-reader
            # migration); this reconcile site was the un-fixed twin.
            sync_kind = "skills"
            replacement = LibrarySkillsListCanvas(
                **self._library_skills_list_canvas_kwargs(),
                id="library-skills-canvas",
            )
        elif shell.canvas_kind == "handoff":
            sync_kind = "handoff"
            expected_selector = "#library-study-handoff-canvas"
        elif shell.canvas_kind == "empty":
            sync_kind = "landing"
            expected_selector = "#library-landing-canvas"

        if (
            local_list_surface
            and shell.canvas_kind not in {"prompts", "skills", "conversations"}
            and self._library_lookup_error is not None
        ):
            expected_selector = "#library-canvas-error"
            # An already-mounted surface is never remounted below (no
            # ``sync_kind``), so a repeat failure repaints here or nowhere.
            # PR M carry M3/M6: only a SHAPE change (bare Static <-> callout
            # with its own Retry) is worth a replacement widget -- clearing
            # ``expected_selector`` sends it down the mount path, which
            # removes the stale node first.
            was_mounted = bool(self.query(expected_selector))
            if not self._sync_library_canvas_error():
                replacement = self._library_canvas_error_widget()
                if was_mounted:
                    expected_selector = ""

        if expected_selector and self.query(expected_selector):
            if sync_kind is None:
                if restore_focus is not None:
                    restore_focus()
                self._complete_library_entry_reconcile(generation, route_key)
                return LibraryEntryReconcileResult.APPLIED
            capture = self._library_entry_focus_capture
            finish = partial(
                self._finish_library_entry_canvas_sync,
                identity,
                generation=generation,
                route_key=route_key,
            )
            if _sync_library_canvas(
                self,
                sync_kind,
                then=finish,
                allow_screen_fallback=False,
                notes_focus_identity=(
                    capture.notes_identity
                    if capture is not None and capture.identity is identity
                    else None
                ),
                deferred_guard=partial(
                    self._library_entry_reconcile_is_current,
                    generation,
                    route_key,
                ),
                sync_prompt_work=sync_kind != "prompts",
            ):
                if sync_kind == "conversations":
                    self._ensure_library_conversation_reader_selection()
                self._library_entry_reconcile_retry_generation = None
                return LibraryEntryReconcileResult.APPLIED
            if restore_focus is not None:
                restore_focus()
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        if local_list_surface and replacement is not None:
            try:
                canvas_host = self._library_entry_canvas_host()
                if canvas_host is None:
                    raise NoMatches("Library canvas host is unavailable")
                outgoing = tuple(canvas_host.children)
                for child in outgoing:
                    child.display = False
                if outgoing:
                    await canvas_host.remove_children(outgoing)
                if generation != self._library_snapshot_state_generation:
                    await self._repair_library_entry_canvas_owner()
                    return self._supersede_library_entry_reconcile(
                        generation, route_key
                    )
                if route_key != self._library_entry_route_key():
                    await self._repair_library_entry_canvas_owner()
                    return self._supersede_library_entry_reconcile(
                        generation, route_key
                    )
                await canvas_host.mount(replacement)
            except Exception:
                logger.debug("Library snapshot canvas replacement failed.")
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )
            if generation != self._library_snapshot_state_generation:
                await self._repair_library_entry_canvas_owner()
                return self._supersede_library_entry_reconcile(generation, route_key)
            if route_key != self._library_entry_route_key():
                await self._repair_library_entry_canvas_owner()
                return self._supersede_library_entry_reconcile(generation, route_key)
            if sync_kind is not None:
                capture = self._library_entry_focus_capture
                finish = partial(
                    self._finish_library_entry_canvas_sync,
                    identity,
                    generation=generation,
                    route_key=route_key,
                )
                if not _sync_library_canvas(
                    self,
                    sync_kind,
                    then=finish,
                    allow_screen_fallback=False,
                    notes_focus_identity=(
                        capture.notes_identity
                        if capture is not None and capture.identity is identity
                        else None
                    ),
                    deferred_guard=partial(
                        self._library_entry_reconcile_is_current,
                        generation,
                        route_key,
                    ),
                    sync_prompt_work=sync_kind != "prompts",
                ):
                    return self._retry_or_fail_library_entry_reconcile(
                        generation, route_key
                    )
                if sync_kind == "conversations":
                    self._ensure_library_conversation_reader_selection()
                # A freshly constructed replacement already carries the
                # target state, so its sync may be a no-op and never fire the
                # queued after-recompose completion.  APPLIED must still
                # settle this generation; the guarded focus callback can run
                # later without changing that ownership result.
                self._complete_library_entry_reconcile(generation, route_key)
            else:
                if restore_focus is not None:
                    restore_focus()
                self._complete_library_entry_reconcile(generation, route_key)
            return LibraryEntryReconcileResult.APPLIED

        if expected_selector:
            if restore_focus is not None:
                restore_focus()
            return self._retry_or_fail_library_entry_reconcile(generation, route_key)

        if shell.canvas_kind == "media":
            viewer = self._mounted_library_media_viewer()
            if viewer is None or not self._sync_library_media_viewer_state(viewer):
                if restore_focus is not None:
                    restore_focus()
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )

        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_SEARCH:
            try:
                self._sync_library_rag_scope_toggle_and_run_gate_widgets()
            except Exception:
                logger.debug("Library Search/RAG snapshot sync failed.")
                if restore_focus is not None:
                    restore_focus()
                return self._retry_or_fail_library_entry_reconcile(
                    generation, route_key
                )

        if restore_focus is not None:
            restore_focus()
        self._complete_library_entry_reconcile(generation, route_key)
        return LibraryEntryReconcileResult.APPLIED

    def _library_canvas_error_widget(self) -> Widget:
        """Build the browse canvas's failed-source surface.

        task-31948: a failure a refetch can clear (the snapshot's own
        deadline/hard-failure states, the only ones carrying
        ``LIBRARY_SOURCE_RETRY_ID``) gets the same one-callout grammar the
        landing hub already paints -- reason and Retry side by side, the
        Retry running the same ``_refresh_local_source_snapshot``. Before
        this, a browse row's only recovery from a failed snapshot was to
        leave the surface and come back. Failures a Retry cannot clear (a
        policy denial, a runtime with no source services) keep the bare
        sentence: an inert Retry is worse than none.

        Returns:
            The callout, or the plain error Static. Either way it is the
            ``#library-canvas-error`` node the reconcile mounts and
            ``_sync_library_canvas_error`` refreshes.
        """
        failure = self._library_source_load_failure()
        if failure is None:
            return Static(
                self._library_lookup_error or "",
                id="library-canvas-error",
                classes="destination-purpose",
                markup=False,
            )
        return load_failure_callout(
            failure,
            id="library-canvas-error",
            copy_id="library-canvas-error-copy",
            retry_id=LIBRARY_SOURCE_RETRY_ID,
        )

    def _sync_library_canvas_error(self) -> bool:
        """Refresh a MOUNTED browse error surface in place.

        The reconcile treats an already-mounted ``#library-canvas-error``
        as current and returns without remounting it, so without this a
        Retry against a failure that has not cleared would repaint nothing
        at all -- the "Retry reads as inert" bug task-31632 fixed on the
        hub, where a canvas ``sync_state`` does this job instead.

        PR M carry M2/M3: the shared sync moves the SEVERITY TINT with the
        copy (a Retry can turn a deadline into a hard failure), and reports
        a shape change -- the bare Static a failure with no Retry paints,
        and the callout -- as "remount me" instead of silently no-op'ing.

        Returns:
            ``True`` when the mounted node still fits the current failure
            and was repainted; ``False`` when the caller must build and
            mount the other shape (including when nothing is mounted yet).
        """
        node = next(iter(self.query("#library-canvas-error")), None)
        if node is None:
            return False
        failure = self._library_source_load_failure()
        if failure is None:
            # A failure a Retry cannot clear (a policy denial, a runtime
            # with no source services) keeps the bare sentence.
            if not isinstance(node, Static):
                return False
            node.update(self._library_lookup_error or "")
            return True
        return sync_load_failure_callout(node, failure)

    def _apply_local_source_snapshot(
        self,
        records: dict[str, tuple[Mapping[str, Any], ...]],
        counts: dict[str, int],
        total_known: dict[str, bool],
        lookup_error: str | None = None,
        recovery_state: DestinationRecoveryState | None = None,
        study_counts: dict[str, int | None] | None = None,
        *,
        schedule_reconcile: bool = True,
    ) -> bool:
        normalized_records = (
            self._conversations_controller._carry_selected_conversation_into_snapshot(
                dict(records)
            )
        )
        normalized_counts = dict(counts)
        normalized_total_known = dict(total_known)
        normalized_study_counts = (
            dict(study_counts)
            if study_counts is not None
            else {"study_decks": None, "flashcards_due": None, "quizzes": None}
        )
        if recovery_state is not None:
            previous_recovery = self._library_lookup_recovery_state
            if (
                previous_recovery is not None
                and dataclasses.replace(recovery_state, attempt=1)
                == dataclasses.replace(previous_recovery, attempt=1)
            ):
                # task-31632 final review I-1: a byte-identical repeat
                # failure must still visibly repaint, never go silent --
                # bumping ``attempt`` breaks the equality check below (and
                # the ones above never differ for a repeat, since records/
                # counts/lookup_error are just as static) so the callout
                # reads a fresh attempt number instead of nothing at all.
                recovery_state = dataclasses.replace(
                    recovery_state, attempt=previous_recovery.attempt + 1
                )
                # Keep the two in sync: every existing ``_library_lookup_
                # error`` consumer (the rail's Details line, and the
                # ``#library-canvas-error`` surface -- task-31948's callout
                # for a retryable failure, the bare Static otherwise)
                # already reads ``recovery_state.message`` through this
                # field.
                lookup_error = recovery_state.message
        presentation_changed = not self._library_loaded or (
            normalized_records != self._local_source_records
            or normalized_counts != self._local_source_counts
            or normalized_total_known != self._local_source_total_known
            or lookup_error != self._library_lookup_error
            or recovery_state != self._library_lookup_recovery_state
            or normalized_study_counts != self._library_study_counts
        )
        if not presentation_changed:
            if (
                schedule_reconcile
                and self.is_attached
                and not self._file_notes_active()
                and (
                    self._library_entry_reconcile_dirty
                    or self._library_snapshot_rendered_generation
                    != self._library_snapshot_state_generation
                )
            ):
                self._library_entry_reconcile_dirty = True
                self._schedule_library_entry_reconcile(
                    self._library_snapshot_state_generation,
                    self._library_entry_route_key(),
                )
            return False

        self._local_source_records = normalized_records
        self._local_source_counts = normalized_counts
        self._local_source_total_known = normalized_total_known
        self._library_lookup_error = lookup_error
        self._library_lookup_recovery_state = recovery_state
        self._library_study_counts = normalized_study_counts
        self._library_loaded = True
        self._invalidate_library_workspace_depth_state()
        self._library_snapshot_state_generation += 1
        self._library_entry_reconcile_dirty = True
        if schedule_reconcile and self.is_attached and not self._file_notes_active():
            self._schedule_library_entry_reconcile(
                self._library_snapshot_state_generation,
                self._library_entry_route_key(),
            )
        return True

    def _seed_local_source_snapshot_from_cache(
        self, *, now: float | None = None
    ) -> bool:
        """Apply a recent detached cache snapshot before first composition.

        Called from both ``__init__`` and ``restore_state`` (task-15459) on a
        freshly constructed, not-yet-mounted instance, so a warm revisit's
        FIRST ``compose_content`` already renders the previous visit's data
        instead of the "Loading…" placeholder. Safe to call this early, and
        twice: ``_apply_local_source_snapshot`` only touches the DOM when
        ``self.is_mounted``, which neither call site is, so a hit is a pure
        attribute assignment and a miss is a no-op. ``on_mount`` still owns
        the cache-miss/expired case and the mount-time reconciliation.

        Args:
            now: Monotonic reading to age the cache against, for tests;
                defaults to ``time.monotonic()``.

        Returns:
            True when a fresh snapshot was applied, False on a miss or on a
            cache older than ``LIBRARY_SNAPSHOT_CACHE_TTL_SECONDS``.
        """
        stamp = getattr(self.app_instance, "_library_source_snapshot_cache_stamp", None)
        if not isinstance(stamp, (int, float)) or not math.isfinite(float(stamp)):
            return False
        age = (time.monotonic() if now is None else now) - float(stamp)
        if age < 0 or age >= LIBRARY_SNAPSHOT_CACHE_TTL_SECONDS:
            return False
        snapshot = clone_library_source_snapshot(
            getattr(self.app_instance, "_library_source_snapshot_cache", None)
        )
        if snapshot is None:
            return False
        self._apply_local_source_snapshot(*snapshot, schedule_reconcile=False)
        self._library_snapshot_rendered_generation = (
            self._library_snapshot_state_generation
        )
        self._library_entry_reconcile_dirty = False
        return True

    def _apply_source_snapshot_timeout(self) -> None:
        """Avoid leaving Library in an indefinite loading state."""
        if self._library_loaded:
            return
        self._apply_local_source_snapshot(
            {"notes": (), "media": (), "conversations": ()},
            {"notes": 0, "media": 0, "conversations": 0},
            {"notes": True, "media": True, "conversations": True},
            LIBRARY_SERVICE_ERROR_COPY,
            None,
            {"study_decks": None, "flashcards_due": None, "quizzes": None},
        )

    @staticmethod
    async def _run_library_service_call(
        callable_obj: Any,
        *args: Any,
        isolate_in_worker: bool = False,
        **kwargs: Any,
    ) -> Any:
        if inspect.iscoroutinefunction(callable_obj) and not isolate_in_worker:
            return await callable_obj(*args, **kwargs)

        def invoke_service_in_worker() -> Any:
            result = callable_obj(*args, **kwargs)
            if inspect.isawaitable(result):

                async def await_result() -> Any:
                    return await result

                # Runs via asyncio.to_thread: this thread has no event loop,
                # and the awaitable must complete here so blocking async
                # services stay off the UI loop.
                return asyncio.run(  # policy-exception: worker-thread loop
                    await_result()
                )
            return result

        if isolate_in_worker:
            return await asyncio.to_thread(invoke_service_in_worker)

        result = await asyncio.to_thread(lambda: callable_obj(*args, **kwargs))
        if inspect.isawaitable(result):
            return await result
        return result

    @staticmethod
    def _safe_text(value: Any, fallback: str = "", *, max_length: int = 500) -> str:
        text = sanitize_string(str(value or ""), max_length=max_length).strip()
        if not text:
            return fallback
        text = text.replace("<", "").replace(">", "")
        for pattern in ("javascript:", "onclick=", "onerror="):
            text = text.replace(pattern, "")
        if validate_text_input(text, max_length=max_length, allow_html=False):
            return text
        return fallback

    @staticmethod
    def _sanitize_media_field(value: Any, *, max_length: int) -> str:
        """Sanitize a user-entered media field at the UI boundary.

        Runs the shared ``input_validation`` helpers before the value is
        handed to a persistence service (``update_media_item`` /
        ``create_highlight`` / ``save_analysis_version``), so over-long
        input is truncated and control characters are stripped, and any
        HTML/script markup that trips ``validate_text_input`` is neutralized
        -- keeping unsafe or oversized content from reaching storage. Normal
        text (including a lone ``<``/``>`` in prose) is returned unchanged.

        Args:
            value: The raw widget value to sanitize.
            max_length: Maximum length to allow before truncation.

        Returns:
            The sanitized field value.
        """
        text = sanitize_string(str(value or ""), max_length=max_length)
        if not validate_text_input(text, max_length=max_length, allow_html=False):
            # A dangerous HTML/script pattern was detected: break it up
            # (drop the angle brackets and inline handlers) but keep the
            # rest of the field rather than discarding user content.
            text = text.replace("<", "").replace(">", "")
            for pattern in ("javascript:", "onclick=", "onerror="):
                text = text.replace(pattern, "")
        return text

    @staticmethod
    def _sanitize_note_content(value: Any, *, max_length: int) -> str:
        """Length-cap Library note body content without HTML neutering.

        ``_sanitize_media_field`` is right for short metadata fields (a
        title, a highlight quote), but note bodies routinely contain code
        blocks, HTML/JS snippets in prose, or long-form markdown -- running
        them through the same control-character stripping and
        angle-bracket/``onclick=``-pattern neutering would silently mangle
        legitimate content. The only boundary a note body needs is a hard
        length cap before it reaches the persistence seam.

        Args:
            value: The raw ``TextArea`` text to sanitize.
            max_length: Maximum length to allow before truncation.

        Returns:
            ``value`` unchanged, truncated to ``max_length`` if needed.
        """
        text = str(value or "")
        if len(text) > max_length:
            text = text[:max_length]
        return text

    def _library_note_keywords_from_input(self, raw_value: str) -> list[str] | None:
        """Parse and sanitize the Library note editor's keywords Input.

        Args:
            raw_value: The raw ``#library-note-keywords`` Input value.

        Returns:
            A list of sanitized, non-empty keyword tokens (each capped at
            100 characters), or ``None`` when no keywords were entered --
            matching the ``save_note`` seam's "omit keywords" contract.
        """
        parsed = [item.strip() for item in (raw_value or "").split(",") if item.strip()]
        if not parsed:
            return None
        sanitized = [
            self._sanitize_media_field(item, max_length=100) for item in parsed
        ]
        sanitized = [item for item in sanitized if item]
        return sanitized or None

    def _library_notes_user_id(self) -> str:
        return self._notes_controller._library_notes_user_id()

    @classmethod
    def _source_optional_title(
        cls, source_type: str, record: Mapping[str, Any]
    ) -> str | None:
        """Return a trustworthy raw source title without a display fallback."""

        title_keys_by_source = {
            "notes": ("title", "name", "note_title", "note_name"),
            "media": ("title", "name", "media_title", "file_name", "url"),
            "conversations": ("title", "name", "conversation_title", "label"),
        }
        for key in title_keys_by_source[source_type]:
            title = cls._safe_text(record.get(key))
            if title:
                return title
        return None

    @classmethod
    def _source_title(cls, source_type: str, record: Mapping[str, Any]) -> str:
        return cls._source_optional_title(source_type, record) or "Untitled source"

    @staticmethod
    def _response_records_and_count(
        result: Any,
    ) -> tuple[tuple[Mapping[str, Any], ...], int, bool]:
        total = None
        if isinstance(result, Mapping):
            raw_items = result.get("items")
            pagination = result.get("pagination")
            total = result.get("total")
            if isinstance(pagination, Mapping):
                total = pagination.get("total", pagination.get("total_items", total))
        elif isinstance(result, Sequence) and not isinstance(
            result, (str, bytes, bytearray)
        ):
            raw_items = result
        else:
            raw_items = ()

        records = tuple(
            record for record in tuple(raw_items or ()) if isinstance(record, Mapping)
        )
        total_known = total is not None
        try:
            count = int(total) if total is not None else len(records)
        except (TypeError, ValueError):
            count = len(records)
            total_known = False
        return records, max(count, 0), total_known

    async def _notes_true_count_or_none(self, count_notes: Any, **kwargs: Any) -> int | None:
        return await self._notes_controller._notes_true_count_or_none(count_notes, **kwargs)

    async def _prompts_count_or_none(self, count_prompts: Any, **kwargs: Any) -> int | None:
        return await self._prompts_controller._prompts_count_or_none(count_prompts, **kwargs)

    async def _skills_context_or_none(self, get_context: Any, **kwargs: Any) -> Mapping[str, Any] | None:
        return await self._skills_controller._skills_context_or_none(get_context, **kwargs)

    async def _study_count_or_none(
        self, count_callable: Any, label: str, **kwargs: Any
    ) -> int | None:
        """Fetch a decorative Create-rail count without failing the source snapshot.

        Args:
            count_callable: Bound scope-service count method.
            label: Debug-log label on failure.
            **kwargs: Arguments forwarded to the count method.

        Returns:
            An integer count, or None on failure/noninteger results (uncounted row).
        """
        # SQLite ``:memory:`` connections are thread-local (``threading.local``
        # on ``CharactersRAGDB``) -- only the thread that created the DB has
        # the migrated schema. Forcing this single COUNT(*) query onto a
        # worker thread would open a brand-new, unmigrated in-memory
        # connection and fail. Same guard as
        # ``LibraryLocalRagSearchService._search_conversations``.
        chachanotes_db = getattr(self.app_instance, "chachanotes_db", None)
        isolate_in_worker = not bool(getattr(chachanotes_db, "is_memory_db", False))
        try:
            result = await self._run_library_service_call(
                count_callable, isolate_in_worker=isolate_in_worker, **kwargs
            )
        except Exception:
            logger.opt(exception=True).debug(
                f"Failed to fetch {label} count for Library create rail."
            )
            return None
        return result if isinstance(result, int) else None

    async def _list_local_source_snapshot(
        self,
    ) -> tuple[
        dict[str, tuple[Mapping[str, Any], ...]],
        dict[str, int],
        dict[str, bool],
        str | None,
        DestinationRecoveryState | None,
        dict[str, int | None],
    ]:
        # task-32057 AC#2: the Collections capture total is one more local
        # source count, read here so it lands with the rest of the snapshot
        # and the screen still reconciles exactly ONCE per snapshot pass
        # (``Tests/UI/test_library_entry_compose_once.py``). It is kept out
        # of the shared gather below on purpose: that gather's deadline and
        # its all-or-nothing failure branches would drop the count whenever
        # an UNRELATED source seam fails, which is precisely the "counts
        # disagree" complaint this fixes. It carries its own
        # ``asyncio.wait_for`` on the same constant so being outside that
        # gather does not mean being unbounded.
        #
        # Fix round 2, finding 3: it runs CONCURRENTLY with that gather
        # rather than ahead of it. Awaited serially, the two equal deadlines
        # stacked -- a stalled Collections read plus a stalled source seam
        # took ~10 s while the resulting message says the pass waited 5 s.
        # Started here and awaited below, the two deadlines overlap and the
        # count keeps its independent degradation.
        count_task = asyncio.ensure_future(self._read_library_collections_count())
        notes_service = getattr(self.app_instance, "notes_scope_service", None)
        media_service = getattr(self.app_instance, "media_reading_scope_service", None)
        conversation_service = getattr(
            self.app_instance, "chat_conversation_scope_service", None
        )
        study_service = getattr(self.app_instance, "study_scope_service", None)
        quiz_service = getattr(self.app_instance, "study_quiz_scope_service", None)
        prompt_service = getattr(self.app_instance, "prompt_scope_service", None)
        skills_service = getattr(self.app_instance, "skills_scope_service", None)
        list_notes = getattr(notes_service, "list_notes", None)
        list_media = getattr(media_service, "list_media_items", None)
        list_conversations = getattr(conversation_service, "list_conversations", None)
        count_notes = getattr(notes_service, "count_notes", None)
        count_notes_available = callable(count_notes)
        count_decks = getattr(study_service, "count_decks", None)
        count_due_flashcards = getattr(study_service, "count_due_flashcards", None)
        count_quizzes = getattr(quiz_service, "count_quizzes", None)
        count_prompts = getattr(prompt_service, "count_prompts", None)
        count_prompts_available = callable(count_prompts)
        get_skills_context = getattr(skills_service, "get_context", None)
        get_skills_context_available = callable(get_skills_context)
        notes_user_id = (
            getattr(self.app_instance, "notes_user_id", None) or "default_user"
        )

        empty_records: dict[str, tuple[Mapping[str, Any], ...]] = {
            "notes": (),
            "media": (),
            "conversations": (),
            # Rail-only count carrier; the second slot intentionally stays empty.
            "prompts": (None, ()),
            # Likewise ``(count, context_payload)`` -- see ``__init__``'s
            # comment on this same key.
            "skills": (None, {"available_skills": [], "blocked_skills": []}),
        }
        empty_counts = {"notes": 0, "media": 0, "conversations": 0}
        empty_total_known = {"notes": True, "media": True, "conversations": True}
        empty_study_counts: dict[str, int | None] = {
            "study_decks": None,
            "flashcards_due": None,
            "quizzes": None,
        }
        if not all(
            callable(call) for call in (list_notes, list_media, list_conversations)
        ):
            await count_task
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                LIBRARY_SERVICE_UNAVAILABLE_COPY,
                None,
                empty_study_counts,
            )

        gathered_calls = [
            self._run_library_service_call(
                list_notes,
                scope="local_note",
                limit=LIBRARY_SOURCE_PAGE_SIZES["notes"],
                offset=0,
                user_id=notes_user_id,
                isolate_in_worker=True,
            ),
            self._run_library_service_call(
                list_media,
                mode="local",
                page=1,
                results_per_page=LIBRARY_SOURCE_PAGE_SIZES["media"],
                include_keywords=False,
                isolate_in_worker=True,
            ),
            self._run_library_service_call(
                list_conversations,
                mode="local",
                # "all" spans global- and workspace-scoped conversations:
                # Console chats persisted inside a workspace session are
                # workspace-scoped and would be invisible (and uncounted)
                # under the service's default 'global' scope.
                scope_type="all",
                limit=LIBRARY_SOURCE_PAGE_SIZES["conversations"],
                offset=0,
                isolate_in_worker=True,
            ),
        ]
        # Optional decorative/exact counts are appended (and unpacked back)
        # by key so this stays simple as the number of optional seams
        # grows -- see ``_notes_true_count_or_none``/``_study_count_or_none``
        # for the per-count degrade-to-None contract.
        optional_calls: list[tuple[str, Any]] = []
        if count_notes_available:
            optional_calls.append(
                (
                    "notes_true_count",
                    self._notes_true_count_or_none(
                        count_notes, scope="local_note", user_id=notes_user_id
                    ),
                )
            )
        if callable(count_decks):
            optional_calls.append(
                ("study_decks", self._study_count_or_none(count_decks, "study decks"))
            )
        if callable(count_due_flashcards):
            optional_calls.append(
                (
                    "flashcards_due",
                    self._study_count_or_none(count_due_flashcards, "flashcards due"),
                )
            )
        if callable(count_quizzes):
            optional_calls.append(
                ("quizzes", self._study_count_or_none(count_quizzes, "quizzes"))
            )
        if count_prompts_available:
            optional_calls.append(
                (
                    "prompts_count",
                    self._prompts_count_or_none(count_prompts, mode="local"),
                )
            )
        if get_skills_context_available:
            optional_calls.append(
                (
                    "skills_context",
                    self._skills_context_or_none(get_skills_context, mode="local"),
                )
            )
        gathered_calls.extend(call for _, call in optional_calls)

        try:
            gathered_results = await asyncio.wait_for(
                asyncio.gather(*gathered_calls),
                timeout=LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS,
            )
        except PolicyDeniedError as exc:
            policy_message = self._safe_text(
                exc.user_message, LIBRARY_SERVICE_ERROR_COPY
            )
            recovery_state = policy_denied_recovery_state(
                exc,
                unavailable_what="Use Library sources in Console",
                stable_selector="library-source-error",
                policy_message=policy_message,
            )
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                recovery_state.visible_copy,
                recovery_state,
                empty_study_counts,
            )
        except TimeoutError:
            # task-31632 AC#2: ``asyncio.TimeoutError`` IS ``TimeoutError``
            # on 3.11+, and it must be told apart from a hard failure --
            # collapsed into the same static sentence, a deadline the next
            # attempt may beat read as an indefinite outage. This is the one
            # place the deadline figure is true, so the reason quotes it.
            # Final review I-2: shares the generic branch's one warning
            # (via ``_log_source_snapshot_failure``) with a deadline marker,
            # so a chronic/repeated deadline stays diagnosable off-screen
            # too, without a second ``logger.*`` call site.
            _log_source_snapshot_failure(
                f" (deadline: waited {LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS:g} s)"
            )
            timeout_state = load_failure_recovery_state(
                what=LIBRARY_SOURCE_TIMEOUT_COPY,
                reason=f"waited {LIBRARY_SOURCE_SNAPSHOT_TIMEOUT_SECONDS:g} s",
                retry_id=LIBRARY_SOURCE_RETRY_ID,
                stable_selector=LIBRARY_SOURCE_FAILURE_SELECTOR,
                kind="timeout",
            )
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                timeout_state.message,
                timeout_state,
                empty_study_counts,
            )
        except Exception as exc:
            _log_source_snapshot_failure()
            # ``_retry_failure_reason`` is the shared leak rule the Media
            # callout already applies: an OS/SQLite message is the reader's
            # own words, anything else is reduced to its KIND of failure
            # (task-31944's map, or "an unexpected error") so an arbitrary
            # exception's text -- which can carry a private path -- never
            # reaches the screen.
            failure_state = load_failure_recovery_state(
                what=LIBRARY_SERVICE_ERROR_COPY,
                reason=_retry_failure_reason(exc),
                retry_id=LIBRARY_SOURCE_RETRY_ID,
                stable_selector=LIBRARY_SOURCE_FAILURE_SELECTOR,
            )
            return (
                empty_records,
                empty_counts,
                empty_total_known,
                failure_state.message,
                failure_state,
                empty_study_counts,
            )
        finally:
            # The count read is bounded by its own deadline, started with
            # the gather above, so this settles it without extending the
            # pass -- on every branch, including the returns above.
            await count_task

        notes_result, media_result, conversation_result, *optional_results = (
            gathered_results
        )
        optional_values = dict(
            zip((key for key, _ in optional_calls), optional_results)
        )

        notes_true_count = optional_values.get("notes_true_count")
        prompts_count = optional_values.get("prompts_count")
        skills_context = optional_values.get("skills_context")
        if isinstance(skills_context, Mapping):
            skills_available = skills_context.get("available_skills") or []
            skills_blocked = skills_context.get("blocked_skills") or []
            skills_count: int | None = len(skills_available) + len(skills_blocked)
            skills_payload: Mapping[str, Any] = skills_context
        else:
            skills_count = None
            skills_payload = {"available_skills": [], "blocked_skills": []}
        study_counts: dict[str, int | None] = {
            "study_decks": optional_values.get("study_decks"),
            "flashcards_due": optional_values.get("flashcards_due"),
            "quizzes": optional_values.get("quizzes"),
        }

        notes, notes_count, notes_total_known = self._response_records_and_count(
            notes_result
        )
        if notes_true_count is not None:
            notes_count = notes_true_count
            notes_total_known = True
        media, media_count, media_total_known = self._response_records_and_count(
            media_result
        )
        (
            conversations,
            conversations_count,
            conversations_total_known,
        ) = self._response_records_and_count(conversation_result)
        return (
            {
                "notes": notes,
                "media": media,
                "conversations": conversations,
                # The second slot is permanently empty: Prompt rows are owned
                # by the exact request-tokened browse result, not this sample.
                "prompts": (prompts_count, ()),
                # (count, context_payload) -- see the ``__init__``/
                # ``empty_records`` comments above. ``skills_count`` spans
                # BOTH ``available_skills`` and ``blocked_skills`` (needs
                # review) per the spec's blocked-skills visibility rule, and
                # degrades to ``None``/empty payload whenever the local
                # backend has no ``get_context`` seam or the fetch failed
                # (degrade-quietly contract; see ``_skills_context_or_none``).
                "skills": (skills_count, skills_payload),
            },
            {
                "notes": notes_count,
                "media": media_count,
                "conversations": conversations_count,
            },
            {
                "notes": notes_total_known,
                "media": media_total_known,
                "conversations": conversations_total_known,
            },
            None,
            None,
            study_counts,
        )

    def _has_local_sources(self) -> bool:
        return any(count > 0 for count in self._local_source_counts.values())

    def _source_snapshot_body(self) -> str:
        lines = ["Local Library source snapshot staged for Console:", ""]
        for source_type, label in (
            ("notes", "Notes"),
            ("media", "Media"),
            ("conversations", "Conversations"),
        ):
            lines.append(self._source_count_label(source_type, label))
            for index, record in enumerate(
                self._local_source_records[source_type], start=1
            ):
                lines.append(f"  {index}. {self._source_title(source_type, record)}")
            lines.append("")
        return "\n".join(lines).strip()

    def _source_count_label(self, source_type: str, label: str) -> str:
        count = self._local_source_counts[source_type]
        if self._local_source_total_known[source_type]:
            return f"{label}: {count}"
        return (
            f"{label} (showing up to {LIBRARY_SOURCE_PAGE_SIZES[source_type]}): {count}"
        )

    def _source_sample_titles(self, source_type: str) -> list[str]:
        return [
            self._source_title(source_type, record)
            for record in self._local_source_records[source_type]
        ]

    def _conversation_records(self) -> tuple[Mapping[str, Any], ...]:
        return self._conversations_controller._conversation_records()


    def _conversation_record_id(self, record: Mapping[str, Any], index: int) -> str:
        return self._conversations_controller._conversation_record_id(record, index)


    @classmethod
    def _conversation_message_count_label(cls, record: Mapping[str, Any]) -> str:
        return LibraryConversationsController._conversation_message_count_label(record)


    @classmethod
    def _conversation_workspace_label(cls, record: Mapping[str, Any]) -> str:
        return LibraryConversationsController._conversation_workspace_label(record)


    @classmethod
    def _conversation_updated_label(cls, record: Mapping[str, Any]) -> str:
        return LibraryConversationsController._conversation_updated_label(record)


    def _selected_conversation_handoff_payload(self) -> ChatHandoffPayload | None:
        selected = self._conversations_controller._selected_conversation_record()
        if selected is None:
            return None
        index, record = selected
        conversation_id = self._conversation_record_id(record, index)
        title = self._source_title("conversations", record)
        message_count = self._conversation_message_count_label(record)
        workspace_label = self._conversation_workspace_label(record)
        updated_label = self._conversation_updated_label(record)
        body = "\n".join(
            (
                f"Conversation: {title}",
                f"Conversation ID: {conversation_id}",
                message_count,
                workspace_label,
                updated_label,
                "Source authority: local",
            )
        )
        return ChatHandoffPayload(
            source="library",
            item_type="conversation",
            title=title,
            body=body,
            source_id=conversation_id,
            display_summary=f"Conversation staged: {title}",
            suggested_prompt="Use this conversation as source context for my next question.",
            runtime_backend="local",
            source_owner="local",
            source_selector_state="local",
            discovery_owner="conversation",
            discovery_entity_id=conversation_id,
            metadata={
                "conversation_id": conversation_id,
                "conversation_title": title,
                "message_count_label": message_count,
                "workspace_label": workspace_label,
                "updated_label": updated_label,
                "source_authority": "local",
            },
        )



    def _library_conversation_workspace_block(self) -> tuple[str, bool, str]:
        """Return the reader's inline workspace refusal (task-32056).

        The DECISION is the very call the press makes --
        ``library_item_context_handoff`` -- not a re-derivation from the
        row model. Fix round 1: the earlier version walked ``source_rows``
        itself and returned "eligible" whenever the row was absent, while
        the press fell through to that helper's aggregate gate and refused
        by toast. Only the short LABEL is looked up per row; a block whose
        reason code has no short label still blocks, under a generic one.

        Returns:
            ``(reason, link_resolves_it, detail)`` -- ``("", False, "")``
            when the conversation is eligible or nothing is loaded.
            ``reason`` is a short phrase for the blocked control ("not in
            this workspace"); ``link_resolves_it`` is True only for the
            reason codes "Link to workspace" actually fixes, so the remedy
            is never offered where it would not work; ``detail`` is the
            eligibility rule's own recovery sentence, which the tooltip
            keeps for the blocks linking cannot resolve (review round 2 --
            the generic label alone dropped "Select an active workspace").
        """
        conversation_id = str(
            self._conversations_state.reader_state.loaded_id or ""
        ).strip()
        if not conversation_id:
            return "", False, ""
        if self._conversations_state.freshness != "fresh":
            # (Qodo bot round #3) The hand-off returns without staging while
            # the page is not fresh, so a pressable "Use as source" -- and
            # the sentence promising it will link and continue -- was an
            # actionable control that did nothing. Reported here as the block
            # it is: NOT link-resolvable, so the action disables with its "○"
            # marker and no link is offered. Reported through this one seam
            # rather than a second metadata key so the reader, the tooltip
            # and the `c` accelerator cannot disagree about it. Resume is
            # unaffected -- reopening the original never needed a fresh list.
            return (
                # Inline, like the canvas's own "List may be out of date"
                # (library_conversations_state.py): one writer, one reader
                # echoing it, so a constant would be ceremony.
                "from a list that may be out of date",
                False,
                "This list may be out of date. Refresh Conversations before "
                "using this one in Console.",
            )
        state = self._library_workspace_depth_state()
        eligible, reason_copy = library_item_context_handoff(
            state, item_type="conversation", item_id=conversation_id
        )
        if eligible:
            return "", False, ""
        detail = str(reason_copy or "").strip()
        for row in state.source_rows:
            if row.item_type == "conversation" and row.item_id == conversation_id:
                label = linkable_ineligibility_label(row.reason_code)
                if label:
                    return label, True, detail
                break
        return LIBRARY_GENERIC_WORKSPACE_BLOCK, False, detail

    def _library_conversation_handoff_ready(self) -> bool:
        """Use the same retained-identity load fence as the Resume button."""
        return self._conversations_state.reader_state.loaded_actions_eligible

    def _library_conversation_link_would_unblock(self) -> bool:
        """Return whether a workspace link is what blocks the hand-off.

        (task-32107) Asks the reader's OWN predicate, over the same three
        inputs, so the enabled state of "Use as source" and this handler's
        decision to link before staging cannot disagree.

        Returns:
            True when linking into the active workspace resolves the only
            block.
        """
        blocked, linkable, _detail = self._library_conversation_workspace_block()
        return library_conversation_link_would_unblock(
            self._conversations_state.reader_state,
            {
                "_workspace_block": blocked,
                "_workspace_block_linkable": linkable,
            },
        )

    def _set_library_conversation_link_receipt(
        self, workspace_name: str, workspace_id: str = ""
    ) -> None:
        """Record (or clear) the workspace the last press linked into.

        A fresh mapping rather than a mutation: ``reader_loaded_metadata`` is
        typed as a ``Mapping`` and is replaced wholesale by each load, which
        is what clears the receipt when a different conversation opens.

        The ID is stored beside the NAME (review fix round 1) because Undo
        has to remove the membership this press added, not whatever is active
        by the time it is pressed -- creating a workspace from the rail
        activates it and recomposes the reader from this same mapping, so the
        active workspace can change underneath a standing receipt.

        Args:
            workspace_name: The linked workspace's display name, or ``""``.
            workspace_id: That workspace's id, or ``""`` to clear.
        """
        self._conversations_state.reader_loaded_metadata = {
            **self._conversations_state.reader_loaded_metadata,
            "_workspace_link_receipt": workspace_name,
            "_workspace_link_receipt_id": workspace_id,
        }

    def _undo_selected_conversation_workspace_link(self) -> None:
        """Remove the membership the last "Use as source" press added.

        The exact inverse of ``_link_selected_conversation_to_workspace``:
        same load fence, same registry, same refresh -- ``unlink_membership``
        instead of ``link_membership``, and the receipt cleared.

        It unlinks the workspace the RECEIPT names, read back by id, not
        whatever is active now (review fix round 1): activating a different
        workspace while the receipt stands would otherwise make Undo remove a
        membership this press never added.
        """
        if not self._conversations_state.reader_state.loaded_actions_eligible:
            return
        registry = getattr(self.app_instance, "workspace_registry_service", None)
        notify = getattr(self.app_instance, "notify", None)
        conversation_id = str(
            self._conversations_state.reader_state.loaded_id or ""
        ).strip()
        workspace_id = str(
            self._conversations_state.reader_loaded_metadata.get(
                "_workspace_link_receipt_id"
            )
            or ""
        ).strip()
        if registry is None or not conversation_id or not workspace_id:
            if callable(notify):
                notify(
                    "Workspaces are unavailable, so this link cannot be "
                    "undone.",
                    severity="warning",
                )
            return
        try:
            registry.unlink_membership(
                workspace_id,
                item_type="conversation",
                item_id=conversation_id,
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Library conversation workspace link could not be undone."
            )
            if callable(notify):
                notify(
                    "This link could not be undone. Try again.",
                    severity="warning",
                )
            return
        self._set_library_conversation_link_receipt("")
        self._invalidate_library_workspace_depth_state()
        self._sync_library_conversation_reader()

    def _link_selected_conversation_to_workspace(self) -> str:
        """Link the open conversation into the active workspace (task-32056).

        The remedy the refusal used to name without offering. A no-op when
        the registry, the active workspace, or the loaded conversation is
        missing -- each of those already blocks the action's own affordance.

        Returns:
            The linked workspace's display name, or ``""`` when nothing was
            linked (task-32107: "Use as source" links first and only
            proceeds on a real name, so a failed link stages nothing).
        """
        # (review round 2) This writes membership for the RETAINED
        # ``loaded_id``. The same fence that hides the button re-checks here,
        # so no sync window can persist the conversation the user already
        # navigated away from.
        if not self._conversations_state.reader_state.loaded_actions_eligible:
            return ""
        registry = getattr(self.app_instance, "workspace_registry_service", None)
        notify = getattr(self.app_instance, "notify", None)
        conversation_id = str(
            self._conversations_state.reader_state.loaded_id or ""
        ).strip()
        if registry is None or not conversation_id:
            if callable(notify):
                notify(
                    "Workspaces are unavailable, so this conversation cannot "
                    "be linked.",
                    severity="warning",
                )
            return ""
        try:
            active = registry.get_active_workspace()
            if active is None:
                raise ValueError("no active workspace")
            # (Qodo bot round #2) ``link_membership`` is INSERT OR IGNORE and
            # returns the EXISTING row when the membership is already there.
            # A press that reaches it through stale cached eligibility would
            # otherwise get a receipt for a link it did not make, and Undo
            # would delete someone else's membership. Read first, receipt
            # only what this press inserted.
            # ponytail: read-then-write, not an atomic "did it insert?" from
            # the registry -- one UI thread makes the window unreachable
            # here; push the answer into `link_membership` if a second writer
            # ever shares it.
            already_linked = any(
                membership.workspace_id == active.workspace_id
                for membership in registry.get_item_memberships(
                    item_type="conversation", item_id=conversation_id
                )
            )
            registry.link_membership(
                active.workspace_id,
                item_type="conversation",
                item_id=conversation_id,
                title=str(
                    self._conversations_state.reader_loaded_metadata.get("title")
                    or conversation_id
                ),
            )
        except Exception:
            logger.opt(exception=True).warning(
                "Library conversation could not be linked to the active workspace."
            )
            if callable(notify):
                notify(
                    "This conversation could not be linked to the active "
                    "workspace. Try again.",
                    severity="warning",
                )
            return ""
        workspace_name = str(getattr(active, "name", "") or active.workspace_id)
        if not already_linked:
            # Nothing was added when it was already linked, so there is
            # nothing to undo -- but the refresh below still has to run, or
            # the cached eligibility that sent us here stays stale and the
            # hand-off refuses the conversation it just accepted.
            self._set_library_conversation_link_receipt(
                workspace_name, active.workspace_id
            )
        self._invalidate_library_workspace_depth_state()
        self._sync_library_conversation_reader()
        return workspace_name

    def _selected_media_handoff_payload(self) -> ChatHandoffPayload | None:
        return self._media_controller._selected_media_handoff_payload()

    def _hub_table_cell(
        self, value: str, width: int = LIBRARY_HUB_RECENT_LABEL_WIDTH
    ) -> str:
        """Keep hub table cells readable in terminal-width layouts."""
        clean_value = " ".join(value.split())
        if len(clean_value) <= width:
            return clean_value
        suffix = "..."
        limit = max(1, width - len(suffix))
        shortened = clean_value[:limit].rsplit(" ", 1)[0].strip()
        if not shortened:
            shortened = clean_value[:limit].strip()
        return f"{shortened}{suffix}"

    def _hub_source_count_value(self, source_type: str) -> str:
        count = self._local_source_counts.get(source_type, 0)
        suffix = "" if self._local_source_total_known.get(source_type, True) else "+"
        return f"{count}{suffix}"

    def _hub_recent_items(self) -> list[tuple[str, str, str, str]]:
        """One recent item per source for the landing hub (task-2238).

        Returns:
            ``(source_type, record_id, title, label)`` tuples in the hub's
            source order, for sources whose most recent record resolves an
            id -- empty sources are skipped, so a fresh library yields an
            empty list (the old line's None-when-empty contract).
        """
        if self._library_lookup_error is not None:
            return []
        items: list[tuple[str, str, str, str]] = []
        for source_type, label in (
            ("notes", "Notes"),
            ("media", "Media"),
            ("conversations", "Conversations"),
        ):
            records = self._local_source_records.get(source_type) or ()
            for record in records:
                record_id = self._source_record_id(record)
                title = self._source_optional_title(source_type, record)
                if not record_id or title is None:
                    continue
                items.append(
                    (source_type, record_id, self._hub_table_cell(title), label)
                )
                break
        return items

    def _hub_counts_line(self) -> str:
        """Per-source counts for the F-010 landing hub.

        While the local source snapshot is still loading (and no lookup
        error has been recorded), the counts read "…" rather than the
        placeholder zeros seeded at construction time -- same honest-
        loading policy `_build_library_shell_input()` applies to the rail's
        own count suffixes. `_hub_source_count_value()` appends "+" when
        the source's total is an estimate, mirroring the rail. On a lookup
        ERROR the line never reports zeros (PR #1318 review; the F-014
        count policy: a failed fetch must not dress up as an empty
        Library) -- it carries the error itself, or stays EMPTY when the
        failure has its own recovery callout above (task-31632).
        """
        if self._library_lookup_error is not None:
            if self._library_source_load_failure() is not None:
                # task-31632: the recovery callout above already reads
                # "<what> · <why>"; repeating it here as a bare line under
                # its own bordered card is the duplicate the callout exists
                # to remove. Failures WITHOUT a load-failure state (policy
                # denials, a runtime with no source services) have no
                # callout and keep carrying their sentence here.
                return ""
            return self._library_lookup_error

        def value(source_type: str) -> str:
            if not self._library_loaded:
                return "…"
            return self._hub_source_count_value(source_type)

        return (
            f"Notes ({value('notes')}) · Media ({value('media')}) · "
            f"Conversations ({value('conversations')})"
        )

    def _library_source_load_failure(self) -> DestinationRecoveryState | None:
        """Return the source-snapshot failure the hub paints as a callout.

        Only the snapshot's OWN load failures (the deadline and the hard
        failure raised at the ``wait_for`` site) carry this Retry id -- a
        policy denial keeps its taxonomy state and its own copy, and a
        runtime without source services has no recovery state at all.

        Returns:
            The recovery state to render, or ``None`` when the current
            lookup error is not one of the snapshot's load failures.
        """
        state = self._library_lookup_recovery_state
        if state is None or state.retry_id != LIBRARY_SOURCE_RETRY_ID:
            return None
        return state

    def _library_landing_canvas_state(self) -> LibraryLandingCanvasState:
        """Build the landing owner's display-only snapshot."""
        get_started = self._library_lifecycle in (
            LibraryLifecycle.UNKNOWN,
            LibraryLifecycle.STARTER,
        )
        lifecycle_status = self._library_onboarding_status_copy if get_started else ""
        # Qodo PR G finding 5: the source-snapshot failure is valid
        # regardless of lifecycle -- a new profile's first source read can
        # time out or fail exactly like a returning one's, and withholding
        # it here left a STARTER/UNKNOWN visit with empty counts and no
        # callout or Retry. The canvas is the one that decides how to
        # compose it per mode (above the starter content in Get-started).
        load_failure = self._library_source_load_failure()
        attention_action = (
            self._library_landing_attention_action()
            if not get_started and not self._notes_state.compact
            else None
        )
        self._library_landing_attention_signature = attention_action
        return LibraryLandingCanvasState(
            purpose=(
                "Add something useful, then use it in Console or Study."
                if get_started
                else LIBRARY_CANVAS_LANDING_COPY
            ),
            counts_line="" if get_started else self._hub_counts_line(),
            recent_items=tuple(
                LibraryLandingRecentItem(
                    source_type=source_type,
                    record_id=record_id,
                    title=title,
                    source_label=source_label,
                )
                for source_type, record_id, title, source_label in self._hub_recent_items()
            )
            if not get_started
            else (),
            lifecycle=self._library_lifecycle,
            lifecycle_status=lifecycle_status,
            show_retry=(
                get_started
                and self._library_onboarding_status
                is LibraryEvidenceStatus.PARTIAL_FAILURE
            ),
            show_explore=get_started and self._library_rail_collapsed,
            # task-32072: the two facts the Get started steps unlock on.
            has_any_content=self._has_local_sources(),
            search_result_selected=self._library_search_result_is_selected(),
            continue_action=(
                self._library_landing_continue_action() if not get_started else None
            ),
            attention_action=attention_action,
            load_failure=load_failure,
        )

    def _library_landing_attention_action(
        self,
    ) -> LibraryLandingAttentionAction | None:
        """Return one bounded recovery derived only from current live state."""

        registry = self._library_ingest_registry()
        jobs_fn = getattr(registry, "jobs", None)
        if callable(jobs_fn):
            # (Qodo 2) ``jobs()`` already hides superseded and dismissed jobs
            # and NOTHING else, so this is exactly the set the Review queue
            # renders -- permanent failures included. The card is still
            # offered only when something in it can actually be retried (the
            # pre-existing trigger), but once offered it must count what the
            # queue shows, or the sentence disagrees with the screen it sends
            # the user to.
            live = tuple(
                job for job in jobs_fn() if not job.dismissed and not job.superseded
            )
            if any(
                job.state is IngestJobState.FAILED and not job.permanent
                for job in live
            ):
                failures = [job for job in live if job.state is IngestJobState.FAILED]
                # task-32351 AC#2 (critique #10, B D2): after 4 of 6 files
                # failed the landing said only "An import needs review." --
                # neutral where the queue itself was exact. The counts are
                # already in the registry snapshot this walks.
                #
                # (review finding 1) The sentence says "Last import", so it
                # counts ONE import: the most recent submission that has a
                # failure, not every unreviewed job in the queue -- two
                # unreviewed imports summed into one sentence would be a
                # wrong count, which is worse than the vague one this
                # replaced. The card still appears for ANY live failure (the
                # trigger above is unchanged); only what it counts is scoped.
                # A job submitted on its own carries no batch id, so it is
                # its own import.
                #
                # (Qodo 3) Ordered by ``finished_at_wall``, not
                # ``submitted_at``: the latter is a ``time.monotonic()`` float
                # with no fixed epoch, so a job restored from before a reboot
                # can outrank one submitted after it. ``finished_at_wall`` is
                # the ISO-8601 UTC stamp ``mark_failed`` writes for exactly
                # this ordering; it is "" only on a row that never reached a
                # terminal state, which cannot be in ``failures``, so
                # ``submitted_at`` stays as the tiebreaker.
                newest = max(
                    failures, key=lambda job: (job.finished_at_wall, job.submitted_at)
                )
                last_import = newest.batch_id or newest.job_id
                members = [
                    job for job in live if (job.batch_id or job.job_id) == last_import
                ]
                failed = sum(
                    1 for job in members if job.state is IngestJobState.FAILED
                )
                skipped = sum(
                    1 for job in members if job.state is IngestJobState.SKIPPED
                )
                noun = "file" if failed == 1 else "files"
                parts = [f"{failed} {noun} failed"]
                if skipped:
                    parts.append(f"{skipped} skipped")
                return LibraryLandingAttentionAction(
                    message=f"Last import: {', '.join(parts)}.",
                    action_label="Review",
                    action_kind="ingest-review",
                )

        if (
            self._library_media_browse_controller.state.freshness == "stale"
            and self._library_media_browse_controller.state.stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Media may be out of date.",
                action_label="Retry",
                action_kind="media-retry",
            )
        if (
            self._library_prompt_browse_controller.freshness == "stale"
            and self._library_prompt_browse_controller.stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Prompts may be out of date.",
                action_label="Retry",
                action_kind="prompts-retry",
            )
        if (
            self._conversations_state.freshness == "stale"
            and self._conversations_state.stale_copy
        ):
            return LibraryLandingAttentionAction(
                message="Conversations may be out of date.",
                action_label="Retry",
                action_kind="conversations-retry",
            )
        return None

    def _library_landing_continue_action(
        self,
    ) -> LibraryLandingContinueAction | None:
        """Describe the validated receipt without exposing record or query text."""

        receipt = self._library_continue_receipt
        if receipt is None:
            return None
        row_id = receipt["row_id"]
        scope = receipt["scope"]
        parts = [_LIBRARY_HELP_SURFACE_LABELS[row_id]]

        if scope.get("query"):
            parts.append("search applied")
        if row_id == LIBRARY_ROW_BROWSE_MEDIA:
            if scope["media_type"] is not None:
                parts.append(f"type: {scope['media_type']}")
            sort_labels = {
                "last_modified_desc": "recent first",
                "last_modified_asc": "oldest first",
                "date_desc": "newest date",
                "date_asc": "oldest date",
                "title_asc": "title A–Z",
                "title_desc": "title Z–A",
                "relevance": "relevance",
            }
            parts.append(sort_labels[scope["sort_by"]])
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            if scope["collection_id"] is not None:
                parts.append("collection applied")
            parts.append(
                "name A–Z"
                if scope["sort_by"] == "name" and scope["sort_order"] == "asc"
                else "name Z–A"
                if scope["sort_by"] == "name"
                else "recent first"
                if scope["sort_order"] == "desc"
                else "oldest first"
            )
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_NOTES:
            if scope["filter"]:
                parts.append("filter applied")
            parts.append(
                {
                    "newest": "recent first",
                    "oldest": "oldest first",
                    "title": "title A–Z",
                }[scope["sort"]]
            )
        elif row_id == LIBRARY_ROW_BROWSE_SKILLS:
            if scope["filter"]:
                parts.append("filter applied")
            parts.append("status order" if scope["sort"] == "status" else "name A–Z")
            if scope["page"] > 1:
                parts.append(f"page {scope['page']}")
        elif row_id == LIBRARY_ROW_BROWSE_SEARCH:
            parts.append("RAG" if scope["mode"] == "rag" else "search")
            if scope["scope_deselected"]:
                parts.append("sources adjusted")

        return LibraryLandingContinueAction(
            label=" · ".join(parts),
            row_id=row_id,
            adjustment=(
                "Item views resume at the source list."
                if receipt["source_list_adjusted"]
                else ""
            ),
        )

    def _library_study_handoff_canvas_state(
        self, kind: str
    ) -> LibraryStudyHandoffCanvasState:
        """Build one handoff owner's display-only snapshot."""
        copy = self._study_handoff_copy(kind)
        return LibraryStudyHandoffCanvasState(
            header=copy["header"],
            purpose=copy["purpose"],
            context=copy["context"],
            owner=copy["owner"],
            recovery=copy["recovery"],
            blocked=not self._has_local_sources(),
            button_label=copy["button_label"],
            button_id={
                "study": "library-open-study",
                "flashcards": "library-open-flashcards",
                "quizzes": "library-open-quizzes",
            }.get(kind, "library-open-study"),
            action_label=copy["action_label"],
        )

    def _library_header_line(self, header_line: str) -> str:
        """Return route-owned header copy without lifecycle feedback."""
        return header_line

    def _library_lifecycle_status_copy(self) -> str:
        """Return the durable lifecycle warning for the screen-owned carrier.

        task-32063: the graduation announcement used to share this line with
        the persistence warning, so one event painted twice -- a toast AND a
        line that lived until the next destination change. The announcement is
        the toast; only the warning (a state, not an event) is durable.
        """
        return self._library_onboarding_persistence_warning

    @classmethod
    def _source_record_id(cls, record: Mapping[str, Any]) -> str | None:
        for key in (
            "id",
            "uuid",
            "record_id",
            "backing_id",
            "source_id",
            "item_id",
            "media_id",
            "note_id",
            "conversation_id",
            "backing_media_id",
        ):
            value = cls._safe_text(record.get(key), max_length=128)
            if value:
                return value
        return None

    def _study_source_items(self) -> tuple[StudySourceItem, ...]:
        source_items: list[StudySourceItem] = []
        source_type_map = {
            "notes": "note",
            "media": "media",
        }
        for source_type, study_source_type in source_type_map.items():
            for record in self._local_source_records[source_type]:
                source_id = self._source_record_id(record)
                if not source_id:
                    continue
                source_items.append(
                    StudySourceItem(
                        source_type=study_source_type,
                        source_id=source_id,
                        label=self._source_title(source_type, record),
                    )
                )
        return tuple(source_items)

    def _source_count_metadata(self) -> dict[str, int | None]:
        metadata: dict[str, int | None] = {}
        for source_type in ("notes", "media", "conversations"):
            count = self._local_source_counts[source_type]
            metadata[f"{source_type}_sample_count"] = len(
                self._local_source_records[source_type]
            )
            metadata[f"{source_type}_total_count"] = (
                count if self._local_source_total_known[source_type] else None
            )
            if self._local_source_total_known[source_type]:
                metadata[f"{source_type}_count"] = count
        return metadata

    def _source_snapshot_metadata(self) -> dict[str, Any]:
        return {
            **self._source_count_metadata(),
            "note_titles": self._source_sample_titles("notes"),
            "media_titles": self._source_sample_titles("media"),
            "conversation_titles": self._source_sample_titles("conversations"),
        }

    def _workspace_source_records(self) -> Mapping[str, tuple[Mapping[str, Any], ...]]:
        records = {
            source_type: tuple(self._local_source_records[source_type])
            for source_type in ("notes", "media", "conversations")
        }
        # Archive pages are outside the active-only startup snapshot. Include
        # their fetched rows in the same per-item workspace eligibility rules.
        conversations = {
            str(row.get("id") or row.get("conversation_id")): row
            for row in records["conversations"]
        }
        for row in self._conversations_state.page_records:
            conversations[str(row.get("id") or row.get("conversation_id"))] = row
        records["conversations"] = tuple(conversations.values())
        return records

    def _invalidate_library_workspace_depth_state(self) -> None:
        self._library_workspace_depth_state_cache = None

    def _library_workspace_depth_state(
        self,
        *,
        refresh: bool = False,
    ) -> LibraryWorkspaceDepthState:
        if refresh or self._library_workspace_depth_state_cache is None:
            self._library_workspace_depth_state_cache = (
                build_library_workspace_depth_state(
                    registry_service=getattr(
                        self.app_instance, "workspace_registry_service", None
                    ),
                    source_records=self._workspace_source_records(),
                )
            )
        return self._library_workspace_depth_state_cache

    def _source_study_context(self) -> StudyScopeContext | None:
        if not self._has_source_study_context():
            return None
        material_titles: list[str] = []
        for source_type in ("notes", "media", "conversations"):
            material_titles.extend(self._source_sample_titles(source_type))
        return StudyScopeContext(
            material_source=MATERIAL_SOURCE_LIBRARY,
            material_title=MATERIAL_TITLE_LIBRARY_SOURCES,
            material_summary=self._source_snapshot_body(),
            material_titles=tuple(material_titles),
            source_items=self._study_source_items(),
            return_hint=MATERIAL_SOURCE_LIBRARY,
        )

    def _source_study_handoff_titles(self) -> tuple[str, ...]:
        material_titles: list[str] = []
        for source_type in ("notes", "media", "conversations"):
            material_titles.extend(self._source_sample_titles(source_type))
        return tuple(material_titles)

    def _has_source_study_context(self) -> bool:
        return self._has_local_sources()

    def _study_handoff_copy(self, kind: str) -> dict[str, str]:
        mode = LIBRARY_STUDY_HANDOFF_MODES.get(
            kind,
            LIBRARY_STUDY_HANDOFF_MODES["study"],
        )
        titles = self._source_study_handoff_titles()
        has_context = self._has_source_study_context()
        action_label = mode["action_label"]
        if has_context and titles:
            context_copy = _library_carries_forward_line(titles)
        elif has_context:
            context_copy = (
                "Carries forward: Library source snapshot (titles unavailable)"
            )
        else:
            # No Library sources at all: the carries-forward line is omitted
            # entirely rather than stating the negative (the blocked
            # "recovery" line below already carries that signal).
            context_copy = ""
        return {
            "header": mode["header"],
            "action_label": action_label,
            "button_label": mode["button_label"],
            "purpose": mode["purpose"],
            "context": context_copy,
            "owner": LIBRARY_STUDY_HANDOFF_OWNERSHIP_COPY,
            "recovery": (
                "Source snapshot is ready."
                if has_context
                else (
                    "Import sources or create notes first, or open "
                    f"{action_label} globally without Library context."
                )
            ),
        }

    def _library_rag_panel_state(self) -> LibraryRagPanelState:
        # B2: explicit selection is every real source type NOT toggled off;
        # `LibraryRagScopeState.from_source_counts` intersects this with
        # actual availability, so a deselected-but-empty source can't
        # falsely count as "selected".
        #
        # PR-T1 final review (C2): that count intersection is only honest
        # once counts EXIST. `restore_state` carries `_rag_search_state.results`
        # across navigation but NOT `_local_source_counts` (bulk snapshots
        # are deliberately re-fetched -- see `save_state`), so a fresh
        # `LibraryScreen` composes with all-zero counts while
        # `_refresh_local_source_snapshot` is still in flight. Feeding an
        # explicit selection into that window intersects every source down
        # to nothing, and D4/task-5's scope filter then hid EVERY restored
        # evidence row, flipping the panel to "No evidence matched the
        # current query" -- naming the restored query, about rows that were
        # right there. Nothing recovered it either: the snapshot lands via
        # the BROWSE_SEARCH branch of `_apply_local_source_snapshot`, which
        # deliberately syncs only the rail + scope toggles and never the
        # results region (RAG-27, so a background ingest can't eject a user
        # mid-search). Only a revisit INSIDE `LIBRARY_SNAPSHOT_CACHE_TTL_
        # SECONDS` escaped, because the cached-snapshot path recomposes.
        #
        # So while counts are unloaded, pass the documented "no explicit
        # scope was supplied" sentinel (`None`) instead: the hybrid basis
        # in `LibraryRagPanelState.from_values` skips the filter entirely
        # for it, and `from_source_counts` derives selection from
        # availability -- which, at all-zero counts, marks exactly the same
        # options unselected as the explicit tuple would. The only
        # difference is that restored rows stay visible until the real
        # counts arrive and the honest intersection can run.
        #
        # PR-T1 fix-wave re-review: `_library_loaded` alone re-opens this
        # same hole through `_apply_source_snapshot_timeout`, which sets
        # `_library_loaded = True` together with placeholder all-zero
        # counts AND `_library_lookup_error`. Gate on the same two-conjunct
        # "counts are real" predicate `_build_library_shell_input` already
        # uses as `counts_available` (~line 4530), so a snapshot timeout's
        # fake zeros can't enable the filter either.
        selected_source_types: tuple[str, ...] | None = tuple(
            source_type
            for source_type in LIBRARY_RAG_SCOPE_TOGGLE_SOURCE_TYPES
            if source_type not in self._rag_search_state.scope_deselected
        )
        if not (self._library_loaded and not self._library_lookup_error):
            selected_source_types = None
        # ONE `resolve -> readiness -> name` pass per render (finding I1):
        # the same call used to be made twice inline below, and the second
        # of them threw away the `ProviderReadiness` object carrying the
        # only text that can tell a user with a selected-but-uncredentialed
        # provider what to actually do.
        provider_gate = library_rag_answer_provider_gate()
        return LibraryRagPanelState.from_values(
            source_counts={
                "notes": self._local_source_counts.get("notes", 0),
                "media": self._local_source_counts.get("media", 0),
                "conversations": self._local_source_counts.get("conversations", 0),
                # "prompts" carries (count, page_records) in
                # `_local_source_records` (see its `__init__` comment), not
                # a bare count in `_local_source_counts` -- reuse the
                # already-fetched count-seam value rather than fetching
                # again.
                "prompts": self._local_source_records.get("prompts", (None, ()))[0]
                or 0,
                "workspaces": 0,
            },
            query=self._rag_search_state.query,
            searched_query=self._rag_search_state.searched_query,
            mode=self._rag_search_state.mode,
            results=self._rag_search_state.results,
            selected_result_id=self._rag_search_state.selected_result_id,
            # PR-3 Task 4: the in-flight answer OVERLAYS the settled
            # retrieval status for display only ("answering" is what Task 3's
            # normalizer and run-gate override key off) -- the retrieval's
            # own status stays intact underneath, so clearing the flag
            # restores it exactly.
            retrieval_status=(
                "answering"
                if self._rag_search_state.answer_in_flight
                else self._rag_search_state.retrieval_status
            ),
            # PR-3 Task 3: named for the in-flight "Asking <provider>..."
            # line -- gated on the same flag as `retrieval_status` above,
            # belt-and-suspenders against a reset gap ever leaving a stale
            # provider name forwarded once the flag itself reads False.
            in_flight_answer_provider=(
                self._rag_search_state.answer_in_flight_provider
                if self._rag_search_state.answer_in_flight
                else ""
            ),
            recovery_copy=(
                self._rag_search_state.recovery_state.visible_copy
                if self._rag_search_state.recovery_state is not None
                else ""
            ),
            recovery_selector=(
                self._rag_search_state.recovery_state.stable_selector
                if self._rag_search_state.recovery_state is not None
                else ""
            ),
            # Deliberately always ready: the UI path never imports torch (or
            # any other optional Search/RAG dependency), and the retrieval
            # service double-guards missing runtimes/indexes at call time.
            # rag mode lazily initializes the shared RAG runtime at query
            # time, and when embeddings support is missing the retrieval
            # service itself returns the "RAG unavailable" recovery state
            # routing to setup -- honest copy a disabled Run button could not
            # carry.
            dependencies_ready=True,
            index_ready=True,
            # `provider_ready` joined this contract in task-249 as a
            # hardcoded `True` -- PR-3 task 2 activated the gate for real,
            # and PR-T2 Task 4 review collapsed it into this single
            # `provider_name` argument, derived inside `LibraryRagQueryState.
            # from_values` as `bool((provider_name or "").strip())` -- see
            # its docstring. A Library with no default LLM endpoint
            # configured (`resolve_library_rag_answer_provider()` returns
            # `(None, None)`) sees the pre-existing "Select a provider/model
            # before asking for a RAG answer." copy -- while a provider that
            # IS configured but cannot authenticate gets the credential
            # remedy instead, carried by `provider_credential_recovery`
            # below (finding I1). Once one is configured AND the gate
            # confirms its credentials actually resolve (PR-T2 Task 7 -- an endpoint
            # NAME alone used to be treated as ready, which is how the
            # Library path spent money while Console's own readiness check
            # showed a blocking wall for the same config), this same value
            # also names the provider in the ready-state quiet line's
            # paid-mode notice (`library_rag_paid_mode_notice`) -- the ONLY
            # provider-adjacent copy on this panel used to be that
            # blocked-branch text, which disappeared the instant a provider
            # was configured, the exact inversion of what a keyboard-fast
            # user needs before pressing a button that spends real money.
            # rag-mode-only by construction (`LibraryRagQueryState.
            # from_values`'s `normalized_mode == "rag"` check) -- keyword
            # Search mode never calls a provider and stays unaffected
            # regardless of this value.
            provider_name=provider_gate.provider,
            provider_credential_recovery=provider_gate.credential_recovery,
            selected_source_types=selected_source_types,
            history=self._rag_search_state.history,
            history_collapsed=self._rag_search_state.history_collapsed,
            diagnostics=self._rag_search_state.diagnostics,
            answer=self._rag_search_state.answer,
        )

