    async def _return_to_library_database_notes(self) -> None:
        """Leave File Notes and return to the Database Notes view.

        Shared by the "Database" strip button and the Files-mode Escape key
        (task-2850) so both exits honor the identical flush/leave-guard
        sequence -- one seam, not a parallel key-driven path that could
        drift from the button's.
        """
        if self._prompts_state.mutation_in_flight:
            return
        if self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE:
            return
        workspace = self._notes_state.file_notes_workspace
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        if not await self._flush_active_file_notes():
            return
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            guard = _LibraryNotesRestoreGuard(
                scroll_generation=self._notes_state.scroll_intent_generation,
                focus_generation=self._notes_state.focus_intent_generation,
            )
            self._notes_controller._evacuate_library_notes_authority_focus("files")
            self._acknowledge_library_destination_change()
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
            self._register_footer_shortcuts()
            workspace = self._notes_state.file_notes_workspace
            retained_switch = False
            try:
                database_shell = self.query_one(
                    ".library-notes-route", LibraryAdaptiveReaderShell
                )
            except (NoMatches, QueryError):
                await self.recompose()
                self.call_after_refresh(
                    self._restore_library_notes_authority_focus,
                    "database",
                )
            else:
                if workspace is not None:
                    workspace.display = False
                database_shell.display = True
                self._notes_controller._sync_library_notes_source_controls()
                self._sync_library_notes_reader_layout_from_shell()
                self._restore_library_notes_authority_focus("database")
                self._notes_state.focus_intent_generation += 1
                retained_switch = True
            receipt = self._notes_state.browse_return_receipt
            if self._notes_state.view == "editor":
                pass
            elif receipt is None:
                # task-2856 AC1: this lands on the Notes LIST (never Files'
                # own editor state), so re-focus its first row the same way
                # every other "enter/return to a list" seam does.
                self._arm_library_list_entry_focus()
            elif retained_switch:
                # task-32055: this used to queue a second, settled restore
                # with ``receipt.focus`` -- an attribute
                # ``LibraryNotesTreeReceipt`` has never had, so leaving
                # Files with a captured browse receipt raised
                # ``AttributeError`` and killed the Escape/back handler
                # outright (found the moment Escape stopped being swallowed
                # by a folder change). The restore below already rebuilds
                # the focus identity from the receipt and queues it.
                self.call_later(
                    self._restore_library_notes_browse_return_receipt,
                    receipt,
                )
            else:
                self.call_after_refresh(
                    self._restore_library_notes_browse_return_receipt,
                    receipt,
                    guard,
                )
        finally:
            if callable(release_source):
                release_source()

    async def action_library_notes_files_back(self) -> None:
        """Escape: leave Files mode and return to Database Notes (task-2850).

        ``check_action`` gates this to ``_file_notes_active()``, so it only
        ever runs while Files mode genuinely owns the Notes canvas.
        """
        workspace = self._notes_state.file_notes_workspace
        if workspace is not None and workspace.cancel_path_task():
            self._register_footer_shortcuts()
            return
        if workspace is not None and workspace.cancel_reload_confirmation():
            self._register_footer_shortcuts()
            return
        await self._return_to_library_database_notes()

    @on(Button.Pressed, ".library-rail-row")
    @on(Button.Pressed, ".library-hub-action")
    async def handle_library_rail_row(self, event: Button.Pressed) -> None:
        """Dispatch a Library rail row press: navigate, browse, or open a canvas.

        `.library-hub-action` covers the F-010 landing hub's next-action
        rows -- they carry the same row_id/target_kind/target_id attributes
        as rail rows, so both flow through this one dispatch (including its
        dirty-edit guards).
        """
        event.stop()
        if self._prompts_state.mutation_in_flight:
            return
        button = event.button
        target_kind = str(getattr(button, "target_kind", "") or "")
        target_id = str(getattr(button, "target_id", "") or "")
        row_id = str(getattr(button, "row_id", "") or "")
        if target_kind == "screen":
            if target_id:
                self.post_message(NavigateToScreen(target_id))
            return
        if target_kind == "canvas":
            await self._select_library_rail_row(row_id)
            if (
                target_id == "conversations"
                and row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS
                and self._library_selected_row_id == row_id
                and self._conversations_controller._library_conversation_page_needs_recovery()
            ):
                self._start_library_conversation_page_request(
                    self._conversations_state.requested_page,
                    self._conversations_state.requested_query,
                )
            return
        if target_kind == "handoff":
            # Study/Flashcards/Quizzes rows (L3b Task 8): resolves to the
            # handoff canvas.
            await self._select_library_rail_row(row_id)
            return
        # Unknown target kind: select the row and recompose from selection.
        await self._select_library_rail_row(row_id)

    async def _replace_library_browse_canvas(self, shell: LibraryShellState) -> bool:
        """Move to a Media/Notes browse route without rebuilding the screen.

        Phase C: the two browse routes share ONE resident
        ``LibraryBrowseReaderShell``, so the rail, nav bar, footer, screen
        chrome and both visited canvases survive a switch. The mechanism and
        its measured numbers live in
        ``UI/Library_Modules/library_browse_route_swap.py``.

        Args:
            shell: Latest normalized Library shell state.

        Returns:
            True when the targeted update completed; False when the caller
            should use the whole-screen fallback.
        """
        from ..Library_Modules.library_browse_route_swap import (  # noqa: PLC0415 -- lazy, same reason as the source-strip import in `compose_content`
            swap_library_browse_route,
        )

        try:
            return await swap_library_browse_route(self, shell)
        except Exception:
            logger.debug(
                "Targeted Library Notes/Media route update failed; falling back "
                "to the central screen recompose seam.",
                exc_info=True,
            )
            return False

    async def _select_library_rail_row(self, row_id: str) -> None:
        """Apply a rail-row selection and recompose the canvas from it.

        Shared by the rail-row press handler and in-canvas mode shortcuts so
        that the single source of selection truth (``_library_selected_row_id``)
        always drives the recomposed canvas.

        A Notes working session is retained only while cycling among the five
        reader destinations. Every other Notes exit flushes first (awaited),
        so it never silently discards unsaved text. A dirty Prompt working copy
        has the same retained-reader boundary; every destructive Prompt exit
        remains vetoed. Dirty skill edits are vetoed (see
        ``_flush_library_skill_save`` -- explicit-Save-only, so there is nothing
        to flush, only to veto on). task-448: the skill guard was originally
        omitted here, so a rail switch silently discarded dirty skill edits
        while Back/row-switch exits vetoed them.
        """
        if self._prompts_state.mutation_in_flight:
            return
        if not await self._flush_active_file_notes():
            return
        release_source = self._acquire_file_notes_transition("source")
        if release_source is False:
            return
        try:
            await self._select_library_rail_row_after_source_admission(row_id)
        finally:
            if callable(release_source):
                release_source()

    async def _select_library_rail_row_after_source_admission(
        self,
        row_id: str,
    ) -> None:
        """Recompose a rail destination while source admission is held."""
        if self._prompts_state.mutation_in_flight:
            return
        retained_reader_rows = {
            LIBRARY_ROW_BROWSE_MEDIA,
            LIBRARY_ROW_BROWSE_COLLECTIONS,
            LIBRARY_ROW_BROWSE_CONVERSATIONS,
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
        }
        note_snapshot = self._library_note_session.snapshot
        retain_note_session = (
            self._library_selected_row_id in retained_reader_rows
            and row_id in retained_reader_rows
            and not (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_NOTES
                and row_id == LIBRARY_ROW_BROWSE_NOTES
            )
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
            and self._notes_state.view == "editor"
            and self._notes_state.load_state == "loaded"
            and note_snapshot is not None
            and note_snapshot.note_id == self._notes_state.selected_note_id
            and self._notes_state.session_blank_id is None
            and not note_snapshot.saving
            and not note_snapshot.in_conflict
            and self._notes_state.autosave_state in {"idle", "saved"}
            and not self._notes_state.confirming_delete
            and not self._library_note_session.destructive_running
            and self._library_note_session.destructive_admission is None
            and not self._library_note_session.conflict_resolution_running
        )
        if retain_note_session:
            self._invalidate_library_note_autosave()
        else:
            note_flush = await self._flush_library_note_save()
            if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
                return
        retain_prompt_draft = (
            self._prompts_state.dirty
            and self._prompts_state.view == "editor"
            and self._library_selected_row_id in retained_reader_rows
            and row_id in retained_reader_rows
        )
        if retain_prompt_draft:
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
                fields = self._read_library_prompt_editor_fields()
                if fields is None or not isinstance(
                    self._prompts_state.detail, Mapping
                ):
                    return
                name, author, details, system, user, keywords = fields
                detail = dict(self._prompts_state.detail)
                detail.update(
                    {
                        "name": name,
                        "author": author,
                        "details": details,
                        "system_prompt": system,
                        "user_prompt": user,
                        "keywords": keywords,
                    }
                )
                self._prompts_state.detail = detail
        elif not await self._flush_library_prompt_save():
            self._prompts_controller._notify_prompt_dirty_veto()
            return
        if not await self._flush_library_skill_save():
            self._notify_skill_dirty_veto()
            return
        self._advance_library_stage_interaction()
        if self._try_switch_retained_library_notes_route(row_id):
            return
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
            and self._media_state.view == "list"
            and row_id != LIBRARY_ROW_BROWSE_MEDIA
        ):
            self._disarm_library_media_return_for_route_change()
        self._acknowledge_library_destination_change()
        self._cancel_library_media_selection_settlement()
        if row_id != LIBRARY_ROW_BROWSE_MEDIA:
            self._library_media_browse_controller.invalidate()
        if (
            row_id != LIBRARY_ROW_BROWSE_COLLECTIONS
            and self._library_collections_capture_controller is not None
        ):
            self._library_collections_capture_controller.unmount()
        if row_id != LIBRARY_ROW_BROWSE_SKILLS:
            self._skills_state.filter_cursor_context = None
            self._library_skills_browse_controller.invalidate()
        self._library_navigation_context_generation += 1
        self._library_unavailable_browse_scope = None
        if (
            self._pending_library_source_open is not None
            and self._pending_library_source_open[0] == "conversations"
            and self._conversations_state.loading
        ):
            self._conversations_state.request_generation += 1
            self._conversations_state.requested_page = self._conversations_state.page
            self._conversations_state.requested_query = (
                self._conversations_state.query
            )
            self._conversations_state.loading = False
        self._pending_library_source_open = None
        if row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._clear_library_prompt_selection(announce=True)
        if row_id == LIBRARY_ROW_CREATE_NOTE:
            # Create Note is a database-only Notes route. File Notes owns a
            # retained workspace, so normalize the source only after its
            # flush and transition admission have succeeded.
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
        if row_id != LIBRARY_ROW_BROWSE_PROMPTS:
            self._invalidate_library_prompts_browse()
        # A rail selection is an explicit route boundary, even when the user
        # later returns to the same visual Notes region. Invalidate the token
        # now so leave→return cannot recreate authority by region equality.
        self._notes_state.operation = None
        # ``render=`` only when this press STAYS on Notes: phase-C task 2.5
        # measured this repaint at 21 of a media switch-back's 81 mounts,
        # rebuilding the canvas the switch is about to hide (it runs before
        # the destination row is set, so the route-ownership guard still sees
        # Notes as the owner). Re-entering Notes repaints it for real --
        # ``_adopt_library_browse_canvas`` syncs every resident canvas it
        # shows -- so the only thing lost is work nobody could see.
        self._supersede_library_notes_navigation(
            render=row_id in LIBRARY_NOTES_RAIL_ROWS
        )
        if row_id == LIBRARY_ROW_CREATE_NOTE and not self._notes_state.create_running:
            # Create status belongs to one visible Create attempt. Import
            # reuses the persistence seam from Navigator, so its internal
            # failure must not leak into a later fresh Create entry.
            self._notes_state.create_status = ""
        self._set_library_destination_with_conversation_fence(row_id)
        if (
            row_id == LIBRARY_ROW_BROWSE_NOTES
            and self._notes_state.source == LIBRARY_NOTES_SOURCE_DATABASE
        ):
            self._request_library_notes_tree_initial_load()
        try:
            shell_width = self.query_one("#library-shell-grid").region.width
        except (NoMatches, QueryError):
            shell_width = 0
        if shell_width > 0:
            self._sync_library_ingest_rail_for_width(shell_width)
        # task-4023 AC#7: a plain rail switch is a fresh entry -- only
        # ``_open_library_export_canvas`` (which bypasses this seam) may
        # arm an Export back-origin.
        self._export_state.origin_row_id = ""
        # task-420: keep the footer's "u" hint in sync with the row gate.
        self._register_footer_shortcuts()
        self._notes_state.explicit_stage_intent = row_id in LIBRARY_NOTES_RAIL_ROWS
        if self._notes_state.explicit_stage_intent:
            self._notes_state.stage = "notes"
        # A rail-row press is always a fresh entry into a content type, so
        # the media canvas must never resume a previously opened viewer
        # (e.g. Browse Media -> open item -> Browse Conversations -> Browse
        # Media again must show the list, not the stale viewer).
        self._media_state.view = "list"
        self._media_state.detail = None
        self._media_state.composed_detail = None
        self._media_state.editing = False
        self._media_state.confirming_delete = False
        self._media_state.highlights = []
        self._media_state.editing_analysis = False
        self._close_library_media_find()
        self._media_state.content_mode = "raw"
        self._notes_state.filter = ""
        self._notes_state.filter_records = None
        self._notes_state.filter_generation += 1
        self._notes_state.tree_filter_state = None
        self._notes_state.browse_return_receipt = None
        if not retain_note_session:
            self._dispatch_database_note_identity_cleared()
            self._reset_library_note_editor_state()
        if not retain_prompt_draft:
            self._reset_library_prompt_editor_state()
        if row_id != LIBRARY_ROW_BROWSE_SKILLS:
            self._library_skill_import_coordinator.invalidate_row()
        # Review finding (Spec 1 T5): this rail-switch reset block does NOT
        # route through _reset_library_skill_editor_state() (skill-editor
        # exits handle their own reset there), so the trust-reset confirm
        # gate needs its own explicit clear here too -- otherwise arming it
        # (editor manifest_error panel or the list header) and then
        # switching rail rows away leaves it armed, and it can reappear
        # unprompted on a later, unrelated entry into the skills view.
        self._skills_state.trust_confirming_reset = False
        # (task-2043) The ingest form now PERSISTS across rail switches --
        # the old full reset discarded a typed path/metadata on every
        # switch, destructive for multi-batch workflows (round-2 critique).
        # Only switch-hygiene runs here; the deep-link entry keeps its
        # documented full reset.
        self._ingest_controller._pause_library_ingest_transient_ui()
        # Always resets to the Everything scope (a plain rail-row press,
        # unlike a browse-canvas "Export…" action, never carries a
        # section-specific filter) -- see
        # ``_reset_library_export_transient_state``'s docstring.
        self._reset_library_export_transient_state()
        self._invalidate_library_workspace_depth_state()
        if row_id == LIBRARY_ROW_CREATE_PROMPT:
            # Task 8b D1: "New prompt" -- applied AFTER
            # _reset_library_prompt_editor_state() above (which it would
            # otherwise immediately undo), mirroring the reset-then-set
            # ordering ``apply_navigation_context``'s notes-create branch
            # already uses.
            self._enter_library_prompt_create_editor()
        if row_id == LIBRARY_ROW_CREATE_SKILL:
            # Skills sub-project (skills-200 spec, "Create > New skill"):
            # same shape as the "New prompt" branch immediately above --
            # ``_enter_library_skill_create_editor`` fully (re)sets every
            # skill-editor field itself, so it needs no preceding
            # ``_reset_library_skill_editor_state()`` call here.
            self._enter_library_skill_create_editor()
        shell = build_library_shell_state(
            self._build_library_shell_input(),
            selected_row_id=self._library_selected_row_id,
        )
        self._library_selected_row_id = shell.selected_row_id
        replaced = False
        if self._library_ordinary_route_active() and self.query(
            "#library-canvas-route-content"
        ):
            replacement = self._build_library_entry_active_child()
            if replacement is not None:
                replaced = (
                    await self._replace_library_canvas_child(
                        replacement,
                        generation=self._library_snapshot_state_generation,
                        route_key=self._library_entry_route_key(),
                        rail_mode="selection",
                        then=self._focus_library_ordinary_canvas_entry,
                    )
                    is LibraryEntryReconcileResult.APPLIED
                )
        elif await self._replace_library_browse_canvas(shell):
            replaced = True
        if not replaced:
            await self.recompose()
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS:
            self.run_worker(
                self._load_library_collections_capture_entry(),
                exclusive=True,
                group="library_collections_capture_entry",
            )
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS:
            # The controller synchronizes its current/loading result
            # immediately. Dispatch only after the destination canvas is
            # mounted; dispatching before the awaited route recompose could
            # let both the immediate result and a fast worker result land in
            # the no-canvas window, permanently stranding a ready controller
            # result off screen under load.
            self._request_library_prompts_browse(
                self._library_prompt_browse_controller.mutation_refresh_scope,
                focus_identity=None,
            )
        if (
            retain_note_session
            and row_id == LIBRARY_ROW_BROWSE_NOTES
            and note_snapshot.dirty
        ):
            self._schedule_library_note_autosave()
        if self._library_ordinary_route_active():
            try:
                width = self.query_one("#library-shell-grid").region.width
            except (NoMatches, QueryError):
                width = 0
            if width > 0 and ordinary_emergency_required(width):
                self._advance_library_stage_interaction()
                self._library_emergency_stage = "canvas-only"
            self._apply_library_notes_stage_visibility()
            self.call_after_refresh(self._apply_library_notes_stage_visibility)
        else:
            self._library_emergency_stage = None
            self._library_emergency_restore_receipt = None
            self._apply_library_notes_stage_visibility()
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._skills_state.view == "list"
        ):
            # The strict posture projection requires its retained owner to exist.
            self._refresh_library_skills_trust_posture()
            self._request_library_skills_browse(
                self._library_skills_browse_controller.mutation_refresh_scope,
            )
            self.call_after_refresh(
                self._present_library_skills_import_choice_if_needed
            )
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA:
            # task-32065 (fix round 1): selecting a destination resolves THAT
            # destination's stage. The resolved layout carries a
            # ``priority_pane`` the resolver inherits on every later resolve,
            # so one "‹ Library" (or Library grip) press below the
            # single-stage floor pinned rail-plus-empty-Reader for the rest of
            # the visit -- critique #8's finding again, with the return
            # control hidden by its own rule. Pane PREFERENCES are untouched
            # (a manual open/close still persists); only the transient
            # starved-layout hint is cleared, and the resolver re-derives it.
            #
            # task-32065 (fix round 2): bounded to that same below-64
            # emergency band. At an ordinary width (100 columns, say) Library
            # and Items can each legitimately need the whole stage to
            # themselves too -- opening Library there closes Items and sets
            # this same ``priority_pane`` deliberately, not as a starved-width
            # artifact. Clearing it unconditionally wiped that choice too: one
            # "Browse Media" press closed the pane the user had just opened.
            try:
                media_shell_width = self.query_one(
                    f"#{LIBRARY_BROWSE_READER_SHELL_ID}"
                ).region.width
            except (NoMatches, QueryError):
                media_shell_width = 0
            if media_shell_width == 0 or media_shell_width < LIBRARY_EMERGENCY_WIDTH:
                self._media_state.reader_layout = dataclasses.replace(
                    self._media_state.reader_layout, priority_pane=None
                )
            self.call_after_refresh(self._sync_library_media_reader_layout_from_shell)
            self._request_library_media_browse(
                self._library_media_browse_controller.state.mutation_refresh_scope,
                focus_identity="#library-media-row-0",
            )
            self._request_library_media_facets()
            # task-28245: entering the media area with an active review set
            # resumes it at its cursor without a keypress (once per set).
            self._maybe_auto_resume_review_set()
        # task-2856 AC1: a rail-row press landing on one of the four list
        # canvases focuses its primary list's first row -- the entry-point
        # half of the same seam ``_exit_library_skill_editor_guarded`` /
        # ``_return_to_library_database_notes`` /
        # ``_exit_library_media_viewer`` / ``_exit_library_note_editor_guarded``
        # / ``_exit_library_prompt_editor_guarded`` use for the RETURN half.
        # Explicitly the four BROWSE_* ids, NOT
        # ``_LIBRARY_LIST_ROW_CLASS_BY_ROW_ID`` (which also maps CREATE_
        # PROMPT/CREATE_SKILL -- needed for the RETURN half's row-class
        # lookup once back on the list, but a FRESH press into either
        # ALWAYS lands in the editor, never the list; the branches below
        # set that editor's own field focus instead).
        if self.is_mounted and self._library_selected_row_id in (
            LIBRARY_ROW_BROWSE_MEDIA,
            LIBRARY_ROW_BROWSE_NOTES,
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
            # task-32228 (critique #9 fix round 1): Conversations is the fifth.
            # It was left out, so arriving here put focus outside the reader
            # shell -- which is why its Escape hop had nowhere to start from
            # and its footer (correctly) withheld the chip. The keys were never
            # missing; the state that makes them live was.
            LIBRARY_ROW_BROWSE_CONVERSATIONS,
        ):
            self._arm_library_list_entry_focus()
        if self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT:
            self._start_library_export_counts_worker()
        self._arm_library_row_entry_focus(row_id)

    def _arm_library_row_entry_focus(self, row_id: str) -> None:
        """Park entry focus for one destination row once its canvas exists.

        task-32245: this was inline in the rail-row switch, so it ran only
        on that route. The navigation-context deep links
        (``apply_navigation_context``) apply the SAME row selection and
        recompose from it, but skipped every arm here -- so the wizard's
        "Write your first note" hand-off landed on the New-note canvas with
        nothing focused: its advertised "enter create note" was dead (the
        footer fell back to the bare "esc back to notes" tier) and the first
        Enter fell through to the app's own binding and left Library for
        Home. Both routes now share this one arm.

        Args:
            row_id: The destination rail row the route is landing on.
        """
        if row_id == LIBRARY_ROW_INGEST_MEDIA and self.is_mounted:
            # task-3302 AC#1 (MI-03): entering Ingest parks the caret in
            # the path field -- the first action on this canvas is always
            # typing/pasting a path. Previously focus stayed wherever it
            # was (the rail search box in the live walk), so typing a path
            # ran a Library search. Same call_after_refresh seam the
            # CREATE_PROMPT/CREATE_SKILL entry-focus branches below use.
            self.call_after_refresh(self._focus_library_ingest_path)
            self.call_after_refresh(self._ingest_controller._sync_library_ingest_rail_from_shell)
        if row_id == LIBRARY_ROW_CREATE_NOTE and self.is_mounted:
            # task-32052 AC#1: the New-note canvas opened with NOTHING
            # focused, so its advertised "enter create note" was dead and
            # the first note was mouse-only. The retained-shell route
            # (``_try_switch_retained_library_notes_route``) already restores
            # this exact control, but it only handles Notes list -> Create;
            # arriving from the landing's ``n`` (or any other row) fell
            # through to this legacy route, which restored nothing.
            self.call_after_refresh(
                self._focus_library_note_control, "#library-notes-create-blank"
            )
        if row_id == LIBRARY_ROW_CREATE_PROMPT and self.is_mounted:
            self.call_after_refresh(self._arm_library_prompt_editor)
        if row_id == LIBRARY_ROW_CREATE_SKILL and self.is_mounted:
            self.call_after_refresh(self._arm_library_skill_editor)
            # task-424: first action in a blank create editor is always
            # naming it -- put the caret there.
            self.call_after_refresh(self._focus_library_skill_name)
        if row_id in {
            LIBRARY_ROW_BROWSE_PROMPTS,
            LIBRARY_ROW_BROWSE_SKILLS,
            LIBRARY_ROW_BROWSE_COLLECTIONS,
            LIBRARY_ROW_BROWSE_SEARCH,
            LIBRARY_ROW_INGEST_EXPORT,
            *LIBRARY_STUDY_HANDOFF_ROW_IDS,
        }:
            self.call_after_refresh(self._focus_library_ordinary_canvas_entry)
            if self._library_emergency_stage == "canvas-only":
                self._focus_library_ordinary_canvas_entry()

    def _try_switch_retained_library_notes_route(self, row_id: str) -> bool:
        return self._notes_controller._try_switch_retained_library_notes_route(row_id)

    @on(Button.Pressed, ".console-rail-section-toggle")
    def handle_library_rail_section_toggle(self, event: Button.Pressed) -> None:
        """Toggle a Library rail section and persist the preference.

        Args:
            event: Button press event emitted by a rail section's
                collapse/expand toggle.
        """
        button_id = event.button.id or ""
        prefix = f"{RAIL_SECTION_TOGGLE_PREFIX}library-"
        if not button_id.startswith(prefix):
            return
        event.stop()
        section_id = button_id.removeprefix(prefix)
        currently_open = bool(
            getattr(self._library_rail_preferences(), f"{section_id}_open", True)
        )
        self._set_library_rail_section(section_id, not currently_open)

    @on(LibraryRail.DiagnosticsOpened)
    def refresh_library_details_sizes_for_diagnostics(
        self, event: LibraryRail.DiagnosticsOpened
    ) -> None:
        """Recompute the DB sizes the Diagnostics disclosure just revealed.

        Qodo review #2: task-4023 AC#3 made opening a disclosure the
        refresh trigger, and `_set_library_rail_section` only fires it for
        the OUTER Details section. Nesting the size rows one disclosure
        deeper (task-32357 AC#2) put them back behind a toggle that
        refreshed nothing, so opening Diagnostics with Details already open
        revealed whatever the cache last held. Same worker, same exclusive
        group, so the two triggers cannot run twice over each other.

        Args:
            event: The rail's own open notice; it never fires on close.
        """
        event.stop()
        self.run_worker(
            self._refresh_library_details_db_sizes(),
            exclusive=True,
            group="library_details_db_sizes",
        )

    @on(Button.Pressed, ".library-conversation-row")
    def handle_library_conversation_row(self, event: Button.Pressed) -> None:
        """Select mode: toggle the row's checkbox. Normal mode: select the row.

        In select mode, a row press toggles that row's id in
        ``self._conversations_state.row_selection`` (conversations resolves
        its selection state through the dotted ``_conversations_state``
        path, not a flat ``_library_conversations_row_selection`` attribute
        -- see ``_apply_library_row_toggle``'s docstring in
        ``UI/Library_Modules/canvas_sync.py`` for the attrgetter dispatch
        that routes each not-yet-extracted subsystem's flat name versus
        conversations' dotted one) and patches the row's
        marker, the "N selected" Static, and export-selected's disabled
        state in place (task-252 Tier 1) -- it never sets the normal-mode
        selection/detail while in select mode. Outside select mode,
        behavior is unchanged: selects the conversation and switches the
        Library rail to the conversations browse row -- a canvas-scoped
        ``sync_state`` (task-252 Tier 2), not a screen-level recompose;
        the rail row itself never changes here (this row press is only
        reachable while already browsing conversations).

        Args:
            event: Button press event emitted by a conversation row button.
        """
        event.stop()
        if self._conversations_state.freshness != "fresh":
            return
        conversation_id = str(getattr(event.button, "conversation_id", "") or "")
        if self._conversations_state.select_mode:
            self._conversations_state.row_selection.toggle(conversation_id)
            _apply_library_row_toggle(
                self, "conversations", event.button, conversation_id
            )
            self._conversations_state.reader_state = project_conversation_multiselect(
                self._conversations_state.reader_state,
                active=True,
                selected_count=self._conversations_state.row_selection.count,
                loaded_preview_selected=self._library_conversation_loaded_preview_selected(),
            )
            self._sync_library_conversation_reader()
            for action in ("archive-selected", "restore-selected"):
                for button in self.query(f"#library-conversations-{action}"):
                    button.disabled = not self._conversations_state.row_selection.count
            return
        if conversation_id:
            self._acknowledge_library_destination_change()
            self._selected_conversation_id = conversation_id
        self._library_selected_row_id = LIBRARY_ROW_BROWSE_CONVERSATIONS
        _sync_library_canvas(self, "conversations")
        if conversation_id:
            self._start_library_conversation_reader_selection(conversation_id)



