    @on(Button.Pressed, "#library-skills-import-review")
    async def handle_library_skills_import_review(self, event: Button.Pressed) -> None:
        """Open the just-imported skill's editor (its trust panel included).

        task-422: the import success copy tells the user to "re-review it
        in the trust panel" -- this is the direct path, reusing the exact
        row-press open flow.

        Args:
            event: Button press event emitted by the import row's
                "Review …" action.
        """
        event.stop()
        if not _library_screen_is_current(self):
            return
        if getattr(self, "_library_skills_import_in_flight", False):
            self._apply_library_skills_import_status(
                "An import is already in progress."
            )
            return
        name = self._library_skills_import_review_name
        if not name:
            return
        if not await self._flush_library_skill_save():
            return
        if getattr(self, "_library_skills_import_in_flight", False):
            self._apply_library_skills_import_status(
                "An import is already in progress."
            )
            return
        self._library_skill_import_coordinator.dismiss()
        self._reset_library_skill_editor_state()
        self._skills_state.selected_skill_name = name
        self._library_selected_row_id = LIBRARY_ROW_BROWSE_SKILLS
        self._skills_state.view = "editor"
        self._skills_state.reader_mode = "trust"
        self.run_worker(
            self._refresh_library_skill_detail(name),
            exclusive=True,
            group="library_skill_detail",
        )
        _sync_library_canvas(self, "skills")

    @on(Input.Changed, "#library-skills-import-path")
    def handle_library_skills_import_path_changed(self, event: Input.Changed) -> None:
        """Track the Import row's path text as the user types it (state only).

        Args:
            event: Input change event emitted by the Import row's path field.
        """
        event.stop()
        if (
            not _library_screen_is_current(self)
            or getattr(self, "_library_skills_import_in_flight", False)
            or not getattr(self, "_library_skills_import_open", True)
            or getattr(
                self,
                "_library_selected_row_id",
                LIBRARY_ROW_BROWSE_SKILLS,
            )
            != LIBRARY_ROW_BROWSE_SKILLS
        ):
            return
        changed_input = getattr(event, "input", None)
        if changed_input is not None:
            try:
                current_input = self.query_one("#library-skills-import-path", Input)
            except (NoMatches, QueryError):
                return
            if changed_input is not current_input:
                return
        if self._library_skills_import_path != event.value:
            self._library_skills_import_generation += 1
            self._library_skill_import_coordinator.update_draft_path(event.value)

