    def _library_skill_editor_active(self) -> bool:
        """True while the in-canvas skill editor is the live view (task-424)."""
        return (
            self._library_selected_row_id
            in (LIBRARY_ROW_BROWSE_SKILLS, LIBRARY_ROW_CREATE_SKILL)
            and self._skills_state.view == "editor"
        )

    def _library_skill_save_available(self) -> bool:
        """Return whether the lifecycle currently exposes a Skill save."""
        return bool(
            self._library_skill_editor_active()
            and (self._skills_state.dirty or not self._skills_state.selected_skill_name)
            and not self._skills_state.conflict
            and not self._skills_state.confirming_delete
            and not self._skills_state.mutation_in_flight
        )

    def check_action(self, action: str, parameters: tuple[object, ...]) -> bool | None:
        """Gate bindings and advertised shortcuts to their active Library context.
        False allows same-key bindings to fall through; every non-universal action
        must have an explicit gate (including Search/RAG evidence-card actions).

        Args:
            action: Binding action name.
            parameters: Unused; gated bindings are parameterless.

        Returns:
            False to deactivate, True to activate, or None for Textual's default."""
        if action in {"focus_next", "focus_previous"}:
            # task-32106 (PR #2571 re-review, NEW-1). These stay universal
            # everywhere except the canvas-only emergency stage, where
            # ``on_key``'s ``emergency_tab`` branch OWNS Tab: it advances the
            # emergency interaction and gives Shift+Tab its hop to
            # ``#library-emergency-return``. A note field's PRIORITY tab
            # binding would be consumed by ``App._check_bindings`` before
            # ``on_key`` runs, so deactivating the action there hands the key
            # back to the normal path and that branch keeps working. The
            # screen's own non-priority binding never ran there either --
            # ``on_key`` stops the event first -- so nothing else changes.
            return not (
                self._library_emergency_stage == "canvas-only"
                and self._library_emergency_restore_receipt is not None
            )
        if action in {
            "library_notes_new",
            "library_notes_focus_filter",
            "library_notes_save",
            "library_notes_escape",
        }:
            visible_notes = self._library_notes_workflow_active() and not (
                self._notes_state.compact and self._notes_state.stage != "notes"
            )
            region = self._library_notes_focus_region()
            if action == "library_notes_new":
                # task-32138: ctrl+n was inert on the Library landing --
                # only the bare `n` accelerator (a separate, manual on_key
                # branch, task-2237) opened Create there, while ctrl+n only
                # fired once already inside Notes. Both keys now cover both
                # places (see the pinned reconciliation note on
                # ``test_library_notes_bindings_are_inactive_outside_notes_
                # workflow``): the landing has no selected row, so widen the
                # gate the same way task-3302 widened `i`/Import to work
                # from anywhere.
                return bool(
                    (
                        visible_notes
                        and region
                        in {"navigator", "editor", "preview", "context"}
                    )
                    or not self._library_selected_row_id
                )
            if action == "library_notes_focus_filter":
                return bool(
                    visible_notes
                    and region == "navigator"
                    and not isinstance(self.focused, (Input, TextArea))
                )
            if action == "library_notes_save":
                return (
                    visible_notes
                    and not self._notes_state.select_mode
                    and region in {"editor", "preview", "context"}
                )
            return visible_notes
        if action == "library_skill_save":
            return self._library_skill_save_available()
        if action == "library_skill_back":
            return self._library_skill_editor_active()
        if action == "library_notes_files_back":
            return self._file_notes_active()
        if action == "library_media_viewer_back":
            return (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and getattr(self._media_state, "view", _MEDIA_VIEW_LIST)
                == _MEDIA_VIEW_VIEWER
                and not self._media_state.bulk_delete_in_flight
                # task-31272: the same seam the footer chip reads (cf. the
                # Conversations gate below). "" means Escape does nothing
                # here -- at the three-pane rail terminus -- so leave the
                # key un-gated rather than swallow it, exactly as the
                # footer advertises no chip there.
                and bool(self._library_media_escape_label())
            )
        if action == "library_media_trash_back":
            # task-4025: only while the media canvas genuinely shows its
            # Trash view -- mirrors the viewer-back gate above.
            trash_controller = getattr(
                self, "_library_media_trash_browse_controller", None
            )
            trash_state = getattr(trash_controller, "state", None)
            return (
                self._library_selected_row_id == LIBRARY_ROW_BROWSE_MEDIA
                and getattr(self._media_state, "view", "list") == "trash"
                and not bool(getattr(trash_state, "mutation_pending", False))
            )
        if action == "library_notes_trash_restore":
            # Exactly when a Restore button is on screen to stand for -- the
            # Notes canvas showing its Trash view, with rows and no mutation
            # already in flight.
            trash = self._notes_state.trash
            return bool(
                self._library_notes_workflow_active()
                and self._notes_state.view == "trash"
                and trash is not None
                and trash.rows
                and not self._library_notes_mutation_fenced()
            )
        if action in {
            "library_media_trash_restore",
            "library_media_trash_delete",
        }:
            # task-31635 item 3: exactly when the buttons these keys stand
            # for are pressable -- see ``_library_media_trash_actions_live``.
            return self._library_media_trash_actions_live()
        if action == "library_note_editor_back":
            return (
                self._library_note_editor_active()
                and not self._notes_state.select_mode
            )
        if action == "library_prompt_editor_back":
            return (
                self._prompts_controller._library_prompt_editor_active()
                and not self._prompts_state.select_mode
            )
        if action == "library_ingest_back":
            return (
                self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA
                and not self._library_emergency_return_eligibility().enabled
            )
        if action == "library_export_back":
            return (
                self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT
                and not self._library_emergency_return_eligibility().enabled
            )
        if action == "library_handoff_back":
            return (
                self._library_selected_row_id in LIBRARY_STUDY_HANDOFF_ROW_IDS
                and not self._library_emergency_return_eligibility().enabled
            )
        if action == "library_media_bulk_delete_cancel":
            # task-3020 AC2: only while the bulk-delete confirmation is
            # genuinely armed -- mirrors the single-item viewer confirm's
            # own Escape-cancels gate (``library_media_viewer_back``'s
            # ``_library_media_confirming_delete`` branch above). Declared
            # BEFORE ``library_list_focus_rail`` in BINDINGS: that gate is
            # ALSO True on this exact state (the list is still genuinely
            # showing), so declaration order is what keeps this one
            # exclusive, not this predicate.
            return (
                self._media_state.confirming_bulk_delete
                and not self._media_state.bulk_delete_in_flight
            )
        if action == "library_conversation_open_console":
            # task-32056: the Conversations half of the shared "c" key.
            # task-32101: live wherever a conversation is OPEN, not only
            # where the hand-off is ready -- the action itself refuses with
            # the sentence the disabled control shows. Gating the key on
            # readiness (fix round 1) made it silent on exactly the state
            # the user needs explained. The footer chip still tracks
            # readiness (see ``_library_route_shortcuts_for_current_state``),
            # so nothing is advertised as working while it is blocked.
            reader_state = self._conversations_state.reader_state
            return self._library_selected_row_id == (
                LIBRARY_ROW_BROWSE_CONVERSATIONS
            ) and bool(reader_state.selected_id or reader_state.loaded_id)
        if action == "library_emergency_return":
            return self._library_emergency_return_eligibility().enabled
        if action == "library_narrow_stage_return":
            # task-32225: exactly while the Library pane is closed on the live
            # adaptive route -- the same predicate the footer chip reads, so
            # the chip and the key can never disagree.
            return self._library_narrow_stage_return_active()
        if action == "library_ingest_retry_last":
            # task-3313: only on the Ingest canvas AND while the affordance
            # itself is offered. THE SAME predicate the state builder uses
            # for ``show_retry_last`` -- imported, not restated. This gate
            # used to carry its own copy of the rule with the settled-queue
            # half missing, so mid-run the key stayed live exactly while
            # the button was hidden to prevent a duplicate batch (xhigh
            # review + live-verify round).
            if self._library_selected_row_id != LIBRARY_ROW_INGEST_MEDIA:
                return False
            registry = self._library_ingest_registry()
            jobs_fn = getattr(registry, "jobs", None)
            jobs = jobs_fn() if callable(jobs_fn) else ()
            return library_ingest_retry_available(
                jobs,
                last_submission_available=(
                    getattr(self._ingest_state, "last_submission", None) is not None
                ),
            )
        if action == "library_blur_text_field":
            # task-32051: only while a text box genuinely owns the caret, and
            # only where no EARLIER Escape binding already owns the key --
            # the same try-in-order resolution Textual applies to the key
            # itself, restated here because ``check_action`` is also what F1
            # and the footer read (they have no notion of declaration order,
            # so a bare "a text field has focus" gate would double the Escape
            # row in F1 on every canvas that already has one).
            if not isinstance(self.focused, (Input, TextArea)):
                return False
            if any(
                self.check_action(earlier, ())
                for earlier in self._library_escape_actions_before(action)
            ):
                return False
            # ...and never take the key from the focus-rail hop declared
            # AFTER this one when that hop would genuinely MOVE focus. On a
            # list canvas with the caret in the canvas filter box, the footer
            # promises "esc focus rail" and must be telling the truth; this
            # binding exists only for the case where that hop lands on the
            # widget that already has focus (the rail search box), which is
            # what made Escape inert and let the next key be typed.
            if self.check_action("library_list_focus_rail", ()):
                target = self._library_list_focus_rail_target().lstrip("#")
                return not target or target == (self.focused.id or "")
            return True
        if action == "library_list_focus_rail":
            # task-4023 AC#7: Collections joins the list-canvas Escape
            # contract (it was the one browse canvas where Escape was
            # inert) -- a plain list surface's Escape is a focus hop
            # toward the rail, never navigation.
            if self._library_emergency_return_eligibility().visible:
                return False
            if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
                return bool(
                    self._conversations_controller._library_conversation_escape_label()
                )
            return (
                self._library_list_canvas_showing_list()
                or self._library_selected_row_id == LIBRARY_ROW_BROWSE_COLLECTIONS
            )
        if action == "library_rag_use_in_console":
            # Mirrors action_library_rag_use_in_console's own gate exactly
            # (that method also accepts no focused card -- "u" stages
            # whatever evidence is already selected -- so this cannot be
            # narrowed to the focused-card predicate below without making
            # the gate stricter than the action itself).
            return self._library_selected_row_id == LIBRARY_ROW_BROWSE_SEARCH
        if action in (
            "library_rag_result_card_select",
            "library_rag_result_card_open",
        ):
            return self._focused_library_rag_result_card_index() is not None
        if action == "library_media_toggle_select_mode":
            # task-28012: only on the media LIST (not viewer/trash), and not
            # while a bulk-delete confirm is armed or a delete is in flight.
            # task-31272: the live LIST SURFACE, not the view flag -- in
            # the three-pane shell the Reader never leaves "viewer", so
            # this gate stayed off for the whole visit while the user was
            # standing on a list row.
            if (
                not self._library_media_list_surface_active()
                or self._media_state.confirming_bulk_delete
                or self._media_state.bulk_delete_in_flight
            ):
                return False
            # task-28012 (Qodo #2309): exiting an active selection is always
            # allowed (rows may have vanished), but ENTERING must obey the
            # same availability as the Select button -- no rows, or a stale
            # page, disables it.
            if self._media_state.select_mode:
                return True
            return self._library_media_select_enter_available()
        if action == "library_media_toggle_row_selection":
            # task-28012: Space is the selection key. task-31271 seam (b):
            # the old gate let a False fall THROUGH to the focused widget,
            # and on a pane grip that collapsed the Library pane while the
            # footer said "toggle selection" (B cap_69). The binding is
            # priority now, so it outranks the focused Button -- which
            # means the gate must claim only what Space should own:
            # a media row (toggle it) and MEDIA's own pane GRIPS (chrome;
            # swallow it). Every other button in select mode -- Done,
            # Select all, Clear, Export, Delete -- keeps its own Space
            # press. A focused Input still swallows the space first
            # (Textual filters consumed keys out of the binding chain), and
            # the freshness/confirm/in-flight guards live inside the action
            # so those states no-op rather than firing something else.
            #
            # Review round: the surface guard and the MEDIA-specific grip
            # class are both load-bearing. Select mode survives a rail
            # switch (only Done, a bulk delete, and the media scope-change
            # sites clear it), and
            # ``library-adaptive-reader-pane-grip`` is the SHARED base
            # class every destination's shell applies -- matching it
            # swallowed Space on the Notes/Prompts/Skills grips after an
            # abandoned media selection. ``library-media-pane-grip`` is what
            # ``LibraryBrowseReaderShell.apply_route`` puts on both grips
            # while Media owns the shared shell; the surface guard mirrors
            # the sibling ``library_media_toggle_select_mode`` branch above.
            if not self._media_state.select_mode:
                return False
            if self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA:
                return False
            focused = self.focused
            return bool(
                focused is not None
                and (
                    focused.has_class("library-media-row")
                    or focused.has_class("library-media-pane-grip")
                )
            )
        if action in ("library_media_next_item", "library_media_prev_item"):
            # task-28005: active only in the plain Reader with a neighbour in
            # that direction, so the key no-ops (and drops from the footer)
            # at the list ends -- the honest-footer idiom that communicates
            # the boundary. A focused Input still consumes "[" / "]" first.
            if not self._library_media_item_traversal_active():
                return False
            # task-30041 (critique P1): with an active review set the keys
            # walk the PINNED SET, so browse-row adjacency is the wrong
            # gate -- it disabled the documented final-] completion gesture
            # at the last browse row and misfired whenever set order
            # diverged from browse order. The walk clamps safely at the
            # set's ends.
            if self._review_set_active():
                return True
            direction = 1 if action == "library_media_next_item" else -1
            return self._library_media_adjacent_row(direction) is not None
        if action in (
            "library_media_read_later",
            "library_media_use_in_console",
            "library_media_move_to_trash",
            "library_media_reader_find",
        ):
            # task-28027: Reader action-row accelerators. Only in a plain
            # media Reader (no edit/confirm/analysis-edit sub-state). Read-
            # later and Move-to-trash are local-only (mirroring the buttons,
            # which are hidden for external/server detail); Use-in-Console
            # works for server items too.
            session = self._media_state.reader_session
            if (
                self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
                or self._media_state.view != "viewer"
                or self._library_media_viewer_substate_active()
            ):
                return False
            # Qodo #2317: while a detail request is pending, the selected id
            # and the displayed detail differ (e.g. mid-traversal), so these
            # actions would combine the new id with stale detail. Gate them
            # off until the displayed detail is the settled selected item.
            if (
                session.pending_request is not None
                or session.loaded_id != self._media_state.selected_media_id
            ):
                return False
            if action == "library_media_reader_find":
                # task-32348: live only where the button is enabled AND the
                # Reader is settled -- the fences above (this row, the
                # viewer view, no sub-state, no pending detail) make the key
                # strictly narrower than the button, which consults only
                # ``analysis_find_unavailable_reason``. The footer chip is
                # gated on this same call, so it can never advertise a
                # refusal either way.
                return not self._library_media_find_unavailable_reason()
            if (
                action == "library_media_move_to_trash"
                and self._media_state.find_open
            ):
                # task-32348 AC#2 (B D4a): with the Find bar open the user is
                # typing a query. The bar takes focus on mount, so this is
                # belt-and-braces -- but the one path where it did NOT (a
                # tab with no bar, now refused outright) armed "Delete this
                # media?" from the "t" of "token". The footer chip drops
                # with the gate.
                return False
            if action == "library_media_use_in_console":
                return True
            return not session.external_detail
        if action in (
            "library_media_exit_review",
            "library_media_toggle_reviewed",
        ):
            # task-28241: only in a plain Reader while a review set is active
            # (so the keys -- and their footer hints -- appear exactly when
            # there is a review to act on).
            return (
                self._library_media_item_traversal_active()
                and self._review_set_active()
            )
        if action == "focus_previous_workbench_pane":
            return bool(self._library_selected_row_id)
        return True

    def action_show_workbench_help(self) -> None:
        """Show live footer shortcuts plus check_action-gated Binding extras.

        Both sources are necessary: generic help leaks inactive editor/evidence
        bindings, while Bindings alone omit on_key/app-global shortcuts and leave
        landing help empty (task-2858/LIB-09). Use the same current-state selection
        as the footer. Do not apply the footer widget's reserved-global filter:
        F1 must retain F6 as the discoverability fallback when narrow footer
        chrome cannot display it (LIB-18).
        """
        from ..Workbench.help import (  # noqa: PLC0415 -- lazy: only needed on F1; keeps the help panel off the module import path
            WorkbenchHelpPanel,
            WorkbenchHelpState,
        )

        footer_shortcuts = self._library_footer_shortcuts_for_current_state()
        # (task-3312 #1) Dedupe on the CANONICAL key, not the raw string:
        # the shared footer sets spell the exit key "esc" while BINDINGS
        # entries spell it "escape" (Textual's key name), so a raw-string
        # comparison kept both and F1 listed the exit twice in Ingest
        # ("esc: back to hub" + "escape: Back to Library hub" -- live,
        # 2026-08-08). Case is folded for the same reason ("F6" vs "f6").
        # (task-4023 AC#4 / RC-10) The seen-set also GROWS as extras
        # accumulate: two simultaneously active same-key BINDINGS extras
        # (this screen's many "escape" entries share one key) previously
        # had no intra-set dedupe, so a surface whose footer set lacks
        # "esc" could still list Escape twice with two labels. Keeping the
        # FIRST active entry matches how Textual resolves same-key
        # bindings -- declaration order, first passing gate wins -- so the
        # panel names the action the key would actually run.
        seen_keys = {
            _canonical_shortcut_key(key) for key, _description in footer_shortcuts
        }
        binding_extras: list[tuple[str, str]] = []
        for pair in self._active_library_binding_shortcuts():
            canonical = _canonical_shortcut_key(pair[0])
            if canonical in seen_keys:
                continue
            seen_keys.add(canonical)
            binding_extras.append(pair)
        # (task-4023 AC#4 / RC-10) Name the surface the panel describes --
        # "Collections' panel says nothing about Collections". The label
        # comes from the selected rail row (surface identity), not from a
        # second copy of the shortcut-set decision tree; the SET itself
        # still has exactly one source (the footer seam above).
        surface_label = self._library_help_surface_label()
        state = WorkbenchHelpState(
            route_id="library",
            title=(
                f"Library Shortcuts — {surface_label}"
                if surface_label
                else "Library Shortcuts"
            ),
            shortcuts=footer_shortcuts + tuple(binding_extras),
        )
        self.app.push_screen(WorkbenchHelpPanel(state))

    def _library_help_surface_label(self) -> str:
        """Return the current surface's human name for the F1 panel title.

        Derived from the selected rail row -- surface identity, not a fork
        of the shortcut-set decision tree. An unmapped row id (e.g. the
        Study staging rows) returns "" and the panel keeps its generic
        title rather than inventing a name.
        """
        row_id = getattr(self, "_library_selected_row_id", "")
        if not row_id:
            return "Landing"
        return _LIBRARY_HELP_SURFACE_LABELS.get(row_id, "")

    def _active_library_binding_shortcuts(self) -> tuple[tuple[str, str], ...]:
        """Filter ``BINDINGS`` through ``check_action`` for the F1 panel.

        Same keep/drop rule ``Screen.active_bindings`` uses: a
        ``check_action`` result of ``False`` means genuinely inactive
        right now (dropped); ``True`` or ``None`` both mean "keep it"
        (``None`` is what ``check_action``'s own fallback branch would
        return for an action with no explicit gate -- none remain on
        this screen after task-2858, see
        ``test_library_screen_bindings_are_all_gated_or_universal``, but
        the same-as-Textual semantics are kept here defensively).
        """
        pairs: list[tuple[str, str]] = []
        for entry in self.BINDINGS:
            if isinstance(entry, Binding):
                key, action, description = entry.key, entry.action, entry.description
            elif isinstance(entry, (tuple, list)) and entry:
                key = str(entry[0])
                action = str(entry[1]) if len(entry) > 1 else ""
                description = str(entry[2]) if len(entry) > 2 else ""
            else:
                continue
            if not action:
                continue
            if action in ("focus_next", "focus_previous"):
                # task-32052: Tab/Shift+Tab are app-wide keyboard chrome
                # this screen only re-declares to scope (see
                # ``action_focus_next``), not Library shortcuts. Listing
                # them would put two universally-true rows at the top of
                # every surface's panel -- the same contamination LIB-09
                # cleaned out.
                continue
            try:
                gate_state = self.check_action(action, ())
            except Exception:
                # A screen-wide help panel must never crash the app over a
                # single misbehaving gate -- fail open (keep the entry)
                # rather than hide a key silently.
                logger.debug(
                    f"check_action raised for Library binding action "
                    f"{action!r}; keeping it in the F1 panel.",
                    exc_info=True,
                )
                gate_state = True
            if gate_state is False:
                continue
            pairs.append((key, description))
        return tuple(pairs)

    def action_library_skill_save(self) -> None:
        """Ctrl+S: save the open skill from anywhere in the editor (task-424)."""
        if not self._library_skill_editor_active():
            return
        # No save during the conflict banner or the delete confirmation --
        # in both states the Save button is gone, so the accelerator must
        # not fire an action the visible chrome no longer offers (review
        # finding for the delete-confirm case).
        if (
            self._skills_state.conflict
            or self._skills_state.confirming_delete
            or self._skills_state.mutation_in_flight
        ):
            return
        self._begin_library_skill_save()

    async def action_library_skill_back(self) -> None:
        """Escape: leave the editor, honoring the unsaved-changes guard (task-424)."""
        if not self._library_skill_editor_active():
            return
        if self._skills_state.more_actions_open:
            self._skills_state.more_actions_open = False
            self._sync_library_skill_lifecycle_actions()
            try:
                self.query_one("#library-skill-more-actions", Button).focus()
            except (NoMatches, QueryError):
                pass
            return
        await self._exit_library_skill_editor_guarded()

    async def _exit_library_skill_editor_guarded(self) -> bool:
        """Shared Back exit: veto (with toast) while dirty, else reset to list.

        Returns:
            ``True`` when the editor was exited; ``False`` on a dirty veto.
        """
        if not await self._flush_library_skill_save():
            self._notify_skill_dirty_veto()
            return False
        self._reset_library_skill_editor_state()
        self._refresh_local_source_snapshot()
        self._request_library_skills_browse(
            self._library_skills_browse_controller.mutation_refresh_scope,
        )
        # task-2856 AC1: every "back to list" exit re-focuses the list's
        # first row so Up/Down/Enter work immediately, without a separate
        # Tab traversal back to it.
        self._arm_library_list_entry_focus()
        return True

