    async def _flush_library_prompt_save(self) -> bool:
        """Veto leaving the prompt editor while an edit is unsaved.

        Unlike the notes editor (autosave debounced on every keystroke),
        the prompt editor is explicit-Save-only: there is no pending
        background save to wait for or silently trigger here. This simply
        reports whether it is safe to proceed -- ``False`` whenever
        ``_prompts_state.dirty`` is set, so destructive callers
        (``flush_pending_work``, prompt-row selection, Back, and non-reader
        rail selection) abort the navigation/switch and leave the user's edit
        in place for them to explicitly Save or abandon, mirroring the veto shape
        ``_flush_library_note_save`` gives ``flush_pending_work`` on a
        genuine save failure.

        Returns:
            ``True`` when there is nothing unsaved (safe to proceed);
            ``False`` when a dirty edit must be resolved first.
        """
        return not self._prompts_state.dirty

    def _apply_library_prompt_working_copy(self, *, state: PromptBlockEditorState, system_prompt: str | None, user_prompt: str | None) -> None:
        return self._prompts_controller._apply_library_prompt_working_copy(state=state, system_prompt=system_prompt, user_prompt=user_prompt)

    def _stage_library_prompt_for_console(
        self,
        *,
        system_prompt: str | None,
        user_prompt: str | None,
    ) -> None:
        """Open the shared Prompt dialog or stage a variable-free User append."""
        if self._prompts_state.mutation_in_flight:
            return
        notify = getattr(self.app_instance, "notify", None)
        target_getter = getattr(
            self.app_instance,
            "console_prompt_target_projection",
            None,
        )

        def _current_console_target() -> ConsolePromptTargetProjection | None:
            try:
                projection = target_getter() if callable(target_getter) else None
            except Exception:
                return None
            return (
                projection
                if isinstance(projection, ConsolePromptTargetProjection)
                else None
            )

        target = _current_console_target()
        if target is None:
            if callable(notify):
                notify(
                    "Open Console once, then retry Use in Console.",
                    severity="warning",
                )
            return
        stage = getattr(self.app_instance, "stage_console_prompt_insert", None)
        push_screen = getattr(self.app_instance, "push_screen", None)
        if not callable(stage) or not callable(push_screen):
            if callable(notify):
                notify("Console insert is unavailable.", severity="warning")
            return

        system_source = self._sanitize_note_content(
            system_prompt or "",
            max_length=LIBRARY_PROMPT_TEXT_MAX_CHARS,
        )
        user_source = self._sanitize_note_content(
            user_prompt or "",
            max_length=LIBRARY_PROMPT_TEXT_MAX_CHARS,
        )
        system_text = system_source if system_source.strip() else None
        user_text = (
            None if system_text is not None and not user_source.strip() else user_source
        )
        if system_text is None and not user_source.strip():
            if callable(notify):
                notify(
                    "This prompt has no user prompt text to insert.",
                    severity="warning",
                )
            return

        plan = compile_prompt_variables(
            system_text=system_text,
            user_text=user_text,
        )
        if system_text is None and plan.is_valid and not plan.variables:
            stage(
                PromptVariableApplication(
                    system_text=None,
                    user_text=user_text,
                    apply_system=False,
                    apply_user=True,
                    destination="append_active",
                    target_session_id=target.target_session_id,
                    composer_fingerprint=None,
                    system_fingerprint=None,
                )
            )
            return

        request = PromptVariablesDialogRequest(
            system_text=system_text,
            user_text=user_text,
            destination="append_active",
            target_session_id=target.target_session_id,
            composer_fingerprint=None,
            system_fingerprint=(
                target.system_fingerprint if system_text is not None else None
            ),
        )

        def _stage_dialog_result(
            application: PromptVariableApplication | None,
        ) -> None:
            if self._prompts_state.mutation_in_flight or application is None:
                return
            live_target = _current_console_target()
            if live_target != target:
                if callable(notify):
                    notify(
                        "Open Console once, then retry Use in Console.",
                        severity="warning",
                    )
                return
            stage(application)

        push_screen(
            PromptVariablesDialog(request),
            callback=_stage_dialog_result,
        )

    @on(Button.Pressed, "#library-prompt-insert-console")
    def handle_library_prompt_insert_console(self, event: Button.Pressed) -> None:
        """Stage the open Prompt through the shared Console append flow.

        Reads the editor's live System/User text after the artifact and dirty
        guards. Variable-bearing or System-bearing prompts use the shared
        dialog; a variable-free User-only prompt takes the typed fast path.

        Args:
            event: Button press event emitted by the editor's "Use in
                Console" action.
        """
        event.stop()
        if self._prompts_state.mutation_in_flight:
            return
        notify = getattr(self.app_instance, "notify", None)
        if self._prompts_state.view != "editor":
            return
        editor_state = self._current_library_prompt_editor_state()
        block_state = editor_state.block_editor_state
        if (
            editor_state.definition_state not in {"legacy", "supported_v2"}
            or block_state is None
        ):
            if callable(notify):
                notify(
                    "This artifact cannot run directly. Use Convert and save as "
                    "new Prompt first.",
                    severity="warning",
                )
            return
        if block_state.artifact_type == "recipe":
            self._apply_library_prompt_working_copy(
                state=block_state,
                system_prompt=None,
                user_prompt=None,
            )
            return
        if block_state.artifact_type != "prompt":
            if callable(notify):
                notify(
                    "This artifact cannot run directly. Use Convert and save as "
                    "new Prompt first.",
                    severity="warning",
                )
            return
        if self._prompts_state.dirty:
            if callable(notify):
                notify(
                    "Save your changes before using this prompt in Console.",
                    severity="warning",
                )
            return
        fields = self._read_library_prompt_editor_fields()
        if fields is None:
            return
        _name, _author, _details, raw_system_prompt, raw_user_prompt, _keywords_text = (
            fields
        )
        self._stage_library_prompt_for_console(
            system_prompt=raw_system_prompt,
            user_prompt=raw_user_prompt,
        )

