    def _library_open_choice_strip(self) -> tuple[str, str, str] | None:
        """Return the open converged choice strip on the LIVE surface.

        task-14902: one predicate shared by the Escape gate
        (``_close_open_library_choice_strip``) and the footer/F1 seam
        (``_library_footer_shortcuts_for_current_state``) so the two can
        never disagree about whether a strip is open. The Notes Sort strip
        keeps its own pre-existing wiring (its visibility lives in the
        notes escape chain and footer tier).

        Returns:
            ``(subject, opener_selector, visibility_attr)`` for the open
            strip, or ``None`` when no converged strip is showing.
        """
        if (
            # Qodo on #2386: VISIBILITY, not key ownership -- a strip stays
            # open while focus is in the Reader, and Escape (which closes
            # it) and the chip that says so must both see it there.
            self._library_media_list_surface_active(require_focus=False)
            and self._media_state.type_choices_visible
        ):
            return (
                "type",
                "#library-media-type-filter",
                "_media_state.type_choices_visible",
            )
        if (
            self._library_media_list_surface_active(require_focus=False)
            and self._media_state.sort_choices_visible
        ):
            return (
                "sort",
                "#library-media-sort",
                "_media_state.sort_choices_visible",
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_PROMPTS
            and self._prompts_state.view == "list"
            and self._prompts_state.sort_choices_visible
        ):
            return (
                "sort",
                "#library-prompts-sort",
                "_prompts_state.sort_choices_visible",
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_BROWSE_SKILLS
            and self._skills_state.view == "list"
            and self._skills_state.sort_choices_visible
        ):
            return (
                "sort",
                "#library-skills-sort",
                "_skills_state.sort_choices_visible",
            )
        if (
            self._library_selected_row_id == LIBRARY_ROW_INGEST_EXPORT
            and self._export_state.quality_choices_visible
        ):
            return (
                "quality",
                "#library-export-quality",
                "_export_state.quality_choices_visible",
            )
        return None

    def _close_open_library_choice_strip(self) -> bool:
        """Close the open converged choice strip, refocusing its opener.

        Returns:
            ``True`` when a strip was open and has been closed (the caller
            should stop -- Escape is consumed), ``False`` otherwise.
        """
        open_strip = self._library_open_choice_strip()
        if open_strip is None:
            return False
        _subject, opener_selector, visibility_attr = open_strip
        _assign_library_reader_preferences_attribute(self, visibility_attr, False)
        self._sync_library_emergency_guard_presentation()
        canvas_kind = {
            "_media_state.type_choices_visible": "media",
            "_media_state.sort_choices_visible": "media",
            "_prompts_state.sort_choices_visible": "prompts",
            "_skills_state.sort_choices_visible": "skills",
            "_export_state.quality_choices_visible": "export",
        }[visibility_attr]
        _sync_library_canvas(
            self,
            canvas_kind,
            then=lambda: self._focus_library_control(opener_selector),
        )
        return True

    @classmethod
    def _library_escape_actions_before(cls, action: str) -> tuple[str, ...]:
        """The ``escape`` actions Textual tries before ``action`` (task-32051).

        Read off ``BINDINGS`` in declaration order rather than restated as a
        literal: this screen has grown from six Escape bindings to a dozen,
        and every hard-coded count/list of them in this file has gone stale
        at least once.

        Args:
            action: The escape action whose predecessors are wanted.

        Returns:
            The action names declared for ``escape`` ahead of ``action``.
        """
        earlier: list[str] = []
        for entry in cls.BINDINGS:
            if isinstance(entry, Binding):
                key, name = entry.key, entry.action
            else:
                key, name = entry[0], entry[1]
            if key != "escape":
                continue
            if name == action:
                break
            earlier.append(str(name))
        return tuple(earlier)

    def action_library_blur_text_field(self) -> None:
        """Escape in a Library text box: hand focus back to the canvas.

        task-32051 (critique #8 row 2): with the caret in the rail "Search
        Library…" box or the Search/RAG query box, Escape did nothing and the
        next printable key was inserted as text (live: ``i`` landed in the
        search box instead of opening Import). Only Tab/F6 could leave.

        Lands on the first canvas control that is neither the field itself
        nor another text box -- so the printable canvas keys (``i``, ``n``,
        ``u``/``o`` on Search/RAG) work on the very next keystroke, which is
        the whole point. Clearing focus outright is the last resort for a
        canvas that offers no focusable control at all.
        """
        for widget in self.focus_chain:
            if widget is self.focused or isinstance(widget, (Input, TextArea)):
                continue
            if any(node.id == "library-canvas" for node in widget.ancestors):
                widget.focus()
                break
        else:
            self.set_focus(None)
        self._refresh_footer_typing_context(self.focused)

    def action_library_list_focus_rail(self) -> None:
        """Escape: move focus from a list canvas toward the rail (task-2856 AC2).

        ``check_action`` gates this to ``_library_list_canvas_showing_list()``
        -- a list canvas (Media/Notes/Prompts/Skills) genuinely showing its
        plain list, never its viewer/editor. Only ever moves keyboard
        focus, never navigation or data state -- converges on the exact
        same ``#library-search-input`` target `/` (``on_key``) and F6
        (``_WORKBENCH_FOCUS_TARGETS``) already use, so all three routes to
        the rail agree on where "the rail" is.

        task-14902: an open choice strip consumes the Escape first (close +
        refocus the opener), mirroring the Notes Sort chooser's own escape
        step -- the focus hop toward the rail happens only from a quiet
        list.
        """
        if self._library_emergency_return_eligibility().visible:
            return
        if self._close_open_library_choice_strip():
            return
        target = self._library_list_focus_rail_target()
        if not target:
            return
        if target == "#library-conversations-filter":
            self._focus_library_control(target)
            return
        self._focus_library_rail_action(target)

    def _library_list_focus_rail_target(self) -> str:
        """The selector ``action_library_list_focus_rail`` would focus, if any.

        Extracted (task-32051 fix round 1) so the ``library_blur_text_field``
        gate can ask "would this hop actually MOVE focus?" without restating
        the destination -- the two answers must never drift, because the
        footer's "esc focus rail" chip promises this destination and the blur
        binding is what could silently take the key away from it.

        Returns:
            The selector, or ``""`` when the hop would focus nothing.
        """
        if self._library_selected_row_id == LIBRARY_ROW_BROWSE_CONVERSATIONS:
            region = self._conversations_controller._library_conversation_focus_region()
            layout = self._conversations_state.reader_layout
            if region == "work" and layout.items_open:
                return "#library-conversations-filter"
            if region in {"work", "items"} and layout.library_open:
                return "#library-search-input"
            return ""
        return "#library-search-input"

