    def _write_library_prompt_export_file(
        self,
        selected_path: Path | None,
        name: str,
        author: str,
        details: str,
        system_prompt: str,
        user_prompt: str,
        keywords_text: str,
        prompt_id: int,
        artifact_fields: Mapping[str, Any] | None = None,
    ) -> None:
        """Write the live prompt to the FileSave destination after path validation.

        Uses the same base-directory-free validator as other user-chosen saves.

        Args:
            selected_path: Destination, or None when cancelled.
            name: Live, possibly unsaved prompt name.
            author: Live author.
            details: Live details.
            system_prompt: Live system prompt.
            user_prompt: Live user prompt.
            keywords_text: Comma-separated live keywords.
            prompt_id: Prompt id, used only for logging.
            artifact_fields: Structured Prompt/Recipe metadata from the working copy.
        """
        if self._prompts_state.mutation_in_flight:
            return
        notify = getattr(self.app_instance, "notify", None)
        if not selected_path:
            if callable(notify):
                notify("Prompt export cancelled.", severity="information")
            return
        try:
            validated_path = validate_path_simple(selected_path, require_exists=False)
        except ValueError as exc:
            logger.warning(
                f"Rejected Library prompt export path {selected_path!r} for {prompt_id!r}: {exc}"
            )
            if callable(notify):
                notify(f"Rejected export path: {exc}", severity="warning")
            return
        keywords = self._library_note_keywords_from_input(keywords_text) or []
        detail = {
            "name": name,
            "author": author,
            "details": details,
            "system_prompt": system_prompt,
            "user_prompt": user_prompt,
            "keywords": keywords,
        }
        if artifact_fields:
            detail.update(artifact_fields)
        try:
            validated_path.write_text(render_prompt_markdown(detail), encoding="utf-8")
        except Exception as exc:
            logger.warning(
                "Failed to export Library prompt {} (category={}).",
                prompt_id,
                type(exc).__name__,
            )
            if callable(notify):
                notify(
                    f"Error exporting prompt: {type(exc).__name__}", severity="error"
                )
            return
        if callable(notify):
            notify(
                f"Prompt exported successfully to {validated_path.name}",
                severity="information",
            )

