    @on(LibraryIngestCanvas.OptionValueChanged)
    def handle_library_ingest_option_value_changed(
        self,
        event: LibraryIngestCanvas.OptionValueChanged,
    ) -> None:
        """Persist per-type option changes in the form echo.

        The canvas stays render-only and posts a message for every value
        change; the screen owns the mutable form state. Checkbox and select
        changes trigger a recompose so panel titles and dependent-field
        disabled states stay in sync, but text/number inputs do not (they
        would remount the Input and lose cursor position mid-typing).
        """
        event.stop()
        self._invalidate_library_external_submission()
        # (task-3314) An option edit changes what the submission will do --
        # a pending Start consent no longer covers it. Both downstream
        # paths (recompose / in-place gate update) re-render the line.
        self._disarm_library_ingest_start_confirm()
        # Same for a pending re-stage: the option the user just changed is
        # among the things the re-stage would overwrite.
        self._disarm_library_ingest_retry_confirm()
        group_options = self._ingest_state.form.type_options.setdefault(
            event.group, {}
        )
        group_options[event.name] = event.value
        # Generic group toggles mirror the legacy top-level form fields so
        # existing submit/config-persistence paths keep working.
        if event.group == "generic":
            form = self._ingest_state.form
            if event.name == "analyze":
                form.analyze = bool(event.value)
            elif event.name == "chunk":
                form.chunk = bool(event.value)
            elif event.name == "chunk_size":
                form.chunk_size = str(event.value)
        cap = get_capabilities(event.group)
        field = next((f for f in cap.fields if f.name == event.name), None)
        if field is not None and field.type not in ("text", "number", "textarea"):
            _sync_library_canvas(self, "ingest")
        elif field is not None:
            # (task-2130) Text/number/textarea edits deliberately skip the recompose
            # (cursor survival), which used to leave the panel-header receipt
            # asserting the OLD value and the only invalid signal a
            # focus-only border. Update the receipt, the inline message, and
            # the Start gate in place instead.
            self._ingest_controller._update_library_ingest_group_receipt(event.group)
            message = validate_ingest_option_value(field, event.value)
            try:
                error_line = self.query_one(
                    f"#opt-{event.group}-{event.name}-error", Static
                )
            except (NoMatches, QueryError):
                pass
            else:
                error_line.update(message)
                error_line.display = bool(message)
            # (task-2230 Qodo round) The persistent invalid marker is set at
            # compose time, but text/number edits deliberately skip the
            # recompose -- without toggling it here a field stayed marked
            # after becoming valid (and never got marked after becoming
            # invalid), which is exactly the unreliable "highlighted" the
            # marker was added to fix.
            try:
                field_input = self.query_one(f"#opt-{event.group}-{event.name}", Input)
            except (NoMatches, QueryError):
                pass
            else:
                field_input.set_class(bool(message), "-ingest-option-invalid")
            self._update_library_ingest_gate(self._build_library_ingest_state())

    @on(LibraryIngestCanvas.DirectoryBrowseRequested)
    def handle_library_ingest_directory_browse(
        self,
        event: LibraryIngestCanvas.DirectoryBrowseRequested,
    ) -> None:
        """Open a real directory picker for one capability-backed option."""

        event.stop()
        if (event.group, event.name) != (
            "audio_video",
            "transcription_model_dir",
        ):
            return

        async def picker_callback(selected_path: Path | None) -> None:
            if selected_path is None:
                return
            self._invalidate_library_external_submission()
            self._disarm_library_ingest_start_confirm()
            self._ingest_state.form.type_options.setdefault(event.group, {})[
                event.name
            ] = str(selected_path)
            if getattr(self, "_is_mounted", False):
                self.refresh(recompose=True)

        self.app.push_screen(
            SelectDirectory(
                str(Path.home()),
                title="Choose Parakeet model directory",
            ),
            picker_callback,
        )

    @on(LibraryIngestCanvas.ExternalPreparationCancelRequested)
    def handle_library_external_preparation_cancel(
        self,
        event: LibraryIngestCanvas.ExternalPreparationCancelRequested,
    ) -> None:
        """Cancel verification or VAD setup without clearing the form."""

        event.stop()
        self._invalidate_library_external_submission()
        self._set_library_external_status(
            "External preparation cancelled; no import was queued.",
            busy=False,
        )

    @on(LibraryIngestCanvas.ParakeetInstallRequested)
    def handle_parakeet_v2_install_requested(
        self,
        event: LibraryIngestCanvas.ParakeetInstallRequested,
    ) -> None:
        """Resolve the immutable install plan, then show it for consent.

        TASK-1696: the consent modal must render real repository, revision,
        license, precision, byte, destination, and free-space figures from
        a ``PreflightReport`` -- computed here, off the Textual event loop,
        before the modal is ever pushed.
        """
        event.stop()
        worker = getattr(self, "_parakeet_v2_install_worker", None)
        if worker is not None and not worker.is_finished:
            self.app_instance.notify(
                "Parakeet v2 installation is already running.",
                severity="information",
            )
            return
        self._parakeet_v2_install_worker = self._run_parakeet_v2_preflight()

    @on(LibraryIngestCanvas.TranscribeCppGGUFRequested)
    def handle_transcribe_cpp_gguf_requested(
        self,
        event: LibraryIngestCanvas.TranscribeCppGGUFRequested,
    ) -> None:
        """Open the direct-local GGUF picker from provider settings."""
        event.stop()
        self._open_transcribe_cpp_gguf_picker()

    def _open_transcribe_cpp_gguf_picker(
        self, *, retry_job_id: str | None = None
    ) -> None:
        """Pick one GGUF, then validate and persist it in a worker thread."""

        async def picker_callback(selected_path: Path | None) -> None:
            if selected_path is not None:
                self._configure_transcribe_cpp_gguf(
                    selected_path, retry_job_id=retry_job_id
                )

        self.app.push_screen(
            FileOpen(
                location=self._library_ingest_browse_location(),
                title="Choose transcribe.cpp GGUF",
                filters=_transcribe_cpp_gguf_filters(),
            ),
            picker_callback,
        )

    @work(
        thread=True,
        group="library_transcribe_cpp_gguf",
        exclusive=True,
        exit_on_error=False,
    )
    def _configure_transcribe_cpp_gguf(
        self, selected_path: Path, *, retry_job_id: str | None = None
    ) -> None:
        """Admit and persist a selected GGUF off the Textual event loop."""
        try:
            configure_transcribe_cpp_model_path(selected_path)
        except Exception:
            self.app.call_from_thread(
                self._apply_transcribe_cpp_gguf_result,
                False,
                retry_job_id,
            )
            return
        self.app.call_from_thread(
            self._apply_transcribe_cpp_gguf_result,
            True,
            retry_job_id,
        )

    def _apply_transcribe_cpp_gguf_result(
        self, configured: bool, retry_job_id: str | None
    ) -> None:
        """Show a path-free result and optionally requeue the failed job."""
        if not configured:
            self.app_instance.notify(
                "That GGUF cannot be used by transcribe.cpp. Choose another GGUF.",
                severity="warning",
            )
            return
        self.app_instance.notify(
            "Local GGUF configured for transcribe.cpp.",
            severity="information",
        )
        self._transcribe_cpp_configured = True
        if retry_job_id is not None:
            retry = getattr(self.app_instance, "retry_library_ingest_job", None)
            if callable(retry):
                retry(retry_job_id)
        self.refresh(recompose=True)

    def _build_library_model_install_progress_widgets(
        self,
    ) -> tuple[Static, ModelInstallProgress]:
        """Construct the deferred install label+bar pair from retained state.

        TASK-23025: shared by ``compose_content`` (recompose while an
        install is retained) and the grow-on-demand mount below, so both
        paths build the identical pair.
        """
        install_progress = ModelInstallProgress(
            self._parakeet_v2_install_progress,
            id="library-model-install-progress",
        )
        install_progress.display = self._parakeet_v2_install_progress is not None
        install_label = Static(
            self._library_model_install_progress_label,
            id="library-model-install-progress-label",
            classes="library-ingest-quiet-line",
            markup=False,
        )
        install_label.display = install_progress.display
        return install_label, install_progress

    def _mount_library_model_install_progress(self) -> bool:
        """Mount the deferred install pair on first use.

        Returns:
            True when a fresh pair was mounted. The fresh
            ``ModelInstallProgress`` renders the retained event from its own
            ``on_mount``, and its children are still composing -- the caller
            must NOT also call ``update_progress`` on it synchronously.
        """
        if self.query("#library-model-install-progress"):
            return False
        anchor = self._library_layout_ref("#library-lifecycle-status")
        parent = anchor.parent if anchor is not None else None
        if not isinstance(parent, Widget):
            return False
        label, progress = self._build_library_model_install_progress_widgets()
        parent.mount(label, progress, after=anchor)
        return True

    @on(InstallProgressed)
    def handle_model_install_progressed(self, event: InstallProgressed) -> None:
        """Retain and render progress after the consent modal is dismissed."""
        event.stop()
        self._parakeet_v2_install_progress = event.progress
        try:
            label = self.query_one("#library-model-install-progress-label", Static)
            progress = self.query_one(
                "#library-model-install-progress", ModelInstallProgress
            )
        except NoMatches:
            # TASK-23025: the pair is deferred off the idle compose; the
            # first event grows it (its on_mount renders the retained
            # progress, so no update call is needed here).
            self._mount_library_model_install_progress()
            return
        label.update(self._library_model_install_progress_label)
        label.display = True
        progress.display = True
        progress.update_progress(event.progress)

    @work(thread=True, group="library_parakeet_v2_preflight", exit_on_error=False)
    def _run_parakeet_v2_preflight(self) -> None:
        """Resolve the managed-download plan off the Textual event loop."""
        try:
            report = asyncio.run(  # policy-exception: worker-thread loop
                run_parakeet_v2_preflight()
            )
        except Exception as exc:
            logger.opt(exception=True).error("Parakeet v2 preflight failed")
            self.app.call_from_thread(
                self._apply_parakeet_v2_preflight_result,
                None,
                install_failure_message(exc, model_label="Parakeet v2"),
            )
            return
        self.app.call_from_thread(
            self._apply_parakeet_v2_preflight_result,
            report,
            None,
        )

    def _apply_parakeet_v2_preflight_result(
        self,
        report: "PreflightReport | None",
        error: str | None,
    ) -> None:
        """Show the plan-driven consent modal, or a sanitized preflight failure."""
        self._parakeet_v2_install_worker = None
        if error is not None or report is None:
            self.app_instance.notify(
                f"Parakeet v2 preflight failed: {error or 'unknown error'}",
                severity="error",
            )
            return
        self._parakeet_v2_pending_report = report
        self.app.push_screen(
            ModelInstallModal(
                report,
                model_label="Parakeet v2",
                container_id="parakeet-v2-install-modal",
                confirm_id="parakeet-v2-install-confirm",
                cancel_id="parakeet-v2-install-cancel",
            ),
            self._confirm_parakeet_v2_install,
        )

    def _confirm_parakeet_v2_install(self, confirmed: bool) -> None:
        """Start the installer worker after explicit confirmation."""
        if not confirmed:
            return
        worker = getattr(self, "_parakeet_v2_install_worker", None)
        if worker is not None and not worker.is_finished:
            return
        self.app_instance.notify(
            "Installing verified Parakeet v2 INT8 in the background…",
            severity="information",
        )
        self._library_model_install_progress_label = "Parakeet v2"
        self._library_model_install_progress_owner = "managed"
        self._parakeet_v2_install_worker = self._run_parakeet_v2_install()

    @work(thread=True, group="library_parakeet_v2_install", exit_on_error=False)
    def _run_parakeet_v2_install(self) -> None:
        """Grant consent and provision off the Textual event loop.

        Reads the pending report from ``self`` (rather than a parameter) so
        this stays a zero-argument call -- see
        ``Tests/UI/test_parakeet_v2_install_ui.py::
        test_confirmation_starts_background_installer_worker``, which pins
        that ``_confirm_parakeet_v2_install`` invokes this with no
        arguments.
        """
        report = self._parakeet_v2_pending_report
        try:
            if report is None:
                raise _ParakeetV2NoPendingReportError(
                    "No Parakeet v2 install plan is available; retry Install."
                )
            installed = asyncio.run(  # policy-exception: worker-thread loop
                run_parakeet_v2_provision(
                    report,
                    progress=make_progress_callback(self.post_message),
                )
            )
        except Exception as exc:
            logger.opt(exception=True).error("Parakeet v2 installation failed")
            self.app.call_from_thread(
                self._apply_parakeet_v2_install_result,
                None,
                install_failure_message(exc, model_label="Parakeet v2"),
            )
            return
        self.app.call_from_thread(
            self._apply_parakeet_v2_install_result,
            installed,
            None,
        )

    def _apply_parakeet_v2_install_result(
        self,
        installed: Path | None,
        error: str | None,
    ) -> None:
        """Populate the current batch form only after verified publication."""
        self._parakeet_v2_install_worker = None
        self._parakeet_v2_pending_report = None
        self._parakeet_v2_install_progress = None
        self._library_model_install_progress_label = ""
        self._library_model_install_progress_owner = None
        try:
            self.query_one(
                "#library-model-install-progress-label", Static
            ).display = False
            self.query_one(
                "#library-model-install-progress", ModelInstallProgress
            ).display = False
        except NoMatches:
            pass
        if error is not None or installed is None:
            self.app_instance.notify(
                f"Parakeet v2 install failed: {error or 'unknown error'}",
                severity="error",
            )
            return
        try:
            self.app_instance._ensure_parakeet_source_service().prefer_managed(
                ParakeetSourceKey.V2_INT8
            )
        except Exception as exc:
            logger.warning(
                "Could not prefer the installed Library Parakeet source "
                "(error_type={}).",
                type(exc).__name__,
            )
            self.app_instance.notify(
                "Parakeet v2 installed, but its source preference could not be updated.",
                severity="error",
            )
            return
        options = self._ingest_state.form.type_options.setdefault("audio_video", {})
        options["transcription_provider"] = "parakeet-onnx"
        options["transcription_precision"] = "int8"
        options.pop("transcription_model_dir", None)
        self.app_instance.notify(
            "Parakeet v2 INT8 installed and selected for this batch.",
            severity="information",
        )
        self.refresh(recompose=True)

    def _invalidate_library_external_submission(self) -> None:
        """Fence and release any not-yet-enqueued external-root submission."""

        self._library_external_submit_generation = (
            getattr(self, "_library_external_submit_generation", 0) + 1
        )
        worker = getattr(self, "_library_external_submit_worker", None)
        scope_id = getattr(self, "_library_external_submit_scope_id", None)
        owner = getattr(self, "_library_model_install_progress_owner", None)
        had_non_status_state = bool(
            worker is not None
            or scope_id
            or getattr(self, "_library_external_submit_backend", None)
            or owner == "external-vad"
            or (
                owner is None
                and getattr(self, "_parakeet_v2_install_progress", None) is not None
            )
        )
        if worker is not None:
            try:
                if not worker.is_finished:
                    worker.cancel()
            except Exception:
                pass
        self._library_external_submit_worker = None
        self._library_external_submit_scope_id = None
        self._library_external_submit_backend = None
        self._library_external_submit_consent = None
        if scope_id:
            try:
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
            except Exception:
                logger.warning("Could not release a provisional Library model scope.")
        status_changed = self._set_library_external_status("", busy=False)
        self._clear_library_external_vad_progress()
        if (
            had_non_status_state
            and not status_changed
            and getattr(self, "_is_mounted", False)
        ):
            self.refresh(recompose=True)

    def _set_library_external_status(self, status: str, *, busy: bool) -> bool:
        """Set path-free preparation state and refresh the mounted canvas."""

        changed = (
            getattr(self, "_library_external_submit_status", "") != status
            or getattr(self, "_library_external_submit_busy", False) != busy
        )
        self._library_external_submit_status = status
        self._library_external_submit_busy = busy
        if changed and getattr(self, "_is_mounted", False):
            self.refresh(recompose=True)
        return changed

    def _clear_library_external_vad_progress(self) -> None:
        """Hide shared progress only when it belongs to external VAD setup."""

        owner = getattr(self, "_library_model_install_progress_owner", None)
        if owner not in (None, "external-vad"):
            return
        if (
            owner is None
            and getattr(self, "_parakeet_v2_install_progress", None) is None
            and not getattr(self, "_library_model_install_progress_label", "")
        ):
            return
        self._parakeet_v2_install_progress = None
        self._library_model_install_progress_label = ""
        self._library_model_install_progress_owner = None
        if not getattr(self, "_is_mounted", False):
            return
        try:
            self.query_one(
                "#library-model-install-progress-label", Static
            ).display = False
            self.query_one(
                "#library-model-install-progress", ModelInstallProgress
            ).display = False
        except (NoMatches, QueryError):
            pass

    def _cancel_library_ingest_preflight(self) -> None:
        return self._ingest_controller._cancel_library_ingest_preflight()

    def _run_debounced_library_ingest_preflight(self) -> None:
        """Timer fire for the while-typing pre-flight (task-2015).

        Skips quietly when the user has already left the ingest canvas or
        emptied the path -- a late fire must never resurrect feedback for a
        path the form is no longer showing (the generation stamp guards the
        worker result itself).
        """
        self._ingest_state.path_debounce_timer = None
        path = self._ingest_state.form.path.strip()
        if path and self._library_selected_row_id == LIBRARY_ROW_INGEST_MEDIA:
            # (TASK-19556) allow_probe=False: this fire is a typing pause,
            # not a request to contact anything. The URL is classified by
            # name here; a network check, if the user has enabled one, runs
            # from the deliberate triggers instead.
            self._trigger_library_ingest_preflight(path, allow_probe=False)

    #: Max staged files probed for the duplicate forecast (task-2130:
    #: when hit, the forecast copy switches to "at least N").
    _DUPLICATE_PROBE_CAP = 20

    def _annotate_preflight_duplicates(
        self, result: PreflightResult
    ) -> PreflightResult:
        """Count staged text files already in the Library (task-2043).

        Runs ON THE PRE-FLIGHT WORKER THREAD: ``MediaDatabase`` uses
        thread-local connections (``check_same_thread=False``), so
        read-only lookups from here are safe. Scoped to the ``generic``
        group because the DB dedups on sha256 of PARSED content and only
        text files' read ≈ parse (hashing a PDF's bytes would never match
        its extracted text). Best-effort with caps (20 files, 8 MB each):
        a forecast must never fail or slow the pre-flight, so per-file
        problems are logged at debug and skipped.

        Args:
            result: The freshly analyzed pre-flight result.

        Returns:
            ``result`` with ``already_in_library`` populated when matches
            were found, otherwise unchanged.
        """
        media_db = getattr(self.app_instance, "media_db", None)
        if media_db is None:
            return result
        all_candidates = list(result.type_groups.get("generic", ()))
        candidates = all_candidates[: self._DUPLICATE_PROBE_CAP]
        capped = len(all_candidates) > len(candidates)
        if not candidates:
            return result
        already = 0
        for candidate in candidates:
            try:
                # (task-2043 review) Same validator the submit path uses --
                # candidates come from the pre-flight walk of a validated
                # root, but every filesystem touch goes through
                # path_validation regardless (defense in depth, rule
                # 497145).
                candidate_path = validate_path_simple(
                    str(candidate), require_exists=True
                )
                if (
                    not candidate_path.is_file()
                    or candidate_path.stat().st_size > 8 * 1024 * 1024
                ):
                    continue
                text = candidate_path.read_text(encoding="utf-8", errors="replace")
                digest = hashlib.sha256(text.encode()).hexdigest()
                if media_db.get_media_by_hash(digest) is not None:
                    already += 1
            except Exception as exc:
                logger.debug(f"Pre-flight duplicate check skipped {candidate!r}: {exc}")
                continue
        if not already:
            return result
        return dataclasses.replace(
            result,
            already_in_library=already,
            already_in_library_capped=capped and already > 0,
        )

    def _invalidate_library_ingest_preflight(self) -> None:
        return self._ingest_controller._invalidate_library_ingest_preflight()

    def _trigger_library_ingest_preflight(
        self, path: str, *, allow_probe: bool = True
    ) -> None:
        return self._ingest_controller._trigger_library_ingest_preflight(path, allow_probe=allow_probe)

    @work(thread=True)
    def _run_library_ingest_preflight(
        self, path: str, generation: int, allow_probe: bool = True
    ) -> None:
        """Analyze ``path`` on a worker thread and apply the result."""
        raw_scan_limit = get_cli_setting("library.ingest_directory_scan_limit", 1000)
        try:
            scan_limit = int(raw_scan_limit)
        except (TypeError, ValueError):
            scan_limit = 1000
        try:
            result = analyze_path(
                path,
                scan_limit=scan_limit,
                probe_url=None if allow_probe else False,
            )
            result = self._annotate_preflight_duplicates(result)
        except Exception as exc:
            logger.opt(exception=True).debug(
                f"Library ingest pre-flight failed for path: {path}"
            )
            result = PreflightResult(
                type_groups={},
                warnings=[],
                errors=[f"Pre-flight analysis failed: {exc}"],
                total_size=0,
                truncated=False,
                total_files=0,
            )
        self.app.call_from_thread(
            self._apply_library_ingest_preflight_result, result, generation
        )

    def _apply_library_ingest_preflight_result(
        self,
        result: PreflightResult,
        generation: int,
    ) -> None:
        return self._ingest_controller._apply_library_ingest_preflight_result(result, generation)

    def _trigger_preflight(self, path: str) -> None:
        """Alias for ``_trigger_library_ingest_preflight``.

        Kept as a short internal seam used by the pre-flight retry button
        (``#ingest-preflight-retry``) and any future callers that just need
        to re-run the analysis for the current form path.
        """
        self._trigger_library_ingest_preflight(path)

    def _notify_library_ingest_warning(self, message: str) -> None:
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(message, severity="warning")

    @on(Button.Pressed, "#library-ingest-start")
    def handle_library_ingest_start(self, event: Button.Pressed) -> None:
        return self._ingest_controller.handle_library_ingest_start(event)

    @on(Input.Submitted, "#library-ingest-path")
    def handle_library_ingest_path_submitted(self, event: Input.Submitted) -> None:
        return self._ingest_controller.handle_library_ingest_path_submitted(event)

    @on(Button.Pressed, "#ingest-preflight-retry")
    def _on_preflight_retry(self) -> None:
        """Re-run pre-flight analysis for the current ingest path."""
        self._trigger_preflight(self._ingest_state.form.path)

    def _resolve_ingest_source(self, raw_path: str) -> str | None:
        """Validate and canonicalise a Library ingest source path or URL.

        Returns ``None`` when validation fails and the caller should stop
        (a warning notification has already been shown). URLs are returned
        as-is; filesystem paths are expanded and normalised by
        ``validate_path_simple``.
        """
        if not raw_path:
            self._notify_library_ingest_warning("Please choose a file to import.")
            return None
        from urllib.parse import urlparse

        if urlparse(raw_path).scheme in ("http", "https"):
            # A URL source: skip the filesystem-existence check entirely --
            # validate_url is a syntax check, not a network fetch, matching
            # the file branch's "cheap, local, synchronous" validation cost.
            if not validate_url(raw_path):
                self._notify_library_ingest_warning(
                    "That doesn't look like a valid http(s) URL."
                )
                return None
            return raw_path
        try:
            validated_path = validate_path_simple(
                Path(raw_path).expanduser(), require_exists=True
            )
        except ValueError:
            logger.opt(exception=True).warning(
                f"Rejected Library ingest path {raw_path!r}."
            )
            self._notify_library_ingest_warning("Could not find that file.")
            return None
        return str(validated_path)

    def _disarm_library_ingest_start_confirm(self) -> None:
        return self._ingest_controller._disarm_library_ingest_start_confirm()

    def _current_library_ingest_start_consent(
        self,
        submitted_source: str,
        gate_state: LibraryIngestCanvasState | None = None,
    ) -> _LibraryIngestStartConsent:
        return self._ingest_controller._current_library_ingest_start_consent(submitted_source, gate_state)

    def _authoritative_library_ingest_consent_is_current(
        self,
        armed: _LibraryIngestStartConsent,
        pending: _LibraryIngestStartConsent,
    ) -> bool:
        return self._ingest_controller._authoritative_library_ingest_consent_is_current(armed, pending)

    def _submit_library_ingest_form(self) -> None:
        return self._ingest_controller._submit_library_ingest_form()

    def _do_submit_ingest(
        self,
        submitted_source: str,
        *,
        active_duplicate_consent: ActiveIngestConsentScope | None = None,
        confirmed_consent: _LibraryIngestStartConsent | None = None,
    ) -> None:
        """Perform the actual Library ingest job submission."""
        submit = getattr(self.app_instance, "submit_library_ingest_job", None)
        if not callable(submit):
            self._notify_library_ingest_warning(INGEST_UNAVAILABLE_COPY)
            return
        form = self._ingest_state.form
        snapshot = self._build_ingest_options_snapshot()
        submit_kwargs = dict(
            source_path=submitted_source,
            ingest_options=snapshot,
            title=self._safe_text(form.title, max_length=300),
            author=self._safe_text(form.author, max_length=200),
            keywords=parse_keywords(form.keywords),
            perform_analysis=form.analyze,
            chunk_enabled=form.chunk,
            chunk_size=clamp_chunk_size(form.chunk_size),
            active_duplicate_consent=active_duplicate_consent,
        )
        audio_options = snapshot.get("audio_video", {})
        resolve_backend = getattr(self.app_instance, "_resolve_ingest_backend", None)
        resolved_backend = resolve_backend() if callable(resolve_backend) else "local"
        captured_backend = "server" if resolved_backend == "server" else "local"
        external_directory = str(
            audio_options.get("transcription_model_dir") or ""
        ).strip()
        if (
            captured_backend == "local"
            and audio_options.get("transcription_provider") == "parakeet-onnx"
            and external_directory
        ):
            route = resolve_batch_stt_route(
                provider="parakeet-onnx",
                language=audio_options.get("language"),
                target_language=(
                    audio_options.get("translation_target_language")
                    or audio_options.get("target_language")
                ),
                precision=audio_options.get("transcription_precision"),
            )
            if getattr(self, "_library_external_submit_scope_id", None):
                self._invalidate_library_external_submission()
            generation = getattr(self, "_library_external_submit_generation", 0) + 1
            scope_id = f"library-external-{uuid.uuid4().hex}"
            self._library_external_submit_generation = generation
            self._library_external_submit_scope_id = scope_id
            self._library_external_submit_backend = captured_backend
            self._library_external_submit_consent = confirmed_consent
            self._set_library_external_status(
                "Verifying external Parakeet model directory…",
                busy=True,
            )
            self._library_external_submit_worker = (
                self._prepare_library_external_submission(
                    generation,
                    scope_id,
                    ParakeetSourceKey.from_values(route.model, route.precision),
                    Path(external_directory),
                    submit_kwargs,
                )
            )
            return
        if getattr(self, "_library_external_submit_scope_id", None):
            self._invalidate_library_external_submission()
        self._enqueue_library_ingest_snapshot(submit_kwargs)

    @work(
        thread=True,
        group="library_external_parakeet_prepare",
        exclusive=True,
        exit_on_error=False,
    )
    def _prepare_library_external_submission(
        self,
        generation: int,
        scope_id: str,
        key: ParakeetSourceKey,
        directory: Path,
        submit_kwargs: dict[str, Any],
    ) -> None:
        """Verify a user-owned root and managed VAD before queue creation."""

        worker = get_current_worker()
        service = self.app_instance._ensure_parakeet_source_service()
        prepared: PreparedExternalSelection | None = None
        try:
            prepared = service.prepare_external(
                key,
                directory,
                owner=("scope", scope_id),
                cancelled=lambda: worker.is_cancelled,
            )
            service.prepare_config_commit(prepared)
            service.retain_prepared(scope_id, prepared)
        except ParakeetSourceError as exc:
            if (
                exc.code is ParakeetSourceErrorCode.VAD_UNAVAILABLE
                and prepared is not None
                and not worker.is_cancelled
            ):
                try:
                    report = asyncio.run(  # policy-exception: worker-thread loop
                        run_parakeet_vad_preflight()
                    )
                except Exception as preflight_error:
                    logger.warning(
                        "Library VAD preflight failed (error_type={}).",
                        type(preflight_error).__name__,
                    )
                else:
                    self.app.call_from_thread(
                        self._apply_library_external_preparation,
                        generation,
                        scope_id,
                        prepared,
                        submit_kwargs,
                        report,
                        None,
                    )
                    return
            logger.warning(
                "Library external model verification failed (error_type={}).",
                type(exc).__name__,
            )
        except Exception as exc:
            logger.warning(
                "Library external model verification failed (error_type={}).",
                type(exc).__name__,
            )
        else:
            if not worker.is_cancelled:
                self.app.call_from_thread(
                    self._apply_library_external_preparation,
                    generation,
                    scope_id,
                    prepared,
                    submit_kwargs,
                    None,
                    None,
                )
                return
        service.release_scope(scope_id)
        if not worker.is_cancelled:
            self.app.call_from_thread(
                self._apply_library_external_preparation,
                generation,
                scope_id,
                prepared,
                submit_kwargs,
                None,
                "validation_failed",
            )

    def _library_external_backend_is_current(self) -> bool:
        """Return whether the captured external submission still targets local."""

        if getattr(self, "_library_external_submit_backend", "local") != "local":
            return False
        resolve_backend = getattr(self.app_instance, "_resolve_ingest_backend", None)
        return not callable(resolve_backend) or resolve_backend() != "server"

    def _apply_library_external_preparation(
        self,
        generation: int,
        scope_id: str,
        prepared: PreparedExternalSelection | None,
        submit_kwargs: dict[str, Any],
        vad_report: "PreflightReport | None",
        error: str | None,
    ) -> None:
        """Apply only the current generation's path-free verification result."""

        if (
            generation != self._library_external_submit_generation
            or scope_id != self._library_external_submit_scope_id
            or not self._library_external_backend_is_current()
        ):
            self.app_instance._ensure_parakeet_source_service().release_scope(scope_id)
            if not getattr(self, "_library_external_submit_scope_id", None):
                self._set_library_external_status("", busy=False)
                self._clear_library_external_vad_progress()
            return
        self._library_external_submit_worker = None
        if error is not None or prepared is None:
            self._library_external_submit_scope_id = None
            self._library_external_submit_backend = None
            self._library_external_submit_consent = None
            self.app_instance._ensure_parakeet_source_service().release_scope(scope_id)
            self._clear_library_external_vad_progress()
            if error == "vad_failed":
                message = "Silero VAD could not be installed; no import was queued."
                status = "Retry, choose Faster Whisper, or install the managed model."
            else:
                message = "That Parakeet model directory could not be verified."
                status = "Directory verification failed. Correct the folder and retry."
            self._set_library_external_status(status, busy=False)
            self.app_instance.notify(message, severity="error")
            return
        if vad_report is not None:
            vad_reference = parakeet_vad_reference()
            vad_source_url = parakeet_vad_descriptor().source_url
            if (
                vad_report.root != vad_reference
                or not vad_report.entries
                or any(
                    entry.ref != vad_reference or entry.source_url != vad_source_url
                    for entry in vad_report.entries
                )
            ):
                self._library_external_submit_scope_id = None
                self._library_external_submit_backend = None
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
                self._clear_library_external_vad_progress()
                self._set_library_external_status(
                    "Silero VAD plan changed. Choose the model again.",
                    busy=False,
                )
                self.app_instance.notify(
                    "The managed VAD plan changed. Choose the model again.",
                    severity="error",
                )
                return
            self._set_library_external_status(
                "Silero VAD dependency is required; review the install plan.",
                busy=True,
            )
            self.app.push_screen(
                ModelInstallModal(
                    vad_report,
                    model_label="Silero VAD dependency",
                    container_id="library-parakeet-vad-modal",
                    confirm_id="library-parakeet-vad-confirm",
                    cancel_id="library-parakeet-vad-cancel",
                ),
                partial(
                    self._confirm_library_external_vad,
                    generation,
                    scope_id,
                    prepared,
                    submit_kwargs,
                    vad_report,
                ),
            )
            return
        confirmed_consent = getattr(self, "_library_external_submit_consent", None)
        if confirmed_consent is not None:
            submitted_source = str(submit_kwargs.get("source_path") or "")
            pending = self._current_library_ingest_start_consent(submitted_source)
            request_changed = (
                pending.consent_context_fingerprint
                != confirmed_consent.consent_context_fingerprint
            )
            authoritative_current = (
                self._authoritative_library_ingest_consent_is_current(
                    confirmed_consent, pending
                )
            )
            membership_changed = (
                pending.active_job_ids != confirmed_consent.active_job_ids
                and not authoritative_current
            )
            replacement_active = bool(pending.active_job_ids)
            if request_changed or (membership_changed and replacement_active):
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
                self._library_external_submit_scope_id = None
                self._library_external_submit_backend = None
                self._library_external_submit_consent = None
                self._clear_library_external_vad_progress()
                self._set_library_external_status("", busy=False)
                self._ingest_state.start_consent = pending if pending.owed else None
                if pending.owed:
                    self._ingest_state.start_confirm_armed_at = time.monotonic()
                self._update_library_ingest_gate(self._build_library_ingest_state())
                self._sync_library_emergency_guard_presentation()
                return
            if membership_changed:
                # The confirmed match finished while preparation ran and no
                # replacement is visible. Tooling was part of the same
                # consent, so proceed under the ordinary authoritative guard.
                submit_kwargs["active_duplicate_consent"] = None
        self._library_external_submit_consent = None
        self._set_library_external_status("Queueing import…", busy=True)
        self._enqueue_library_ingest_snapshot(
            submit_kwargs,
            generation=generation,
            scope_id=scope_id,
        )

    def _confirm_library_external_vad(
        self,
        generation: int,
        scope_id: str,
        prepared: PreparedExternalSelection,
        submit_kwargs: dict[str, Any],
        report: "PreflightReport",
        confirmed: bool,
    ) -> None:
        """Provision only the VAD after consent, or release the scope."""

        if (
            generation != self._library_external_submit_generation
            or scope_id != self._library_external_submit_scope_id
            or not self._library_external_backend_is_current()
        ):
            self.app_instance._ensure_parakeet_source_service().release_scope(scope_id)
            return
        if not confirmed:
            self._invalidate_library_external_submission()
            self._set_library_external_status(
                "Silero VAD install cancelled; no import was queued.",
                busy=False,
            )
            return
        self._library_model_install_progress_label = "Silero VAD dependency"
        self._library_model_install_progress_owner = "external-vad"
        self._set_library_external_status(
            "Installing Silero VAD dependency…",
            busy=True,
        )
        self._library_external_submit_worker = self._provision_library_external_vad(
            generation,
            scope_id,
            prepared,
            submit_kwargs,
            report,
        )

    @work(
        group="library_external_parakeet_vad",
        exclusive=True,
        exit_on_error=False,
    )
    async def _provision_library_external_vad(
        self,
        generation: int,
        scope_id: str,
        prepared: PreparedExternalSelection,
        submit_kwargs: dict[str, Any],
        report: "PreflightReport",
    ) -> None:
        """Provision VAD, then perform the final snapshot check and retain."""

        service = self.app_instance._ensure_parakeet_source_service()

        def progress(event: Any) -> None:
            self._apply_library_external_vad_progress(generation, scope_id, event)

        try:
            await run_parakeet_vad_provision(report, progress=progress)
            service.prepare_config_commit(prepared)
            service.retain_prepared(scope_id, prepared)
        except asyncio.CancelledError:
            service.release_scope(scope_id)
            raise
        except Exception as exc:
            logger.warning(
                "Library VAD provision failed (error_type={}).",
                type(exc).__name__,
            )
            self._apply_library_external_preparation(
                generation,
                scope_id,
                prepared,
                submit_kwargs,
                None,
                "vad_failed",
            )
            return
        self._apply_library_external_preparation(
            generation,
            scope_id,
            prepared,
            submit_kwargs,
            None,
            None,
        )

    def _apply_library_external_vad_progress(
        self,
        generation: int,
        scope_id: str,
        event: Any,
    ) -> None:
        """Render progress only for the still-current local submission."""

        if (
            generation != self._library_external_submit_generation
            or scope_id != self._library_external_submit_scope_id
            or not self._library_external_backend_is_current()
        ):
            return
        self._parakeet_v2_install_progress = event
        self._library_model_install_progress_label = "Silero VAD dependency"
        self._library_model_install_progress_owner = "external-vad"
        try:
            label = self.query_one("#library-model-install-progress-label", Static)
            progress = self.query_one(
                "#library-model-install-progress", ModelInstallProgress
            )
        except (NoMatches, QueryError):
            # TASK-23025: the pair is deferred off the idle compose; the
            # first event grows it (its on_mount renders the retained
            # progress, so no update call is needed here).
            self._mount_library_model_install_progress()
            return
        label.update("Silero VAD dependency")
        label.display = True
        progress.display = True
        progress.update_progress(event)

    def _enqueue_library_ingest_snapshot(
        self,
        submit_kwargs: dict[str, Any],
        *,
        generation: int | None = None,
        scope_id: str | None = None,
    ) -> None:
        """Enqueue one captured snapshot and transfer any retained scope."""

        if generation is not None and (
            generation != self._library_external_submit_generation
            or scope_id != self._library_external_submit_scope_id
            or not self._library_external_backend_is_current()
        ):
            if scope_id:
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
            return
        snapshot = submit_kwargs["ingest_options"]
        if scope_id is not None:
            snapshot.setdefault("audio_video", {})[
                "transcription_external_scope_id"
            ] = scope_id
        registry = self._library_ingest_registry()
        prior_job_ids = (
            {job.job_id for job in registry.jobs()} if registry is not None else set()
        )
        submit = self.app_instance.submit_library_ingest_job
        try:
            submit(**submit_kwargs)
        except ActiveIngestSubmissionRefused as refusal:
            current_job_ids = (
                {job.job_id for job in registry.jobs()}
                if registry is not None
                else set()
            )
            if scope_id and current_job_ids == prior_job_ids:
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
            self._library_external_submit_worker = None
            self._library_external_submit_scope_id = None
            self._library_external_submit_backend = None
            self._library_external_submit_consent = None
            self._clear_library_external_vad_progress()
            self._set_library_external_status("", busy=False)

            submitted_source = str(submit_kwargs.get("source_path") or "")
            pending = self._current_library_ingest_start_consent(submitted_source)
            refused_scope = refusal.consent_scope
            if refused_scope is None:
                # The authoritative guard can win a race after the preview.
                # Retain only stable IDs; a preview that cannot reconstruct
                # sources gets the safe generic duplicate copy.
                refused_scope = build_active_ingest_consent_scope(
                    [submitted_source],
                    origin=pending.admission_scope.origin,
                    active_job_ids=(ref.job_id for ref in refusal.matches),
                    active_source_count=0,
                )
            payload = {
                "request": pending.request_fingerprint,
                "candidate_digest": refused_scope.candidate_digest,
                "candidate_count": refused_scope.candidate_count,
                "tooling_affected_count": pending.tooling_affected_count,
                "active_job_ids": refused_scope.active_job_ids,
                "active_job_count": refused_scope.active_job_count,
                "active_job_ids_complete": refused_scope.active_job_ids_complete,
            }
            pending = _LibraryIngestStartConsent(
                fingerprint=json.dumps(
                    payload,
                    sort_keys=True,
                    separators=(",", ":"),
                    ensure_ascii=False,
                    default=str,
                ),
                admission_scope=refused_scope,
                tooling_affected_count=pending.tooling_affected_count,
                is_folder=refused_scope.candidate_count > 1,
                request_fingerprint=pending.request_fingerprint,
                consent_context_fingerprint=pending.consent_context_fingerprint,
                authoritative_refusal=True,
                candidate_changed=refusal.candidate_changed,
            )
            self._ingest_state.start_consent = pending
            self._ingest_state.start_confirm_armed_at = time.monotonic()
            self._update_library_ingest_gate(self._build_library_ingest_state())
            self._sync_library_emergency_guard_presentation()
            return
        except Exception as exc:
            current_job_ids = (
                {job.job_id for job in registry.jobs()}
                if registry is not None
                else set()
            )
            if scope_id and current_job_ids == prior_job_ids:
                self.app_instance._ensure_parakeet_source_service().release_scope(
                    scope_id
                )
            logger.warning(
                "Library ingest submission failed (error_type={}).",
                type(exc).__name__,
            )
            self._library_external_submit_worker = None
            self._library_external_submit_scope_id = None
            self._library_external_submit_backend = None
            self._library_external_submit_consent = None
            self._clear_library_external_vad_progress()
            self._set_library_external_status(
                "Queueing failed. Correct the form and retry.",
                busy=False,
            )
            self.app_instance.notify(
                "The import could not be queued. Your form is still available.",
                severity="error",
            )
            return
        if scope_id is not None:
            self._library_external_submit_worker = None
            self._library_external_submit_scope_id = None
            self._library_external_submit_backend = None
            self._library_external_submit_consent = None
            self._clear_library_external_vad_progress()
            self._set_library_external_status("", busy=False)
        # One batched write. Saving key-by-key re-read and re-parsed the whole
        # config file and invalidated the global settings cache once per
        # option -- roughly six full reload cycles for a single submitted file,
        # growing with every option and every submission.
        option_settings: dict[str, dict[str, Any]] = {}
        for group, values in snapshot.items():
            persisted = dict(values)
            if group == "audio_video":
                persisted.pop("transcription_model_dir", None)
                persisted.pop("transcription_external_scope_id", None)
            if persisted:
                option_settings[f"library.ingest_options.{group}"] = persisted
        if option_settings:
            self._save_library_ingest_options(option_settings)
        form = self._ingest_state.form
        # (task-3313) Session-scoped snapshot of what was just submitted,
        # captured BEFORE the form clears, so "Retry this batch" can
        # re-stage the exact same source with its options and metadata.
        # Values are copied (not aliased) so later form edits never mutate
        # the record of what actually ran.
        self._ingest_state.last_submission = LibraryIngestLastSubmission(
            source=str(submit_kwargs["source_path"]),
            title=form.title,
            author=form.author,
            keywords=form.keywords,
            analyze=form.analyze,
            chunk=form.chunk,
            chunk_size=str(form.chunk_size),
            type_options={
                group: dict(values) for group, values in form.type_options.items()
            },
        )
        form.path = ""
        form.title = ""
        # The summary described the file that just left the form, so keeping
        # it would leave the canvas asserting two things at once: "Enter a
        # file path to start." next to "1 plain text file - 333 B", which
        # reads as though something is still staged. Cancellation alone is
        # cooperative and cannot stop a worker that already finished; the
        # generation bump inside the invalidate is what actually fences the
        # late result out (task-2011).
        self._invalidate_library_ingest_preflight()
        self.refresh(recompose=True)
        # (task-3304, MI-08) The receipt must be seen, not just exist: the
        # queue's outcome area sat below the fold on every submit. After
        # the recompose settles, bring the queue heading into view.
        self.call_after_refresh(self._ingest_controller._scroll_library_ingest_queue_into_view)

    @work(thread=True)
    def _save_library_ingest_options(
        self, option_settings: dict[str, dict[str, Any]]
    ) -> None:
        """Persist submitted per-type ingest options without blocking the UI.

        task-15470: the batched call itself (one atomic mutation for every
        changed type-options group, replacing what used to be one
        ``save_setting_to_cli_config`` call per option) already landed
        separately; this only moves that one call off the event loop,
        matching this file's established ``@work(thread=True)`` pattern for
        click-path config writes. ``option_settings`` is a fresh dict built
        by the caller from a point-in-time snapshot, so no further mutation
        of it races this worker thread's read.
        """
        try:
            save_settings_to_cli_config(option_settings)
        except Exception:
            logger.error("Failed to persist Library ingest options")

    def _load_library_ingest_options_from_config(self) -> None:
        """Load persisted per-type ingest options into the form echo.

        Called from ``on_mount`` so a fresh Library visit carries forward the
        last-used options from previous sessions.

        task-24456: the app constructs a NEW ``LibraryScreen`` on every visit
        (verified live -- three visits, three distinct instance ids), so this
        ran 43 `get_cli_setting` calls per visit to rebuild a value that only
        changes when the configuration does. The reads are memoised on
        `current_config_identity()`, which tracks both config writes and a
        user who edits ingest options still sees them on the next visit while
        an unchanged config costs one integer comparison.
        """
        form = self._ingest_state.form
        cached = _library_ingest_options_for(self)
        self._transcribe_cpp_configured = cached["transcribe_cpp_configured"]
        for name, value in cached["generic_form_fields"].items():
            setattr(form, name, value)
        for group, stored in cached["type_options"].items():
            form.type_options.setdefault(group, {}).update(dict(stored))

    def _build_ingest_options_snapshot(self) -> dict[str, dict[str, Any]]:
        """Capture the current per-type ingestion options as a snapshot.

        Returns a shallow copy of ``self._ingest_state.form.type_options``,
        with the top-level generic toggles (analyze, chunk, chunk_size)
        merged into the ``generic`` group so the downstream pipeline has a
        single canonical options map.

        Returns:
            A group-keyed dict mapping type group ids (``generic``, ``pdf``,
            ``audio_video``, ``ebook``) to their option name/value maps.
        """
        form = self._ingest_state.form
        snapshot: dict[str, dict[str, Any]] = {
            group: dict(opts) for group, opts in form.type_options.items()
        }
        generic = snapshot.setdefault("generic", {})
        generic["analyze"] = form.analyze
        generic["chunk"] = form.chunk
        # Prefer the generic panel's chunk_size when the user has set one;
        # otherwise fall back to the legacy top-level form field.
        if "chunk_size" not in generic:
            generic["chunk_size"] = clamp_chunk_size(form.chunk_size)
        # (task-3301) The panel's number Inputs hand back display TEXT
        # ("1000"); this snapshot is both what the job pipeline consumes
        # and what gets persisted to config, so numbers are coerced to
        # ints here, at the boundary, and never downstream. The values
        # were already gate-validated (``collect_ingest_option_errors``
        # blocks Start on a non-integer), so the clamp/fallback below is
        # defensive, not a second validator.
        generic["chunk_size"] = clamp_chunk_size(str(generic["chunk_size"]))
        if "chunk_overlap" in generic:
            try:
                generic["chunk_overlap"] = max(
                    0, int(str(generic["chunk_overlap"]).strip())
                )
            except (TypeError, ValueError):
                generic.pop("chunk_overlap")  # fall back to the schema default
        # Preserve a complete generic form state in every job snapshot. The
        # generic capability schema owns these defaults, including the
        # server-only ``keep_original_file`` value; backend projection decides
        # whether a snapshot value can reach a particular ingest path.
        for field in get_capabilities("generic").fields:
            generic.setdefault(field.name, field.default)
        # (task-3303 xhigh review round 2, F11) The ebook chunk-method is
        # scheme IDENTITY, so every NEW snapshot must carry it explicitly
        # even when untouched: the job-option builder treats an ABSENT
        # value as "this snapshot predates the field" and falls back to
        # the pre-branch sentences scheme for requeue parity. Without this
        # seed a fresh untouched submission would be indistinguishable
        # from a legacy job and lose the chapters default.
        ebook = snapshot.setdefault("ebook", {})
        if not str(ebook.get("chunk_method") or "").strip():
            ebook["chunk_method"] = next(
                (
                    field.default
                    for field in get_capabilities("ebook").fields
                    if field.name == "chunk_method"
                ),
                "chapters",
            )
        return snapshot

    def _library_ingest_job_by_id(self, job_id: str) -> LibraryIngestJob | None:
        """Resolve a job by id from the live registry snapshot, or ``None``.

        Reads ``registry.jobs()`` fresh on every call (never a cached row
        list) so a click always resolves against the queue's current
        truth, including any transition that landed between render and
        click.
        """
        registry = self._library_ingest_registry()
        jobs_fn = getattr(registry, "jobs", None)
        jobs = jobs_fn() if callable(jobs_fn) else ()
        return next((job for job in jobs if job.job_id == job_id), None)

    def _navigate_to_media(self, media_id: str | int) -> None:
        return self._media_controller._navigate_to_media(media_id)

    def _open_job_in_library(self, job: LibraryIngestJob) -> None:
        """Resolve a done ingest job to a media item and open it.

        Falls back to source-path and content-hash lookups when the job was
        deduplicated and therefore has no stamped ``media_id``. Defensively
        skips fallback when the media database is unavailable.
        """
        # Delegate to the tally's own predicate: ``progress`` is a dict
        # with the marker under ["message"] (Qodo caught a str() check that
        # could never match).
        if count_duplicate_done_jobs((job,)):
            self._media_state.arrival_note = (
                "Matched an existing item — nothing new was imported."
            )
        media_id = job.media_id
        if media_id is None:
            media_db = getattr(self.app_instance, "media_db", None)
            if media_db is not None:
                # Fallback 1: match by source URL/path.
                try:
                    media = media_db.get_media_by_url(job.source_path)
                    if media:
                        media_id = media.get("id")
                except Exception:
                    logger.opt(exception=True).debug(
                        f"ingest open-in-library URL lookup failed: {job.source_path}"
                    )
                # Fallback 2: match by content hash if the job recorded one.
                if media_id is None and job.content_hash:
                    try:
                        media = media_db.get_media_by_hash(job.content_hash)
                        if media:
                            media_id = media.get("id")
                    except Exception:
                        logger.opt(exception=True).debug(
                            f"ingest open-in-library hash lookup failed: {job.content_hash}"
                        )
        if media_id:
            self._navigate_to_media(media_id)
        else:
            # Show a transient status when no single match can be resolved.
            self.notify("Already in Library — no single match found")

