    async def _exit_library_note_editor_guarded(self) -> bool:
        """Flush edits and return to the list only if no unsaved state remains.
        Back and Escape share this seam. Refetch source truth for ordering, ages and
        counts; the immediate repaint uses the saved patch. If blank-note GC already
        requested a refetch, the exclusive snapshot worker supersedes it.

        Returns:
            True on exit; False when unsaved edits veto it."""
        if self._notes_state.select_mode:
            return False
        note_id = self._notes_state.selected_note_id
        note_flush = await self._flush_library_note_save()
        if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
            # task-32133 AC#1 (fix round 1): notify from THIS shared seam,
            # not just the Escape caller -- the "‹ Notes"/"‹ Back to list"
            # button, action_library_note_editor_back, and the wide
            # task-return control all reach this exact veto through this
            # one function and were discarding the False silently too.
            notify = getattr(self.app_instance, "notify", None)
            if callable(notify):
                notify(
                    _library_note_editor_exit_veto_message(note_flush.kind),
                    severity="warning",
                )
            return False
        navigation_generation = self._supersede_library_notes_navigation()
        placement_id = self._notes_state.tree_selected_placement_id
        receipt = self._notes_state.browse_return_receipt
        identity = (
            receipt.focus_identity
            if receipt is not None
            else LibraryNotesFocusIdentity(
                stage="notes",
                region="navigator",
                note_id=note_id or None,
                semantic_role=(
                    f"note-placement:{placement_id}"
                    if note_id and placement_id
                    else (f"note-row:{note_id}" if note_id else "filter")
                ),
            )
        )
        self._notes_state.pending_focus_identity = identity
        self._notes_state.pending_focus_waits_for_snapshot = True
        self._notes_state.pending_focus_generation = navigation_generation
        self._dispatch_database_note_identity_cleared()
        self._reset_library_note_editor_state()
        if receipt is None:
            restore_after_projection = partial(
                self._restore_library_notes_focus_identity, identity
            )
        else:
            restore_after_projection = partial(
                self._restore_library_notes_browse_return_receipt,
                receipt,
                _LibraryNotesRestoreGuard(
                    scroll_generation=self._notes_state.scroll_intent_generation,
                    focus_generation=self._notes_state.focus_intent_generation,
                ),
            )

        def finish_list_projection() -> None:
            restore_after_projection()
            self._refresh_local_source_snapshot()

        _sync_library_canvas(self, "notes", then=finish_list_projection)
        return True

