    def _begin_library_note_create(self) -> str | None:
        """Claim one monotonic Create token before a worker can be scheduled."""
        if self._notes_state.create_running or self._library_notes_mutation_fenced():
            return None
        self._notes_state.notice = ""
        self._notes_state.create_counter += 1
        token = f"create-{self._notes_state.create_counter}"
        self._notes_state.create_token = token
        self._notes_state.create_running = True
        self._notes_state.mutation_in_flight = True
        LibraryScreen._fence_library_notes_tree_mutation(self)
        self._notes_state.create_status = "Create…"
        if self.is_mounted:
            _sync_library_canvas(self, "notes")
        return token

    def _finish_library_note_create(self, create_token: str, *, status: str='') -> bool:
        return self._notes_controller._finish_library_note_create(create_token, status=status)

    @staticmethod
    def _library_note_template_fields(template: Any) -> tuple[Any, Any]:
        """Resolve known date/time/datetime placeholders only in valid string fields.
        Keep unknown placeholders and stray braces literal. Never coerce missing or
        malformed values: the shared lossless validator must visibly reject them.

        Args:
            template: Raw NOTE_TEMPLATES value, or None for an unknown key.

        Returns:
            Raw (title, content), with substitution only for valid strings."""
        if not isinstance(template, Mapping):
            return None, None
        title = template.get("title")
        content = template.get("content")
        if isinstance(title, str):
            title = resolve_note_template_placeholders(title)
        if isinstance(content, str):
            content = resolve_note_template_placeholders(content)
        return title, content

    async def _create_library_note(
        self,
        *,
        title: Any,
        content: Any,
        keywords: Any = None,
        create_token: str | None = None,
        blank: bool = False,
    ) -> LibraryNoteCreateOutcome:
        """Create a local note from Blank/template input and open its typed session.

        Validate the lossless draft through the editor Save boundary; invalid
        input stays visible, never truncated. Offload save_note(note_id=None)
        through the service seam. Success refreshes source rows/counts and admits
        the loaded coordinator session before opening the editor. Missing/failed
        save leaves Create visible with a warning.

        Args:
            title: Exact resolved title.
            content: Exact resolved body.
            keywords: Exact template keywords, if any.
            create_token: Preclaimed monotonic activation token.
            blank: Commit immediately, but arm untouched Blank notes for quiet
                deletion on exit (LIB-14); templates retain their real content.

        Returns:
            Typed pre-commit failure, committed recovery, or opened editor session.
        """
        origin_row = self._library_selected_row_id
        origin_view = self._notes_state.view
        active_token = create_token or self._begin_library_note_create()
        if active_token is None:
            return LibraryNoteCreateOutcome("failed")
        if keywords is None:
            keywords_text: Any = ""
        elif isinstance(keywords, str):
            keywords_text = keywords
        elif (
            isinstance(keywords, Sequence)
            and not isinstance(keywords, (bytes, bytearray))
            and all(isinstance(keyword, str) for keyword in keywords)
        ):
            keywords_text = ", ".join(keywords)
        else:
            keywords_text = keywords
        draft = DatabaseNoteDraft(
            note_id="",
            title=title,
            body=content,
            keywords_text=keywords_text,
            revision=0,
        )
        payload = validate_database_note_draft(draft)
        if not isinstance(payload, DatabaseNoteSavePayload):
            status = f"Create failed — {payload.message}"
            if self._finish_library_note_create(active_token, status=status):
                _sync_library_canvas(self, "notes")
            return LibraryNoteCreateOutcome("failed")

        service = getattr(self.app_instance, "notes_scope_service", None)
        save_note = getattr(service, "save_note", None)
        if not callable(save_note):
            self._notify_library_note_create_warning("Note creation is unavailable.")
            if self._finish_library_note_create(
                active_token,
                status="Create failed — creation is unavailable. Try again.",
            ):
                _sync_library_canvas(self, "notes")
            return LibraryNoteCreateOutcome("failed")
        try:
            result = await self._run_library_service_call(
                save_note,
                scope="local_note",
                title=payload.title,
                content=payload.body,
                note_id=None,
                user_id=self._library_notes_user_id(),
                keywords=list(payload.keywords) if payload.keywords else None,
                isolate_in_worker=True,
            )
        except Exception as exc:  # noqa: BLE001 - privacy-safe service boundary
            logger.warning(
                "Database Notes note create failed; epoch={}; error_type={}",
                self._notes_state.tree_topology_epoch,
                type(exc).__name__,
            )
            self._notify_library_note_create_warning("Could not create the note.")
            if self._finish_library_note_create(
                active_token,
                status="Create failed — check the service and try again.",
            ):
                _sync_library_canvas(self, "notes")
            return LibraryNoteCreateOutcome("failed")

        if active_token != self._notes_state.create_token:
            return LibraryNoteCreateOutcome("failed")

        created_id = result.get("id") if isinstance(result, Mapping) else result
        created_id = str(created_id) if created_id else ""
        if not created_id:
            self._notify_library_note_create_warning("Could not create the note.")
            if self._finish_library_note_create(
                active_token,
                status="Create failed — no note was returned. Try again.",
            ):
                _sync_library_canvas(self, "notes")
            return LibraryNoteCreateOutcome("failed")

        # The returned identity is the commit point. Patch the exact shared
        # list/count state while the one mutation interlock is still held;
        # a detached snapshot worker could otherwise land after an Undo and
        # overwrite its restoration with stale pre-Undo data.
        created_version = (
            int(result.get("version") or 1) if isinstance(result, Mapping) else 1
        )
        self._notes_controller._append_library_note_source_record(
            {
                "id": created_id,
                "title": payload.title,
                "content": payload.body,
                "version": created_version,
                "keywords": list(payload.keywords),
                "last_modified": datetime.now(timezone.utc).isoformat(),
            }
        )
        await LibraryScreen._reconcile_library_notes_tree_mutation(
            self,
            "note_create",
            {"note_id": created_id},
            before=None,
            result=result,
        )
        self._refresh_local_source_snapshot()
        route_is_current = (
            self._library_selected_row_id == origin_row
            and self._notes_state.view == origin_view
        )
        if not route_is_current:
            self._finish_library_note_create(active_token)
            self._notes_state.notice = "Note created — select it from Notes to open."
            return LibraryNoteCreateOutcome("created_not_opened", created_id)

        outcome = await self._library_note_session.open_session(
            created_id, untouched_create_token=active_token
        )
        if active_token != self._notes_state.create_token:
            return LibraryNoteCreateOutcome("created_not_opened", created_id)
        route_is_current = (
            self._library_selected_row_id == origin_row
            and self._notes_state.view == origin_view
        )
        if outcome.kind is not NoteLoadOutcomeKind.LOADED or not route_is_current:
            if outcome.kind is NoteLoadOutcomeKind.LOADED:
                self._library_note_session.close_session()
            self._finish_library_note_create(active_token)
            self._notes_state.notice = "Note created — select it from Notes to open."
            if route_is_current:
                self._dispatch_database_note_identity_cleared()
                self._reset_library_note_editor_state()
                self._library_selected_row_id = LIBRARY_ROW_BROWSE_NOTES
                self._notes_state.filter = ""
                self._notes_state.filter_records = None
                self._notes_state.filter_generation += 1
                self._notes_state.tree_filter_state = None
            if self.is_mounted:
                await self._notes_controller._reconcile_library_notes_list_canvas()
            return LibraryNoteCreateOutcome("created_not_opened", created_id)

        self._notes_state.notice = ""
        self._library_selected_row_id = LIBRARY_ROW_BROWSE_NOTES
        self._notes_state.filter = ""
        self._notes_state.filter_records = None
        self._notes_state.filter_generation += 1
        self._notes_state.tree_filter_state = None
        self._notes_state.selected_note_id = created_id
        self._notes_state.view = "editor"
        self._notes_state.load_state = "loaded"
        self._notes_state.load_message = ""
        self._notes_state.autosave_state = "idle"
        self._notes_state.confirming_delete = False
        self._notes_state.preview = False
        self._notes_state.context = False
        self._notes_state.delete_origin_context = False
        self._notes_state.delete_origin_preview = False
        self._notes_state.editor_armed = False
        self._notes_state.work_session_activation_pending = True
        if self.is_mounted:
            self.call_later(
                self._activate_database_note_work_session,
                created_id,
            )
        self._notes_state.pending_blank_gc_id = created_id if blank else None
        self._notes_state.session_blank_id = created_id if blank else None
        # (P0) A freshly created note's title is whatever the create seam
        # seeded -- untouched by definition.
        self._notes_state.title_user_edited = False
        self._finish_library_note_create(active_token)
        if self.is_mounted:

            def finish_create_projection() -> None:
                self._arm_library_note_editor()
                self._focus_library_note_control("#library-note-title")

            _sync_library_canvas(self, "notes", then=finish_create_projection)
        return LibraryNoteCreateOutcome("opened", created_id)

