    def _exit_library_media_viewer(self) -> None:
        """Shared Back exit: return the media canvas from viewer to list.

        Shared by the "‹ Back to list" button and the viewer's Escape
        binding (``action_library_media_viewer_back``, task-2856 AC2) so
        both exits run the identical reset sequence -- one seam, not a
        parallel key-driven path that could drift from the button's. Runs
        unconditionally regardless of the viewer's editing/confirming-
        delete sub-state, mirroring the "‹ Back to list" button itself,
        which renders (and is reachable) in every one of those sub-states.
        """
        self._cancel_library_media_selection_settlement()
        self._media_state.reader_session = leave_external_detail(
            self._media_state.reader_session
        )
        self._media_state.view = "list"
        self._media_state.editing = False
        self._media_state.confirming_delete = False
        self._media_state.editing_analysis = False
        self._close_library_media_find()
        self._media_state.content_mode = "raw"
        self._load_library_media_list_if_needed()
        # task-21116: the exit is a canvas-child swap (viewer -> list), not
        # a whole-screen rebuild. Scheduled via ``call_next`` because this
        # seam is synchronous (Button handler + Escape action) while the
        # child replacement awaits its unmount/mount; the task-2856 AC1
        # entry-focus arm rides the same continuation so its immediate
        # attempt runs against the MOUNTED list rows.
        media_return = self._media_state.viewer_return
        self._media_state.viewer_return = None
        if media_return is not None and media_return.final_focus_policy == "row":
            # The focused Back control is about to be removed. Clear it before
            # the child swap so Textual cannot choose the replacement semantic
            # row as an implicit successor ahead of exact scroll settlement.
            self.set_focus(None)
        self.call_next(self._apply_library_media_list_return, media_return)

    def action_library_media_viewer_back(self) -> None:
        """Escape steps back one level on the active Media viewer.
        Edit, delete-confirm and analysis-edit mirror their existing Cancel actions,
        which discard that sub-state and return to read-only viewing. Only the plain
        viewer exits to the list; do not invent dirty guards absent from those forms.
        The visible Back-to-list button retains its separate existing behavior."""
        if self._media_state.bulk_delete_in_flight:
            return
        if self._media_state.editing:
            self._media_state.editing = False
            self._sync_library_media_viewer_or_recompose()
            return
        if self._media_state.confirming_delete:
            self._media_state.confirming_delete = False
            self._sync_library_media_viewer_or_recompose()
            return
        if self._media_state.editing_analysis:
            self._media_state.editing_analysis = False
            self._sync_library_media_viewer_or_recompose()
            return
        focused = self.focused
        # task-31271 seam (a): same seam as the footer's escape label, so
        # the chip and this key can never describe different outcomes.
        find_open, find_controls = self._library_media_find_state()
        if (
            find_controls is not None
            and focused is not None
            and (focused is find_controls or find_controls in focused.ancestors)
        ):
            self._close_library_media_find()
            self._after_library_media_viewer_sync("#library-media-reader-find")
            return
        if self._media_state.reader_session.more_open:
            self._media_state.reader_session = set_more_open(
                self._media_state.reader_session, False
            )
            self._after_library_media_viewer_sync("#library-media-reader-more")
            return
        # task-31272: the Items pane's own type/sort strips open over the
        # three-pane Reader too, and this action owns Escape there (the
        # list canvas's ``library_list_focus_rail`` is gated to the "list"
        # view). Close the strip first, exactly as its "esc cancel" chip
        # promises -- the same one-transient-at-a-time shape as Find/More.
        if self._close_open_library_choice_strip():
            return
        try:
            shell = self.query_one(
                ".library-media-route", LibraryBrowseReaderShell
            )
        except (NoMatches, QueryError):
            self._exit_library_media_viewer()
            return
        layout = shell.effective_layout
        if focused is not None and (
            focused is shell.items or shell.items in focused.ancestors
        ):
            if layout.library_open:
                # task-31272 (critique #4, A cap 20): the ACTIVE RAIL ROW,
                # never "#library-search-input" -- landing in the rail's
                # text field made the NEXT Escape (and every letter after
                # it) typing, so leaving the Reader took three presses and
                # the middle one was invisible.
                self._focus_library_rail_action(
                    f"#library-row-{LIBRARY_ROW_BROWSE_MEDIA}"
                )
                self._register_footer_shortcuts()
            else:
                self._exit_library_media_viewer()
            return
        if focused is not None and (
            focused is shell.library or shell.library in focused.ancestors
        ):
            # task-31272: in the three-pane shell the rail row is the
            # ladder's terminus. Exiting from here used to set
            # ``_library_media_view = "list"`` while the Reader kept
            # painting the document (that layout's Items pane already shows
            # the list, so the flip changed no pixels) -- and every Reader
            # binding is gated on that flag, so Escape, ] and [ all died on
            # identical pixels (critique #4, A cap 25/31/39, and the
            # "close more" that did nothing at B cap_106).
            # ``_library_media_escape_label`` returns "" there so the
            # footer advertises no chip for a key that does nothing.
            if self._library_media_reader_exit_available(layout):
                self._exit_library_media_viewer()
            return
        # Qodo on #2367: an open Find bar is a reader substate regardless
        # of where focus sits INSIDE the reader region (F6 to the content
        # pane must not leave the bar stranded) -- Escape closes it first,
        # and _library_media_escape_label advertises exactly that. The
        # items/library-pane branches above stay untouched: their Escape
        # never consumes the reader's find state.
        if find_open:
            self._close_library_media_find()
            self._after_library_media_viewer_sync("#library-media-reader-find")
            return
        if layout.items_open:
            self._focus_library_media_items_pane()
        elif layout.library_open:
            self._focus_library_rail_action(
                f"#library-row-{LIBRARY_ROW_BROWSE_MEDIA}"
            )
        else:
            self._exit_library_media_viewer()
        self._register_footer_shortcuts()

    def _library_media_adjacent_row(self, direction: int) -> tuple[str, str] | None:
        return self._media_controller._library_media_adjacent_row(direction)

    def _library_media_item_traversal_active(self) -> bool:
        return self._media_controller._library_media_item_traversal_active()

    def action_library_media_next_item(self) -> None:
        return self._media_controller.action_library_media_next_item()

    def action_library_media_prev_item(self) -> None:
        return self._media_controller.action_library_media_prev_item()

    def _review_set_service(self):
        """Return the review-set service, or ``None`` when storage is absent.

        Lazily built from the app's Library collections DB and cached on the
        screen. Returns ``None`` (never raises) when that DB is unavailable, so
        every review-set call site can guard on it and fall back cleanly.

        Returns:
            A ``ReviewSetService`` or ``None``.
        """
        service = getattr(self, "_cached_review_set_service", None)
        if service is not None:
            return service
        db = getattr(self.app_instance, "local_library_collections_db", None)
        if db is None:
            return None
        from tldw_chatbook.Library.review_set_service import ReviewSetService

        service = ReviewSetService(db)
        self._cached_review_set_service = service
        return service

    #: Max ids per liveness ``IN (…)`` batch, safely under SQLite's default
    #: 999-variable limit (Qodo #2333: bound the query even for a large set).
    _REVIEW_SET_LIVENESS_BATCH = 900

    def _review_set_live_ids(self, backing_ids: "Iterable[int]") -> set[int]:
        """Return the subset of backing media ids that are still live.

        Live means present in the Media table with ``deleted = 0`` and
        ``is_trash = 0``. Resolved in batched ``IN (…)`` queries (one round-trip
        per ``_REVIEW_SET_LIVENESS_BATCH`` ids) so the query stays bounded even
        for a large set, and each cursor is closed deterministically. When the
        Media DB is unavailable the ids are treated as live -- the walker must
        not hide items it cannot check.

        Args:
            backing_ids: The set's backing media ids.

        Returns:
            The subset that resolves to a live media item.
        """
        ids = [int(backing_id) for backing_id in backing_ids]
        if not ids:
            return set()
        media_db = getattr(self.app_instance, "media_db", None)
        if media_db is None:
            return set(ids)
        live: set[int] = set()
        try:
            for start in range(0, len(ids), self._REVIEW_SET_LIVENESS_BATCH):
                chunk = ids[start : start + self._REVIEW_SET_LIVENESS_BATCH]
                placeholders = ",".join("?" * len(chunk))
                with closing(
                    media_db.execute_query(
                        f"SELECT id FROM Media WHERE id IN ({placeholders}) "
                        "AND deleted = 0 AND is_trash = 0",
                        tuple(chunk),
                    )
                ) as cursor:
                    live.update(int(row[0]) for row in cursor.fetchall())
        except Exception:
            # Safe fallback: if the Media DB can't be queried, treat every id
            # as live -- the walker must never HIDE an item it failed to check
            # (better to show a possibly-deleted item than to skip a real one).
            return set(ids)
        return live

    def _walk_active_review_set(self, direction: int) -> bool:
        """Walk the active review set one step; return ``True`` if it handled it.

        task-28241: a forward step marks the item being left done (the
        completion gesture on the last item), Prev never marks, and tombstones
        are skipped -- all decided by the pure ``plan_walk``. The item at the
        new cursor is loaded through the same actuator the browse traversal
        uses, so fenced loading, scroll capture/restore, and mode-persistence
        keep working.

        Args:
            direction: ``+1`` for Next, ``-1`` for Prev.

        Returns:
            ``True`` when an active set consumed the step; ``False`` to let the
            browse-row traversal handle it.
        """
        service = self._review_set_service()
        if service is None:
            return False
        # task-30042 (user ruling: silent failure is never acceptable): a
        # storage error mid-walk surfaces and consumes the key -- falling
        # through to browse traversal would stack a second action on top of
        # an error the user hasn't seen yet.
        try:
            return self._walk_active_review_set_unguarded(service, direction)
        except Exception:
            logger.opt(exception=True).warning("review-set walk failed")
            self._notify_review_set(
                "Couldn't walk the review set — storage error.",
                severity="error",
            )
            return True

    def _walk_active_review_set_unguarded(self, service, direction: int) -> bool:
        """The walk body; storage exceptions are the caller's to surface."""
        review_set = service.get_active_review_set()
        if review_set is None:
            return False
        from tldw_chatbook.Library.review_set_state import plan_walk, resolve_cursor

        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        is_live = lambda backing_id: backing_id in live_ids  # noqa: E731
        by_position = {item.position: item for item in review_set.items}

        # Qodo #2333: the walk marks/advances from the item the Reader is
        # actually SHOWING, not the persisted cursor -- otherwise a step could
        # mark an unseen item done. When the Reader is not on a set item (fresh
        # entry, or a browse item), the first step just RESUMES the set at its
        # cursor, marking nothing.
        loaded_backing = self._media_state.reader_session.loaded_backing_id
        try:
            loaded_backing = int(loaded_backing) if loaded_backing is not None else None
        except (TypeError, ValueError):
            loaded_backing = None
        displayed_position = next(
            (
                item.position
                for item in review_set.items
                if item.backing_media_id == loaded_backing
            ),
            None,
        )
        if displayed_position is None:
            resumed = resolve_cursor(review_set.items, review_set.cursor, is_live)
            target = by_position.get(resumed)
            if target is None:
                return True  # empty / all-tombstoned set: nothing to load
            if resumed != review_set.cursor:
                service.set_cursor(review_set.set_id, resumed)
            self._select_library_media_reader_row(
                f"local:media:{target.backing_media_id}",
                target.title_snapshot,
                immediate=True,
            )
            return True

        outcome = plan_walk(
            review_set.items, displayed_position, direction, is_live
        )
        was_complete = review_set.completed_at is not None
        if outcome.mark_done_backing_id is not None:
            service.mark_item_done(
                review_set.set_id, outcome.mark_done_backing_id, True
            )
        if outcome.new_cursor != review_set.cursor:
            service.set_cursor(review_set.set_id, outcome.new_cursor)
        complete = service.refresh_completion(review_set.set_id, is_live)
        if outcome.target is not None:
            self._select_library_media_reader_row(
                f"local:media:{outcome.target.backing_media_id}",
                outcome.target.title_snapshot,
                immediate=True,
            )
        else:
            # task-30041 (critique P1): the clamp step -- including the
            # final-] completion gesture -- changes marks/completion without
            # loading a new item, so the Reader chrome must refresh here or
            # the footer stays stale at exactly the finish.
            self._sync_library_media_viewer_or_recompose()
        if complete and not was_complete and outcome.mark_done_backing_id is not None:
            live_count = sum(
                1 for item in review_set.items if is_live(item.backing_media_id)
            )
            self._notify_review_set(f"All {live_count} reviewed.")
        return True

    def _review_cursor_for_display(self, review_set) -> int:
        """The set position the READER is on, else the persisted cursor.

        task-31635 (critique #5 item 10): clicking a row inside the active
        set loads it without committing a walk position, so the persisted
        cursor stayed put and every "X of M" readout described an item
        nobody was looking at. ``_walk_active_review_set_unguarded`` has
        measured from the DISPLAYED item since Qodo #2333 and
        ``_active_review_loaded_at_last`` since Qodo on #2386 -- this is the
        same rule, shared by the two readouts that were still on the cursor.

        Deliberately READ-ONLY: no ``set_cursor`` here. A click moves what
        the readouts describe, not where the set resumes -- that stays the
        walk's own gesture.

        Args:
            review_set: The active set.

        Returns:
            The loaded item's position when the Reader holds one of the
            set's items, else ``review_set.cursor``.
        """
        loaded = library_media_int_backing_id(
            getattr(self._media_state.reader_session, "loaded_backing_id", None)
        )
        if loaded is None:
            return review_set.cursor
        return next(
            (
                item.position
                for item in review_set.items
                if item.backing_media_id == loaded
            ),
            review_set.cursor,
        )

    def _active_review_progress(self) -> ReviewProgress | None:
        """Return the active set's live progress, or ``None``.

        task-31271 seam (c): the footer needs the live ``index``/``total``
        (to name the completion gesture on the last item), not just the
        rendered line, so the measurement and its formatting are separate
        seams now.

        Returns:
            The live :class:`ReviewProgress` when a set is active, else
            ``None``.
        """
        service = self._review_set_service()
        if service is None:
            return None
        review_set = service.get_active_review_set()
        if review_set is None:
            return None
        # Lazy: review sets are one Reader mode.
        from tldw_chatbook.Library.review_set_state import (
            review_progress,
        )

        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        is_live = lambda backing_id: backing_id in live_ids  # noqa: E731
        return review_progress(
            review_set.items,
            self._review_cursor_for_display(review_set),
            is_live,
        )

    def _active_review_loaded_at_last(self) -> bool:
        """True when the Reader's LOADED item is the set's last live item.

        Qodo on #2386: the footer's ``at_last`` came from the persisted
        CURSOR, so with an off-set item in the Reader (PR A's "· this item
        is not in the set" state) it promised "] finish review" while ``]``
        would only RESUME the set at its cursor.
        ``_walk_active_review_set`` has measured from the DISPLAYED item
        since Qodo #2333; this makes the chip that describes it agree.

        Returns:
            True only when a set is active, the Reader holds one of its
            live items, and that item is the last of them.
        """
        service = self._review_set_service()
        if service is None:
            return False
        review_set = service.get_active_review_set()
        if review_set is None:
            return False
        loaded_backing = self._media_state.reader_session.loaded_backing_id
        try:
            loaded_backing = (
                int(loaded_backing) if loaded_backing is not None else None
            )
        except (TypeError, ValueError):
            return False
        if loaded_backing is None:
            return False
        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        live_items = sorted(
            (item for item in review_set.items if item.backing_media_id in live_ids),
            key=lambda item: item.position,
        )
        return bool(live_items) and live_items[-1].backing_media_id == loaded_backing

    def _active_review_set_banner(self) -> str | None:
        """Build the Reader's one-line review-set banner (task-30045).

        ``"Reviewing: <name> — X of M · N reviewed · ✓ reviewed"`` -- the
        set's identity, its live progress, and (when the loaded item belongs
        to the set) that item's own reviewed state, so ``m``'s effect is
        visible at a glance instead of a counter diff. ``None`` when no set
        is active; fails CLOSED on a storage error (the explicit gesture
        paths carry the notices).

        Returns:
            The banner line, or ``None``.
        """
        service = self._review_set_service()
        if service is None:
            return None
        try:
            review_set = service.get_active_review_set()
            if review_set is None:
                return None
            from tldw_chatbook.Library.review_set_state import (
                format_review_progress,
                review_progress,
            )

            live_ids = self._review_set_live_ids(
                item.backing_media_id for item in review_set.items
            )
            progress = format_review_progress(
                review_progress(
                    review_set.items,
                    # task-31635 item 10: the ordinal names the item the
                    # Reader is SHOWING, so a click inside the set moves it.
                    self._review_cursor_for_display(review_set),
                    lambda candidate: candidate in live_ids,
                )
            )
            loaded = self._media_state.reader_session.loaded_backing_id
            try:
                loaded = int(loaded) if loaded is not None else None
            except (TypeError, ValueError):
                loaded = None
            item_state = ""
            current = next(
                (
                    item
                    for item in review_set.items
                    if item.backing_media_id == loaded
                ),
                None,
            )
            if current is not None and current.backing_media_id in live_ids:
                # Live items only (Qodo #2351): progress counts live items,
                # so claiming a state for a tombstoned (deleted-but-open)
                # item would contradict the set's own arithmetic.
                item_state = (
                    " · ✓ reviewed" if current.done else " · not yet reviewed"
                )
            elif loaded is not None and current is None:
                # task-31273: an explicit open outside the set keeps the
                # set's banner but never claims a state for this item.
                item_state = " · this item is not in the set"
            return f"Reviewing: {review_set.name} — {progress}{item_state}"
        except Exception:
            logger.opt(exception=True).warning(
                "review-set banner build failed; omitting the banner"
            )
            return None

    def _review_set_active(self) -> bool:
        """True when a review set is active (drives the Reader footer + gating).

        Fails CLOSED on a storage error (Qodo #2346): this runs on every key
        resolution and footer render, so raising here would crash-loop the
        screen and a notice here would toast-storm. The keys degrade to
        browse traversal; the explicit gesture paths carry the notices.
        """
        service = self._review_set_service()
        if service is None:
            return False
        try:
            return service.get_active_review_set() is not None
        except Exception:
            logger.opt(exception=True).warning(
                "review-set active-check failed; gating fails closed"
            )
            return False

    def action_library_media_exit_review(self) -> None:
        """Exit review mode: deactivate the active set, keeping it resumable.

        task-28241 (AC3): distinct from Escape (which keeps the set active and
        just leaves the Reader). Only meaningful in the plain Reader with an
        active set; a no-op otherwise.
        """
        if not self._library_media_item_traversal_active():
            return
        service = self._review_set_service()
        if service is None:
            return
        # task-30042: surface a storage error instead of crashing the action.
        try:
            if service.get_active_review_set() is None:
                return
            service.deactivate_active()
        except Exception:
            logger.opt(exception=True).warning("review-set exit failed")
            self._notify_review_set(
                "Couldn't exit review — storage error.", severity="error"
            )
            return
        self._sync_library_media_viewer_or_recompose()

    def action_library_media_toggle_reviewed(self) -> None:
        """Toggle the current item's done mark in the active review set.

        task-28241 (AC2): the explicit counterpart to forward-advance's
        auto-mark -- lets a user un-mark a skimmed item, or mark the last one
        without advancing. A no-op outside a plain Reader with an active set
        whose cursor item is loaded.
        """
        if not self._library_media_item_traversal_active():
            return
        service = self._review_set_service()
        if service is None:
            return
        # task-30042: a storage error on an explicit mark gesture surfaces
        # instead of crashing the action or silently dropping the mark.
        try:
            self._toggle_reviewed_unguarded(service)
        except Exception:
            logger.opt(exception=True).warning("review-set toggle failed")
            self._notify_review_set(
                "Couldn't update the reviewed mark — storage error.",
                severity="error",
            )

    def _toggle_reviewed_unguarded(self, service) -> None:
        """The toggle body; storage exceptions are the caller's to surface."""
        review_set = service.get_active_review_set()
        if review_set is None:
            return
        backing_id = self._media_state.reader_session.loaded_backing_id
        if backing_id is None:
            return
        try:
            backing_id = int(backing_id)
        except (TypeError, ValueError):
            return
        current = next(
            (
                item
                for item in review_set.items
                if item.backing_media_id == backing_id
            ),
            None,
        )
        if current is None:
            return
        service.mark_item_done(review_set.set_id, backing_id, not current.done)
        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        service.refresh_completion(
            review_set.set_id, lambda candidate: candidate in live_ids
        )
        self._sync_library_media_viewer_or_recompose()

    # -- review-set entry points (task-28242) --------------------------------

    async def _review_these_worker(self) -> None:
        """Page the whole filtered result, then create + open the set.

        Wrapped so a search/DB failure surfaces a notice instead of a silent
        no-op (Qodo #2335) -- the worker runs with ``exit_on_error=False``.
        """
        try:
            scope = getattr(
                self._library_media_browse_controller.state, "applied_scope", None
            )
            if scope is None:
                return
            pairs = await self._collect_review_pairs_from_scope(scope)
            self._create_and_open_review_set(
                self._review_these_name(scope), "browse", pairs
            )
        except Exception:
            self._notify_review_set(
                "Couldn't build the review set.", severity="error"
            )

    async def _review_selected_worker(self, backing_ids: tuple[int, ...]) -> None:
        """Order the selected ids by the browse sort, then create + open."""
        try:
            pairs = await self._order_selected_review_pairs(backing_ids)
            self._create_and_open_review_set(
                f"{len(backing_ids)} selected items", "selection", pairs
            )
        except Exception:
            self._notify_review_set(
                "Couldn't build the review set.", severity="error"
            )

    async def _collect_review_pairs_from_scope(
        self, scope: Any
    ) -> list[tuple[int, str]]:
        """Page the whole filtered result into ordered (backing_id, title) pairs.

        Reads the raw ``search_media`` envelope page by page (off the event
        loop) in browse-sort order, stopping at the total, an empty page, or one
        past the 500 cap (so ``build_pinned_items`` can flag truncation).
        """
        search = getattr(
            getattr(self.app_instance, "media_reading_scope_service", None),
            "search_media",
            None,
        )
        if not callable(search):
            return []
        from tldw_chatbook.Library.review_set_state import REVIEW_SET_CAP

        pairs: list[tuple[int, str]] = []
        page = 1
        page_size = scope.page_size
        while True:
            filters: dict[str, Any] = {"sort_by": scope.sort_by}
            if scope.media_type:
                filters["media_types"] = [scope.media_type]
            payload = await self._run_library_service_call(
                search,
                mode="local",
                query=scope.query,
                limit=page_size,
                offset=(page - 1) * page_size,
                library_summary=True,
                isolate_in_worker=True,
                **filters,
            )
            items = payload.get("items", []) if isinstance(payload, Mapping) else []
            for item in items:
                pairs.append((int(item["backing_media_id"]), str(item["title"])))
            total = int(payload.get("total", 0)) if isinstance(payload, Mapping) else 0
            if (
                not items
                or page * page_size >= total
                or len(pairs) > REVIEW_SET_CAP
            ):
                break
            page += 1
        return pairs

    async def _order_selected_review_pairs(
        self, backing_ids: tuple[int, ...]
    ) -> list[tuple[int, str]]:
        """Order selected backing ids by the browse sort (deterministic).

        Uses ``search_media``'s ``id_allowlist`` so the selection reads in the
        same order the user saw, regardless of which pages it spanned -- NOT the
        unordered RowSelection set.
        """
        search = getattr(
            getattr(self.app_instance, "media_reading_scope_service", None),
            "search_media",
            None,
        )
        if not callable(search):
            return []
        from tldw_chatbook.Library.review_set_state import REVIEW_SET_CAP

        scope = getattr(self._library_media_browse_controller.state, "applied_scope", None)
        sort_by = scope.sort_by if scope is not None else "last_modified_desc"
        # Qodo #2335: bound the query to the cap (+1 to flag overflow), not the
        # unrestricted selection size.
        ids = list(backing_ids)[: REVIEW_SET_CAP + 1]
        payload = await self._run_library_service_call(
            search,
            mode="local",
            query="",
            library_summary=True,
            isolate_in_worker=True,
            id_allowlist=ids,
            sort_by=sort_by,
            limit=len(ids),
            offset=0,
        )
        items = payload.get("items", []) if isinstance(payload, Mapping) else []
        return [(int(item["backing_media_id"]), str(item["title"])) for item in items]

    @staticmethod
    def _review_these_name(scope: Any) -> str:
        """A human name for a browse-derived review set."""
        if scope.query:
            return f'Search: "{scope.query}"'
        if scope.media_type:
            return f"{scope.media_type} items"
        return "All media"

    def _create_and_open_review_set(
        self, name: str, origin: str, pairs: list[tuple[int, str]]
    ) -> None:
        """Create the set from pinned pairs, activate it, and open it in Reader.

        A no-op (with a notice) when nothing resolved; warns when the 500 cap
        dropped items.

        Args:
            name: Human label for the set.
            origin: ``'browse'`` or ``'selection'``.
            pairs: Ordered ``(backing_media_id, title)`` pairs.
        """
        from tldw_chatbook.Library.review_set_state import (
            REVIEW_SET_CAP,
            build_pinned_items,
        )

        items, truncated = build_pinned_items(pairs, cap=REVIEW_SET_CAP)
        if not items:
            self._notify_review_set(
                "No media items to review.", severity="warning"
            )
            return
        service = self._review_set_service()
        if service is None:
            # task-30042: the items resolved but there is nowhere to pin
            # them -- say so instead of silently discarding the gesture.
            self._notify_review_set(
                self._REVIEW_SET_STORAGE_UNAVAILABLE, severity="error"
            )
            return
        # task-31238: creating a set displaces the active one (one-active
        # invariant) -- capture it BEFORE the create so an in-progress walk
        # never just stops being resumable-by-] without a word.
        displaced = service.get_active_review_set()
        service.create_review_set(name, origin, items)
        if truncated:
            self._notify_review_set(
                f"Review set capped at the first {REVIEW_SET_CAP} items.",
                severity="warning",
            )
        elif self._active_review_set_banner() is None:
            # task-31635 (critique #5 item 17, ruling): the Reader this
            # create is about to open paints "Reviewing: <name> — 1 of N ·
            # 0 reviewed" -- strictly more than this toast said, and at
            # 100x30 the toast landed ON that Reader's border. So it is
            # dropped whenever the banner can carry the fact, and kept as
            # the fallback when it cannot (no active set to describe).
            self._notify_review_set(f"Reviewing {len(items)} items.")
        if displaced is not None and displaced.completed_at is None:
            from rich.markup import escape

            from tldw_chatbook.Library.review_set_state import (
                format_review_progress,
                review_progress,
            )

            live = self._review_set_live_ids(
                item.backing_media_id for item in displaced.items
            )
            progress = format_review_progress(
                review_progress(
                    displaced.items, displaced.cursor, live.__contains__
                )
            )
            self._notify_review_set(
                f"Paused '{escape(displaced.name)}' at {progress}. "
                "Resume from Sets."
            )
        # task-31233: a create invoked from Select mode must leave it before
        # landing -- select mode is otherwise cleared only by Done/bulk-delete,
        # so the viewer open below never surfaced (blank reader, boxes reset).
        # The selection was consumed, not discarded: no notice. The canvas
        # sync mirrors the Done toggle's -- the viewer open below syncs only
        # the VIEWER in place, leaving the select toolbar stale without it
        # (live-verified 2026-09-04).
        if getattr(self._media_state, "select_mode", False):
            self._exit_library_media_select_mode(announce_discard=False)
            _sync_library_canvas(self, "media")
        self._open_library_media_viewer(f"local:media:{items[0][0]}")

    _REVIEW_SET_STORAGE_UNAVAILABLE = "Review-set storage is unavailable."

    def _notify_review_set(
        self, message: str, *, severity: str = "information"
    ) -> None:
        notify = getattr(self.app_instance, "notify", None)
        if callable(notify):
            notify(message, severity=severity)

    # -- review-set picker (task-28243) ---------------------------------------

    async def _review_set_picker_worker(self) -> None:
        """List saved sets, await one picker decision, and apply it.

        One decision per open (lean v1): resume/switch loads the chosen set at
        its cursor, dismiss soft-deletes it. Wrapped so a DB failure surfaces a
        notice instead of a silent no-op (the worker runs with
        ``exit_on_error=False``).
        """
        try:
            service = self._review_set_service()
            if service is None:
                # task-30042: a dead button is indistinguishable from the
                # feature not existing -- the press always responds.
                self._notify_review_set(
                    self._REVIEW_SET_STORAGE_UNAVAILABLE, severity="error"
                )
                return
            rows = await self._run_library_service_call(
                self._collect_review_set_picker_rows, isolate_in_worker=True
            )
            decision = await self._push_review_set_picker(rows)
            if decision is None:
                return
            from tldw_chatbook.Widgets.Library.library_review_set_picker import (
                PICKER_DISMISS,
                PICKER_OPEN,
                PICKER_READ_LATER,
            )

            action, set_id = decision
            if action == PICKER_READ_LATER:
                pairs = await self._review_read_later_pairs()
                self._create_and_open_review_set(
                    "Read later", "read_later", pairs
                )
                return
            if action == PICKER_DISMISS:
                dismissed_row = next(
                    (row for row in rows if row[0] == set_id), None
                )
                await self._run_library_service_call(
                    service.dismiss, set_id, isolate_in_worker=True
                )
                # task-31236: the confirmation is an in-list undo receipt,
                # not a toast -- a one-click dismissal of a mid-walk set
                # must be recoverable in place (user ruling, critique #3).
                self._media_state.review_dismiss_receipt = (
                    set_id,
                    dismissed_row[1] if dismissed_row else "review set",
                    bool(dismissed_row[3]) if dismissed_row else False,
                )
                # Dismissing the ACTIVE set must drop the Reader's set chrome
                # -- without this the footer kept advertising "] next in set"
                # after the set was gone (live-verified 2026-09-02). The
                # canvas sync is separate: the viewer seam updates only the
                # VIEWER in place, so the receipt row never mounted without
                # it (live-verified 2026-09-04).
                _sync_library_canvas(self, "media")
                self._sync_library_media_viewer_or_recompose()
                return
            if action != PICKER_OPEN:
                return
            landing = await self._run_library_service_call(
                self._activate_review_set, set_id, isolate_in_worker=True
            )
            if landing is None:
                self._notify_review_set(
                    "All items in this set were removed.", severity="warning"
                )
                return
            self._open_library_media_viewer(f"local:media:{landing}")
        except Exception:
            # task-31220: the one review-set wrapper task-30042 missed -- a
            # live wedge left NO trace in the log because this swallowed the
            # traceback.
            logger.opt(exception=True).warning("review-set picker failed")
            self._notify_review_set(
                "Couldn't open review sets.", severity="error"
            )

    @on(Button.Pressed, "#library-media-review-dismiss-undo")
    def handle_library_media_review_dismiss_undo(
        self, event: Button.Pressed
    ) -> None:
        """Restore the set named by the dismiss receipt (task-31236).

        Args:
            event: The receipt row's "Undo" press.
        """
        event.stop()
        receipt = self._media_state.review_dismiss_receipt
        # Qodo on #2366: one in-flight undo owns the receipt until it
        # settles -- a second press would CANCEL the first through the
        # exclusive worker group, and a racing receipt-close would strand
        # the restore without its receipt.
        if receipt is None or getattr(
            self, "_review_dismiss_undo_in_flight", False
        ):
            return
        self._review_dismiss_undo_in_flight = True
        self.run_worker(
            self._review_dismiss_undo_worker(receipt),
            group="library_review_set",
            exclusive=True,
            exit_on_error=False,
        )

    @on(Button.Pressed, "#library-media-review-dismiss-receipt-close")
    def handle_library_media_review_dismiss_receipt_close(
        self, event: Button.Pressed
    ) -> None:
        """Clear the dismiss receipt without restoring anything.

        Args:
            event: The receipt row's "Dismiss" press.
        """
        event.stop()
        # Qodo on #2366: the receipt belongs to a pending undo until that
        # settles -- clearing it mid-restore left the restored set with no
        # visible acknowledgment.
        if getattr(self, "_review_dismiss_undo_in_flight", False):
            return
        self._media_state.review_dismiss_receipt = None
        _sync_library_canvas(self, "media")

    async def _review_dismiss_undo_worker(
        self, receipt: tuple[str, str, bool]
    ) -> None:
        """Un-tombstone the receipt's set, restoring activation if it had it.

        task-31236 AC#2: cursor and done marks were never touched by the
        dismiss, so the service-side ``undismiss`` brings the set back
        exactly as it was; re-activation yields to any set that became
        active since (the one-active invariant outranks the undo).

        Args:
            receipt: ``(set_id, name, was_active)`` captured at dismissal.
        """
        try:
            service = self._review_set_service()
            if service is None:
                self._notify_review_set(
                    self._REVIEW_SET_STORAGE_UNAVAILABLE, severity="error"
                )
                return
            set_id, _name, was_active = receipt
            await self._run_library_service_call(
                partial(service.undismiss, set_id, reactivate=was_active),
                isolate_in_worker=True,
            )
            self._media_state.review_dismiss_receipt = None
            # Canvas sync clears the receipt row; the viewer seam re-arms
            # the set chrome when the restored set is active again.
            _sync_library_canvas(self, "media")
            self._sync_library_media_viewer_or_recompose()
        except Exception:
            # task-30042 (user ruling): failures are never silent.
            logger.opt(exception=True).warning(
                "review-set dismiss undo failed"
            )
            self._notify_review_set(
                "Couldn't restore the review set.", severity="error"
            )
        finally:
            self._review_dismiss_undo_in_flight = False

    async def _review_read_later_pairs(self) -> list[tuple[int, str]]:
        """Build ordered (backing_id, title) pairs from the read-later queue.

        task-28244: ids come from ``list_read_it_later_media_ids`` (already
        ordered ``saved_at DESC``); titles come from the same bounded
        allowlist query Review-selected uses, whose browse-sort order is then
        discarded in favor of the saved order.

        Returns:
            Pairs in saved-at order; empty when the queue is empty or the
            Media DB is unavailable.
        """
        from tldw_chatbook.Library.review_set_state import REVIEW_SET_CAP

        lister = getattr(
            getattr(self.app_instance, "media_db", None),
            "list_read_it_later_media_ids",
            None,
        )
        if not callable(lister):
            return []
        # Bound the DB query itself (Qodo #2340) -- +1 so build_pinned_items
        # can still flag truncation; the client-side slice stays as a guard
        # for listers without limit support.
        ids = await self._run_library_service_call(
            lister, isolate_in_worker=True, limit=REVIEW_SET_CAP + 1
        )
        ids = [int(backing_id) for backing_id in ids][: REVIEW_SET_CAP + 1]
        if not ids:
            return []
        pairs = await self._order_selected_review_pairs(tuple(ids))
        title_by_id = {backing_id: title for backing_id, title in pairs}
        return [
            (backing_id, title_by_id[backing_id])
            for backing_id in ids
            if backing_id in title_by_id
        ]

    def _collect_review_set_picker_rows(
        self,
    ) -> list[tuple[str, str, str, bool]]:
        """Build the picker's display rows with live progress (off the loop).

        One liveness resolve covers the union of every listed set's backing
        ids, so per-set progress shares a single chunked Media-DB query.
        """
        from tldw_chatbook.Library.review_set_state import build_picker_rows

        service = self._review_set_service()
        if service is None:
            return []
        sets = service.list_review_sets()
        live_ids = self._review_set_live_ids(
            item.backing_media_id
            for review_set in sets
            for item in review_set.items
        )
        return build_picker_rows(sets, lambda candidate: candidate in live_ids)

    async def _push_review_set_picker(
        self, rows: list[tuple[str, str, str, bool]]
    ) -> tuple[str, str] | None:
        """Push the picker modal and await its decision.

        Returns:
            ``("open", set_id)`` | ``("dismiss", set_id)``, or ``None`` on
            cancel (or when the host cannot push modals).
        """
        push_screen_wait = getattr(self.app, "push_screen_wait", None)
        if not callable(push_screen_wait):
            return None
        from tldw_chatbook.Widgets.Library.library_review_set_picker import (
            LibraryReviewSetPickerDialog,
        )

        return await push_screen_wait(LibraryReviewSetPickerDialog(rows))

    def _activate_review_set(self, set_id: str) -> int | None:
        """Activate ``set_id`` and return its landing backing id (off-loop).

        Reopens a completed set first (AC#2); activation deactivates any other
        active set (the service's one-active invariant). An all-tombstoned set
        is NOT activated -- the caller shows the empty notice instead (design
        §7: an empty set is empty, never resumable).

        Returns:
            The live backing id at the set's resolved cursor, or ``None``.
        """
        from tldw_chatbook.Library.review_set_state import resolve_cursor

        service = self._review_set_service()
        if service is None:
            return None
        review_set = service.get_review_set(set_id)
        if review_set is None:
            return None
        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        resolved = resolve_cursor(
            review_set.items,
            review_set.cursor,
            lambda candidate: candidate in live_ids,
        )
        landing = {item.position: item for item in review_set.items}.get(resolved)
        if landing is None or landing.backing_media_id not in live_ids:
            return None
        if review_set.completed_at is not None:
            service.reopen(set_id)
        service.activate(set_id)
        if resolved != review_set.cursor:
            # Persist the tombstone resolve (the walker does the same on
            # resume) so a later restore of the deleted item cannot yank a
            # subsequent resume back to the stale cursor (Qodo #2337).
            service.set_cursor(set_id, resolved)
        return landing.backing_media_id

    # -- auto-resume on media entry (task-28245) ------------------------------

    def _cancel_pending_review_set_resume(self) -> None:
        """Drop an in-flight auto-resume when the user opens something explicitly.

        task-31273 (user ruling at the critique #4 close): an explicit open --
        a row press, a deep link, open-by-id -- wins over the entry-time
        auto-resume; plain rail entry with no target still resumes.
        """
        self.workers.cancel_group(self, _REVIEW_SET_RESUME_WORKER_GROUP)

    def _maybe_auto_resume_review_set(self) -> None:
        """Kick the once-per-set auto-resume of an active review set.

        Called ONLY from the rail-select seam (an explicit user gesture) --
        never from the mount leg, whose boot-time timing made the worker's
        lazy imports race the _ui_ready module census (flaky Perf Guard).
        The worker still re-checks the surface right before opening, so an
        entry that gets yanked away aborts cleanly.

        Its OWN exclusive group, not ``library_review_set`` -- joining the
        entry-point builders' group would CANCEL an in-flight "Review these"
        build when the user clicks the Media rail mid-build (Qodo #2342).
        """
        self.run_worker(
            self._auto_resume_review_set_worker(),
            group=_REVIEW_SET_RESUME_WORKER_GROUP,
            exclusive=True,
            exit_on_error=False,
        )

    async def _auto_resume_review_set_worker(self) -> None:
        """Open the active set's cursor item in the Reader, on every entry.

        task-31234 (supersedes task-28245's once-per-set gate, user ruling
        at the critique #3 close): the banner and the visible document must
        always agree, so every entry with an active set lands at the saved
        place -- Escape shows the list until the next entry gesture.
        task-28245 AC#3 still holds: the final still-on-the-media-list +
        current-screen gates make a cold-start yank abort without opening.
        task-30042 (user ruling): failures are NEVER silent -- missing
        storage warns once per session, and any storage error surfaces;
        only the ordinary no-active-set case stays quiet.
        """
        try:
            if self._review_set_service() is None:
                if not getattr(self, "_review_set_storage_warned", False):
                    self._review_set_storage_warned = True
                    # Deliberately WARNING where the explicit gestures use
                    # ERROR (task-31225 rider): this fires ambiently on
                    # media entry, not in answer to a press -- ambient
                    # severity stays a notch below gesture severity.
                    self._notify_review_set(
                        self._REVIEW_SET_STORAGE_UNAVAILABLE,
                        severity="warning",
                    )
                return
            landing = await self._run_library_service_call(
                self._resolve_active_review_set_landing, isolate_in_worker=True
            )
            if landing is None:
                return
            _set_id, backing_id = landing
            if (
                self._library_selected_row_id != LIBRARY_ROW_BROWSE_MEDIA
                or self._media_state.view != "list"
                or not getattr(self, "is_current", False)
            ):
                return
            # task-31234 (supersedes task-28245's once-per-set gate, user
            # ruling at the critique #3 close): open the cursor item on
            # EVERY entry. The gate restored the banner but not the item on
            # re-entry -- the status line pointed at an off-set document.
            self._open_library_media_viewer(f"local:media:{backing_id}")
        except Exception:
            # task-30042: resuming failed on a real error -- surface it; the
            # user has an active set they can no longer see.
            logger.opt(exception=True).warning("review-set auto-resume failed")
            self._notify_review_set(
                "Couldn't resume the review set — storage error.",
                severity="error",
            )

    def _resolve_active_review_set_landing(self) -> tuple[str, int] | None:
        """Resolve the active set's live cursor item (runs off the loop).

        Returns:
            ``(set_id, backing_media_id)`` for the item the Reader should
            resume at, or ``None`` when no set is active or every pinned
            item is a tombstone.
        """
        from tldw_chatbook.Library.review_set_state import resolve_cursor

        service = self._review_set_service()
        if service is None:
            return None
        review_set = service.get_active_review_set()
        if review_set is None:
            return None
        live_ids = self._review_set_live_ids(
            item.backing_media_id for item in review_set.items
        )
        resolved = resolve_cursor(
            review_set.items,
            review_set.cursor,
            lambda candidate: candidate in live_ids,
        )
        landing = {item.position: item for item in review_set.items}.get(resolved)
        if landing is None or landing.backing_media_id not in live_ids:
            return None
        # Qodo on #2366 (the Qodo #2337 pattern, third path): persist a
        # tombstone-resolved cursor so a later restore of the deleted item
        # cannot yank a subsequent entry back to the stale position.
        if resolved != review_set.cursor:
            service.set_cursor(review_set.set_id, resolved)
        return review_set.set_id, landing.backing_media_id

    def _focus_library_media_items_pane(self) -> None:
        return self._media_controller._focus_library_media_items_pane()

    def _library_media_find_state(self) -> tuple[bool, Widget | None]:
        """Whether the content Find bar is OPEN, plus its widget if mounted.

        task-31271 seam (a): openness is the screen's own state -- the DOM
        is one refresh behind it in both directions, so reading widget
        presence let Escape and the footer chip that describes Escape
        disagree (the chip promised "close find" over a bar the recompose
        had already removed). The state test mirrors the viewer's own
        render condition (``find_open or content_query``), so the two agree
        at rest; the widget is returned only for focus-containment tests,
        which need the real node.

        Returns:
            ``(find_open, controls)`` -- ``controls`` is ``None`` when the
            bar is closed or has not been mounted yet.
        """
        find_open = bool(
            self._media_state.find_open or self._media_state.content_query
        )
        if not find_open:
            return False, None
        try:
            return True, self.query_one("#library-media-content-search-controls")
        except (NoMatches, QueryError):
            return True, None

    def _library_media_reader_exit_available(
        self, layout: MediaReaderEffectiveLayout | None = None
    ) -> bool:
        """Whether a "back to list" exit means anything in this layout.

        task-31272: the three-pane shell shows the media list in its Items
        pane at all times, so ``_library_media_view = "list"`` changes no
        pixels there -- it only revokes every Reader binding gated on that
        flag (Escape, ] and [ died on identical pixels: critique #4, A cap
        25/31/39). Every other layout genuinely returns focus to a visible
        list, so its exit -- the "‹ Back" control, which composes exactly
        where this is True, and Escape's compact branch -- is unchanged.

        Args:
            layout: Effective shell layout to judge; read from the mounted
                shell (falling back to the screen's own copy) when omitted.

        Returns:
            True when the Reader has a real exit to offer.
        """
        if layout is None:
            try:
                layout = self.query_one(
                    ".library-media-route", LibraryBrowseReaderShell
                ).effective_layout
            except (NoMatches, QueryError):
                layout = self._media_state.reader_layout
        return not (layout.library_open and layout.items_open)

    def _library_media_list_surface_active(self, *, require_focus: bool=True) -> bool:
        return self._media_controller._library_media_list_surface_active(require_focus=require_focus)

    def _library_media_escape_label(self) -> str:
        """Describe the action Escape will take from the current effective role.

        task-31272: exactly four words -- "close" (find bar, More menu, or
        an armed delete/edit cancel), "focus Items", "focus Library" and
        "back" (the compact exit) -- plus "" where Escape does nothing and
        the footer must therefore advertise nothing. Critique #4 counted
        eight distinct ``esc …`` chips live.
        """
        session = self._media_state.reader_session
        # Qodo on PR #2583 (task-32222): mirror the FIRST THREE branches of
        # ``action_library_media_viewer_back`` -- it closes the metadata-edit
        # and analysis-edit forms exactly as it closes a delete confirm, but
        # this label checked only the delete, so the footer advertised "focus
        # Items" over a form Escape would merely close. That is the same
        # chip-vs-key drift task-31272 closed at four other seams, and
        # LIBRARY_MEDIA_SUBSTATE_BACK_SHORTCUTS already promised all three
        # sub-states this one word.
        if (
            self._media_state.editing
            or self._media_state.confirming_delete
            or self._media_state.editing_analysis
        ):
            return "close"
        if session.more_open:
            return "close"
        # Qodo on #2386: an Items strip opened over the Reader is a
        # transient this Escape closes (see the matching branch in
        # ``action_library_media_viewer_back``), wherever focus sits.
        if self._library_open_choice_strip() is not None:
            return "close"
        focused = self.focused
        try:
            shell = self.query_one(
                ".library-media-route", LibraryBrowseReaderShell
            )
        except (NoMatches, QueryError):
            return "back"
        # task-31271 seam (a): the bar's LIVE state, not its DOM presence
        # (critique #4, A cap 08/23, B cap_21) -- and the same seam Escape
        # itself reads, so the chip and the key can never disagree.
        find_open, find_controls = self._library_media_find_state()
        if (
            find_controls is not None
            and focused is not None
            and (focused is find_controls or find_controls in focused.ancestors)
        ):
            return "close"
        if focused is not None and (
            focused is shell.items or shell.items in focused.ancestors
        ):
            return "focus Library" if shell.effective_layout.library_open else "back"
        if focused is not None and (
            focused is shell.library or shell.library in focused.ancestors
        ):
            # task-31272: no chip where Escape is inert (see the matching
            # branch in ``action_library_media_viewer_back``).
            return (
                "back"
                if self._library_media_reader_exit_available(shell.effective_layout)
                else ""
            )
        # Qodo on #2367: with the Find bar open, a reader-region Escape
        # closes it first (see action_library_media_viewer_back) -- the
        # label says so even when focus has left the bar (F6 to content).
        if find_open:
            return "close"
        if shell.effective_layout.items_open:
            return "focus Items"
        if shell.effective_layout.library_open:
            return "focus Library"
        return "back"

