    @staticmethod
    def _trailing_index(button_id: str | None) -> int | None:
        """Parse the trailing `-{index}` integer from a button id, or None."""
        if not button_id:
            return None
        try:
            index = int(button_id.rsplit("-", 1)[-1])
        except ValueError:
            return None
        return index if index >= 0 else None

