    async def _open_library_item_by_id(
        self,
        source_type: str,
        record_id: str,
        *,
        entry_origin: bool = False,
        required_database: Any | None = None,
        required_authority: str = "",
    ) -> LibraryEntryReconcileResult | None:
        """Open a Library item straight to its detail surface by id.

        Shared route for per-result Search/RAG "Open" actions -- unlike
        rail-row navigation (``_select_library_rail_row``), which always
        lands on the list/browse view for a content type, this jumps
        straight to the media viewer, the notes editor, or a specific
        conversation. Also the route the future ingest-queue "open result"
        actions reuse.

        Args:
            source_type: ``"media"``, ``"notes"``, ``"conversations"``, or
                ``"prompt"`` (singular -- distinct from the "prompts"
                scope-toggle/source key; see ``_OPEN_SOURCE_TYPE_MAP``).
                Any other value (including empty) is a no-op -- defensive
                only, since the Open action is only rendered for rows with
                resolvable provenance (``LibraryRagResultRow.can_open``).
            record_id: The item's id within its source type.
            entry_origin: Whether this open belongs to the automatic Library
                entry lifecycle and therefore must use strict retained-owner
                synchronization with no screen-level fallback.
        """
        if self._prompts_state.mutation_in_flight:
            return
        if not record_id or source_type not in (
            "media",
            "notes",
            "conversations",
            "prompt",
        ):
            return None

        open_generation = self._library_navigation_context_generation
        entry_route_key = self._library_entry_route_key() if entry_origin else None
        entry_generation = (
            self._library_snapshot_state_generation if entry_origin else None
        )
        entry_conversation_id = (
            self._selected_conversation_id
            if entry_origin and source_type == "conversations"
            else None
        )

        def required_character_scope_is_current() -> bool:
            if required_database is None:
                return True
            return getattr(
                self.app_instance, "chachanotes_db", None
            ) is required_database and self._unavailable_navigation._library_character_authority_is_current(
                self,
                required_authority
            )

        def entry_is_current() -> bool:
            return (
                required_character_scope_is_current()
                and open_generation == self._library_navigation_context_generation
                and (
                    not entry_origin
                    or (
                        entry_generation == self._library_snapshot_state_generation
                        and entry_route_key == self._library_entry_route_key()
                        and (
                            entry_conversation_id is None
                            or entry_conversation_id
                            == self._selected_conversation_id
                        )
                    )
                )
            )

        if source_type == "prompt":
            if not await self._flush_library_prompt_save():
                return None
            if not entry_is_current():
                return LibraryEntryReconcileResult.SUPERSEDED
            try:
                parsed_prompt_id = int(record_id)
            except (TypeError, ValueError):
                return None
            if parsed_prompt_id < 1:
                return None
            if not entry_origin:
                self._acknowledge_library_destination_change()
            self._clear_library_prompt_selection(announce=True)
            self._invalidate_library_prompts_browse()
            # Mirrors handle_library_prompt_row's full state-set exactly so
            # the recomposed canvas lands on a clean editor, never a stale
            # one carried over from a previously opened prompt.
            self._reset_library_prompt_editor_state()
            self._prompts_state.selected_prompt_id = parsed_prompt_id
            self._library_selected_row_id = LIBRARY_ROW_BROWSE_PROMPTS
            self._prompts_state.view = "editor"
            if entry_origin:
                generation = self._library_snapshot_state_generation
                route_key = self._library_entry_route_key()
                result = await self._replace_library_canvas_child(
                    LibraryPromptsListCanvas(
                        **self._library_prompts_canvas_kwargs(),
                        id="library-prompts-canvas",
                    ),
                    generation=generation,
                    route_key=route_key,
                )
                if result is not LibraryEntryReconcileResult.APPLIED:
                    return result
            self.run_worker(
                self._refresh_library_prompt_detail(
                    parsed_prompt_id,
                    entry_origin=entry_origin,
                ),
                exclusive=True,
                group="library_prompt_detail",
            )
            if entry_origin:
                return LibraryEntryReconcileResult.APPLIED
            if not self.query("#library-prompts-reader-shell"):
                # Search/RAG and the other generic Library destinations do
                # not own Prompts' retained Library/Items/Work shell. A
                # canvas-child swap would mount only Items and strand the
                # fetched editor state with no Work pane to render it.
                self.refresh(recompose=True)
                return None
            # task-21116: per-click open routes through the same targeted
            # canvas-child replacement the entry lifecycle uses.
            await self._apply_library_open_item_surface(
                lambda: LibraryPromptsListCanvas(
                    **self._library_prompts_canvas_kwargs(),
                    id="library-prompts-canvas",
                )
            )
            return None

        if source_type == "media":
            note_flush = await self._flush_library_note_save()
            if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
                return None
            if not entry_is_current():
                return LibraryEntryReconcileResult.SUPERSEDED
            if not entry_origin:
                self._acknowledge_library_destination_change()
            self._clear_library_prompt_selection(announce=True)
            # Mirrors handle_library_media_row's full state-set EXACTLY so
            # the recomposed canvas lands on a clean viewer, never a stale
            # one carried over from a previously opened item.
            if self._media_state.reader_session.external_detail:
                self._media_state.reader_session = leave_external_detail(
                    self._media_state.reader_session
                )
            self._media_state.selected_media_id = record_id
            self._library_selected_row_id = LIBRARY_ROW_BROWSE_MEDIA
            self._cancel_pending_review_set_resume()
            self._media_state.view = "viewer"
            reader_identity = self._library_media_reader_identity(record_id)
            if reader_identity is not None:
                canonical_id, backing_id = reader_identity
                self._media_state.reader_session = begin_selection(
                    self._media_state.reader_session,
                    canonical_id,
                    backing_id,
                    record_id,
                    immediate=True,
                )
            self._media_state.editing = False
            self._media_state.confirming_delete = False
            self._media_state.highlights = []
            self._media_state.editing_analysis = False
            self._close_library_media_find()
            self._media_state.content_mode = "raw"
            if not entry_origin:
                if self.query(".library-media-route"):
                    await self._apply_library_media_active_surface()
                else:
                    await self._apply_library_open_item_surface(
                        self._build_library_media_active_child
                    )
                if not entry_is_current():
                    return LibraryEntryReconcileResult.SUPERSEDED
            # task-32065: reclaim the Reader width after its surface is composed.
            self.call_after_refresh(self._restore_library_media_reader_width_on_open)
            self.run_worker(
                self._refresh_library_media_detail(
                    record_id,
                    entry_origin=entry_origin,
                ),
                exclusive=True,
                group="library_media_detail",
            )
            if entry_origin:
                return LibraryEntryReconcileResult.APPLIED
            # task-31797: ingest, Search/RAG and landing-hub deep links jump
            # to the viewer; also populate Items through the rail's browse/facet
            # requests, preserving viewer focus with focus_identity=None.
            self._request_library_media_browse(
                self._library_media_browse_controller.state.mutation_refresh_scope,
                focus_identity=None,
            )
            self._request_library_media_facets()
            return None

        if source_type == "notes":
            note_flush = await self._flush_library_note_save()
            if note_flush.kind is not NoteFlushOutcomeKind.PERMITTED:
                return None
            if not entry_is_current():
                return LibraryEntryReconcileResult.SUPERSEDED
            if not entry_origin:
                self._acknowledge_library_destination_change()
            self._clear_library_prompt_selection(announce=True)
            self._notes_state.browse_return_receipt = None
            self._set_library_notes_source(LIBRARY_NOTES_SOURCE_DATABASE)
            self._set_library_destination_with_conversation_fence(
                LIBRARY_ROW_BROWSE_NOTES
            )
            if entry_origin:
                self._supersede_library_notes_navigation()
                self._library_note_session.close_session()
                self._notes_state.selected_note_id = record_id
                self._notes_state.view = "editor"
                self._notes_state.load_state = "loading"
                self._notes_state.load_message = ""
                self._notes_state.autosave_state = "idle"
                self._notes_state.shortcut_status = ""
                self._notes_state.confirming_delete = False
                self._notes_state.preview = False
                self._notes_state.context = False
                self._notes_state.delete_origin_context = False
                self._notes_state.delete_origin_preview = False
                self._notes_state.editor_armed = False
                generation = self._library_snapshot_state_generation
                route_key = self._library_entry_route_key()
                result = await self._replace_library_canvas_child(
                    LibraryNotesCanvas(
                        **self._library_notes_list_canvas_kwargs(),
                        id="library-notes-canvas",
                    ),
                    generation=generation,
                    route_key=route_key,
                )
                if result is not LibraryEntryReconcileResult.APPLIED:
                    return result
            self._begin_library_note_load(record_id, entry_origin=entry_origin)
            if entry_origin:
                return LibraryEntryReconcileResult.APPLIED
            if self.query(".library-notes-route"):
                _sync_library_canvas(self, "notes")
            else:
                # Crossing into Notes is structural because it installs the
                # adaptive shell and source strip. Once mounted, its Items
                # owner is always list-only; detail belongs to the permanent
                # work pane beside it.
                await self._apply_library_open_item_surface(
                    lambda: LibraryNotesCanvas(
                        **self._library_notes_list_canvas_kwargs(),
                        id="library-notes-canvas",
                    )
                )
            return None

        locator_intent = ("conversations", record_id)
        self._pending_library_source_open = locator_intent
        normalized_query, generation = self._prepare_library_conversation_page_request(
            "",
            page=1,
        )
        service = getattr(self.app_instance, "chat_conversation_scope_service", None)
        locate_page = getattr(service, "locate_conversation_page", None)
        if not callable(locate_page):
            self._conversations_controller._fail_library_conversation_request(
                1,
                normalized_query,
                generation,
                copy="Conversation is unavailable. Try again.",
            )
            self._conversations_controller._notify_library_conversation_unavailable()
            return None
        try:
            located = await self._run_library_service_call(
                locate_page,
                record_id,
                mode="local",
                scope_type="all",
                archive_scope=self._conversation_recovery().scope,
                limit=LIBRARY_CONVERSATION_PAGE_SIZE,
            )
        except Exception:
            if generation != self._conversations_state.request_generation:
                return LibraryEntryReconcileResult.SUPERSEDED
            self._conversations_controller._fail_library_conversation_request(
                1,
                normalized_query,
                generation,
                copy="Couldn't open conversation; try again.",
            )
            return None
        if generation != self._conversations_state.request_generation:
            return LibraryEntryReconcileResult.SUPERSEDED
        if not entry_is_current():
            return LibraryEntryReconcileResult.SUPERSEDED
        if located is None:
            self._conversations_controller._fail_library_conversation_request(
                1,
                normalized_query,
                generation,
                copy="Conversation is unavailable. Try again.",
            )
            self._conversations_controller._notify_library_conversation_unavailable()
            return None
        try:
            records, resolved_page, total, has_more = (
                self._validate_library_conversation_locator(located, record_id)
            )
        except (TypeError, ValueError):
            self._conversations_controller._fail_library_conversation_request(
                1,
                normalized_query,
                generation,
                copy="Couldn't open conversation; try again.",
            )
            return None

        self._conversations_state.page_records = records
        self._conversations_state.page = resolved_page
        self._conversations_state.total = total
        self._conversations_state.total_known = True
        self._conversations_state.has_more = has_more
        self._conversations_state.page_loaded = True
        self._conversations_state.query = ""
        self._conversations_state.requested_page = resolved_page
        self._conversations_state.requested_query = ""
        self._conversations_state.freshness = "fresh"
        self._conversations_state.stale_copy = ""
        self._conversations_state.loading = False
        self._conversations_state.error = ""
        self._selected_conversation_id = record_id
        if entry_origin:
            self._library_selected_row_id = LIBRARY_ROW_BROWSE_CONVERSATIONS
            conversations_state = self._build_library_conversations_state()
            self._conversations_controller._adopt_library_conversation_state_selection(
                conversations_state.selected_id
            )
            generation = self._library_snapshot_state_generation
            route_key = self._library_entry_route_key()
            result = await self._replace_library_canvas_child(
                LibraryConversationsCanvas(
                    conversations_state,
                    id="library-conversations-canvas",
                ),
                generation=generation,
                route_key=route_key,
            )
            if result is LibraryEntryReconcileResult.APPLIED:
                self._ensure_library_conversation_reader_selection()
            return result
        await self._select_library_rail_row(LIBRARY_ROW_BROWSE_CONVERSATIONS)
        if self._pending_library_source_open == locator_intent:
            self._pending_library_source_open = None
        return None

    @staticmethod
    def _validate_library_conversation_locator(response: object, conversation_id: str) -> tuple[tuple[Mapping[str, Any], ...], int, int, bool]:
        return LibraryConversationsController._validate_library_conversation_locator(response, conversation_id)


